customize_in vec2 vUV;

float sdRoundBoxBevel(vec2 uv, vec2 c, vec2 size, float bevel, float blur) {
  float radius = 1.0;
  size *= radius;
  if (iResolution.x < iResolution.y) {
    bevel *= size.x;
  } else {
    bevel *= size.y;
  }
  radius *= bevel;

  uv = abs(uv - c) - size + radius;
  float d = length(max(uv, 0.0)) + min(max(uv.x, uv.y), 0.0) - radius;
  return smoothstep(0.0, blur, abs(d) * step(0.0, -d));
}

vec4 mixFunc(vec4 back, vec4 overlap, float alp) {
  float invAlp = 1.0 - alp;
  vec4 ret = back;

  if (alp > 0.0) {
    ret.xyz = overlap.xyz + back.xyz * invAlp;
    ret.a = alp + back.a * invAlp;
  }
  return ret;
}

vec2 SetScale(vec2 uv, vec2 center, float s){
  uv -= center;
  uv /= s;
  uv += center;
  return uv;
}

float inBound(vec2 uv){
  return step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
}

float sat(float x){
  return clamp(x, 0.0, 1.0);
}

float pickGray(vec4 color){
  return dot(color.rgb, vec3(0.299, 0.587, 0.114));
}

vec4 FUNCNAME(vec2 tc) {
  float iPro = PREFIX(iPro);
  vec2 uv = vUV;
  vec4 retColor = vec4(0.0);
  int uStep = PREFIX(uStep);
  vec2 resRadio = vec2(iResolution.x / iResolution.y, 1.0);
  if (iResolution.x < iResolution.y) {
    resRadio = vec2(1.0, iResolution.y / iResolution.x);
  }
  float bevel = 0.0;
  if(uStep == 0) {
    if(iPro < 0.5) {
      retColor = vec4(INPUT1(uv).rgb, 1.0);
    } else {
      retColor = vec4(INPUT2(vec2(uv.x, 1.0 - uv.y)).rgb, 1.0);
    }

    vec2 st = ((uv * 2.0 - 1.0)) * resRadio;
    vec2 r2 = vec2(1.0) * resRadio;
    vec2 r22 = vec2(0.05);
    float mask1 = sdRoundBoxBevel(st, vec2(0.0), r2, bevel, 0.01);
    float mask2 = sdRoundBoxBevel(st, vec2(0.0), r2 - r22, bevel, 0.01);
    vec4 mask = vec4(mask1 - mask2);

    retColor = mixFunc(retColor, mask, mask.a) * mask1;
    return retColor;
  } else {
    float bloomPro = PREFIX(uBloomPro);
    vec4 inputColor1 = INPUT1(uv);
    vec4 inputColor2 = INPUT2(uv);
    vec4 bloomColor = clamp(vec4(inputColor2.rgb * mix(1.0, 1.5, bloomPro), inputColor2.a), 0.0, 1.0);
    retColor = mixFunc(inputColor1, bloomColor, bloomColor.a);
    return vec4(retColor.rgb, 1.0);
  }
}

