float ramp(float y, float start, float end){
	float inside = step(start,y) - step(end,y);
	float fact = (y-start)/(end-start)*inside;
	return (1.-fact) * inside;	
}

float stripes(vec2 uv, float iTime){	
	float noi = rand(uv*vec2(0.5,1.) + vec2(1.,3.));
  float inx = floor(uv.y*100.0);
  float yOff = rand(vec2(inx,0.0))*0.1*rand(vec2(0.0, iTime));
	return ramp(mod(uv.y*100.0 + iTime/2.+sin(iTime + sin(iTime*0.63)),1.0),0.0,1.0)*noi
         * clamp((abs(sin((uv.x-yOff)*400.0))-0.1)*1.2,-1.0,1.0)*step(0.4,yOff*10.0)*showScanLine(uv);
}
float calBrightValue(float bright){
  float brightValue = 0.0;
  if (bright > 0.0){
    brightValue = 1.0 + bright / 100.0;
  }
  else{
    brightValue = 1.0 - 1.0 / (0.99 + bright / 253.0);	
    brightValue *= 0.6;
  }
  return brightValue;
}

vec4 calBrightnessColor(vec4 color, float brightness){
  float bright = calBrightValue(brightness);
  vec4 ret;
  if (bright > 0.0)
    ret = color * bright;
  else
    ret = color + bright;

  ret.w = color.w;
  ret = clamp(ret, vec4(0.0), vec4(1.0));
  return ret;
}

const float EPSILON = 1e-4;
vec3 HUEtoRGB(in float hue)
{
    vec3 rgb = abs(hue * 6. - vec3(3, 2, 4)) * vec3(1, -1, -1) + vec3(-1, 2, 2);
    return clamp(rgb, 0., 1.);
}

vec3 RGBtoHCV(in vec3 rgb)
{
    vec4 p = (rgb.g < rgb.b) ? vec4(rgb.bg, -1., 2. / 3.) : vec4(rgb.gb, 0., -1. / 3.);
    vec4 q = (rgb.r < p.x) ? vec4(p.xyw, rgb.r) : vec4(rgb.r, p.yzx);
    float c = q.x - min(q.w, q.y);
    float h = abs((q.w - q.y) / (6. * c + EPSILON) + q.z);
    return vec3(h, c, q.x);
}
vec3 hsl2rgb(in vec3 hsl)
{
    vec3 rgb = HUEtoRGB(hsl.x);
    float c = (1. - abs(2. * hsl.z - 1.)) * hsl.y;
    return (rgb - 0.5) * c + hsl.z;
}
vec3 rgb2hsl(in vec3 rgb)
{
    vec3 hcv = RGBtoHCV(rgb);
    float z = hcv.z - hcv.y * 0.5;
    float s = hcv.y / (1. - abs(z * 2. - 1.) + EPSILON);
    return vec3(hcv.x, s, z);
}
