    vec4 I = INPUT1(uv + texelSize * vec2(-0.5,  0.5));
    vec4 J = INPUT1(uv + texelSize * vec2( 0.5,  0.5));
    vec4 K = INPUT1(uv + texelSize * vec2(-1.0,  1.0));
    vec4 L = INPUT1(uv + texelSize * vec2( 0.0,  1.0));
    vec4 M = INPUT1(uv + texelSize * vec2( 1.0,  1.0));

    vec2 div = (1.0 / 4.0) * vec2(0.5, 0.125);

    vec4 o = (D + E + I + J) * div.x;
    o += (A + B + G + F) * div.y;
    o += (B + C + H + G) * div.y;
    o += (F + G + L + K) * div.y;
    o += (G + H + M + L) * div.y;

    return o;
}

vec4 UpsampleTent(vec2 uv, vec2 texelSize)
{
    vec4 d = texelSize.xyxy * vec4(1.0, 1.0, -1.0, 0.0);

    vec4 s;
    s =  INPUT2(uv - d.xy);
    s += INPUT2(uv - d.wy) * 2.0;
    s += INPUT2(uv - d.zy);

    s += INPUT2(uv + d.zw) * 2.0;
    s += INPUT2(uv) * 4.0;
    s += INPUT2(uv + d.xw) * 2.0;

    s += INPUT2(uv + d.zy);
    s += INPUT2(uv + d.wy) * 2.0;
    s += INPUT2(uv + d.xy);

    return s * (1.0 / 16.0);
}

