  vec4 p = vec4(.47,.06,.49,.93);

  if(uStep == 0){
    float strength = 0.2 * iPro;
    vec2 dir = vec2(cos(angle), sin(angle)) * strength;
    float motion_progress = KeySpline(p, progress);
    float offset = 0.5;
