  vec4 bgCol = INPUT2(tc);
  vec4 blurCol = INPUT3(tc);

  vec4 backCol = progress < 0.5 ? fgCol : bgCol;
  if (progress < 0.3) {
    iPro = progress / 0.3;
  } else if (progress < 0.7) {
    iPro = 1.0;
  } else {
