vec3 HSL_RGBtoHSL(vec3 RGB)
{
    vec3 hsl;
    float R = RGB.x;
    float G = RGB.y;
    float B = RGB.z;
    float Max = 0.0;
    float Min = 0.0;
    float H = 0.0;
    float S = 0.0;
    float L = 0.0;

    Min = min(R, min(G, B));
    Max = max(R, max(G, B));

    if (Min == Max)
    {
        H = 2.0 / 3.0;
        S = 0.0;
        L = R;
    }
    else
    {
        L = (Max + Min) / 2.0;

        if (L < 0.5)
            S = (Max - Min) / (Max + Min);
        else
            S = (Max - Min) / (2.0 - Max - Min);

        if (R == Max)
            H = (G - B) / (Max - Min);
        else if (G == Max)
            H = 2.0 + (B - R) / (Max - Min);
        else
            H = 4.0 + (R - G) / (Max - Min);

        H /= 6.0;
        if (H < 0.0)
            H += 1.0;
    }

    hsl.x = H * 360.0;
    hsl.y = S;
    hsl.z = L;

    return hsl;
}

