    float G = 0.0;
    float B = 0.0;
    float var_1 = 0.0;
    float var_2 = 0.0;
    float tempr = 0.0;
    float tempg = 0.0;
    float tempb = 0.0;

    if (S == 0.0)
    {
        R = G = B = L;
    }
    else
    {
        if (L < 0.5)
            var_2 = L * (1.0 + S);
        else
            var_2 = (L + S) - (L * S);

        var_1 = 2.0 * L - var_2;

        tempr = H + 1.0 / 3.0;
        if (tempr > 1.0)
            tempr = tempr - 1.0;

        tempg = H;

        tempb = H - 1.0 / 3.0;
        if (tempb < 0.0)
            tempb = tempb + 1.0;

        // Red
        if (tempr < 1.0 / 6.0)
            R = var_1 + (var_2 - var_1) * 6.0 * tempr;
        else if (tempr < 0.5)
            R = var_2;
        else if (tempr < 2.0 / 3.0)
            R = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempr) * 6.0;
        else
            R = var_1;
        // Green
