    return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
    return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
    return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
    float aGuessT = aX;
    for (int i = 0; i < 6; ++i) {
        float currentSlope = GetSlope(aGuessT, mX1, mX2);
        if (currentSlope == 0.0)
            return aGuessT;
        float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
        aGuessT -= currentX / currentSlope;
    }
    return aGuessT;
}

float KeySpline(vec4 p, float aX) {
    float mX1 = p.x;
    float mY1 = p.y;
    float mX2 = p.z; 
    float mY2 = p.w;
    if (mX1 == mY1 && mX2 == mY2)
        return aX;    // linear
    return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec3 HSL_RGBtoHSL(vec3 RGB)
{
    vec3 hsl;
    float R = RGB.x;
    float G = RGB.y;
    float B = RGB.z;
    float Max = 0.0;
    float Min = 0.0;
    float H = 0.0;
    float S = 0.0;
    float L = 0.0;

    Min = min(R, min(G, B));
    Max = max(R, max(G, B));

    if (Min == Max)
    {
        H = 2.0 / 3.0;
        S = 0.0;
        L = R;
    }
    else
    {
        L = (Max + Min) / 2.0;

        if (L < 0.5)
            S = (Max - Min) / (Max + Min);
        else
            S = (Max - Min) / (2.0 - Max - Min);

        if (R == Max)
            H = (G - B) / (Max - Min);
        else if (G == Max)
            H = 2.0 + (B - R) / (Max - Min);
        else
            H = 4.0 + (R - G) / (Max - Min);

        H /= 6.0;
        if (H < 0.0)
            H += 1.0;
    }

    hsl.x = H * 360.0;
    hsl.y = S;
    hsl.z = L;

    return hsl;
}

vec3 HSL_HSLtoRGB(vec3 HSL)
{
    vec3 RGB;
    float H = HSL.x / 360.0;
    float S = HSL.y;
    float L = HSL.z;
    float R = 0.0;
    float G = 0.0;
    float B = 0.0;
    float var_1 = 0.0;
    float var_2 = 0.0;
    float tempr = 0.0;
    float tempg = 0.0;
    float tempb = 0.0;

    if (S == 0.0)
    {
        R = G = B = L;
    }
    else
    {
        if (L < 0.5)
            var_2 = L * (1.0 + S);
        else
            var_2 = (L + S) - (L * S);

        var_1 = 2.0 * L - var_2;

        tempr = H + 1.0 / 3.0;
        if (tempr > 1.0)
            tempr = tempr - 1.0;

        tempg = H;

        tempb = H - 1.0 / 3.0;
        if (tempb < 0.0)
            tempb = tempb + 1.0;

        // Red
        if (tempr < 1.0 / 6.0)
            R = var_1 + (var_2 - var_1) * 6.0 * tempr;
        else if (tempr < 0.5)
            R = var_2;
        else if (tempr < 2.0 / 3.0)
            R = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempr) * 6.0;
        else
            R = var_1;
        // Green
        if (tempg < 1.0 / 6.0)
            G = var_1 + (var_2 - var_1) * 6.0 * tempg;
        else if (tempg < 0.5)
            G = var_2;
        else if (tempg < 2.0 / 3.0)
            G = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempg) * 6.0;
        else
            G = var_1;
        // Blue
        if (tempb < 1.0 / 6.0)
            B = var_1 + (var_2 - var_1) * 6.0 * tempb;
        else if (tempb < 0.5)
            B = var_2;
        else if (tempb < 2.0 / 3.0)
            B = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempb) * 6.0;
        else
            B = var_1;
    }

    RGB.x = R;
    RGB.y = G;
    RGB.z = B;

    return RGB.zyx;
}

vec4 FUNCNAME(vec2 tc)
{   
    float iGlobalTime = PREFIX(global_time);
    float iTotalTime = PREFIX(total_time);
    float frame_rate = PREFIX(frame_rate);
    int Color = PREFIX(Color);
    float Distortion = float(PREFIX(Distortion)) / 100.0;
    float Strength = float(PREFIX(Strength)) / 100.0;
    float Filter = float(PREFIX(Filter)) / 100.0;
    int uStep = PREFIX(uStep);
    float UseLight = PREFIX(UseLight);

    float iPro = min(iGlobalTime / iTotalTime, 1.0);

    float move_time = 0.25;
    float blur_time = 0.2;
    float end_move_time = move_time + blur_time;

    if(uStep == 1){
        vec4 ret = INPUT1(tc);
        float alpha = INPUT3(tc).a;
        if(iPro > end_move_time){
            alpha = INPUT4(tc).a;
        }
        ret.a = alpha;
        ret.rgb *= ret.a;
        return ret;
    }

    float blur_process = (iPro - move_time) / blur_time;
    blur_process = clamp(blur_process, 0.0, 1.0);
    vec4 p = vec4(.39,.79,.48,.94);
    blur_process = KeySpline(p, blur_process);

    float move_process = clamp(iPro / move_time, 0.0, 1.0);

    vec3 inputCol = vec3(float(Color & 0xff), float((Color >> 8) & 0xff), float((Color >> 16) & 0xff)) / 255.0;

    vec2 uv = tc;
    uv.y = 1.0 - uv.y;
    vec2 prop = vec2(1.0, iResolution.y / iResolution.x);
    if(iResolution.y > iResolution.x){
        prop = vec2(iResolution.x / iResolution.y, 1.0);
    }
    uv = (uv - vec2(0.5)) * prop + vec2(0.5);

    vec4 origCol = INPUT1(tc);
    vec4 lightCol = INPUT3(uv);
    vec4 retCol = origCol;

    if(!(inputCol.r == inputCol.g && inputCol.r == inputCol.b)){
        vec3 inputHsl = HSL_RGBtoHSL(inputCol.bgr);
        vec3 lightHsl = HSL_RGBtoHSL(lightCol.bgr);
        lightHsl.x = inputHsl.x;
        lightCol.rgb = HSL_HSLtoRGB(lightHsl);
    }

    vec2 center = vec2(0.5);
    vec2 move_uv = tc;
    move_uv.x -= sin(move_process * 3.0 * PI) * 0.01 * Strength;
    retCol = INPUT1(move_uv);

    int Samples = 20;
    float BlurWidth = 0.3 * blur_process * (1.0 + Distortion);
    float Scale = mix(1.0, 0.35 - Distortion * 0.3, blur_process);
    vec2 radial_uv = move_uv - center;
    radial_uv.x -= 0.02 * Strength;
    float blurStart = 1.0;
    float precompute = BlurWidth * (1.0 / float(Samples - 1));

    if(iPro >= move_time && iPro < move_time + blur_time){
        retCol = vec4(0.0);
        for(int i = 0; i < Samples; i++)
        {
            float temp = blurStart + float(i) * precompute;
            retCol += INPUT1(radial_uv * temp * Scale + center);
        }

        retCol /= float(Samples);
        retCol.rgb *= 1.0 - pow(blur_process, 3.0) * 0.85;
    }

    if(iPro > move_time && UseLight > 0.0){
        retCol.rgb = retCol.rgb + lightCol.rgb * Filter;
    }
    retCol = clamp(retCol, 0.0, 1.0);

    if(iPro > end_move_time){
        move_process = clamp((iPro - end_move_time) / move_time, 0.0, 1.0);
        move_uv = tc;
        move_uv.x -= sin(move_process * 3.0 * PI) * 0.01 * Strength;
        retCol = INPUT2(move_uv);
    }

    return retCol;
}

