#undef INPUT2
#define INPUT2(p) unpackOverlay(p)
vec3 darken(vec3 s, vec3 d)
{
    return min(s,d);
}

vec3 multiply(vec3 s, vec3 d)
{
    return s*d;
}

vec3 colorBurn(vec3 s, vec3 d)
{
    return 1.0 - (1.0 - d) / s;
}

vec3 linearBurn(vec3 s, vec3 d)
{
    return s + d - 1.0;
}

vec3 darkerColor(vec3 s, vec3 d)
{
    return (s.x + s.y + s.z < d.x + d.y + d.z) ? s : d;
}

vec3 lighten(vec3 s, vec3 d)
{
    return max(s,d);
}

vec3 screen(vec3 s, vec3 d)
{
    return s + d - s * d;
}

vec3 colorDodge(vec3 s, vec3 d)
{
    return d / (1.0 - s);
}

vec3 linearDodge(vec3 s, vec3 d)
{
    return s + d;
}

vec3 lighterColor(vec3 s, vec3 d)
{
    return (s.x + s.y + s.z > d.x + d.y + d.z) ? s : d;
}

float overlayFunc( float s, float d)
{
    return (d < 0.5) ? (2.0 * s * d) : (1.0 - 2.0 * (1.0 - s) * (1.0 - d));
}

vec3 overlay(vec3 s, vec3 d)
{
    vec3 c;
    c.x = overlayFunc(s.x,d.x);
    c.y = overlayFunc(s.y,d.y);
    c.z = overlayFunc(s.z,d.z);
    return c;
}

float softLightFunc(float s, float d)
{
    return (s < 0.5) ? (d - (1.0 - 2.0 * s) * d * (1.0 - d)) 
        : ((d < 0.25) ? (d + (2.0 * s - 1.0) * d * ((16.0 * d - 12.0) * d + 3.0)) 
                     : (d + (2.0 * s - 1.0) * (sqrt(d) - d)));
}

vec3 softLight(vec3 s, vec3 d)
{
    vec3 c;
    c.x = softLightFunc(s.x,d.x);
    c.y = softLightFunc(s.y,d.y);
    c.z = softLightFunc(s.z,d.z);
    return c;
}

float hardLightFunc(float s, float d)
{
    return (s < 0.5) ? (2.0 * s * d) : (1.0 - 2.0 * (1.0 - s) * (1.0 - d));
}

vec3 hardLight(vec3 s, vec3 d)
{
    vec3 c;
    c.x = hardLightFunc(s.x,d.x);
    c.y = hardLightFunc(s.y,d.y);
    c.z = hardLightFunc(s.z,d.z);
    return c;
}

float vividLightFunc(float s, float d)
{
    return (s < 0.5) ? (1.0 - (1.0 - d) / (2.0 * s)) : (d / (2.0 * (1.0 - s)));
}

vec3 vividLight(vec3 s, vec3 d)
{
    vec3 c;
    c.x = vividLightFunc(s.x,d.x);
    c.y = vividLightFunc(s.y,d.y);
    c.z = vividLightFunc(s.z,d.z);
    return c;
}

vec3 linearLight(vec3 s, vec3 d)
{
    return 2.0 * s + d - 1.0;
}

float pinLightFunc(float s, float d)
{
    return (2.0 * s - 1.0 > d) ? (2.0 * s - 1.0) : ((s < 0.5 * d) ? (2.0 * s) : d);
}

vec3 pinLight(vec3 s, vec3 d)
{
    vec3 c;
    c.x = pinLightFunc(s.x,d.x);
    c.y = pinLightFunc(s.y,d.y);
    c.z = pinLightFunc(s.z,d.z);
    return c;
}

vec3 hardMix(vec3 s, vec3 d)
{
    return floor(s + d);
}

vec3 difference(vec3 s, vec3 d)
{
    return abs(d - s);
}

vec3 exclusion(vec3 s, vec3 d)
{
    return s + d - 2.0 * s * d;
}

vec3 subtract(vec3 s, vec3 d)
{
    return d - s;
}

vec3 divide(vec3 s, vec3 d)
{
    return d / s;
}

vec3 BlendFunc(vec3 s, vec3 d, int id)
{
    if(id==1)    return darken(s,d);
    if(id==2)    return multiply(s,d);
    if(id==3)    return colorBurn(s,d);
    if(id==4)    return linearBurn(s,d);
    if(id==5)    return darkerColor(s,d);

    if(id==6)    return lighten(s,d);
    if(id==7)    return screen(s,d);
    if(id==8)    return colorDodge(s,d);
    if(id==9)    return linearDodge(s,d);
    if(id==10)    return lighterColor(s,d);

    if(id==11)    return overlay(s,d);
    if(id==12)    return softLight(s,d);
    if(id==13)    return hardLight(s,d);
    if(id==14)    return vividLight(s,d);
    if(id==15)    return linearLight(s,d);
    if(id==16)    return pinLight(s,d);
    if(id==17)    return hardMix(s,d);

    if(id==18)    return difference(s,d);
    if(id==19)    return exclusion(s,d);
    if(id==20)    return subtract(s,d);
    if(id==21)    return divide(s,d);

    return s;
}

vec2 texResize(vec2 tc, vec2 resolution, vec2 texSize, float scaleFactor)
{
    vec2 fragCoord = tc * resolution;
    vec2 uv = (fragCoord - resolution * 0.5) / (texSize * scaleFactor) + vec2(0.5);
    return uv;
}

vec4 FUNCNAME(vec2 tc)
{
    int Premultiplied = PREFIX(Premultiplied);
    int Blend = PREFIX(Blend);
    int OverlayOpacity = PREFIX(OverlayOpacity);
    int Opacity = PREFIX(Opacity);
    int TexWidth = PREFIX(TexWidth);
    int TexHeight = PREFIX(TexHeight);

    vec2 uv = tc;
    float aspect = iResolution.y / iResolution.x;
    vec2 texSize = vec2(float(TexWidth), float(TexHeight));
    float tex_aspect = texSize.y / texSize.x;
    float scale_factor = 1.0;
    if(aspect >= tex_aspect){
        scale_factor = iResolution.y / texSize.y;   
    } else {
        scale_factor = iResolution.x / texSize.x; 
    }
    uv = texResize(uv, iResolution, texSize, scale_factor);

    vec4 origCol = INPUT1(tc);
    float matt = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
    vec4 overlayCol = INPUT2(uv) * matt;
    if(Premultiplied == 0){
      overlayCol.rgb *= overlayCol.a;
    }

    overlayCol *= float(OverlayOpacity) / 100.0;

    vec4 retCol = origCol;
    if(Blend == 0){
      retCol.rgb = origCol.rgb * (1.0 - overlayCol.a) + overlayCol.rgb;
    }else{
      retCol.rgb = BlendFunc(overlayCol.rgb, origCol.rgb, Blend);
    }
    retCol.rgb = clamp(retCol.rgb, 0.0, 1.0);

    return retCol * float(Opacity) / 100.0;
}

