float bezier(float t) {
    float p0 = 0.0;
    float p1 = 0.0;
    float p2 = 0.05;
    float p3 = 1.0;

    float q0 = mix(p0, p1, t);
    float q1 = mix(p1, p2, t);
    float q2 = mix(p2, p3, t);

    float r0 = mix(q0, q1, t);
    float r1 = mix(q1, q2, t);

    return mix(r0, r1, t);
}
