#define param_iTime clamp(u_global_time/u_total_time,0.0,1.0)
vec2 shakeUV(vec2 uv, float time, float intensity) {
  float shakeX = sin(time * 50.0) * cos(time * 44.0) * intensity * 0.2;
  float shakeY = sin(time * 46.0) * cos(time * 62.0) * intensity * 0.1;

  return uv - vec2(shakeX, shakeY);
}

float moveFunc(float x) {
  return min(1.0, 1.0 * (max(0.0, 1.0 - pow(abs(4.0 * x - 1.3333), 4.0)) * step(x, 0.3333) * 0.7 + (0.7 + pow(abs(4.0 * x - 1.3333), 4.0)) * step(0.3333, x)));
}

vec4 FUNCNAME(vec2 tc) {
  vec2 uv = tc;
  vec4 fragOutCol = vec4(0.0);
  float iGlobalTime = PREFIX(iTime);

  if (PREFIX(StepType) == 1) {
    fragOutCol = INPUT2(uv);
    vec4 mask = INPUT3(uv);

    fragOutCol *= step(0.1, mask.a);
  } else {
    float move_process = moveFunc(iGlobalTime);

    if (move_process < 0.9999) {
      vec2 move_uv = uv;
      move_uv.y += mix(1.0, 0.0, move_process);
      vec4 mask = INPUT3(move_uv) * step(move_uv.y, 1.0);

      fragOutCol = INPUT1(uv);
      fragOutCol = mix(fragOutCol, mask, mask.a);
    } else {
      float zoom_process = pow(abs(2.0 * iGlobalTime - 0.8), 2.0);
      float shake_process = max(0.0, 1.0 - pow(abs(6.0 * iGlobalTime - 3.0), 2.0));

      float shake = 10.0;
      float PI = 3.14159265;
      uv = shakeUV(uv, iGlobalTime, shake_process);

      vec2 zoom_uv = uv;
      zoom_uv = (zoom_uv - vec2(0.5)) * mix(1.0, 0.2, zoom_process) + vec2(0.5);
      float mask_a = mix(1.0, 0.0, min(1.0, zoom_process));

      vec4 mask = INPUT4(zoom_uv) * mask_a;
      fragOutCol = INPUT4(uv) * step(0.0001, shake_process) + INPUT2(uv) * step(shake_process, 0.0001);
      fragOutCol += mask;
    }
  }

  return fragOutCol;
}

