#ifdef GL_ES
precision mediump float;
#endif

bool inBounds (vec2 p) {
  vec2 boundMin = vec2(0.0, 0.0);
  vec2 boundMax = vec2(1.0, 1.0);
  return all(lessThan(boundMin, p)) && all(lessThan(p, boundMax));
}

vec2 project (vec2 p) {
  return p * vec2(1.0, -1.2) + vec2(0.0, -0.02);
}

vec4 bgColor (vec2 p, vec2 pto) {
  vec4 black = vec4(0.0, 0.0, 0.0, 0.0);
  float reflection = 0.4;
  vec4 c = black;
  pto = project(pto);
  if (inBounds(pto)) {
    c += mix(black, INPUT2(pto), reflection * mix(1.0, 0.0, pto.y));
  }
  return c;
}

vec4 FUNCNAME(vec2 tc) {
  float perspective = 0.4;
  float depth = 3.0;
  vec4 fragOutColor;
  vec2 p = tc;
  float progress = PREFIX(global_time)/PREFIX(total_time);

  vec2 pfr = vec2(-1.), pto = vec2(-1.);

  float middleSlit = 2.0 * abs(p.x-0.5) - progress + 0.0001;
  if (middleSlit > 0.0) {
    pfr = p + (p.x > 0.5 ? -1.0 : 1.0) * vec2(0.5*progress, 0.0);
    float d = 1.0/(1.0+perspective*progress*(1.0-middleSlit));
    pfr.y -= d/2.;
    pfr.y *= d;
    pfr.y += d/2.;
  }

  float size = mix(1.0, depth, 1.-progress);
  pto = (p + vec2(-0.5, -0.5)) * vec2(size, size) + vec2(0.5, 0.5);

  if (inBounds(pfr)) {
    fragOutColor = INPUT1(pfr);
  }
  else if (inBounds(pto)) {
    fragOutColor = INPUT2(pto);
  }
  else {
    fragOutColor = bgColor(p, pto);
  }
  return fragOutColor;
}

#ifdef GL_ES
precision mediump float;
#endif

vec4 FUNCNAME(vec2 tc) 
{
    float progress = PREFIX(global_time) / PREFIX(total_time);
	vec2 uv = tc;
	float iPro = (3.0 * progress * progress - 2.0 * progress * progress * progress); 	//(3 * t * t  - 2 * t * t * t)

	vec4 colorfrom = INPUT1(uv);
	vec4 colorto = INPUT2(uv);
    vec2 res = iResolutionOrig;
    int height = int(res.y);
    float y = tc.y * res.y;

	int block = int(32.0 * res.y / 360.0);
	int n_blocks = (height + (block - 1)) / block;
	float matt = 0.0;
    float speed = 2.0;
	int process = int(speed * iPro * res.y);
	int offset = 0;
	for(int i = 0; i < n_blocks; i++)
	{
		if(process > i * block)
		{
			offset = i * block - (process - i * block);
			matt += step(float(offset), y) * step(y, float(offset + block));
		}
        else
		{
			matt += step( float(i * block) , y);
		}
	}
	vec4 outputCol = mix( colorto, colorfrom, clamp(matt, 0.0 , 1.0));

	return outputCol;
}

