vec4 FUNCNAME(vec2 tc) {
    float progress     = (u_global_time/u_total_time);
    float thresholdVal = 1.231373 * progress;
    float alphaMux     = thresholdVal - 0.12549;
    float alphaAdd     = thresholdVal + 0.12549;	
	vec4 inputCol1     = INPUT1(tc);
	vec4 inputCol2     = INPUT2(tc);
	vec4 alphaCol      = INPUT3(vec2( 1.0 - tc.x, 1.0 - tc.y));
	float alpha        = 0.2989 * alphaCol.b + 0.5870 * alphaCol.g + 0.1140* alphaCol.r;

	vec4 outputCol  = inputCol1;
    if (alpha < alphaMux) {
        outputCol   = inputCol2;
    } 
	else if (alpha >= alphaMux && alpha < alphaAdd) {
        float strength = clamp((alpha - alphaMux) * 4.0, 0.0, 1.0);
		outputCol   = mix(inputCol2, inputCol1, strength);
    }
	return outputCol;
}

