#define PI 3.141592653589

vec4 FUNCNAME(vec2 tc)
{
	float progress = PREFIX(global_time) / PREFIX(total_time);
    float width = iResolution.x;
    float height = iResolution.y;
    float SIN45 = sin(45.0 * PI / 180.0);
    float MaxDistance = 400.0;
    float SIN45V = SIN45 * 256.0;
    vec2 uv = vec2(tc.x, 1.0 - tc.y);
    float MaxSplitLineX = width + height + MaxDistance / SIN45;
    vec2 coord = uv.xy * iResolution.xy;

    float splitLineX = progress * MaxSplitLineX ;
    float xOnLine = splitLineX - coord.y;
    if(xOnLine <= 0.0)
        return INPUT1(tc);
    float xOnLine2 = MaxDistance / SIN45;
    float begin = 0.0;
    float end = 0.0;    
    vec4 color2 = vec4(0.0);
    if (xOnLine < xOnLine2) 
    {
        begin = 0.0;
        end = min(width, xOnLine - 1.0) / width;
        color2 = INPUT1(tc);
    } 
    else 
    {
        begin = min(width, max(0.0, xOnLine - xOnLine2)) / width;
        end = 1.0;
        color2 = INPUT2(tc);
    }
    float matt = step(begin, tc.x) * step(tc.x , end);
    float distance = (xOnLine - coord.x) * SIN45V;
    float alpha2 = clamp(max(0.0, distance / MaxDistance) / 255.0 , 0.0, 1.0);

    vec4 retColor =  mix(INPUT1(tc), INPUT2(tc), alpha2);
    return mix(color2, retColor, matt);
}

vec4 FUNCNAME(vec2 tc)
{
    int blendMode = PREFIX(blendMode);
    int use8Bits = PREFIX(use8Bits);

    vec4 mask1 = INPUT1(tc);  // First mask input
    vec4 mask2 = INPUT2(tc);  // Second mask input
    vec4 result = vec4(0.0);

    if (use8Bits == 1) {
        // For 8-bit grayscale masks, work with single channel
        float val1 = mask1.r; // Use red channel for grayscale
        float val2 = mask2.r;
        float blended = 0.0;

        if (blendMode == 0) {
            // BLEND_NONE
            blended = val1;
        } else if (blendMode == 1) {
            // BLEND_UNION: alpha over blend
            blended = val1 + val2 * (1.0 - val1);
        } else if (blendMode == 2) {
            // BLEND_SUBTRACT: saturated subtraction
            blended = max(0.0, val1 - val2);
        } else if (blendMode == 3) {
            // BLEND_INTERSECTION: minimum
            blended = min(val1, val2);
        } else {
            blended = val1;
        }

        result = vec4(blended, blended, blended, blended);
    } else {
        // For BGRA masks, work with all channels
        if (blendMode == 0) {
            // BLEND_NONE
            result = mask1;
        } else if (blendMode == 1) {
            // BLEND_UNION: alpha over blend for each channel
            result.r = mask1.r + mask2.r * (1.0 - mask1.r);
            result.g = mask1.g + mask2.g * (1.0 - mask1.g);
            result.b = mask1.b + mask2.b * (1.0 - mask1.b);
            result.a = mask1.a + mask2.a * (1.0 - mask1.a);
        } else if (blendMode == 2) {
            // BLEND_SUBTRACT: saturated subtraction for each channel
            result.r = max(0.0, mask1.r - mask2.r);
            result.g = max(0.0, mask1.g - mask2.g);
            result.b = max(0.0, mask1.b - mask2.b);
            result.a = max(0.0, mask1.a - mask2.a);
        } else if (blendMode == 3) {
            // BLEND_INTERSECTION: minimum for each channel
            result.r = min(mask1.r, mask2.r);
            result.g = min(mask1.g, mask2.g);
            result.b = min(mask1.b, mask2.b);
            result.a = min(mask1.a, mask2.a);
        } else {
            result = mask1;
        }
    }

    return result;
}

