#ifdef GL_ES
precision highp float;
#endif
#define SAMPLES 4.0

vec4 FUNCNAME(vec2 tc) {
  vec4 fragOutColor = vec4(0.0);
  vec2 p = tc;
  vec2 textCoord = tc * iResolution.xy;
  float progress = PREFIX(global_time)/PREFIX(total_time);

  for(float i = 0.0; i < SAMPLES; i++) {
    for(float j = 0.0; j < SAMPLES; j++) {
      vec2 offset = vec2(i, j) / (SAMPLES);
      p = (textCoord + offset)/iResolution.xy;
      float circPos = atan(p.y - 0.5, p.x - 0.5) + (2.0-progress*2.0);
      float modPos = mod(circPos, 3.14 / 2.);
      float signed = sign((2.0-progress*2.0) - modPos);
      float smoothed = smoothstep(-0.01, 1.01, signed);

      if (smoothed < 0.5){
        fragOutColor += INPUT2(p);
      } else {
        fragOutColor += INPUT1(p);
      }
    }
  }

  return fragOutColor / (SAMPLES * SAMPLES);
}

