vec4 FUNCNAME(vec2 tc) {

	float progress = PREFIX(global_time)/PREFIX(total_time);
	vec2 resolution = iResolution; 
	const float eps = 1e-5;
	float dLength = PREFIX(total_len);
	float dCurPos = PREFIX(current_pos);

	float alpha1 = (dLength - dCurPos) / max(dLength, eps);
	float alpha2 = dCurPos / max(dLength, eps);
	if(alpha1 == 1.0)
	{		
		return INPUT1(tc);
