bool inBounds (vec2 p,vec2 resolution) 
{
  float xMax = resolution.x / resolution.y / 2.0;
  vec2 temp1 = vec2(-xMax, -0.5);
  vec2 temp2 = vec2( xMax,  0.5);
  return temp1.x < p.x && temp1.y < p.y && p.x < temp2.x && p.y < temp2.y;
}

vec4 FUNCNAME(vec2 tc) {
	float progress = PREFIX(global_time)/PREFIX(total_time);	
	float curPos = progress * 2.0;	
	vec2 uv = tc;

	vec4 retColor = vec4(0.0);
	vec2 r = vec2(tc.xy * iResolution.xy - 0.5 * iResolution.xy) / iResolution.y;
	float xMax = iResolution.x / iResolution.y;
	vec2 q;
	float angle;
	if(progress < 0.5)
	{
	  angle = progress * 10.0 * 3.1415926; 

	  q.x =   cos(angle)* r.x + sin(angle)* r.y;
	  q.y = - sin(angle)* r.x + cos(angle)* r.y;
	  q = q * vec2(1.0 + progress * 50.0);

	  if(inBounds(q, iResolution))
	  {
		vec2 rp = q + vec2(xMax / 2.0, 0.5);
		retColor = INPUT1(vec2(rp.x / xMax, rp.y));
	  }

	}
	else
	{
	  angle = (1.0 - progress) * 10.0 * 3.1415926; 

	  q.x =   cos(angle) * r.x + sin(angle) * r.y;
	  q.y = - sin(angle) * r.x + cos(angle) * r.y;

	  q = q * vec2(50.0 - progress *49.0);

	  if(inBounds(q , iResolution))
	  {
		vec2 rp = q + vec2(xMax / 2.0, 0.5);
		retColor = INPUT2(vec2(rp.x / xMax, rp.y));
	  }
	}
	return retColor;
}

