customize_in vec4 newNormals;
customize_in vec2 vUV;

vec4 pixelShader(float iTime, vec2 uv, vec4 wnor )
{		
  vec3 darkCol = vec3(31.0)/255.0 * INPUT1(uv).a;
	vec3 brightCol = vec3(144.0)/255.0 * INPUT2(uv).a;

	vec4 col = vec4(mix(darkCol, INPUT1( uv ).xyz, iTime), INPUT1( uv ).a) * abs(wnor.x) + 
		        vec4(mix(brightCol, INPUT2( uv ).xyz, 1.0-iTime), INPUT2( uv ).a) * abs(wnor.z);

  return col;
}

float inBounds (vec2 p) {
  return step(0.0, p.x)*step(0.0, p.y)*step(p.x, 1.0)*step(p.y, 1.0);
}

vec4 FUNCNAME(vec2 tc){
  vec2 tUV = tc;
  vec2 uv = vUV;
  float bounceTimeCurve = PREFIX(uProcessTime);
  float colorGradTimeCurve = clamp(pow((bounceTimeCurve), 7.0), 0.0, 1.0);
  vec4 color = pixelShader(colorGradTimeCurve,uv, newNormals);

  float alp = inBounds(uv);
  float a = 1.0;
  float eclosionScale = 0.995;

  if(uv.y >= eclosionScale)
	a = 1.0 - smoothstep(eclosionScale, 1.0, uv.y);
  else if(uv.y < 1.0 - eclosionScale)
	a = smoothstep(0.0, 1.0 - eclosionScale, uv.y);

  float talp = mix(0.0, alp, a);
  color = mix(vec4(0.0), color, a);
  return vec4(vec3(0.0), 1.0 - talp) + color;	
}

