float cross2d(vec2 a, vec2 b) {
  return a.x * b.y - a.y * b.x;
}

float inBounds(vec2 p) {
  return step(0.0, p.x) * step(0.0, p.y) * step(p.x, 1.0) * step(p.y, 1.0);
}

vec4 pixelShader(float iTime, vec2 uv, vec3 wnor) {
  vec3 darkCol = vec3(37.0) / 255.0 * INPUT1(uv).a;
  vec3 brightCol = vec3(144.0) / 255.0 * INPUT2(uv).a;

  vec4 col = vec4(mix(darkCol, INPUT1(uv).xyz, 1.0 - iTime), INPUT1(uv).a) * abs(wnor.z) +
             vec4(mix(brightCol, INPUT2(uv).xyz, iTime), INPUT2(uv).a) * abs(wnor.x);

  return col;
}

float calBezierTime(vec2 p1, vec2 p2, float t) {
  vec2 p0 = vec2(0.0, 0.0);
  vec2 p3 = vec2(1., 1.);

  vec2 q0 = mix(p0, p1, t);
  vec2 q1 = mix(p1, p2, t);
  vec2 q2 = mix(p2, p3, t);

  vec2 r0 = mix(q0, q1, t);
  vec2 r1 = mix(q1, q2, t);

  return (mix(r0, r1, t)).y;
}

bool greaterThanFunc(vec3 lv, vec3 rv) {
  return (lv.x > rv.x) && (lv.y > rv.y) && (lv.z > rv.z);
}

vec4 FUNCNAME(vec2 tc) 
{
  float iGlobalTime = PREFIX(global_time);
  float totalTime = PREFIX(total_time);
  float process = min(iGlobalTime / totalTime, 1.0);
  float iPro = (3.0 * process * process - 2.0 * process * process * process);
  vec2 p1 = vec2(0.0, .65);
  vec2 p2 = vec2(1.0, .64);

  float bezierTime = calBezierTime(p1, p2, iPro);
  float tPro = clamp(pow((bezierTime + 0.1), 6.0), 0.0, 1.0);

  float rotY = radians(-90.0) * (bezierTime);
  float rotY2 = radians(90.0) * (bezierTime);

  float depth = -4.9;
  mat4 mdv = setTranslation(0.0, 0.0, depth) * setRotation(0.0, rotY, 0.0);

  mat4 mdv2 = setTranslation(0.0, 0.0, depth) * setRotation(0.0, rotY2, 0.0);

  createCube();

  vec2 px = 2.0 * tc - 1.0;
  vec4 color = vec4(0.0);
  vec2 uv = vec2(0.0);
  float alp = 0.0;

  // clear zbuffer
  float mindist = -1000000.0;

  // render 8 triangles, two boxs
  for (int i = 0; i < 8; i++) {
    // transform to eye space
    mat4 tMdv = mat4(0.0);
    if (i < 4)
      tMdv = mdv;
    else
      tMdv = mdv2;

    vec3 ep0 = (tMdv * vec4(triangles[i].a, 1.0)).xyz;
    vec3 ep1 = (tMdv * vec4(triangles[i].b, 1.0)).xyz;
    vec3 ep2 = (tMdv * vec4(triangles[i].c, 1.0)).xyz;
    vec3 nor = (tMdv * vec4(triangles[i].n, 0.0)).xyz;

    // transform to clip space
    float w0 = 1.0 / ep0.z;
    float w1 = 1.0 / ep1.z;
    float w2 = 1.0 / ep2.z;

    float cpRadio = 2.0 + abs(depth) - 3.0 + 1.0 - bezierTime;
    vec2 cp0 = cpRadio * ep0.xy * -w0;
    vec2 cp1 = cpRadio * ep1.xy * -w1;
    vec2 cp2 = cpRadio * ep2.xy * -w2;

    // fetch vertex attributes, and divide by z
    vec2 u0 = triangles[i].aUV * w0;
    vec2 u1 = triangles[i].bUV * w1;
    vec2 u2 = triangles[i].cUV * w2;

    //-----------------------------------
    // rasterize
    //-----------------------------------

    // calculate areas for subtriangles
    vec3 di = vec3(cross2d(cp1 - cp0, px - cp0), cross2d(cp2 - cp1, px - cp1), cross2d(cp0 - cp2, px - cp2));

    // if all positive, point is inside triangle
    if (greaterThanFunc(di, vec3(0.0))) {
      // calc barycentric coordinates
      vec3 ba = di.yzx / (di.x + di.y + di.z);

      // barycentric interpolation of attributes and 1/z
      float iz = ba.x * w0 + ba.y * w1 + ba.z * w2;
      uv = ba.x * u0 + ba.y * u1 + ba.z * u2;

      // recover interpolated attributes
      float z = 1.0 / iz;
      uv *= z;
      alp = inBounds(uv);

      // depth (-1/z) buffer test
      if (z > mindist) {
        mindist = z;

        color = pixelShader(tPro, uv, triangles[i].n);
      }
    }
  }

  float a = 1.0;
  float eclosionScale = 0.995;

  if (uv.y >= eclosionScale)
    a = 1.0 - smoothstep(eclosionScale, 1.0, uv.y);
  else if (uv.y < 1.0 - eclosionScale)
    a = smoothstep(0.0, 1.0 - eclosionScale, uv.y);

  float talp = mix(0.0, alp, a);
  color = mix(vec4(0.0), color, a);
  return vec4(vec3(0.0), 1.0 - talp) + color;

  return color;
}

