#define RGB_OFFSET 0.03  // RGB偏移量

bool checkUvRange(float x) {
    float absX = abs(x);
    float floorX = floor(absX);
    bool modX = mod(floorX, 2.0) == 0.0;
    return x > 0.0 ? !modX : modX;
}

// RGB偏移函数 - 对两个输入分别应用偏移后混合
vec4 applyRGBOffset(vec2 uv, float offset, float progress) {
    // 对 INPUT1 (前景) 应用 RGB 偏移
    vec4 fg_r = INPUT1(vec2(uv.x + offset, uv.y));
    vec4 fg_g = INPUT1(uv);
    vec4 fg_b = INPUT1(vec2(uv.x - offset, uv.y));
    vec4 fg_color = vec4(fg_r.r, fg_g.g, fg_b.b, fg_g.a);

    // 对 INPUT2 (背景) 应用 RGB 偏移
    vec4 bg_r = INPUT2(vec2(uv.x + offset, uv.y));
    vec4 bg_g = INPUT2(uv);
    vec4 bg_b = INPUT2(vec2(uv.x - offset, uv.y));
    vec4 bg_color = vec4(bg_r.r, bg_g.g, bg_b.b, bg_g.a);

    // 根据动画进度混合两个图片
    return mix(fg_color, bg_color, progress);
}

// 中间区域采样函数
vec4 sampleMiddleArea(vec2 uv, float smoothX, float smoothY, float progress) {
  vec4 retColor = vec4(0.0, 0.0, 0.0, 0.0);
  float org_uv_x = uv.x;

  if (uv.y >= 0.0 && uv.y <= 1.0) {
    // 应用镜像循环
    uv.x = checkUvRange(uv.x) ? 1.0 - uv.x : uv.x;

    // RGB分离效果只在滚动阶段（25%-75%）启用，带平滑淡入淡出
    float a = 0.0;
    if(progress >= 0.25 && progress <= 0.75){
      float t = (progress - 0.25) / 0.5;  // 归一化到 0-1
      // 在滚动阶段的开始和结束添加淡入淡出
      if(t < 0.1){
        // 前10%淡入
        a = smoothstep(0.0, 0.1, t);
      }else if(t > 0.9){
        // 后10%淡出
        a = smoothstep(1.0, 0.9, t);
      }else{
        // 中间80%保持全强度
        a = 1.0;
      }
    }
    // 应用RGB偏移效果
    float rgbOffset = RGB_OFFSET * a;
    retColor = applyRGBOffset(uv, rgbOffset, progress);

  }

  float eyery_y = mod(uv.y, 1.0);
  retColor.rgb *= pow((smoothstep(0.0, smoothY, eyery_y) - smoothstep(1.0 - smoothY, 1.0, eyery_y)), 2.0);

  float eyery_x = fract(uv.x);
  if(org_uv_x < 1.0 && org_uv_x > 0.0){
    retColor.rgb *= pow((smoothstep(0.0, smoothX, eyery_x) - smoothstep(1.0 - smoothX, 1.0, eyery_x)), 4.0);
  }
  else{
    eyery_x = 1.0 - eyery_x;
    retColor.rgb *=  pow((smoothstep(0.0, smoothX, eyery_x) - smoothstep(1.0 - smoothX, 1.0, eyery_x)), 4.0);

  }
  return retColor;
}


// 鱼眼畸变补偿函数
vec2 optical_compensate(vec2 tc, float u_fov) {
  const int num = 12;
  vec2 uv = tc;

  for (int i = 1; i < num; ++i)
  {
      uv -= 0.5;
      float d = length(uv * 2.0);
      if(u_fov >= 0.0)
      {
          uv.y = uv.y * (1.0 + u_fov * (0.25 * (2.0 - d*d)) / (1.0 + exp(-(u_fov - 5.0))));
      }
      else{
          float temp_u_fov = -u_fov;
          uv = uv * (2.0 - (1.0 + temp_u_fov * (0.25 * (2.0 - d*d)) / (1.0 + exp(-(temp_u_fov - 5.0)))) );
      }
      uv += 0.5;
  }
  return uv; 
}

float easeOutExpo(float x){
  return x == 1.0 ? 1.0 : 1.0 - pow(2.0, -10.0 * x);
}

