float Hash( vec2 p)
{
     vec3 p2 = vec3(p.xy,1.0);
    return fract(sin(dot(p2,vec3(37.1,61.7, 12.4)))*3758.5453123);
}

float noiseGlow(in vec2 p)
{
    vec2 i = floor(p) + vec2(1.0);
     vec2 f = fract(p);
     f *= f * (3.0-2.0*f);

    return mix(mix(Hash(i + vec2(0.,0.)), Hash(i + vec2(1.,0.)),f.x),
               mix(Hash(i + vec2(0.,1.)), Hash(i + vec2(1.,1.)),f.x),
               f.y);
}

float fbmGlow(vec2 p)
{
     float v = 0.0;
     v += noiseGlow(p*1.0)*.5;
     v += noiseGlow(p*2.)*.25;
     v += noiseGlow(p*4.)*.125;
     return v;
}

vec3 cloudsGlow( vec2 uv, vec2 dir,float time)
{
    dir *= time;
    vec3 finalColor = fbmGlow( (uv * 1.5) + dir ) * vec3( 1.0 );
    return finalColor;
}

vec2 random(vec2 st){
    st = vec2( dot(st,vec2(127.1,311.7)),
              dot(st,vec2(269.5,183.3)) );
    return -1.0 + 2.0*fract(sin(st)*43758.5453123);
}

float noise2D(vec2 v){
    vec2 scaledV=v*1.;
    vec2 fl=floor(scaledV);
    vec2 fr=fract(scaledV);
    vec2 ratio=fr*fr*(3.-2.*fr);
    vec2 p=random(fl);
    vec2 pr=random(fl+vec2(1.,0.));
    vec2 pd=random(fl+vec2(0.,1.));
    vec2 pdr=random(fl+vec2(1.,1.));

    float nUp=dot(p,fr)*(1.-ratio.x)+dot(pr,vec2(fr.x-1.,fr.y))*ratio.x;
   // float nUp=mix(dot(p,fr),dot(pr,vec2(fr.x-1.,fr.y)),ratio.x);
   // float nDown=mix(dot(pd,vec2(fr.x,fr.y-1.)),dot(pdr,vec2(fr.x-1.,fr.y-1.)),ratio.x);
    float nDown=dot(pd,vec2(fr.x,fr.y-1.))*(1.-ratio.x)+dot(pdr,vec2(fr.x-1.,fr.y-1.))*ratio.x;
    return mix(nUp,nDown,ratio.y);
}
