  process_range[2] = vec2(0.33, 0.66);
  depth_range[2] = vec2(0.2, 0.4);

  process_range[3] = vec2(0.55, 0.88);
  depth_range[3] = vec2(0.1, 0.2);

  process_range[4] = vec2(0.77, 1.0);
  depth_range[4] = vec2(0.0, 0.1);

  for (int i = 0; i < steps; ++i) {
    if (step(process_range[i].x, process) * step(process, process_range[i].y) >
        0.) {
      float depth = INPUT3(tc).r;
      if (step(depth_range[i].x, depth) * step(depth, depth_range[i].y) > 0.) {
        float intensity = pow(sin(((process - process_range[i].x) /
                                   (process_range[i].y - process_range[i].x)) *
                                  PI),
                              3.);
        float strength = float(PREFIX(Strength)) / 50.0;
        intensity *= strength;
        col.rgb += intensity * vec3(1.0, 0.0, 0.0);

        float t = PREFIX(global_time);

        vec2 uvDist = tc;
        uvDist.x = uvDist.x + 1024.0 * sin(t / 100000.0);
        uvDist.y = uvDist.y + 1024.0 * sin(t / 100000.0);

        vec4 distortionColor = INPUT4(uvDist);

        vec2 offset = vec2(distortionColor.x, distortionColor.y) * 0.2;

        vec3 mask_col = INPUT2(tc + offset).rgb * intensity;
        col.rgb = mix(col.rgb, mask_col, intensity * 0.2);
        col.rgb +=
            smoothstep(depth_range[i].x + 0.001, depth_range[i].x, depth) *
            vec3(1.0, 0.0, 0.0);
        break;
      }
    }
  }

  return col;
}

vec4 BufferB(vec2 tc, float process) {
  vec4 col = vec4(0.);
  vec4 bg_col = INPUT2(tc);

  const int steps = 5;
  vec2 process_range[steps];
  vec2 smoothstep_range[steps];
  vec2 depth_range[steps];
  process_range[0] = vec2(0.1, 1.0);
  smoothstep_range[0] = vec2(0.0, 0.2);
  depth_range[0] = vec2(0.6, 1.0);

  process_range[1] = vec2(0.25, 1.0);
  smoothstep_range[1] = vec2(0.25, 0.4);
  depth_range[1] = vec2(0.4, 0.6);

  process_range[2] = vec2(0.5, 1.0);
  smoothstep_range[2] = vec2(0.35, 0.6);
  depth_range[2] = vec2(0.2, 0.4);

  process_range[3] = vec2(0.7, 1.0);
  smoothstep_range[3] = vec2(0.65, 0.8);
  depth_range[3] = vec2(0.1, 0.2);

  process_range[4] = vec2(0.9, 1.0);
  smoothstep_range[4] = vec2(0.7, 1.0);
  depth_range[4] = vec2(0.0, 0.1);

  for (int i = 0; i < steps; ++i) {
    if (step(process_range[i].x, process) * step(process, process_range[i].y) >
        0.) {
      float depth = INPUT3(tc).r;
      if (step(depth_range[i].x, depth) * step(depth, depth_range[i].y) > 0.) {
        float intensity = pow(
            smoothstep(smoothstep_range[i].x, smoothstep_range[i].y, process),
            3.);

        float t = PREFIX(global_time);

        vec2 uvDist = tc;
        uvDist.x = uvDist.x + 1024.0 * sin(t / 100000.0);
        uvDist.y = uvDist.y + 1024.0 * sin(t / 100000.0);

        vec4 distortionColor = INPUT4(uvDist);

        vec2 offset = vec2(distortionColor.x, distortionColor.y) * 0.1;
        offset *= 1.0 - smoothstep(smoothstep_range[i].x, min(smoothstep_range[i].y * 2.5, 1.), process);
        col += INPUT2(tc + offset) * intensity;
        break;
      }
    }
  }

  col = min(col, bg_col);
  return col;
}

