vec4 Blend(vec2 tc, float process) {
  vec4 col = INPUT1(tc);
  col.a = max(col.a, INPUT2(tc).a);
  col.rgb *= 1.0 - smoothstep(0.5, 1.0, process);
  vec2 offset = vec2(rand(process)) * 0.01;
  offset *= pow(1.0 - process, 0.5);
  vec4 mask = INPUT4(tc + offset);
  col.rgb = mix(col.rgb, mask.rgb, mask.a);
  col.rgb += INPUT3(tc + offset).rgb;
  col.rgb *= col.a;
  return col;
}

