float easeInBounce(float t) {
    float n1 = 7.5625;
    float d1 = 2.75;
    float x = t;

    if (x < 1.0 / d1) {
        return n1 * x * x;
    } else if (x < 2.0 / d1) {
        return pow(abs(n1 * (x -= 1.5 / d1) * x + 0.75), 0.25);
    } else if (x < 2.5 / d1) {
        return pow(abs(n1 * (x -= 2.25 / d1) * x + 0.9375), 0.25);
    } else {
        return pow(abs(n1 * (x -= 2.625 / d1) * x + 0.984375), 0.25);
    }
}

