vec4 applyComicEffect(vec4 color, vec2 tc, float opacity ) {

    vec3 baseColor = color.rgb;

    vec3 quantizedColor;
    quantizedColor.r = floor(baseColor.r * 4.0 + 0.5) / 4.0;
    quantizedColor.g = floor(baseColor.g * 4.0 + 0.5) / 4.0;
    quantizedColor.b = floor(baseColor.b * 4.0 + 0.5) / 4.0;

    float luminance = dot(baseColor, vec3(0.299, 0.587, 0.114));
    vec3 enhancedColor = mix(vec3(luminance), baseColor, 1.0);
    // enhancedColor = pow(enhancedColor, vec3(0.7));

    vec2 texelSize = 1.0 / iResolution.xy;
    vec4 center = INPUT1(tc);
    vec4 up = INPUT1(tc + vec2(0.0, texelSize.y));
    vec4 down = INPUT1(tc - vec2(0.0, texelSize.y));
    vec4 left = INPUT1(tc - vec2(texelSize.x, 0.0));
    vec4 right = INPUT1(tc + vec2(texelSize.x, 0.0));

    float edgeH = abs(dot(left.rgb - right.rgb, vec3(0.299, 0.587, 0.114)));
    float edgeV = abs(dot(up.rgb - down.rgb, vec3(0.299, 0.587, 0.114)));
    float edge = max(edgeH, edgeV);

    vec3 finalColor = enhancedColor;
    if(edge > 0.07) {
        finalColor = mix(finalColor, vec3(0.0), opacity*0.35);
    }

    finalColor = clamp(finalColor, 0.0, 1.0);

    return vec4(finalColor, color.a);
}
