#define PI 3.1415926
vec2 EdgeFishEye_Smooth(vec2 uv,
                        float radius,
                        float strength,
                        float range,
						float texscale,
						float dist, 
                        vec2 center)
{
    vec2 uv0 = uv;

    if (dist <= radius && radius > 0.0)
    {
        vec2 dir = (uv - center) / dist;
        float scale = 1.0 - strength + strength * clamp(dist / radius,0.0, 1.0);
        float newDist = dist * scale;
        uv = center + newDist * dir;
    }

	float t = smoothstep(0.0, radius, dist);
    float w = pow(t, range);
    return mix(uv0, uv, w);
}

vec2 Transform(vec2 uv,vec2 center,float range,float strength,float k)
{
    float dist = distance(uv , center);
    vec2 dir = normalize(uv - center);
    float scale = 1. - strength + strength * smoothstep(0., 1., pow(dist/range,k));
    float newDist = dist * scale;
    if (range == 0.0 || strength == 0.0)
    {
        return uv;
    }
    vec2 result = center + newDist * dir;
    return result;
}



float GetParabolaMap(float t)	
{
	return (3.0 * t * t - 2.0 * t * t * t);
}

float GetEasyinoutMap(float t)	
{
	return t - sin(2.0 * PI * t) / (2.0 * PI);
}

