float Hash(vec2 p)
{
  vec3 p2 = vec3(p.xy,1.0);
  return fract(sin(dot(p2,vec3(37.1,61.7, 12.4)))*3758.5453123);
}

float noiseGlow(vec2 p)
{
  vec2 i = floor(p) + vec2(1.0);
  vec2 f = fract(p);
  f *= f * (3.0-2.0*f);

  return mix(mix(Hash(i + vec2(0.,0.)), Hash(i + vec2(1.,0.)),f.x),
             mix(Hash(i + vec2(0.,1.)), Hash(i + vec2(1.,1.)),f.x),
             f.y);
}

float fbmGlow(vec2 p)
{
   float v = 0.0;
   v += noiseGlow(p*1.)*.5;
   v += noiseGlow(p*2.)*.25;
   v += noiseGlow(p*4.)*.125;
   return v;
}

vec4 cloudsGlow(vec2 uv, vec2 dir, float time)
{
  dir *= time;
  vec4 finalColor = fbmGlow((uv * 1.5) + dir) * vec4(1.0);
  return finalColor;
}

vec2 random(vec2 st){
  st = vec2( dot(st,vec2(127.1,311.7)),
            dot(st,vec2(269.5,183.3)) );
  return -1.0 + 2.0*fract(sin(st)*43758.5453123);
}

float noise2D(vec2 v){
  vec2 scaledV=v*1.;
  vec2 fl=floor(scaledV);
  vec2 fr=fract(scaledV);
  vec2 ratio=fr*fr*(3.-2.*fr);
  vec2 p=random(fl);
  vec2 pr=random(fl+vec2(1.,0.));
  vec2 pd=random(fl+vec2(0.,1.));
  vec2 pdr=random(fl+vec2(1.,1.));

  float nUp=dot(p,fr)*(1.-ratio.x)+dot(pr,vec2(fr.x-1.,fr.y))*ratio.x;
  float nDown=dot(pd,vec2(fr.x,fr.y-1.))*(1.-ratio.x)+dot(pdr,vec2(fr.x-1.,fr.y-1.))*ratio.x;
  return mix(nUp,nDown,ratio.y);
}

float fbm(vec2 st){
 float height=0.8;
 float frequency=2.;
 float offset=1.3;
 float add=0.;
 for(int i=0;i<8;i++){
     add+=height*noise2D(frequency*st+offset);
     offset*=1.1;
     height*=0.9;
     frequency*=1.2;
 }
 return add; 
}

float GenMask(vec2 uv, vec2 p1, vec2 p2, float blur) {
  float intensity = 0.01 * 1080.0 / min(iResolution.x, iResolution.y);

  vec2 dir = normalize(p2 - p1);

  vec2 uvToP1 = uv - p1;
  float t = dot(uvToP1, dir);

  vec2 closestPoint = p1 + t * dir;

  float noiseValue = noise2D(closestPoint * 10.0);
  vec2 offset = vec2(-dir.y, dir.x) * noiseValue * intensity;

  closestPoint += offset;

  vec2 v1 = uv - closestPoint;
  vec2 v2 = p2 - p1;
  float crossVal = v1.x * v2.y - v1.y * v2.x;

  return smoothstep(0.0, blur, crossVal);
}

float plot(vec2 st, vec2 p1, vec2 p2) {
  float intensity = 0.01 * 1080.0 / min(iResolution.x, iResolution.y);

  vec2 dir = normalize(p2 - p1);

  vec2 stToP1 = st - p1;
  float t = dot(stToP1, dir);

  t = clamp(t, 0.0, length(p2 - p1));

  vec2 closestPoint = p1 + t * dir;

  float noiseValue = noise2D(closestPoint * 10.0);
  vec2 offset = vec2(-dir.y, dir.x) * noiseValue * intensity;

  closestPoint += offset;

  float distance = length(st - closestPoint);

  // float lineWidth = 0.0015 * 1080.0 / min(iResolution.x, iResolution.y);
  float lineWidth = 0.0015 * 1080.0 / 720.0;
  return 1.0 - smoothstep(0.0, lineWidth, distance);
}


vec2 rotateUV(vec2 videoImageCoord, vec2 centerImageCoord, float radianAngle)
{
    mat2 rotateMat = mat2(cos(radianAngle),sin(radianAngle),
                        -sin(radianAngle),cos(radianAngle));
    vec2 deltaOffset = rotateMat * (videoImageCoord - centerImageCoord);
    videoImageCoord = deltaOffset + centerImageCoord;
    return videoImageCoord;
