vec4 FlashLamp(vec2 tc, float progress) {
    vec2 uv = tc;
    float ins = 0.0;

    ins = abs(sin(2.0*PI*progress));
    ins *= 0.8 + 0.2*sin(5.0*PI*progress);

    float light = ins*0.2 + 1.0;
    vec4 fragColor = INPUT1(uv);
    fragColor.rgb *= light;
    return fragColor;
}

