vec4 compressPixel(vec4 inputColor, float thres){
  vec3 tempColor = inputColor.rgb;
  tempColor = mix(vec3(0.0), (tempColor - thres) / (1.0 - thres), step(thres, tempColor));
  float brightness = (tempColor.r + tempColor.g + tempColor.b) / 
                     max(inputColor.r + inputColor.g + inputColor.b, 0.0001);
  return vec4(inputColor.rgb*brightness, inputColor.a);
}

