  newX = abs(newX);
  if(newX > resolution.x){
    newX = resolution.x - mod(newX,resolution.x);
  }
  newY = abs(newY);
  if(newY > resolution.y){
    newY = resolution.y - mod(newY,resolution.y);	   
  }
  return vec2(newX, newY)/resolution;
}

