float hexagon(vec2 uv){
	float skew = 1.73;
    vec2 cen = iResolution.xy * 0.5;
	uv = (uv * iResolution - cen) / min(iResolution.x,iResolution.y);
	float size = .4;

    uv = abs(uv);
    float odd = step(max(dot(uv,normalize(vec2(1., skew))), uv.x), size);

    return -sign(odd - 0.5);
}

