float bounceAnimation(float time, float amplitude, float frequency, float damping) {
    float normalizedTime = clamp(time, 0.0, 1.0);
    float t = normalizedTime * PI * 2.0 * frequency;
    float dampingFactor = exp(-normalizedTime * damping);
    return (-sin(t) * amplitude * dampingFactor);
}
vec4 radialBlur(vec2 uv, float maxDistance) {
    vec2 center =vec2(0.5);
    vec2 delta = uv - center;  
    float dist = length(delta);  
    float scaleFactor = smoothstep(0.0, 0.0, dist);
    float blur = (scaleFactor)*(maxDistance); 

    vec4 color = vec4(0.0);
    int samples = 30;  
    for (int i = 0; i < samples; i++) {
        vec2 offset = delta * (blur * float(i) / float(samples - 1)); 
        color += INPUT1(uv + offset);  
    }
    color /= float(samples);  
    return color;
}
