  if (frameColor.r > whiteThreshold && frameColor.g > whiteThreshold && frameColor.b > whiteThreshold) {
    frameColor.a = 0.0;
  }

  // 处理黑色替换为背景色
  float blackThreshold = 0.01;
  if (frameColor.r < blackThreshold && frameColor.g < blackThreshold && frameColor.b < blackThreshold) {
    frameColor.rgb = videoColor.rgb;
  }

  // 混合frame和视频
  vec3 finalColor = mix(videoColor.rgb, frameColor.rgb, frameColor.a);

  return vec4(finalColor, videoColor.a);
}

