#define PI 3.141592
#define RotationCenter vec3(0.0, 0.0, 0.0)

vec2 rotate(vec2 v, vec2 o, float a) {
    float s = sin(a);
    float c = cos(a);
    mat2 m = mat2(c, -s, s, c);
    return m * (v-o) + o;
}

vec3 rotateZ(vec3 v, vec3 o, float a) {
    float s = sin(a);
    float c = cos(a);
    mat2 m = mat2(c, -s, s, c);
    return vec3(m * (v.xy - o.xy) + o.xy, v.z);
}

vec2 TransformPlane(vec2 uv, vec3 center, float XRot, float YRot, float ZRot) {
    if(fract(YRot/PI) <= 0.35 || fract(YRot/PI) >= 0.65 ){
        if(mod(YRot, 2.0*PI) >= 0.5*PI && mod(YRot, 2.0*PI) <= 1.5*PI) {
            uv.x = 0.5 - (uv.x - 0.5);
            YRot = PI - YRot;
        }
        uv = -1.0 + 2.0 * uv;
        // First Rotate around Y axis
        vec2 RayDirection =  vec2(uv.x, 0.0);
        vec2 A1 = vec2(0.0, -1.0);//vec2(0.0, -1.0);
        vec2 B1 = RayDirection - A1;
        vec2 C1 = rotate(vec2(-1.0, 0.0), vec2(center.x, 0.0), YRot);
        vec2 D1 = rotate(vec2(1.0, 0.0), vec2(center.x, 0.0), YRot) - C1;

        // calculate intersection point
        float u = ( (C1.y + 1.0) * D1.x - C1.x * D1.y ) / (D1.x*B1.y-D1.y*B1.x);

        // position on the XY plane after Y-axis rotation
        float sx = u * B1.x * (1.0 + abs(sin(YRot)));
        float sy = u * uv.y;

        // Now Rotate around X axis
        RayDirection = vec2(sy, 0.0);
        vec2 B2 = RayDirection - A1;
        vec2 C2 = rotate(vec2(-1.0, 0.0), vec2(center.y, 0.0), XRot);
        vec2 D2 = rotate(vec2(1.0, 0.0), vec2(center.y, 0.0), XRot) - C2;

        // calculate intersection point
        float v = ( (C2.y + 1.0) * D2.x - C2.x * D2.y ) / (D2.x*B2.y-D2.y*B2.x);

        // the position after x and y rotations
        vec3 pos = vec3(v * sx, v * B2.x, 0.0 );

        // Now rotate the position around Z axis
        vec3 finalPos = rotateZ(pos, center, ZRot);

        // final position on the 3D plane after Z-axis rotation
        return finalPos.xy;
    } else {
        return vec2(-2.0);
    }
}

vec4 DirectionBlur(vec2 itc, float iprocess, float iglobalTime) {
	float angle = 0.0;
    int strength = int(ceil(70.0 * pow(min(cos(PI*((iprocess-0.3)/0.5*2.0-1.0)/2.0), 1.0-abs(((iprocess-0.3)/0.5*2.0-1.0))), 3.5)));

    int radius = 2 * strength + 1;
    float theta = radians(angle);  
    vec2 dir = vec2(cos(theta), sin(theta));

	vec4 retCol = vec4(0.0);
    vec2 onePixel = 1.0 / iResolution.xy; 
    vec4 roi = vec4(0.0, 0.0, 1.0, 1.0);
	float matt = 0.0;

	for (int i = -strength; i <= strength; i++){
		vec2 t = vec2(i) * onePixel;
        vec2 xy = dir * t;
		vec2 uv = itc + xy;

		matt = step(roi.x, uv.x);
		uv.x = mix(roi.x * 2.0 - uv.x,uv.x,matt);

		matt = step(roi.x + roi.z,uv.x);
		uv.x = mix(uv.x,(roi.x + roi.z) * 2.0 - uv.x,matt);

        if(iglobalTime <= 0.5){
            retCol += INPUT1(uv);
        }else{
            retCol += INPUT2(uv);
        }
	}	

	retCol /= float(radius);
	matt = step(roi.x,itc.x)*step(itc.x,roi.x + roi.z + onePixel.x);
	retCol *= matt;

	return retCol;
}

