vec4 ReadLocalTexture1(vec2 tc){
    float aspect = iResolution.x / iResolution.y;
    vec2 uv = vec2(tc.x - 0.5, tc.y - 0.5);
    vec2 texResolution = vec2(1920.0, 1080.0);
    if(aspect < 1.0){
        uv.x *= (texResolution.y / texResolution.x) * aspect;
    }else{
        uv.y *= (texResolution.x / texResolution.y) * (1.0 / aspect);
    }
    uv = vec2(uv.x + 0.5, uv.y + 0.5);
    vec4 res = INPUT3(vec2(uv.x,1.0-  uv.y));
    // res.rgb *= res.a;
    return res;
}
mat2 roataionAngle (float a ){
    float s = sin(a);
    float c = cos(a);
    return mat2(c,-s,s,c);
}
vec2 textureRotationOffset(vec2 uv,float offset,vec2 prop){   

    uv *= prop;
    uv = roataionAngle(offset) * uv;
    uv /= prop;

    return uv;
}

