        float matt = step(0.0, uv.x) * step(uv.x, 0.5) * step(0.0, uv.y) * step(uv.y, 0.5);
        vec4 humanImage = INPUT1(uv) * matt;
        vec4 blackImage = vec4(0.0);
        humanImage = mix(blackImage, humanImage,  uOpacity);
        return humanImage;
    }else if(PREFIX(uStep) == 3){
        float uStretchY = PREFIX(uStretchY);
        vec2 uv = StretchY(tc, uStretchY);
        float matt = step(0.5, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 0.5);
        vec4 humanImage = INPUT1(uv) * matt;
        vec4 blackImage = vec4(0.0);
        humanImage = mix(blackImage, humanImage, uOpacity);
        return humanImage;
