        return INPUT1(tc) + INPUT2(tc) + INPUT3(tc) + INPUT4(tc);
        // return INPUT4(tc);
    }else if(PREFIX(uStep) == 5){
        vec4 black = vec4(0.0);
        vec2 prop = vec2(iResolution.x / iResolution.y, 1.0);
