        vec2 uv = (tc - center) * prop * ellipseScale + center;

        float max_size = max(iResolution.x, iResolution.y);
        float diagonal = sqrt((iResolution.x * 0.5) * (iResolution.x * 0.5) + (iResolution.y * 0.5) * (iResolution.y * 0.5)) / (max_size * 0.5);
        float outer_radius = diagonal * process1 * 1.1;
        outer_radius = max(outer_radius, 0.0);
        float inter_radius = outer_radius - 0.08;
        inter_radius = max(inter_radius, 0.0);
        float outer_dist = circle(uv, center, outer_radius);
        float inter_dist = circle(uv, center, inter_radius);

        float feather = 0.12;
        float matt = (1.0 - smoothstep(0.0, feather, outer_dist)) * smoothstep(0.0, feather, inter_dist);
        if(process1 == 0.0){
            return black;
        }else{
            return vec4(matt); 
        }

    }else if(PREFIX(uStep) == 6){
        vec4 black = vec4(0.0);
        vec2 prop = vec2(iResolution.x / iResolution.y, 1.0);
        if(iResolution.y > iResolution.x){
