        float outer_radius = diagonal * process2 * 1.1;
        outer_radius = max(outer_radius, 0.0);
        float inter_radius = outer_radius - 0.08;
        inter_radius = max(inter_radius, 0.0);
        float outer_dist = circle(uv, center, outer_radius);
        float inter_dist = circle(uv, center, inter_radius);

        float feather = 0.12;
        float matt = (1.0 - smoothstep(0.0, feather, outer_dist)) * smoothstep(0.0, feather, inter_dist);
        if(process2 == 0.0){
            return black;
        }else{
            return vec4(matt);
        }
    }else if(PREFIX(uStep) == 7){
        float Strength = 0.1;
        float black = 0.0;
        vec4 origCol = INPUT1(tc);

        float light_process =1.5;

        vec3 CamPos = vec3(0.0, 0.0, 10.0);
        float mask1 = INPUT2(tc).g;
        float mask2 = INPUT3(tc).g;
        float mask = clamp(mask1 + mask2, 0.0, 1.0);

        mask = mix(black, mask, Opacity);

        vec3 normalDir = mix(vec3(0.0, 0.0, 1.0), normalize(vec3(mask, mask, 1.0 - mask)), Strength);
        normalDir = normalize(normalDir);
        vec3 incidentDir = normalize(-CamPos);
        vec3 refractDir = normalize(refract(incidentDir, -normalDir, 1.0));

        vec3 light_normalDir = mix(vec3(0.0, 0.0, 1.0), normalize(vec3(mask, mask, 1.0 - mask)), 0.5);
        light_normalDir = normalize(light_normalDir);
        vec3 light_refractDir = normalize(refract(incidentDir, -light_normalDir, 1.0));

        vec4 retCol = INPUT1(tc + refractDir.xy / 20.0) * (1.0 + light_refractDir.x * 0.5 * light_process);
        retCol.rgb = mix(origCol.rgb, retCol.rgb, step(0.00001, origCol.a));
        retCol.a = origCol.a;

        return retCol; 
    }
    else if(PREFIX(uStep) == 8){

        vec4 fgColor = INPUT1(tc);
