float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
  float mX1 = p.x;
  float mY1 = p.y;
  float mX2 = p.z;
  float mY2 = p.w;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec2 SetScale(vec2 uv, vec2 c, float scale) {
  uv -= c;
  uv *= max(scale, 0.0001);
  uv += c;
  return uv;
}

float uvProtect(vec2 uv)
{
    vec2 uvp = step(vec2(0.0), uv) * step(uv, vec2(1.0));
    return uvp.x * uvp.y;
}

vec2 Mirror(vec2 x) 
{ 
	return abs(mod(x-1.0, 2.0) -1.0); 
}

vec4 radial_blur(vec2 uv, float strength, float close)
{
	float amount = 50.0;
	float quality = 10.0 * strength * close;
	vec2 center = vec2(0.5, 0.5);
	float x = length(uv - center);
	float weight = 1.0;
    vec4 res = INPUT3(uv) * weight;
    float sumWeight = weight;
    float s = abs(amount) * x * quality + 1.0;
    for (float i = 1.0; i < s; i += 1.0)
    {
        res += INPUT3(uv) * weight;
        sumWeight += weight;
    }
	return vec4(res / sumWeight);
}

vec4 distort1(vec2 uv, float strength)
{
	for (int i = 1; i < 16; ++i)
    {
        uv -= 0.5;
        float d = length(uv * 2.0);
        uv = uv * pow((d*d) + 1.0, -pow(strength, 3.0));
        uv += 0.5;
    }
	return INPUT1(uv);
}


vec4 distort2(vec2 uv, float strength)
{
	for (int i = 1; i < 16; ++i)
    {
        uv -= 0.5;
        float d = length(uv * 2.0);
        uv = uv * pow((d*d) + 1.0, -pow(strength, 3.0));
        uv += 0.5;
    }
	return INPUT2(uv);
}


