float calBezierTime(vec2 p1, vec2 p2, float t) {
  vec2 p0 = vec2(0.0, 0.0);
  vec2 p3 = vec2(1., 1.);

  vec2 q0 = mix(p0, p1, t);
  vec2 q1 = mix(p1, p2, t);
  vec2 q2 = mix(p2, p3, t);

  vec2 r0 = mix(q0, q1, t);
  vec2 r1 = mix(q1, q2, t);

  return (mix(r0, r1, t)).y;
}

float easeOutBounce(float t) {
  const float n1 = 7.5625;
  const float d1 = 2.75;
  const float c = 2.5 / d1;

  float x = t * c;

  if (x < 1.0 / d1) {
    return n1 * x * x;
  } else if (x < 2.0 / d1) {
    float u = x - 1.5 / d1;
    return n1 * u * u + 0.75;
  } else {
    float u = x - 2.25 / d1;
    const float k = 0.7;              // 0<k<=1；越小回弹越小，建议 0.7~0.9
    float aBound = 0.25 / d1;         // 第三段端点处的 |u|
    float base3 = 1.0 - k * n1 * aBound * aBound; // 保障端点仍返回 1.0
    return base3 + k * n1 * u * u;
  }
}

