float customBounce(float iTime) {
  // 线性时间分割和角度映射：超调到105度，回弹到85度，最终稳定在90度
  // 输出值范围：0 -> 1.167 (105度) -> 0.96 (85度) -> 1.0 (90度)

  if (iTime < 0.5) {
    // 第一阶段：从0线性到超调值1.167 (对应105度)
    float t = iTime / 0.5;
    return 1.167 * t;
  } else if (iTime < 0.8) {
    // 第二阶段：从1.167线性回弹到0.96 (对应85度)
    float t = (iTime - 0.5) / 0.3;
    return 1.167 - (1.167 - 0.96) * t;
  } else {
    // 第三阶段：从0.96线性到1.0 (对应90度)
    float t = (iTime - 0.8) / 0.2;
    return 0.96 + (1.0 - 0.96) * t;
  }
}

