vec4 FUNCNAME(vec2 tc) {

  float iGlobalTime = PREFIX(global_time);
  float totalTime = PREFIX(total_time);
  float process = min(iGlobalTime / totalTime, 1.0);
  process = clamp(process, 0.3, 0.7);
  process = (process - 0.3) / 0.4;

  float iPro = (3.0 * process * process - 2.0 * process * process * process);
  float bounceTimeCurve = customBounce(iPro);
  // 避免临界值导致的黑线问题
  if (bounceTimeCurve == 0.0) bounceTimeCurve = 0.001;
  if (bounceTimeCurve == 1.0) bounceTimeCurve = 0.999;

  float colorGradTimeCurve = clamp(pow((bounceTimeCurve + 0.4), 7.0), 0.0, 1.0);

  float rotX = radians(90.0) * bounceTimeCurve;

  float depth = -4.9;
  mat4 mdv = setTranslation(0.0, 0.0, depth) * setRotation(rotX, 0.0, 0.0);

  vec2 px = 2.0 * tc - 1.0;
  vec2 uv = vec2(0.0);
  vec4 color = vec4(0.0);
  float alp = 0.0;

  create2FaceCube();

  // clear zbuffer
  float mindist = -1000000.0;

  // render 4 triangles
  for (int i = 0; i < 4; i++) {
    // transform to eye space
    vec3 ep0 = (mdv * vec4(triangles[i].a, 1.0)).xyz;
    vec3 ep1 = (mdv * vec4(triangles[i].b, 1.0)).xyz;
    vec3 ep2 = (mdv * vec4(triangles[i].c, 1.0)).xyz;
    vec3 nor = (mdv * vec4(triangles[i].n, 0.0)).xyz;

    // transform to clip space
    float w0 = 1.0 / ep0.z;
    float w1 = 1.0 / ep1.z;
    float w2 = 1.0 / ep2.z;

    float cpRadio = 2.0 + abs(depth) - 3.0;
    vec2 cp0 = cpRadio * ep0.xy * -w0;
    vec2 cp1 = cpRadio * ep1.xy * -w1;
    vec2 cp2 = cpRadio * ep2.xy * -w2;

    // fetch vertex attributes, and divide by z
    vec2 u0 = triangles[i].aUV * w0;
    vec2 u1 = triangles[i].bUV * w1;
    vec2 u2 = triangles[i].cUV * w2;

    //-----------------------------------
    // rasterize
    //-----------------------------------

    // calculate areas for subtriangles
    vec3 di = vec3(cross2d(cp1 - cp0, px - cp0), cross2d(cp2 - cp1, px - cp1), cross2d(cp0 - cp2, px - cp2));

    // if all positive, point is inside triangle
    if (greaterThanFunc(di, vec3(0.0))) {
      // calc barycentric coordinates
      vec3 ba = di.yzx / (di.x + di.y + di.z);

      // barycentric interpolation of attributes and 1/z
      float iz = ba.x * w0 + ba.y * w1 + ba.z * w2;
      uv = ba.x * u0 + ba.y * u1 + ba.z * u2;

      // recover interpolated attributes
      float z = 1.0 / iz;
      uv *= z;
      alp = inBounds(uv);

      // depth (-1/z) buffer test
      if (z > mindist) {
        mindist = z;
        // perform lighting/shading
        color = pixelShader(colorGradTimeCurve, uv, triangles[i].n);
      }
    }
  }

  float a = 1.0;

  // 根据动画进度控制羽化强度
  // iPro: 0.0-0.2 逐渐羽化，0.2-0.8 正常羽化，0.8-1.0 逐渐减少羽化到零
  float featherStrength = 1.0;
  if (iPro < 0.3) {
    // 开始阶段：从无羽化逐渐到正常羽化
    featherStrength = smoothstep(0.0, 0.2, iPro);
  } else if (iPro > 0.7) {
    // 结束阶段：从正常羽化逐渐到无羽化
    featherStrength = 1.0 - smoothstep(0.8, 1.0, iPro);
  }
  // 中间阶段 0.2-0.8：featherStrength = 1.0 (正常羽化)
  // 动态调整羽化范围：从0.99逐渐变到1.0（无羽化）
  float eclosionScale = mix(0.99, 1.0, 1.0 - featherStrength);

  // 修复：使用uv.x进行羽化（左右边缘），避免在上下交接处产生缝隙
  if (uv.x >= eclosionScale && featherStrength > 0.0)
    a = 1.0 - smoothstep(eclosionScale, 1.0, uv.x) * featherStrength;
  else if (uv.x < 1.0 - eclosionScale && featherStrength > 0.0)
    a = smoothstep(0.0, 1.0 - eclosionScale, uv.x) * featherStrength + (1.0 - featherStrength);

  float talp = mix(0.0, alp, a);
  color = mix(vec4(0.0), color, a);
  return vec4(color.rgb, color.a * talp);
}

