float calBezierTime(vec2 p1, vec2 p2, float t) {
  vec2 p0 = vec2(0.0, 0.0);
  vec2 p3 = vec2(1., 1.);

  vec2 q0 = mix(p0, p1, t);
  vec2 q1 = mix(p1, p2, t);
  vec2 q2 = mix(p2, p3, t);

  vec2 r0 = mix(q0, q1, t);
  vec2 r1 = mix(q1, q2, t);

  return (mix(r0, r1, t)).y;
}

float easeOutBounce(float iTime) {
  const float n1 = 7.5625;
  const float d1 = 2.75;

  if (iTime < 1. / d1) {
    return n1 * iTime * iTime;
  } else if (iTime < 2. / d1) {
    float tVar = iTime - 1.5 / d1;
    return n1 * tVar * tVar + 0.75;
  } else if (iTime < 2.5 / d1) {
    float tVar = iTime - 2.25 / d1;
    return n1 * tVar * tVar + 0.9375;
  } else {
    float tVar = iTime - 2.625 / d1;
    return n1 * tVar * tVar + 0.984375;
  }
}

bool greaterThanFunc(vec3 lv, vec3 rv) {
  return (lv.x > rv.x) && (lv.y > rv.y) && (lv.z > rv.z);
}

