vec4 whBoundry(vec2 uv, vec4 curColor,float process){
  vec4 BoundryColor = vec4(1.0);
  float boundryWidth = 0.04;
  float animationPro = max(process - 0.95, 0.0) * 20.0;
  animationPro = 1.0 - animationPro;
  boundryWidth *= animationPro;

  vec2 fc = uv * 2.0 - 1.0;

  float horizontalBound = abs(fc.x) - (1.0 - boundryWidth);
  float verticalBound = abs(fc.y) - (1.0 - boundryWidth);

  float boundryAlpha = smoothstep(0.0, 0.01, max(horizontalBound, verticalBound));

  vec4 finalColor = mix(curColor, BoundryColor, boundryAlpha);
  finalColor.a = curColor.a;
  return finalColor;

}

