float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
  vec2 p1 = vec2(p.x, p.y);
  vec2 p2 = vec2(p.z, p.w);
  float mX1 = p1.x;
  float mY1 = p1.y;
  float mX2 = p2.x;
  float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;

  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec2 rotateFunc(vec2 uv, vec2 center, float theta, float scale, vec2 resolution)
{
  vec2 tc = uv - center;
  tc.y *= resolution.y / resolution.x;
  vec2 temp;
  temp.x = dot(vec2(cos(theta), -sin(theta)), tc);
  temp.y = dot(vec2(sin(theta), cos(theta)), tc);
  temp.y /= resolution.y / resolution.x;
  temp *= scale;
  temp += center;
  return temp;
}

float inBound(vec2 tc, float feather){
  float matt = smoothstep(0.0, feather, tc.x) * (1.0 - smoothstep(1.0 - feather, 1.0, tc.x)) * smoothstep(0.0, feather, tc.y) * (1.0 - smoothstep(1.0 - feather, 1.0, tc.y));
  return matt;
}

vec4 FUNCNAME(vec2 tc) {
  float global_time = PREFIX(global_time);
  float total_time = PREFIX(total_time);

  float progress = global_time / total_time;
  float duration = 0.8;
  float start_time = (1.0 - duration) * 0.5;
  float freeze_time = 0.1;
  float move_time = (duration - freeze_time) * 0.5;

  if(progress <= start_time){
    return INPUT1(tc);
  }else if(progress > (1.0 - start_time)){
    return INPUT2(tc);
  }

  float feather = 0.002;
  float iPro = progress;
  if(progress < start_time + move_time){
    iPro = (progress - start_time) / move_time;
  }else if(progress < start_time + move_time + freeze_time){
    iPro = 1.0;
  }else{
    iPro = (progress - start_time - move_time - freeze_time) / move_time;
    iPro = 1.0 - iPro;
    if(iPro < 0.01){
      feather *= iPro;
      feather = max(feather, 0.00001);
    }
  }

  iPro = clamp(iPro, 0.0, 1.0);
  vec4 p = vec4(.52,.03,.52,.97);
  iPro = KeySpline(p, iPro);

  vec2 uv = tc;
  if(iResolution.x >= iResolution.y){
    uv.x += mix(0.0, 0.37, iPro);
    uv.y += mix(0.0, 0.015, iPro);
  }else{
    uv.x += mix(0.0, 0.43, iPro);
    uv.y += mix(0.0, 0.015, iPro);
  }

  float theta = radians(mix(0.0, -10.0, iPro));
  float scale = mix(1.0, 1.65, iPro);
  uv = rotateFunc(uv, vec2(0.5), theta, scale, iResolution);
  float matt = inBound(uv, feather);
  vec4 foreCol = INPUT1(uv) * matt;

  vec2 back_uv = tc;
  if(iResolution.x >= iResolution.y){
    back_uv.x += mix(0.0, -0.31, iPro);
    back_uv.y += mix(0.0, -0.005, iPro);
  }else{
    back_uv.x += mix(0.0, -0.4, iPro);
    back_uv.y += mix(0.0, -0.005, iPro);
  }
  float back_theta = radians(mix(0.0, 10.0, iPro));
  back_uv = rotateFunc(back_uv, vec2(0.5), back_theta, scale, iResolution);
  float back_matt = inBound(back_uv, feather);
  vec4 backCol = INPUT2(back_uv) * back_matt;

  float alpha = matt * smoothstep(0.0, 0.001, foreCol.a);
  if(progress >= start_time + move_time + freeze_time){
    alpha = 1.0 - back_matt * smoothstep(0.0, 0.001, backCol.a);
  }
  vec4 retCol = mix(backCol, foreCol, alpha);
  return retCol;
}

