vec4 InputCoordinate(vec2 uv) {
  float aspect = PREFIX(aspect);
  // w值：0.0=back, 1.0=front, 2.0=bottom, 3.0=top
  if(vIndex < 0.5){
    // back面：显示第一个视频
    return vec4(INPUT1(uv).rgb, 1.0);
  } else if(vIndex < 1.5){
    // front面：显示第一个视频
    return vec4(INPUT1(uv).rgb, 1.0);
  } else if(vIndex < 2.5){
    // bottom面：显示第二个视频
    // bottom面在xz平面上，uv.y对应z轴
    // 由于front面的y轴被缩放为1/aspect，bottom面的z轴也需要等效缩放
    // 将uv.y映射到纹理中心区域[0.5-0.5/aspect, 0.5+0.5/aspect]，然后重新映射到[0,1]
    float halfRange = 0.5 / aspect;
    float texY = 0.5 + (uv.y - 0.5) / aspect;
    texY = clamp(texY, 0.5 - halfRange, 0.5 + halfRange);
    float adjustedY = (texY - (0.5 - halfRange)) / (2.0 * halfRange);
    // 翻转Y避免倒置
    return vec4(INPUT2(vec2(uv.x, 1.0 - adjustedY)).rgb, 1.0);
  } else {
    // top面：显示第二个视频
    // top面在xz平面上，uv.y对应z轴，同样需要调整UV采样
    float halfRange = 0.5 / aspect;
    float texY = 0.5 + (uv.y - 0.5) / aspect;
    texY = clamp(texY, 0.5 - halfRange, 0.5 + halfRange);
    float adjustedY = (texY - (0.5 - halfRange)) / (2.0 * halfRange);
    // top面直接使用，不翻转
    return vec4(INPUT2(vec2(uv.x, adjustedY)).rgb, 1.0);
  }
}

