vec4 InputCoordinate(vec2 uv) {
  // 圆角参数
  float cornerRadius = 0.05; // 圆角半径

  // 四个角的圆心坐标
  vec2 topRight = vec2(0.95, 0.95);    // 右上角
  vec2 topLeft = vec2(0.05, 0.95);     // 左上角
  vec2 bottomRight = vec2(0.95, 0.05); // 右下角
  vec2 bottomLeft = vec2(0.05, 0.05);  // 左下角

  // 计算到四个角的距离
  float distTopRight = length(uv - topRight);
  float distTopLeft = length(uv - topLeft);
  float distBottomRight = length(uv - bottomRight);
  float distBottomLeft = length(uv - bottomLeft);

  // 判断是否在圆角区域内（需要透明的区域）
  bool inCorner = false;

  // 右上角：当 uv.x > 0.95 且 uv.y > 0.95 时，检查距离
  if(uv.x > 0.95 && uv.y > 0.94 && distTopRight > cornerRadius) {
    inCorner = true;
  }
  // 左上角：当 uv.x < 0.05 且 uv.y > 0.95 时，检查距离
  else if(uv.x < 0.05 && uv.y > 0.94 && distTopLeft > cornerRadius) {
    inCorner = true;
  }
  // 右下角：当 uv.x > 0.95 且 uv.y < 0.05 时，检查距离
  else if(uv.x > 0.95 && uv.y < 0.06 && distBottomRight > cornerRadius) {
    inCorner = true;
  }
  // 左下角：当 uv.x < 0.05 且 uv.y < 0.05 时，检查距离
  else if(uv.x < 0.05 && uv.y < 0.06 && distBottomLeft > cornerRadius) {
    inCorner = true;
  }

  // 如果在圆角外部区域，返回透明
  if(inCorner) {
    return vec4(0.0, 0.0, 0.0, 0.0);
  }

  // w值：0.0=back, 1.0=front, 2.0=bottom, 3.0=top, 4.0=前上, 5.0=后下, 6.0=前下, 7.0=后上
  // INPUT1和INPUT2间隔出现：0,2,4,6=INPUT2, 1,3,5,7=INPUT1
  if(vIndex < 0.5){
    // back面：显示第二个视频（图像上下翻转+左右翻转）
    return vec4(INPUT1(uv).rgb, 1.0);
