    // front面：显示第一个视频
    return vec4(INPUT1(uv).rgb, 1.0);
  } else if(vIndex < 2.5){
    // bottom面：显示第一个视频
    return vec4(INPUT1(uv).rgb, 1.0);
  } else if(vIndex < 3.5){
    // top面：显示第一个视频
    return vec4(INPUT1(uv).rgb, 1.0);
  } else if(vIndex < 4.5){
    // 前上面：显示第二个视频
    return vec4(INPUT2(uv).rgb, 1.0);
  } else if(vIndex < 5.5){
    // 后下面：显示第一个视频
    return vec4(INPUT2(uv).rgb, 1.0);
  } else if(vIndex < 6.5){
    // 前下面：显示第二个视频
    return vec4(INPUT2(uv).rgb, 1.0);
  } else if(vIndex < 7.5){
    // 后上面：显示第一个视频
    return vec4(INPUT2(uv).rgb, 1.0);
  } else {
    return vec4(0.0, 0.0, 0.0, 0.0);
    // // 正方形：先渲染 INPUT4，再渲染 INPUT3
