#define PI 3.1415926535897932

float A(float aA1, float aA2) {
    return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
    return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
    return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
    return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
    return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
    float aGuessT = aX;
    for (int i = 0; i < 6; ++i) {
        float currentSlope = GetSlope(aGuessT, mX1, mX2);
        if (currentSlope == 0.0)
            return aGuessT;
        float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
        aGuessT -= currentX / currentSlope;
    }
    return aGuessT;
}

float KeySpline(vec4 p, float aX) {
    float mX1 = p.x;
    float mY1 = p.y;
    float mX2 = p.z;
    float mY2 = p.w;
    if (mX1 == mY1 && mX2 == mY2)
        return aX; // linear
    return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

mat2 Rot(float angle){
  float s = sin(angle);
  float c = cos(angle);
  mat2 m = mat2(c, -s, s, c);
  return m;
}

mat2 Rot2(float angle){
  float s = sin(angle);
  float c = cos(angle);
  mat2 m = mat2(c, s, -s, c);
  return m;
}

vec2 RotateFunc1(vec2 tc, float angle, float scale, float ratio){
  vec2 uv = Rot(angle) * vec2((tc.x * 2.0 - 1.0) * ratio, tc.y * 2.0 - 1.0) * scale;
  uv = vec2((uv.x/ratio + 1.0)/2.0, (uv.y + 1.0)/2.0);
  return uv;
}

vec2 RotateFunc2(vec2 tc, float angle, float scale, float ratio){
  vec2 uv = Rot2(angle) * vec2((tc.x * 2.0 - 1.0) * ratio, tc.y * 2.0 - 1.0) * scale;
  uv = vec2((uv.x/ratio + 1.0)/2.0, (uv.y + 1.0)/2.0);
  return uv;
}

vec4 GlitchEffect(vec2 tc, float iTime, float total_time, float scale_factor){
  vec4 origCol = INPUT1(tc);

  float process = clamp(iTime / total_time, 0.0, 1.0);
  float globalTime = iTime;
  float ratio = iResolution.x / iResolution.y;

  float strength = 0.0;
  if(process < 0.5){
    float progress = clamp((process - 0.2) / 0.15, 0.0, 1.0);
    strength = sin(PI * 2.0 * progress) * 0.05;
  }else{
    float progress = clamp((process - 0.7) / 0.15, 0.0, 1.0);
    strength = sin(PI * 2.0 * progress) * 0.05;
  }

  vec2 uv = tc;

  if(process >= 0.2 && process < 0.6){
    float iPro = clamp((process - 0.2) / 0.4, 0.0, 1.0);
    vec4 p = vec4(.04,.55,.45,.93);
    iPro = KeySpline(p, iPro);
    float scale12 = (iPro - 1.0) * (0.65 - 1.0) + 0.65;
    globalTime = globalTime + total_time * 0.2;
    float time = total_time * 0.2 + total_time;
    float scale = (globalTime - time) / (time - 0.4 * total_time) *(-0.7) + 0.3;
    float angle = iPro * 0.19 * PI * 0.5;
    uv = RotateFunc1(tc, angle, scale12, ratio);
  }else if (process >= 0.6 && process < 1.0){
    float iPro = clamp((process - 0.6) / 0.8, 0.0, 1.0);
    vec4 p = vec4(.06,.35,.58,.98);
    iPro = KeySpline(p, iPro);
    iPro = (iPro - 0.76) / 0.76 * (-0.19);
    globalTime = globalTime + total_time * 0.6;
    float time = total_time * 0.6 + total_time;
    float scale = (globalTime - time) / (time - 1.2 * total_time) * 0.35 + 1.0;
    float angle = -iPro * PI * 0.5;
    uv = RotateFunc2(tc, angle, scale, ratio);
  }

  vec3 retCol;
  vec2 uv1 = (vec2(uv.x + strength, uv.y) - 0.5) * scale_factor + 0.5;
  vec2 uv2 = (uv - 0.5) * scale_factor + 0.5;
  vec2 uv3 = (vec2(uv.x - strength, uv.y) - 0.5) * scale_factor + 0.5;
  vec4 retCol1 = INPUT1(uv1);
  vec4 retCol2 = INPUT1(uv2);
  vec4 retCol3 = INPUT1(uv3);
  retCol.r = retCol1.r;
  retCol.g = retCol2.g;
  retCol.b = retCol3.b;
  float alpha = max(max(retCol1.a, retCol2.a), retCol3.a);

  return vec4(retCol, alpha);
}

vec4 adjustExposure(vec4 origCol, float exposure){
  if(exposure < 0.0){
      origCol.rgb *= pow(2.0, exposure * 0.02353);
      origCol = clamp(origCol, 0.0, 1.0);
  }else if(exposure > 0.0){
      origCol.rgb *= 1.0 + pow(vec3(6.0), -origCol.rgb) * exposure * 0.034;
      origCol = clamp(origCol, 0.0, 1.0);
  }

  return origCol;
}

vec4 adjustContrast(vec4 retCol, float contrastVal){
  if(contrastVal < 0.0){
      float contrast = 1.0 / (1.0 + abs(contrastVal) * 0.005);

      if(retCol.r > 0.0 && retCol.r < 0.5){
          retCol.r = pow(retCol.r * 2.0, contrast) / 2.0;
      }else if(retCol.r >= 0.5 && retCol.r < 1.0){
          retCol.r = 1.0 - pow(2.0 - retCol.r * 2.0, contrast) / 2.0;
      }

      if(retCol.g > 0.0 && retCol.g < 0.5){
          retCol.g = pow(retCol.g * 2.0, contrast) / 2.0;
      }else if(retCol.g >= 0.5 && retCol.g < 1.0){
          retCol.g = 1.0 - pow(2.0 - retCol.g * 2.0, contrast) / 2.0;
      }

      if(retCol.b > 0.0 && retCol.b < 0.5){
          retCol.b = pow(retCol.b * 2.0, contrast) / 2.0;
      }else if(retCol.b >= 0.5 && retCol.b < 1.0){
          retCol.b = 1.0 - pow(2.0 - retCol.b * 2.0, contrast) / 2.0;
      }
  }else if(contrastVal > 0.0){
      float contrast = 1.0 + contrastVal * 0.005;

      if(retCol.r > 0.0 && retCol.r < 0.5){
          retCol.r = pow(retCol.r * 2.0, contrast) / 2.0;
      }else if(retCol.r >= 0.5 && retCol.r < 1.0){
          retCol.r = 1.0 - pow(2.0 - retCol.r * 2.0, contrast) / 2.0;
      }

      if(retCol.g > 0.0 && retCol.g < 0.5){
          retCol.g = pow(retCol.g * 2.0, contrast) / 2.0;
      }else if(retCol.g >= 0.5 && retCol.g < 1.0){
          retCol.g = 1.0 - pow(2.0 - retCol.g * 2.0, contrast) / 2.0;
      }

      if(retCol.b > 0.0 && retCol.b < 0.5){
          retCol.b = pow(retCol.b * 2.0, contrast) / 2.0;
      }else if(retCol.b >= 0.5 && retCol.b < 1.0){
          retCol.b = 1.0 - pow(2.0 - retCol.b * 2.0, contrast) / 2.0;
      }
  }
  return clamp(retCol, 0.0, 1.0);
}

vec4 FUNCNAME(vec2 tc)
{
  int uStep = PREFIX(uStep);
  float scaleFactor = PREFIX(scaleFactor);
  float global_time = PREFIX(global_time);
  float total_time = PREFIX(total_time);
  if(uStep == 0){
