// 计算圆角遮罩
float roundedBoxMask(vec2 uv, float radius, float smoothness) {
    vec2 centered = uv - 0.5;
    vec2 distFromEdge = abs(centered) - (0.5 - radius);
    float cornerDist = length(max(distFromEdge, 0.0));
    float alpha = 1.0 - smoothstep(radius - smoothness, radius, cornerDist);

    return alpha;
}

vec4 InputCoordinate(vec2 uv) {
  // UV x 方向同向同值缩小（与 vert 几何缩放一致），保留中间 30%，丢弃两侧，比例不变
  vec2 adjustedUV = uv;
  adjustedUV.x = 0.5 + (uv.x - 0.5) * vFaceScaleX;
  if (adjustedUV.x < 0.0 || adjustedUV.x > 1.0) {
    return vec4(0.0);
  }

  if(vIndex < 4.5){
    return INPUT1(adjustedUV);
  }
  else{
    return INPUT2(adjustedUV);
  }
}

float normpdf(in float x, in float sigma)
{
  return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}

vec4 texture2Dmirror(vec2 uv) {
  uv = mod(uv, 2.0);
  uv = mix(uv, 2.0 - uv, step(vec2(1.0), uv));
  return InputCoordinate(fract(uv));
}

vec4 directionBlurFunc(vec2 tc, float strength, float angle)
{
  float theta = angle* 3.1415926 / 180.0;
  vec2 rect = vec2(min(720.0, 720.0 * iResolution.x / iResolution.y), min(720.0, 720.0 * iResolution.y / iResolution.x));
  vec2 dir = vec2(cos(theta), sin(theta)) / rect;

  float sigma = 4.0;
  float weight = normpdf(0.0, sigma);

  vec4 sum            = vec4(0.0);
  vec4 result         = vec4(0.0);
  vec2 unitUv        = dir * 6.0;
  float gamma         = 1.0;
  vec4 curColor       = InputCoordinate(tc);
  vec4 centerPixel    = pow(curColor, vec4(gamma))*weight;
  float sumWeight    = weight;

  for(int i=1;i<=100;i++)
  {
      if (float(i)>strength) break;
      vec2 curRightCoordinate = tc+float(i)*unitUv;
      vec2 curLeftCoordinate  = tc+float(-i)*unitUv;
      vec4 rightColor = texture2Dmirror(curRightCoordinate);
      vec4 leftColor = texture2Dmirror(curLeftCoordinate);
      weight = normpdf(float(i) / strength * 15.0, sigma);
      sum+=pow(rightColor, vec4(gamma))*weight;
      sum+=pow(leftColor, vec4(gamma))*weight;
      sumWeight+=weight*2.0;
  }
  result = (sum+centerPixel)/sumWeight; 
  result = pow(result, vec4(1.0 / gamma));
  return clamp(result, 0.0, 1.0);
}

vec4 FUNCNAME(vec2 tc)
{
  vec4 color = InputCoordinate(tc);

  // 应用圆角遮罩：开始时缓慢出现(0~0.25)，结束时缓慢消失(0.75~1.0)
  float cornerRadiusBase = 0.08;  // 圆角半径
  float edgeSmoothness = 0.01; // 边缘平滑度，用于抗锯齿
  float transitionProgress = PREFIX(transitionProgress);
  float fadeOut = 1.0 - smoothstep(0.75, 1.0, transitionProgress);
  // 圆角逐渐消失，但保持最小值 > edgeSmoothness，避免 mask 让整体变透明
  float cornerRadius = max(cornerRadiusBase * fadeOut, edgeSmoothness * 1.5);

  float mask = roundedBoxMask(tc, cornerRadius, edgeSmoothness);
  color.a *= mask;

  // 除右下角面（vIndex == 7）以外，在进度 0.9~1.0 时透明度逐渐变为 0
  if(abs(vIndex - 7.0) > 0.1) {
    float otherFaceFade = 1.0 - smoothstep(0.9, 1.0, transitionProgress);
    color.a *= otherFaceFade;
  }

  return color;
}

#define PI 3.1415926
#define RotationCenter vec3(0.0, 0.0, 0.0)

vec2 rotate(vec2 v, vec2 o, float a) {
    float s = sin(a);
    float c = cos(a);
    mat2 m = mat2(c, -s, s, c);
    return m * (v-o) + o;
}

vec3 rotateZ(vec3 v, vec3 o, float a) {
    float s = sin(a);
    float c = cos(a);
    mat2 m = mat2(c, -s, s, c);
    return vec3(m * (v.xy - o.xy) + o.xy, v.z);
}

vec2 TransformPlane(vec2 uv, vec3 center, float XRot, float YRot, float ZRot) {
  if(fract(XRot/PI) <= 0.4 || fract(XRot/PI) >= 0.6 ){
    // if(mod(YRot, 2.0*PI) >= 0.5*PI && mod(YRot, 2.0*PI) <= 1.5*PI) {
    //     uv.x = 0.5 - (uv.x - 0.5);
    //     YRot = PI - YRot;
    // }
    uv = -1.0 + 2.0 * uv;
    // First Rotate around Y axis
    vec2 RayDirection = vec2(uv.x, 0.0);
    vec2 A1 = vec2(0.0, -1.0);
    vec2 B1 = RayDirection - A1;
    vec2 C1 = rotate(vec2(-1.0, 0.0), vec2(center.x, 0.0), YRot);
    vec2 D1 = rotate(vec2(1.0, 0.0), vec2(center.x, 0.0), YRot) - C1;

    // calculate intersection point
    float u = ( (C1.y + 1.0) * D1.x - C1.x * D1.y ) / (D1.x*B1.y-D1.y*B1.x);

    // position on the XY plane after Y-axis rotation
    float sx = u * B1.x; //  * (1.0 + abs(sin(YRot)))
    float sy = u * uv.y;

    // Now Rotate around X axis
    RayDirection = vec2(sy, 0.0);
    vec2 B2 = RayDirection - A1;
    vec2 C2 = rotate(vec2(-1.0, 0.0), vec2(center.y, 0.0), XRot);
    vec2 D2 = rotate(vec2(1.0, 0.0), vec2(center.y, 0.0), XRot) - C2;

    // calculate intersection point
    float v = ( (C2.y + 1.0) * D2.x - C2.x * D2.y ) / (D2.x*B2.y-D2.y*B2.x);

    // the position after x and y rotations
    // vec3 pos = vec3(v * sx, v * B2.x * (1.0 + 3.0*abs(sin(XRot))), 0.0 );
    float y_strength = exp(-20.0 * pow(abs(1.6*abs(XRot)/PI-0.8), 4.0));
    vec3 pos = vec3(v * sx, v * B2.x * (1.0 + 1.0*y_strength), 0.0 );

    // Now rotate the position around Z axis
    vec3 finalPos = rotateZ(pos, center, ZRot);

    // final position on the 3D plane after Z-axis rotation
    return finalPos.xy;
  } else {
    return vec2(-2.0);
  }
}

