vec2 s(vec2 p, float uWarp){
    float d=13.0*0.6;
    float x=50.0 * uWarp * (p.x+d);
    float y=15.0 * uWarp * (p.y+d);
    x = cos(x-y) * sin(uWarp);
    y = sin(x+y) * sin(x);
    return vec2(x,y);
}
