#define PI 3.141592653589793

vec2 Spiral(vec2 uv, vec2 center, float intensity, float time, vec2 prop, float direction, float maxRadius) {
    vec2 centeredUV = (uv - center) * prop;
    float distance = length(centeredUV);
    float angle = atan(centeredUV.y, centeredUV.x);

    float rotationIntensity = PREFIX(Speed);

    float decay = 3.0;
    float spiralRotation = intensity * rotationIntensity * exp(-distance * decay);
    float maxSpiralRotation = intensity * rotationIntensity * exp(-maxRadius * decay);

    float rotation = 0.0;
    if (distance < maxRadius) {
        rotation = spiralRotation;
    } else {
        rotation = maxSpiralRotation;
    }

    if (direction == 0.0) {
        angle -= rotation;
    } else {
        angle += rotation;
    }

    vec2 newPos = center + distance * vec2(cos(angle), sin(angle)) / prop;
    return newPos;
}


vec2 Rotated(vec2 uv, vec2 center, float intensity, float time, vec2 prop, float maxRadius, float direction) {
    vec2 centeredUV = (uv - center) * prop;

    float distance = length(centeredUV);
    float angle = atan(centeredUV.y, centeredUV.x);

    float twistIntensity = 1.5 * PREFIX(Speed);
    float rotation = 0.0;
    if (distance <= maxRadius) {
        float radiusFactor = 1.0 - smoothstep(0.0, maxRadius, distance);
        rotation = intensity * twistIntensity * radiusFactor;
    }
    if(direction == 0.0){
        angle -= rotation;
    }else{
        angle += rotation;
    }

    vec2 newPos = center + distance * vec2(cos(angle), sin(angle)) / prop;

    return newPos;
}



