{
	float iGlobalTime = PREFIX(global_time);
	float totalTime = PREFIX(total_time);

	float process = min(iGlobalTime / totalTime, 1.0);
	float iPro = (3.0 * process * process - 2.0 * process * process * process);

	vec4 y1 = INPUT1(tc);
	vec4 y2 = INPUT2(tc);

	vec4 retCol = y1;

	vec4 white = vec4(1.0);
	float progress = 0.0;
	if(process < 0.5){
		retCol.a = y1.a;
		progress = process * 2.0 * 0.8;
		retCol.rgb = mix(y1.rgb, white.rgb, progress);
	}else{
		retCol.a = y2.a;
		progress = (1.0 - (process - 0.5) * 2.0) * 0.8;
		float amount = 0.04 * progress;
		vec3 sum = vec3(0.0);
		float samples = 10.0;
		for (float i = 0.0; i < samples; i++) { 
			vec2 q = vec2(cos(degrees((i/samples)*360.0)), sin(degrees((i/samples)*360.0))) * (rand(vec2(i,tc.x+tc.y)) + amount); 
			vec2 uv2 = tc + (q * amount);
			sum += INPUT2(uv2).rgb / 2.0;
			q = vec2(cos(degrees((i/samples)*360.0)), sin(degrees((i/samples)*360.0))) * (rand(vec2(i+2.0,tc.x+tc.y+24.0)) + amount); 
			uv2 = tc + (q * amount);
			sum += INPUT2(uv2).rgb / 2.0;
		}

		sum /= samples;
		white.rgb = mix(y1.rgb, white.rgb, min(0.8 + (process - 0.5) * 0.5, 1.0));
		retCol.rgb = mix(sum, white.rgb, progress);
	}

	retCol.rgb *= retCol.a;

	return retCol;
}

