vec4 trailMotionBlur(vec2 uv, float process) {
    vec4 color = vec4(0.0);
    int samples = 100;

    float blurAmount = 1.4 * process + 0.1; 
    float stepLength = blurAmount / float(samples);

    for (int i = 0; i < samples; i++) {
        float t = float(i) / float(samples - 1); 
        vec2 sampleUV = uv + vec2(stepLength * float(i), 0.0);
        color += INPUT1(sampleUV);
    }

    return color / float(samples);
}

vec4 trailMotionBlur2(vec2 uv, float process) {
    vec4 color = vec4(0.0);
    int samples = 100;

    float blurAmount = 1.5 * (1.0 -process); 
    float stepLength = blurAmount / float(samples);

    for (int i = 0; i < samples; i++) {
        float t = float(i) / float(samples - 1); 
        vec2 sampleUV = uv + vec2(stepLength * float(i), 0.0);
