vec4 pan(vec2 tc, float process) {
    vec4 fragColor = vec4(0.0);
    vec2 uv = tc;
    vec4 leftBlur = trailMotionBlur(tc + vec2(process + 0.3, 0.0), process); 
    uv.x = tc.x - (1.0 - process);
    vec4 rightBlur = trailMotionBlur2(uv, process);
    float mixFactor = smoothstep(-0.2, 0.2, tc.x - (1.0 - process)); 
    fragColor = mix(leftBlur, rightBlur, mixFactor); 
    return fragColor;
}

