vec4 BlurColor (vec2 Coord, float MipBias, float istrength) {
	vec2 TexelSize = MipBias/iResolution.xy;

    vec4  Color = INPUT1(Coord);
    Color += INPUT1(Coord + vec2(TexelSize.x,0.0)) * istrength * GetColor(16776960);    	
    Color += INPUT1(Coord + vec2(-TexelSize.x,0.0)) * istrength * GetColor(16776960);    	
    Color += INPUT1(Coord + vec2(0.0,TexelSize.y)) * istrength * GetColor(16776960);    	
    Color += INPUT1(Coord + vec2(0.0,-TexelSize.y)) * istrength * GetColor(16776960);    	
    Color += INPUT1(Coord + vec2(TexelSize.x,TexelSize.y)) * istrength * GetColor(16776960);    	
    Color += INPUT1(Coord + vec2(-TexelSize.x,TexelSize.y)) * istrength * GetColor(16776960);    	
    Color += INPUT1(Coord + vec2(TexelSize.x,-TexelSize.y)) * istrength * GetColor(16776960);    	
    Color += INPUT1(Coord + vec2(-TexelSize.x,-TexelSize.y)) * istrength * GetColor(16776960);    

    return Color/9.0;
}

vec3 BloomFunc(vec2 iuv) {   
    vec2 center = vec2(0.5);
    float Threshold = 0.0 + center.y/iResolution.y*1.0;
    float Intensity = 2.0 - center.x/iResolution.x*2.0;
    float BlurSize = 6.0 - center.x/iResolution.x*6.0;

    vec4 Color = INPUT1(iuv);

    vec4 Highlight = clamp(BlurColor(iuv, BlurSize, PREFIX(lightProcess))-Threshold,0.0,1.0)*1.0/(1.0-Threshold);

    vec4 fragColor = 1.0 - (1.0-Color) * (1.0-Highlight*Intensity);

    return fragColor.rgb;
}

