        vec4 bg = INPUT1(zoom_uv);
        vec4 mask_human = bg * step(0.25, mask.a);

        vec4 fragOutCol = mix(INPUT1(tc), mask_human, mask_human.a);
        if (itime > 0.5) {
            fragOutCol = INPUT2(zoom_uv);
        }

        return fragOutCol;
    } else {
        vec4 fragOutCol = INPUT1(tc);
        vec4 bg = INPUT2(tc);
        fragOutCol.rgb = mix(fragOutCol.rgb, BloomFunc(tc), smoothstep(0.25, 0.35, PREFIX(iTime)));
        fragOutCol.rgb = mix(fragOutCol.rgb, bg.rgb, smoothstep(0.6, 0.8, PREFIX(iTime)));

        return fragOutCol;
    }

}

