// 计算圆角遮罩
float roundedBoxMask(vec2 uv, float radius, float smoothness) {
    vec2 centered = uv - 0.5;
    vec2 distFromEdge = abs(centered) - (0.5 - radius);
    float cornerDist = length(max(distFromEdge, 0.0));
    float alpha = 1.0 - smoothstep(radius - smoothness, radius, cornerDist);

    return alpha;
}

vec4 InputCoordinate(vec2 uv) {
  // 获取转场进度
  float transitionProgress = PREFIX(transitionProgress);
  bool swapInputs = transitionProgress > 0.57;

  if(vIndex < 1.5){
    if(swapInputs) {
      return vec4(INPUT2(uv).rgb, 1.0);
    } else {
      return vec4(INPUT1(uv).rgb, 1.0);
    }
  } else if(vIndex < 2.5){
    if(swapInputs) {
      return vec4(INPUT1(uv).rgb, 1.0);
    } else {
      return vec4(INPUT2(uv).rgb, 1.0);
    }
  } else {
    if(swapInputs) {
      return vec4(INPUT2(uv).rgb, 1.0);
    } else {
      return vec4(INPUT1(uv).rgb, 1.0);
    }
  }
}

float normpdf(in float x, in float sigma)
{
  return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}

vec4 texture2Dmirror(vec2 uv) {
  uv = mod(uv, 2.0);
  uv = mix(uv, 2.0 - uv, step(vec2(1.0), uv));
  return InputCoordinate(fract(uv));
}

vec4 directionBlurFunc(vec2 tc, float strength, float angle)
{
  float theta = angle* 3.1415926 / 180.0;
  vec2 rect = vec2(min(720.0, 720.0 * iResolution.x / iResolution.y), min(720.0, 720.0 * iResolution.y / iResolution.x));
  vec2 dir = vec2(cos(theta), sin(theta)) / rect;

  float sigma = 4.0;
  float weight = normpdf(0.0, sigma);

  vec4 sum            = vec4(0.0);
  vec4 result         = vec4(0.0);
  vec2 unitUv        = dir * 6.0;
  float gamma         = 1.0;
  vec4 curColor       = InputCoordinate(tc);
  vec4 centerPixel    = pow(curColor, vec4(gamma))*weight;
  float sumWeight    = weight;

  for(int i=1;i<=100;i++)
  {
      if (float(i)>strength) break;
      vec2 curRightCoordinate = tc+float(i)*unitUv;
      vec2 curLeftCoordinate  = tc+float(-i)*unitUv;
      vec4 rightColor = texture2Dmirror(curRightCoordinate);
      vec4 leftColor = texture2Dmirror(curLeftCoordinate);
      weight = normpdf(float(i) / strength * 15.0, sigma);
      sum+=pow(rightColor, vec4(gamma))*weight;
      sum+=pow(leftColor, vec4(gamma))*weight;
      sumWeight+=weight*2.0;
  }
  result = (sum+centerPixel)/sumWeight; 
  result = pow(result, vec4(1.0 / gamma));
  return clamp(result, 0.0, 1.0);
}

vec4 FUNCNAME(vec2 tc)
{
  float blurRotateValue = PREFIX(blurRotateValue);
