vec4 iBlur(vec2 iuv, float iprocess) {
  vec2 uv = iuv;
  vec2 center = vec2(0.5);
  int nsamples = 10;

  float blurStart = 1.0;
  float blurWidth =  0.1 * iprocess;

  uv -= center;
  float precompute = blurWidth * (1.0 / float(nsamples - 1));

  vec4 color = vec4(0.0);
  for(int i = 0; i < nsamples; i++)
  {
    float scale = blurStart - (float(i)* precompute);
    color += INPUT3(uv * scale + center);
  }

  color /= float(nsamples);

  return color;
}

vec2 irotate(vec2 iuv, float istrength, float iprocess) {
  vec2 center = vec2(0.5);
  vec2 rotateUV = iuv * iResolution;
  float rotation = istrength * iprocess;
  rotateUV -= center * iResolution;
  vec4 rotateMat = vec4(cos(rotation), -sin(rotation), sin(rotation), cos(rotation));
  float new_x = rotateUV.x*rotateMat.x + rotateUV.y*rotateMat.z;
  float new_y = rotateUV.x*rotateMat.y + rotateUV.y*rotateMat.w;
  rotateUV = vec2(new_x, new_y);
  rotateUV += center * iResolution;
  rotateUV = rotateUV / iResolution;

  return rotateUV;
}

float checkBorder(vec2 iuv) {
  return step(iuv.x, 1.0) * step(0.0, iuv.x) * step(iuv.y, 1.0) * step(0.0, iuv.y);
}

