  float firstShakePeak = 0.14; // 第一次抖动的峰值位置
  float firstShakeHoldEnd = 0.28; // 第一次抖动保持最大值阶段结束点
  float firstShakeFallEnd = firstShakeHoldEnd + (firstShakePeak - firstShakeStart); // 下降阶段结束点

  if (process >= firstShakeStart && process <= firstShakePeak) {
    // 第一次抖动上升阶段
    translate_x = pow(cos(((process - firstShakePeak) / (firstShakePeak - firstShakeStart)) * M_PI * 0.5), 6.) * 0.4;
  } else if (process > firstShakePeak && process <= firstShakeHoldEnd) {
    // 第一次抖动保持最大值阶段
    translate_x = 0.4;
  } else if (process > firstShakeHoldEnd && process <= firstShakeFallEnd) {
    // 第一次抖动下降阶段
    float fallProgress = (process - firstShakeHoldEnd) / (firstShakeFallEnd - firstShakeHoldEnd);
    translate_x = pow(cos(fallProgress * M_PI * 0.5), 6.) * 0.4;
  } else if (process >= 0.4125 && process <= 0.5775) {
    translate_x = -pow(cos(((process - 0.495) / 0.0825) * M_PI * 0.5), 6.) * 0.4;
  } else if (process >= 0.7425 && process <= 0.9075){
    translate_x = pow(cos(((process - 0.825) / 0.0825) * M_PI * 0.5), 3.) * 0.8;
  }

  return vec2(translate_x, translate_y);
}

vec4 InputCoordinate(vec2 uv) {
  float aspect = PREFIX(aspect);
  float transitionProgress = PREFIX(transitionProgress);

  // w值：1.0=front, 2.0=back
  if(vIndex < 0.5){
    // back面：显示第一个视频
    return INPUT1(uv);
  } else if(vIndex < 1.5){
    // front面：显示第一个视频，在0.42-0.5之间与back面混合，0.5之后完全显示back
    vec4 frontColor = INPUT1(uv);

    // 计算back面的颜色（与vIndex < 2.5分支中的逻辑相同）
    float halfRange = 0.5 / aspect;
    float texY = 0.5 + (uv.y - 0.5) / aspect;
    texY = clamp(texY, 0.5 - halfRange, 0.5 + halfRange);
    float adjustedY = (texY - (0.5 - halfRange)) / (2.0 * halfRange);
    vec4 backColor = INPUT2(vec2(uv.x, adjustedY));

    // 计算混合因子：0.42时为0（完全front），0.5时为1（完全back），0.5之后保持1
    float blendFactor = 0.0;
    if(transitionProgress >= 0.42) {
      if(transitionProgress <= 0.53) {
        blendFactor = smoothstep(0.42, 0.53, transitionProgress);  // 0到1的平滑过渡
      } else {
        blendFactor = 1.0;  // 0.5之后保持完全back（第一个视频透明度恒为0）
      }
    }

    // 混合front和back的颜色
    return mix(frontColor, backColor, blendFactor);
  } else if(vIndex < 2.5){
    // back面：显示第二个视频
    float halfRange = 0.5 / aspect;
    float texY = 0.5 + (uv.y - 0.5) / aspect;
    texY = clamp(texY, 0.5 - halfRange, 0.5 + halfRange);
    float adjustedY = (texY - (0.5 - halfRange)) / (2.0 * halfRange);
    return INPUT2(vec2(uv.x, adjustedY));
  } else {
    // top面：显示第二个视频
    float halfRange = 0.5 / aspect;
    float texY = 0.5 + (uv.y - 0.5) / aspect;
    texY = clamp(texY, 0.5 - halfRange, 0.5 + halfRange);
    float adjustedY = (texY - (0.5 - halfRange)) / (2.0 * halfRange);
    return INPUT2(vec2(uv.x, adjustedY));
  }
}

// 高斯权重函数
float gaussianWeight(float x, float sigma) {
  return exp(-0.5 * x * x / (sigma * sigma));
}

// 镜像纹理采样
vec4 texture2Dmirror(vec2 uv) {
  uv = mod(uv, 2.0);
  uv = mix(uv, 2.0 - uv, step(vec2(1.0), uv));
  return InputCoordinate(fract(uv));
}

// 直接采样第二个视频（用于RGB分离）
vec4 sampleInput2(vec2 uv) {
  float aspect = PREFIX(aspect);
  float halfRange = 0.5 / aspect;
  float texY = 0.5 + (uv.y - 0.5) / aspect;
  texY = clamp(texY, 0.5 - halfRange, 0.5 + halfRange);
  float adjustedY = (texY - (0.5 - halfRange)) / (2.0 * halfRange);
  return INPUT2(vec2(uv.x, adjustedY));
}

// 直接采样第一个视频（用于RGB分离）
vec4 sampleInput1(vec2 uv) {
  return INPUT1(uv);
}

// 运动模糊（Motion Blur）- 在特定方向上产生拉伸效果
vec4 motionBlurFunc(vec2 tc, float strength, float angle)
{
  // 性能优化：自适应采样策略
  int useSmallBlur = PREFIX(uUseSmallBlur);

  // 将角度转换为弧度
  float theta = angle * 3.1415926 / 180.0;

  // 计算运动方向向量
  vec2 direction = vec2(cos(theta), sin(theta));

  // 计算采样步长（基于分辨率）
  vec2 rect = vec2(min(720.0, 720.0 * iResolution.x / iResolution.y), min(720.0, 720.0 * iResolution.y / iResolution.x));
  vec2 stepSize = direction / rect;

  // 计算采样数量和sigma
  float radius = strength;
  float sigma = radius / 3.0;  // sigma约为半径的1/3

  vec3 resultRGB = vec3(0.0);
  float totalWeight = 0.0;

  // 获取原始颜色的alpha值（用于保持透明度）
  vec4 originalColor = InputCoordinate(tc);
  float originalAlpha = originalColor.a;

  // 采样参数：增大采样次数，减小采样距离
  float stepMultiplier = 2.0;  // 步长倍数
  int sampleCountMultiplier = 1;  // 采样数量倍数
  int sampleCount = int(ceil(radius * float(sampleCountMultiplier) * 2.0));  // 乘以2与Bulge Pan保持一致
  sampleCount = min(sampleCount, 25);  // 设置上限

  // 优化：当模糊强度较大时，适度减少采样次数
  if(useSmallBlur > 0) {
    sampleCount = min(sampleCount, 15);  // 进一步限制采样次数
    stepMultiplier *= 1.3;  // 增大步长
  }

  // 沿运动方向进行采样
  for(int i = -sampleCount; i <= sampleCount; i++) {
    // 计算采样点位置（沿运动方向）
    vec2 offset = stepSize * float(i) * stepMultiplier; 
    vec2 sampleCoord = tc + offset;

    // 计算沿运动方向的距离
    float dist = abs(float(i)) * stepMultiplier;

    // 如果距离超过半径，跳过
    if(dist > radius * stepMultiplier) continue;

    // 计算高斯权重
    float weight = gaussianWeight(dist, sigma * stepMultiplier);

    // 采样并累加RGB通道
    vec4 sampleColor = texture2Dmirror(sampleCoord);
    resultRGB += sampleColor.rgb * weight;
    totalWeight += weight;
  }

  // 归一化RGB通道
  vec3 finalRGB;
  if(totalWeight > 0.0) {
    finalRGB = resultRGB / totalWeight;
  } else {
    finalRGB = originalColor.rgb;
  }

  // 返回模糊后的RGB，但保留原始的alpha值
  return vec4(finalRGB, originalAlpha);
}

