    // 采样第二个视频的不同UV位置来实现RGB分离
    vec4 sample2_1_2 = INPUT2(vec2(temp1_2.x, adjustedY1_2));
    vec4 sample2_2_2 = INPUT2(vec2(temp2_2.x, adjustedY2_2));
    vec4 sample2_3_2 = INPUT2(vec2(temp3_2.x, adjustedY3_2));

    // 组合第二个视频的RGB通道
    vec4 rgbSplitInput2 = vec4(0.0);
    rgbSplitInput2.ra += sample2_1_2.ra;  // R和A通道使用原始位置
    rgbSplitInput2.g += sample2_2_2.g;    // G通道使用向右偏移的位置
    rgbSplitInput2.b += sample2_3_2.b;     // B通道使用向右偏移的位置
    rgbSplitInput2.rgb *= rgbSplitInput2.a;

    // ========== 优化的合并模糊循环：同时处理图一和图二 ==========
    vec2 direction = vec2(1.0, 0.0); // 水平方向: cos(0°)=1, sin(0°)=0
