    vec2 stepSize = direction / rect;

    // 图一使用完整的blurStrength，图二使用0.2倍的blurStrength
    float radius1 = blurRotateValue * blurStrength;
    const float blurRatio = 0.2;
    float radius2 = radius1 * blurRatio;  // 图二半径为图一的0.2倍

    float stepMultiplier = 2.0;
    int sampleCountMultiplier = 1;

    float invSigma1 = 1.0 / (radius1 / 3.0 * stepMultiplier);
    float invSigma2 = 1.0 / (radius2 / 3.0 * stepMultiplier);

    // 使用图一的采样数量，乘以2并设置上限
    int sampleCount = int(ceil(radius1 * float(sampleCountMultiplier) * 2.0));
    sampleCount = min(sampleCount, 25);

    // 性能优化：根据模糊强度调整采样
    int useSmallBlur = PREFIX(uUseSmallBlur);
    if(useSmallBlur > 0) {
      sampleCount = min(sampleCount, 15);
      stepMultiplier *= 1.3;
    }

    float maxDist1 = radius1 * stepMultiplier;
    float maxDist2 = radius2 * stepMultiplier;

    vec3 resultRGB1 = vec3(0.0);
    vec3 resultRGB2 = vec3(0.0);
    float totalWeight1 = 0.0;
    float totalWeight2 = 0.0;

    // 预计算RGB偏移量
    float onePixelX100 = onePixel.x * 100.0;
    float rgbOffsetX = processColorSp.x;
    float dragOffsetG = intensityMultiplier2 * 0.06 * onePixelX100 + processColorSp2.x * onePixelX100;
    float dragOffsetB = intensityMultiplier2 * 0.1 * onePixelX100 - processColorSp2.x * onePixelX100;

    // 合并的模糊采样循环 - 同时处理图一和图二
    for(int i = -sampleCount; i <= sampleCount; i++) {
      float fi = float(i);
      vec2 sampleCoord = tc + stepSize * fi * stepMultiplier;
      float dist = abs(fi) * stepMultiplier;

      // 处理图一的模糊
      if(dist <= maxDist1) {
        float weight1 = gaussianWeight(dist, invSigma1);

        // RGB Shake风格的水平抖动
        vec2 sTemp1_1 = clamp(sampleCoord, 0.0, 1.0);
        vec2 sTemp2_1 = clamp(sampleCoord + vec2(processColorSp.x, 0.0), 0.0, 1.0);
        vec2 sTemp3_1 = clamp(sampleCoord - vec2(processColorSp.x, 0.0), 0.0, 1.0);

        vec4 sSample1_1 = sampleInput1(sTemp1_1);
        vec4 sSample2_1 = sampleInput1(sTemp2_1);
        vec4 sSample3_1 = sampleInput1(sTemp3_1);

        // 直接累加RGB通道
        resultRGB1.r += sSample1_1.r * sSample1_1.a * weight1;
        resultRGB1.g += sSample2_1.g * sSample2_1.a * weight1;
        resultRGB1.b += sSample3_1.b * sSample3_1.a * weight1;
        totalWeight1 += weight1;
      }

      // 处理图二的模糊
      if(dist <= maxDist2) {
        float weight2 = gaussianWeight(dist, invSigma2);

        // Bulge Stretch风格的RGB拖影
        vec2 sTemp1_2 = sampleCoord;
        vec2 sTemp2_2 = sampleCoord + vec2(dragOffsetG, 0.0);
        vec2 sTemp3_2 = sampleCoord + vec2(dragOffsetB, 0.0);

        float sTexY1_2 = 0.5 + (sTemp1_2.y - 0.5) / aspect;
        sTexY1_2 = clamp(sTexY1_2, 0.5 - halfRange, 0.5 + halfRange);
        float sAdjustedY1_2 = (sTexY1_2 - (0.5 - halfRange)) / (2.0 * halfRange);

        float sTexY2_2 = 0.5 + (sTemp2_2.y - 0.5) / aspect;
        sTexY2_2 = clamp(sTexY2_2, 0.5 - halfRange, 0.5 + halfRange);
        float sAdjustedY2_2 = (sTexY2_2 - (0.5 - halfRange)) / (2.0 * halfRange);

        float sTexY3_2 = 0.5 + (sTemp3_2.y - 0.5) / aspect;
        sTexY3_2 = clamp(sTexY3_2, 0.5 - halfRange, 0.5 + halfRange);
        float sAdjustedY3_2 = (sTexY3_2 - (0.5 - halfRange)) / (2.0 * halfRange);

        vec4 sSample2_1_2 = vec4(INPUT2(vec2(sTemp1_2.x, sAdjustedY1_2)).rgb, 1.0);
        vec4 sSample2_2_2 = vec4(INPUT2(vec2(sTemp2_2.x, sAdjustedY2_2)).rgb, 1.0);
        vec4 sSample2_3_2 = vec4(INPUT2(vec2(sTemp3_2.x, sAdjustedY3_2)).rgb, 1.0);

        // 直接累加RGB通道
        resultRGB2.r += sSample2_1_2.r * sSample2_1_2.a * weight2;
        resultRGB2.g += sSample2_2_2.g * sSample2_2_2.a * weight2;
        resultRGB2.b += sSample2_3_2.b * sSample2_3_2.a * weight2;
        totalWeight2 += weight2;
      }
    }

    // 归一化结果
    vec3 finalRGB1 = (totalWeight1 > 0.0) ? (resultRGB1 / totalWeight1) : rgbSplitInput1.rgb;
    vec3 finalRGB2 = (totalWeight2 > 0.0) ? (resultRGB2 / totalWeight2) : rgbSplitInput2.rgb;

    // 混合模糊后的图一和图二
    vec4 mixedColor = mix(vec4(finalRGB1, rgbSplitInput1.a), vec4(finalRGB2, rgbSplitInput2.a), 1.0 - blendFactor);

    return vec4(clamp(mixedColor.rgb, 0.0, 1.0), mixedColor.a);
  }

  // 不在RGB分离时间段内，正常处理（水平方向运动模糊）
  vec4 blurredResult = motionBlurFunc(tc, blurRotateValue, 0.0);
  return blurredResult;
}

customize_in vec2 vUV;
customize_in float vIndex;

// RGB Shake 风格的位移计算函数（竖直方向）
vec2 GetTranslate(float process) {
  const float M_PI = 3.1415926535897932384626433832795;
  float translate_x = 0.;
  float translate_y = 0.;

  float firstShakeStart = 0.0825;
  float firstShakePeak = 0.14; // 第一次抖动的峰值位置
  float firstShakeHoldEnd = 0.28; // 第一次抖动保持最大值阶段结束点
  float firstShakeFallEnd = firstShakeHoldEnd + (firstShakePeak - firstShakeStart); // 下降阶段结束点

  if (process >= firstShakeStart && process <= firstShakePeak) {
    // 第一次抖动上升阶段
    translate_y = pow(cos(((process - firstShakePeak) / (firstShakePeak - firstShakeStart)) * M_PI * 0.5), 6.) * 0.4;
  } else if (process > firstShakePeak && process <= firstShakeHoldEnd) {
    // 第一次抖动保持最大值阶段
    translate_y = 0.4;
  } else if (process > firstShakeHoldEnd && process <= firstShakeFallEnd) {
    // 第一次抖动下降阶段
    float fallProgress = (process - firstShakeHoldEnd) / (firstShakeFallEnd - firstShakeHoldEnd);
    translate_y = pow(cos(fallProgress * M_PI * 0.5), 6.) * 0.4;
  } else if (process >= 0.4125 && process <= 0.5775) {
    translate_y = -pow(cos(((process - 0.495) / 0.0825) * M_PI * 0.5), 6.) * 0.4;
  } else if (process >= 0.7425 && process <= 0.9075){
    translate_y = pow(cos(((process - 0.825) / 0.0825) * M_PI * 0.5), 3.) * 0.8;
  }

  return vec2(translate_x, translate_y);
}

vec4 InputCoordinate(vec2 uv) {
  float aspect = PREFIX(aspect);
  float transitionProgress = PREFIX(transitionProgress);

  // w值：1.0=front, 2.0=back
  if(vIndex < 0.5){
