// RGB Shake 风格的位移计算函数
vec2 GetTranslate(float process) {
  const float M_PI = 3.1415926535897932384626433832795;
  float translate_x = 0.;
  float translate_y = 0.;
  if (process >= 0.0825 && process <= 0.2475) {
    translate_x = pow(cos(((process - 0.165) / 0.0825) * M_PI * 0.5), 6.) * 0.4;
  } else if (process >= 0.4125 && process <= 0.5775) {
    translate_x = -pow(cos(((process - 0.495) / 0.0825) * M_PI * 0.5), 6.) * 0.4;
  } else if (process >= 0.7425 && process <= 0.9075){
    translate_x = pow(cos(((process - 0.825) / 0.0825) * M_PI * 0.5), 3.) * 0.8;
  }

  return vec2(translate_x, translate_y);
}

