    float baseIntensityMultiplier = 6.0; // 基础强度倍数，用于控制拖影长度

    if(transitionProgress <= 0.5) {
      // 0.3-0.5：拖影逐渐增强
      float normalizedProgress = (transitionProgress - 0.3) / (0.5 - 0.3);
      intensityMultiplier = normalizedProgress * baseIntensityMultiplier;
    } else {
      // 0.5-0.6：拖影逐渐减弱
      float normalizedProgress = (transitionProgress - 0.5) / (0.6 - 0.5);
      intensityMultiplier = (1.0 - normalizedProgress) * baseIntensityMultiplier;
    }

    // 用于RGB Shake的process计算（仅在增强阶段使用）
    float process = clamp((transitionProgress - 0.3) / (0.5 - 0.3), 0.0, 1.0);

    // 计算像素单位（用于UV偏移）
    vec2 onePixel = 1.0 / iResolution.xy;

    // 向上拉长的拖影：RGB通道分别向上偏移不同距离，创建彩色拖影效果
    // R/A通道：原始UV位置（不偏移，保持原位置）
    vec2 temp1 = tc;
    // G通道：向上偏移（y减小，创建绿色拖影）
    vec2 temp2 = tc + vec2(0.0, -intensityMultiplier * 0.03 * onePixel.y * 100.0);
    // B通道：向上偏移更多（y减小更多，创建蓝色拖影，拖影更长）
    vec2 temp3 = tc + vec2(0.0, -intensityMultiplier * 0.05 * onePixel.y * 100.0);

    // 直接采样第一个视频的不同UV位置来实现RGB分离
    vec4 sample1 = sampleInput1(temp1);
    vec4 sample2 = sampleInput1(temp2);
    vec4 sample3 = sampleInput1(temp3);

    // 组合RGB通道（参考RGB Shake的实现方式）
    vec4 rgbSplitInput1 = vec4(0.0);
    rgbSplitInput1.ra += sample1.ra;  // R和A通道使用原始位置
    rgbSplitInput1.g += sample2.g;     // G通道使用向上偏移的位置
    rgbSplitInput1.b += sample3.b;     // B通道使用向上偏移的位置
    rgbSplitInput1.rgb *= rgbSplitInput1.a;

    // 计算混合因子（第一个视频的显示比例，在0.3-0.6时间段内逐渐减少到0）
    float blendFactor = 1.0 - smoothstep(0.3, 0.6, transitionProgress);

    // 第二个视频：也应用RGB分离效果
    float aspect = PREFIX(aspect);
    float halfRange = 0.5 / aspect;

    // 计算第二个视频的UV坐标
    float texY1 = 0.5 + (temp1.y - 0.5) / aspect;
    texY1 = clamp(texY1, 0.5 - halfRange, 0.5 + halfRange);
    float adjustedY1 = (texY1 - (0.5 - halfRange)) / (2.0 * halfRange);

    float texY2 = 0.5 + (temp2.y - 0.5) / aspect;
    texY2 = clamp(texY2, 0.5 - halfRange, 0.5 + halfRange);
    float adjustedY2 = (texY2 - (0.5 - halfRange)) / (2.0 * halfRange);

    float texY3 = 0.5 + (temp3.y - 0.5) / aspect;
    texY3 = clamp(texY3, 0.5 - halfRange, 0.5 + halfRange);
    float adjustedY3 = (texY3 - (0.5 - halfRange)) / (2.0 * halfRange);

    // 采样第二个视频的不同UV位置来实现RGB分离
    vec4 sample2_1 = INPUT2(vec2(temp1.x, adjustedY1));
    vec4 sample2_2 = INPUT2(vec2(temp2.x, adjustedY2));
    vec4 sample2_3 = INPUT2(vec2(temp3.x, adjustedY3));

    // 组合第二个视频的RGB通道
    vec4 rgbSplitInput2 = vec4(0.0);
    rgbSplitInput2.ra += sample2_1.ra;  // R和A通道使用原始位置
    rgbSplitInput2.g += sample2_2.g;    // G通道使用向上偏移的位置
    rgbSplitInput2.b += sample2_3.b;     // B通道使用向上偏移的位置
    rgbSplitInput2.rgb *= rgbSplitInput2.a;

    // 混合RGB分离后的第一个视频和第二个视频
    vec4 mixedColor = mix(rgbSplitInput1, rgbSplitInput2, 1.0 - blendFactor);

    // 对混合后的颜色应用运动模糊
    float theta = 90.0 * 3.1415926 / 180.0;
    vec2 direction = vec2(cos(theta), sin(theta));
    vec2 rect = vec2(min(720.0, 720.0 * iResolution.x / iResolution.y), min(720.0, 720.0 * iResolution.y / iResolution.x));
    vec2 stepSize = direction / rect;
    float radius = blurRotateValue;
    float sigma = radius / 3.0;
    float stepMultiplier = 2.0;
    int sampleCountMultiplier = 4;
    int sampleCount = int(ceil(radius * float(sampleCountMultiplier)));

    vec3 resultRGB = vec3(0.0);
    float totalWeight = 0.0;

    // 沿运动方向进行采样
    for(int i = -sampleCount; i <= sampleCount; i++) {
      vec2 offset = stepSize * float(i) * stepMultiplier;
      vec2 sampleCoord = tc + offset;
      float dist = abs(float(i)) * stepMultiplier;

      if(dist > radius * stepMultiplier) continue;

      float weight = gaussianWeight(dist, sigma * stepMultiplier);

      // 对每个采样点也应用RGB分离和混合（向上拉长）
      vec2 sTemp1 = sampleCoord;
      vec2 sTemp2 = sampleCoord + vec2(0.0, -intensityMultiplier * 0.03 * onePixel.y * 100.0);
      vec2 sTemp3 = sampleCoord + vec2(0.0, -intensityMultiplier * 0.05 * onePixel.y * 100.0);

      // 采样第一个视频的不同UV位置
      vec4 sSample1 = sampleInput1(sTemp1);
      vec4 sSample2 = sampleInput1(sTemp2);
      vec4 sSample3 = sampleInput1(sTemp3);

      // 组合第一个视频的RGB通道
      vec4 sRgbSplit1 = vec4(0.0);
      sRgbSplit1.ra += sSample1.ra;
      sRgbSplit1.g += sSample2.g;
      sRgbSplit1.b += sSample3.b;
      sRgbSplit1.rgb *= sRgbSplit1.a;

      // 采样第二个视频的不同UV位置（也应用RGB分离）
      float sTexY1 = 0.5 + (sTemp1.y - 0.5) / aspect;
      sTexY1 = clamp(sTexY1, 0.5 - halfRange, 0.5 + halfRange);
      float sAdjustedY1 = (sTexY1 - (0.5 - halfRange)) / (2.0 * halfRange);

      float sTexY2 = 0.5 + (sTemp2.y - 0.5) / aspect;
      sTexY2 = clamp(sTexY2, 0.5 - halfRange, 0.5 + halfRange);
      float sAdjustedY2 = (sTexY2 - (0.5 - halfRange)) / (2.0 * halfRange);

      float sTexY3 = 0.5 + (sTemp3.y - 0.5) / aspect;
      sTexY3 = clamp(sTexY3, 0.5 - halfRange, 0.5 + halfRange);
      float sAdjustedY3 = (sTexY3 - (0.5 - halfRange)) / (2.0 * halfRange);

      vec4 sSample2_1 = INPUT2(vec2(sTemp1.x, sAdjustedY1));
      vec4 sSample2_2 = INPUT2(vec2(sTemp2.x, sAdjustedY2));
      vec4 sSample2_3 = INPUT2(vec2(sTemp3.x, sAdjustedY3));

      // 组合第二个视频的RGB通道
      vec4 sRgbSplit2 = vec4(0.0);
      sRgbSplit2.ra += sSample2_1.ra;
      sRgbSplit2.g += sSample2_2.g;
      sRgbSplit2.b += sSample2_3.b;
      sRgbSplit2.rgb *= sRgbSplit2.a;

      // 混合第一个视频（RGB分离）和第二个视频（RGB分离）
      vec4 sMixed = mix(sRgbSplit1, sRgbSplit2, 1.0 - blendFactor);

      resultRGB += sMixed.rgb * weight;
      totalWeight += weight;
    }

    vec3 finalRGB;
    if(totalWeight > 0.0) {
      finalRGB = resultRGB / totalWeight;
    } else {
      finalRGB = mixedColor.rgb;
    }

    return mixedColor;
  }

  // 不在RGB分离时间段内，正常处理
  vec4 blurredResult = motionBlurFunc(tc, blurRotateValue, 90.0);
  return blurredResult;
}

