#ifdef GL_ES
precision highp float;
#endif

float compute(vec2 p, float progress, vec2 center) {
	float PI = 3.14159265358979323846264;
	float amplitude = 1.0;
	float waves = 30.0;
	vec2 o = p*sin(progress * amplitude)-center;
	// horizontal vector
	vec2 h = vec2(1., 0.);
	// butterfly polar function (don't ask me why this one :))
	float theta = acos(dot(o, h)) * waves;
	float temp = sin((2.*theta - PI) / 24.);
	temp = temp*temp*temp*temp*temp; 
	return (exp(cos(theta)) - 2.*cos(4.*theta) + temp ) / 10.;
}

vec4 FUNCNAME(vec2 tc) {
	float progress = PREFIX(global_time)/PREFIX(total_time);
	float colorSeparation = 0.3;
	vec4 fragOutColor;
	vec2 p = tc;
	float inv = 1. - progress;
	vec2 dir = p - vec2(.5);
	float dist = length(dir);
	float disp = compute(p, progress, vec2(0.5, 0.5)) ;
	vec4 texTo = INPUT2(p + inv*disp);
	vec4 texFrom = vec4(
	INPUT1(p + progress*disp*(1.0 - colorSeparation)).r,
	INPUT1(p + progress*disp).g,
                    INPUT1(p + progress*disp*(1.0 + colorSeparation)).b,
                    INPUT1(p + progress*disp*(1.0 - colorSeparation)).a);
	return texTo*progress + texFrom*inv;
}

#define PI 3.14159265359
#define TAU 6.283185307179

vec4 chooseImage(vec2 uv, int index) {
  if (index == 1) {
    return INPUT3(uv);
  } else if (index == 2) {
    return INPUT4(uv);
  } else if (index == 3) {
    return INPUT5(uv);
  } else if (index == 4) {
    return INPUT6(uv);
  } else if (index == 5) {
    return INPUT7(uv);
  } else if (index >= 6 && index <= 8) {
    return INPUT8(uv);
  } else if (index == 9) {
    return INPUT9(uv);
  } else if (index == 10) {
    return INPUT10(uv);
  } else if (index == 11) {
    return INPUT11(uv);
  } else {
    return vec4(0.0);
  }
}

float normpdf(vec2 v, float sigma) {
  float sigma_quad = sigma * sigma;
  return (1.0 / (TAU * sigma_quad)) * exp(-0.5 * dot(v, v) / sigma_quad);
}

vec4 CalGaussBlurColor(vec2 tc, int radius, float sigma, int index) {
  float weight = 0.0;
  vec4 retColor = vec4(0.0);

  vec2 res = vec2(720.0, 540.0);
  for (int i = -radius; i <= radius; i++) {
    for (int j = -radius; j <= radius; j++) {
      vec2 offset = vec2(i, j);
      float g = normpdf(offset, sigma);
      if (index == 1) {
        retColor += g * INPUT1(tc + offset / res);
      } else if (index == 2) {
        retColor += g * INPUT2(tc + offset / res);
      }
      weight += g;
    }
  }
  return retColor / weight;
}

float calBrightValue(float bright) {
  float brightValue = 0.0;
  if (bright > 0.0) {
    brightValue = 1.0 + bright / 100.0;
  } else {
    brightValue = 1.0 - 1.0 / (0.99 + bright / 253.0);
    brightValue *= 0.6;
  }
  return brightValue;
}

vec4 calBrightnessColor(vec4 color, float brightness) {
  float bright = calBrightValue(brightness);
  vec4 ret;
  if (bright > 0.0)
    ret = color * bright;
  else
    ret = color + bright;

  ret.w = color.w;
  ret = clamp(ret, vec4(0.0), vec4(1.0));
  return ret;
}

vec4 ScreenBlend(vec4 back, vec4 blend) {
  return 1.0 - (1.0 - back) * (1.0 - blend);
}

float timeCurveFunc(float t) {
  t = 2.0 * t - 1.0;
  if (t < 0.0) {
    return 1.0 - pow(max(0.0, abs(t) * 2.0 - 1.0), 3.5);
  } else {
    return pow(cos(PI * t / 2.0), 3.5);
  }
}

