#define NOISE_SIMPLEX_1_DIV_289 0.00346020761245674740484429065744

vec2 mod289(vec2 x){
	return x - floor(x * NOISE_SIMPLEX_1_DIV_289) * 289.0;
}

vec3 mod289(vec3 x){
	return x - floor(x * NOISE_SIMPLEX_1_DIV_289) * 289.0;
}

vec3 permute(vec3 x){
	return mod289(x * x * 34.0 + x);
}

vec3 taylorInvSqrt(vec3 r){
	return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec2 v){
	const vec4 C = vec4(0.211324865405187,    // (3.0-sqrt(3.0))/6.0
                        0.366025403784439,    // 0.5*(sqrt(3.0)-1.0)
                       -0.577350269189626,  // -1.0 + 2.0 * C.x
                        0.024390243902439);   // 1.0 / 41.0
	// First corner
	vec2 i = floor(v + dot(v, C.yy));
	vec2 x0 = v - i + dot(i, C.xx);

	// Other corners
	vec2 i1;
	i1.x = step(x0.y, x0.x);
	i1.y = 1.0 - i1.x;

	vec2 x1 = x0 + C.xx - i1;
	vec2 x2 = x0 + C.zz;

	// Permutations
	i = mod289(i); // Avoid truncation effects in permutation
	vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));

	vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x1, x1), dot(x2, x2)), 0.0);
	m = m * m;
	m = m * m;

	// Gradients: 41 points uniformly over a line, mapped onto a diamond.
	// The ring size 17*17 = 289 is close to a multiple of 41 (41*7 = 287)
	vec3 x = 2.0 * fract(p * C.www) - 1.0;
	vec3 h = abs(x) - 0.5;
	vec3 ox = floor(x + 0.5);
	vec3 a0 = x - ox;

	// Normalise gradients implicitly by scaling m
	m *= taylorInvSqrt(a0 * a0 + h * h);

	// Compute final noise value at P
	vec3 g;
	g.x = a0.x * x0.x + h.x * x0.y;
	g.y = a0.y * x1.x + h.y * x1.y;
	g.z = a0.z * x2.x + h.z * x2.y;
	return 130.0 * dot(m, g);
}

vec4 DirBlur(vec2 uv, vec2 dir) {
  float sigma = 4.0;
  float weight = normpdf(0.0, sigma);

  vec4 sum = vec4(0.0);
  vec4 result = vec4(0.0);
  vec2 unit_uv = dir;
  float gamma = 2.2;
  vec4 curColor = INPUT1(uv);
  vec4 centerPixel = pow(curColor, vec4(gamma)) * weight;
  float sum_weight = weight;
  float s = 64.0;
  for (int i = 1; i <= 64; i++) {
    vec2 curRightCoordinate = uv + float(i) * unit_uv;
    vec2 curLeftCoordinate = uv + float(-i) * unit_uv;
    vec4 rightColor = INPUT1(curRightCoordinate);
    vec4 leftColor = INPUT1(curLeftCoordinate);
    weight = normpdf(float(i) / s * 15.0, sigma);
    sum += pow(rightColor, vec4(gamma)) * weight;
    sum += pow(leftColor, vec4(gamma)) * weight;
    sum_weight += weight * 2.0;
  }
  result = (sum + centerPixel) / sum_weight;
  result = pow(result, vec4(1.0 / gamma));
  return clamp(result, 0.0, 1.0);
}

