float layerEdgeCoverage(vec2 uv) {
    float sd = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
    float fw = max(length(vec2(dFdx(sd), dFdy(sd))) * 2.0, 1e-5);
    return smoothstep(-fw, fw, sd);
}

float roundedRectMask(vec2 uv, float radiusParam, float fadeParam) {
    float minEdge = min(iResolution.x, iResolution.y);
    float halfMinEdge = minEdge * 0.5;
    float radiusPx = halfMinEdge * (radiusParam / 256.0);
    if (radiusPx < 0.5) {
        return 1.0;
    }
    vec2 halfRes = iResolution.xy * 0.5;
    vec2 p = uv * iResolution.xy;
    vec2 d = abs(p - halfRes) - (halfRes - vec2(radiusPx));
    float dist = length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0) - radiusPx;
    float fade0 = -(halfMinEdge * fadeParam / 256.0) - 0.1;
    float fade1 = 0.0;
    return smoothstep(fade0, fade1, -dist);
}

vec2 cardUV() {
    float invW = vInvW;
    if (invW < 1e-6) {
        invW = 1e-6;
    }
    return vUVOverW / invW;
}

// [@pass:uStep=0] 压暗 A 后 5x5 盒模糊（已降采样）
vec4 featureDarkBlur(vec2 tc) {
    vec2 texel = 1.0 / iResolution.xy;
    vec3 dark = vec3(0.08627451211214);
    vec4 sum = vec4(0.0);
    float weightSum = 0.0;
    for (float y = -2.0; y <= 2.0; y += 1.0) {
        for (float x = -2.0; x <= 2.0; x += 1.0) {
            vec4 s = INPUT1(tc + vec2(x, y) * texel);
            s.rgb = mix(s.rgb, dark, 0.9);
            sum += s;
            weightSum += 1.0;
        }
    }
    vec4 blurred = sum / max(weightSum, 1.0);
    blurred.a = 1.0;
    vec4 keepB = INPUT2(tc);
    blurred.rgb += keepB.rgb * 0.0;
    return blurred;
}

// [@pass:uStep=1] 全屏直出
vec4 featureBlit(vec2 tc) {
    vec4 colorA = INPUT1(tc);
    vec4 colorB = INPUT2(tc);
    return vec4(colorA.rgb + colorB.rgb * 0.0, 1.0);
}

// [@pass:uStep=2] 孤立卡片
vec4 featureCard(vec2 tc) {
    vec2 uv = cardUV();
    vec4 colorA = INPUT1(uv);
    vec4 colorB = INPUT2(uv);
    vec4 src = colorA;
    if (PREFIX(uCardId) == 1) {
        src = colorB;
    }
    float alpha = src.a;
    alpha *= roundedRectMask(uv, PREFIX(uCornerRadius), PREFIX(uCornerFade));
    if (PREFIX(uEdgeAA) == 1) {
        alpha *= layerEdgeCoverage(uv);
    }
    src.rgb *= alpha;
    src.a = alpha;
    return src;
}

vec4 FUNCNAME(vec2 tc) {
    int uStep = PREFIX(uStep);
    if (uStep == 0) {
        return featureDarkBlur(tc);
    }
    if (uStep == 2) {
        return featureCard(tc);
    }
    return featureBlit(tc);
}

customize_in vec2 vUV;

vec4 DirectBlur(vec2 uv, float blurRadius, float rotateRad, int iteration) {
  float sinVal = sin(rotateRad) * blurRadius * 0.05 / float(iteration);
  float cosVal = cos(rotateRad) * blurRadius * 0.05 / float(iteration);
  vec2 direction = vec2(cosVal, sinVal);
  vec4 color = vec4(0.0);
  color = INPUT1(uv);
  for (int k = 1; k < iteration; k++) {
    vec2 curUV = uv - direction * float(k);
    vec2 curUV2 = uv + direction * float(k);
    color += INPUT1(curUV);
    color += INPUT1(curUV2);
  }
  vec4 finalColor = color / max(float(iteration) * 2.0 - 1.0, 1.0);
  return finalColor;
}

float rand(vec2 co) {
  return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453) * 2.0 - 1.0;
}

vec4 motionBlur(vec2 _st, vec2 dir, float iterNum) {
  vec2 texCoord = _st.xy;
  vec3 color = vec3(0.0);
  float total = 0.0;
  float offset = rand(_st);
  vec4 inputCol = INPUT1(_st);

  if (inputCol.a > 0.0) {
    for (float t = 0.0; t <= iterNum; t += 1.0) {
      float percent = (t + offset) / iterNum;
      float weight = 4.0 * (percent - percent * percent);
      color += INPUT1(fract(texCoord - dir * percent)).rgb * weight;
      total += weight;
    }
    color /= total;
  }
  return vec4(color * inputCol.a, inputCol.a);
}

