float channelHash(vec2 p, float t)
{
    return fract(sin(dot(p, vec2(12.9898, 78.233)) + t * 100.0) * 43758.5453);
}

vec4 channelAlignTransition(vec2 tc, float p)
{
    float ratio = iResolution.x / max(iResolution.y, 1.0);
    float shakeMax = PREFIX(shakeMax);
    float scanlinePower = PREFIX(scanlinePower);
    float noisePower = PREFIX(noisePower);
    float distortionPower = PREFIX(distortionPower);

    float shake = shakeMax * smoothstep(0.6, 0.9, p) * smoothstep(1.0, 0.9, p);
    float distortion = distortionPower * (1.0 - p);
    float scanlineIntensity = scanlinePower * (1.0 - p);
    float noiseIntensity = noisePower * (1.0 - p);

    vec2 centeredUV = tc * 2.0 - 1.0;
    centeredUV.x *= ratio;
    float dist = length(centeredUV);
    vec2 distortedUV = centeredUV * (1.0 + distortion * dist * dist);
    distortedUV.x /= ratio;
    distortedUV = distortedUV * 0.5 + 0.5;

    vec2 rOffset = vec2(0.0, distortion * 0.5) * (1.0 - p)
                 + shake * (vec2(fract(sin(p * 100.0) * 10.0) - 0.5,
                                  fract(cos(p * 90.0) * 10.0) - 0.5));
    vec2 gOffset = vec2(-distortion * 0.4, -distortion * 0.2) * (1.0 - p)
                 + shake * (vec2(fract(sin(p * 110.0) * 10.0) - 0.5,
                                  fract(cos(p * 80.0) * 10.0) - 0.5));
    vec2 bOffset = vec2(distortion * 0.4, distortion * 0.3) * (1.0 - p)
                 + shake * (vec2(fract(sin(p * 120.0) * 10.0) - 0.5,
                                  fract(cos(p * 70.0) * 10.0) - 0.5));

    vec2 rUV = clamp(distortedUV + rOffset, 0.0, 1.0);
    vec2 gUV = clamp(distortedUV + gOffset, 0.0, 1.0);
    vec2 bUV = clamp(distortedUV + bOffset, 0.0, 1.0);
    vec4 colorA = INPUT1(distortedUV);
    vec4 colorB = INPUT2(distortedUV);

    float r = mix(INPUT1(rUV).r, INPUT2(rUV).r, p);
    float g = mix(INPUT1(gUV).g, INPUT2(gUV).g, p);
    float b = mix(INPUT1(bUV).b, INPUT2(bUV).b, p);
    float a = mix(colorA.a, colorB.a, p);

    float scanline = sin(tc.y * 480.0 * 3.14159) * 0.5 + 0.5;
    scanline = scanline * scanlineIntensity + 1.0 - scanlineIntensity;
    r *= scanline; g *= scanline; b *= scanline;

    float noise = channelHash(tc, p);
    r += noise * noiseIntensity; g += noise * noiseIntensity; b += noise * noiseIntensity;

    vec3 rgb = clamp(vec3(r, g, b), 0.0, 1.0);
    return vec4(rgb, a);
}

vec4 FUNCNAME(vec2 tc) {
    float progress = clamp(PREFIX(iProgress), 0.0, 1.0);
    // [@规则:R-T01][@规则:R-T05] 双输入与端点闭合。
    vec4 colorA = INPUT1(tc);
    vec4 colorB = INPUT2(tc);
    const float fadeInEnd = 0.1;
    const float fadeOutStart = 0.9;
    float inner = clamp((progress - fadeInEnd) / (fadeOutStart - fadeInEnd), 0.0, 1.0);
    vec4 transitionColor = channelAlignTransition(tc, inner);
    float blendIn = smoothstep(0.0, fadeInEnd, progress);
    float blendOut = smoothstep(fadeOutStart, 1.0, progress);
    vec4 result = mix(colorA, transitionColor, blendIn);
    return mix(result, colorB, blendOut);
}

