    float progress = clamp((iGlobalTime - iTotalTime * delay_ratio) / (iTotalTime * duration_ratio), 0.0, 1.0);

    vec4 p = vec4(.6,.23,.47,.84);
    progress = KeySpline(p, progress);

    vec2 uv0 = tc;
