// Collage Turn · frag
// uMeshMode=0 端点 Blit；uMeshMode=1 透明空间 + 3x3 卡片 + 中心 B 叠层。

customize_in vec2 vUV;
customize_in vec2 vUVOverW;
customize_in float vInvW;
customize_in float vSource;

float layerEdgeCoverage(vec2 uv) {
    // [@规则:R-AA-01] 孤立卡片：UV 0/1 内侧约 2px 覆盖率，与底色混合。
    float sd = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
    float fw = max(length(vec2(dFdx(sd), dFdy(sd))) * 2.0, 1e-5);
    return smoothstep(-fw, fw, sd);
}

vec4 FUNCNAME(vec2 tc) {
    float p = PREFIX(iProgress);
    if (p < 0.0) {
        p = 0.0;
    }
    if (p > 1.0) {
        p = 1.0;
    }

    if (PREFIX(uMeshMode) == 0) {
        // [@规则:R-T05] p=0 只显示 A，p=1 只显示 B。
        if (p <= 0.0) {
            return INPUT1(tc);
        }
        return INPUT2(tc);
    }

    float invW = vInvW;
    if (invW < 0.000001) {
        invW = 0.000001;
    }
    vec2 uv = vUVOverW / invW;
    uv = clamp(uv, vec2(0.0), vec2(1.0));

    vec4 color = INPUT1(uv);
    if (vSource > 0.5) {
        color = INPUT2(uv);
    }

    if (vSource > 2.5) {
        float overlayAlpha = PREFIX(uOverlayAlpha);
        if (overlayAlpha < 0.0) {
            overlayAlpha = 0.0;
        }
        if (overlayAlpha > 1.0) {
            overlayAlpha = 1.0;
        }
        color *= overlayAlpha;
    }

    // [@规则:R-AA-01] 孤立卡片 + 旋转/透视斜边：覆盖率乘进 rgba，与下层轨道混合。
    if (PREFIX(uEdgeAA) == 1) {
        color *= layerEdgeCoverage(vUV);
    }
    // 图片小于卡片时的透明区：discard 不写深度，避免遮挡后面一层卡片。
    if (color.a < 0.01) {
        discard;
    }
    return color;
}

#define M_PI (3.1415926535897932384626433832795)
#define EPSILON (0.000001)

vec3 permute(vec3 x) { return mod(((x * 34.0) + 1.0) * x, 289.0); }

float snoise(vec2 v) {
  const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626,
                      0.024390243902439);
  vec2 i = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);
  vec2 i1;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod(i, 289.0);
  vec3 p =
      permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
  vec3 m = max(
      0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

float wes_smooth(float x, float th) {
  return x <= th ? 0.0 : (x - th) / (1.0 - th);
}

float GetProcess(float time) { 
  return min(0.36, 0.4 * time / PREFIX(total_time));
}

float GetScale(float time) {
  float process = GetProcess(time);
  float frame_rate = PREFIX(frame_rate);
  float frame_offset = GetProcess(1. / frame_rate);
  float half_frame_offset = frame_offset * 0.49;
  float scale = 0.0;
  for (float shake_time = 0.2; shake_time <= 1.; shake_time += 0.2) {
    if (step(shake_time - frame_offset * 5., process) *
            step(process, shake_time + frame_offset * 5.) >
        0.) {
      scale = smoothstep(shake_time - half_frame_offset * 5.,
                         shake_time - half_frame_offset, process) *
              (1. - smoothstep(shake_time + half_frame_offset,
                               shake_time + half_frame_offset * 5., process));
      break;
    }
  }
  return scale;
}

float GetExposure(float time) {
  float process = GetProcess(time);
  float frame_rate = PREFIX(frame_rate);
  float frame_offset = GetProcess(1. / frame_rate);
  float half_frame_offset = frame_offset * 0.49;
  float scale = 0.0;
  scale += smoothstep(0.0, 0.05, process) *
           pow(1. - smoothstep(0.05, 0.10, process), 0.5) * 0.2;
  scale += smoothstep(0.05, 0.10, process) *
           pow(1. - smoothstep(0.10, 0.15, process), 0.5) * 0.4;
  scale += smoothstep(0.10, 0.15, process) *
           pow(1. - smoothstep(0.15, 0.20, process), 0.5) * 0.6;
  for (float shake_time = 0.2; shake_time <= 1.; shake_time += 0.2) {
    if (step(shake_time - frame_offset * 5., process) *
            step(process, shake_time + frame_offset * 20.) >
        0.) {
      scale +=
          smoothstep(shake_time - half_frame_offset * 5.,
                     shake_time - half_frame_offset, process) *
          pow(1. - smoothstep(shake_time + half_frame_offset,
                              shake_time + half_frame_offset * 20., process),
              0.5);
    }
  }
  return scale;
}

float GetDark(float time) {
  float process = GetProcess(time);
  float frame_rate = PREFIX(frame_rate);
  float frame_offset = GetProcess(1. / frame_rate);
  float half_frame_offset = frame_offset * 0.49;
  float scale = 0.0;
  scale += smoothstep(0.02, 0.035, process) *
           pow(1. - smoothstep(0.035, 0.085, process), 0.5) * 0.2;
  scale += smoothstep(0.035, 0.085, process) *
           pow(1. - smoothstep(0.085, 0.135, process), 0.5) * 0.4;
  scale += smoothstep(0.085, 0.135, process) *
           pow(1. - smoothstep(0.135, 0.185, process), 0.5) * 0.6;
  for (float shake_time = 0.18; shake_time <= 1.; shake_time += 0.2) {
    if (step(shake_time - frame_offset * 2., process) *
            step(process, shake_time + frame_offset * 2.) >
        0.) {
      scale += smoothstep(shake_time - half_frame_offset * 2.,
                          shake_time - half_frame_offset, process) *
               (1. - smoothstep(shake_time + half_frame_offset,
                                shake_time + half_frame_offset * 2., process));
    }
  }
  return scale;
}

float GetRedLine(float time) {
  float process = GetProcess(time);
  float frame_rate = PREFIX(frame_rate);
  float frame_offset = GetProcess(1. / frame_rate);
  float half_frame_offset = frame_offset * 0.49;
  float scale = 0.0;
  scale +=
      pow(1. - smoothstep(0., 0.2 + half_frame_offset * 20., process), 0.5);
  return scale;
}

vec2 GetOffset(float time) {

  float process = PREFIX(process);
  vec2 offset = vec2(snoise(vec2(time)), snoise(vec2(-time)));
  offset = (offset - 0.5) * 2.;
  offset = pow(abs(offset), vec2(0.1, 0.1)) *
           vec2(-0.1 * sign(offset.x), 0.05 * sign(offset.y));
  return offset * (1.0 - smoothstep(0.5, 0.6, process));
}

float normpdf(in float x, in float sigma) {
  return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

float blendScreen(float base, float blend) {
  return 1.0 - ((1.0 - base) * (1.0 - blend));
}

vec3 blendScreen(vec3 base, vec3 blend) {
  return vec3(blendScreen(base.r, blend.r), blendScreen(base.g, blend.g),
              blendScreen(base.b, blend.b));
}

vec4 gaussianBlur(vec2 uv, vec2 dir) {
  float sigma = 4.0;
  float weight = normpdf(0.0, sigma);

  vec4 sum = vec4(0.0);
  vec4 result = vec4(0.0);
  vec2 unit_uv = dir;
  float gamma = 2.2;
  vec4 curColor = INPUT1(uv);
  vec4 centerPixel = pow(curColor, vec4(gamma)) * weight;
  float sum_weight = weight;
  float s = 64.0;
  for (int i = 1; i <= 64; i++) {
    vec2 curRightCoordinate = uv + float(i) * unit_uv;
    vec2 curLeftCoordinate = uv + float(-i) * unit_uv;
    vec4 rightColor = INPUT1(curRightCoordinate);
    vec4 leftColor = INPUT1(curLeftCoordinate);
    weight = normpdf(float(i) / s * 15.0, sigma);
    sum += pow(rightColor, vec4(gamma)) * weight;
    sum += pow(leftColor, vec4(gamma)) * weight;
    sum_weight += weight * 2.0;
  }
  result = (sum + centerPixel) / sum_weight;
  result = pow(result, vec4(1.0 / gamma));
  return clamp(result, 0.0, 1.0);
}

vec4 Exposure(vec4 col, float _intensity, float _offset,
              float _gray_scale_correct, float _linear) {
  if (_linear < 0.5)
    col.rgb = pow(col.rgb, vec3(2.2));
  col.rgb *= pow(2.0, _intensity);
  col.rgb += _offset;
  vec3 s = sign(col.rgb);
  col.rgb = pow(abs(col.rgb), vec3(1.0 / _gray_scale_correct)) * s;
  s = sign(col.rgb);
  if (_linear < 0.5)
    col.rgb = pow(abs(col.rgb), vec3(0.454545454545)) * s;
  return col;
}

vec4 RedLine0(vec2 tc) {
  vec2 mySize = iResolution.xy / min(iResolution.x, iResolution.y) * 720.;
  vec2 offset = vec2(0.0, 1.) * vec2(1.) / mySize;
  float weight0 = normpdf(0.0, 4.);
  vec4 resultCol = INPUT1(tc) * weight0;
  float num = weight0;
  for (int i = 1; i <= 8; i++) {
    float j = float(i);
    float tempWeight = normpdf(j, 4.);
    resultCol += INPUT1(tc + j * offset) * tempWeight;
    resultCol += INPUT1(tc - j * offset) * tempWeight;
    num += 2.0 * tempWeight;
  }
  resultCol /= num;

  return vec4(resultCol);
}

vec4 RedLine1(vec2 tc) {
  float time = PREFIX(global_time);
  vec2 mySize = iResolution.xy / min(iResolution.x, iResolution.y) * 720.;
  vec2 offset = vec2(0.0, 1.) * vec2(1.) / mySize;
  float weight0 = normpdf(0.0, 4.);
  vec4 resultCol = INPUT2(tc) * weight0;
  float num = weight0;
  for (int i = 1; i <= 8; i++) {
    float j = float(i);
    float tempWeight = normpdf(j, 4.);
    resultCol += INPUT2(tc + j * offset) * tempWeight;
    resultCol += INPUT2(tc - j * offset) * tempWeight;
    num += 2.0 * tempWeight;
  }
  resultCol /= num;
  vec4 oriCol = INPUT1(tc);
  vec3 col = abs(oriCol.rgb - resultCol.rgb);
  float gray = dot(col, vec3(0.299, 0.587, 0.114));
  oriCol.rgb =
      mix(oriCol.rgb, blendScreen(oriCol.rgb, vec3(255., 255., 44.) / 255.),
          4. * gray * GetRedLine(time));
  return vec4(oriCol);
}

vec4 BaseMove(vec2 tc) {
  float time = PREFIX(global_time);
  float scale = GetScale(time) + 0.1;
  float intensity = float(PREFIX(Intensity)) / 100.0;

  vec2 offset = GetOffset(time * 3.);
  tc += offset * scale * intensity * 2.;
  return INPUT1(tc);
}

vec4 DirBlur(vec2 tc) {
  float time = PREFIX(global_time);
  vec2 ratio = 720.0 * iResolution.xy / min(iResolution.x, iResolution.y);
  vec2 offset = GetOffset(time * 3.) * GetScale(time);
  float frame_rate = PREFIX(frame_rate);
  vec2 pre_offset = GetOffset(time - (1.0 / frame_rate)) *
                    GetScale(time - (1.0 / frame_rate));
  vec2 dir = (offset - pre_offset) / ratio;
  float blur = float(PREFIX(Blur)) / 100.0;
  vec4 color = gaussianBlur(tc, dir * 20. * blur);
  return color;
}

vec4 Atmosphere(vec2 tc) {
  float time = PREFIX(global_time);
  float scale = GetExposure(time) * float(PREFIX(Atmosphere)) / 100.0;
  float process = GetProcess(time);
  vec4 col = INPUT1(tc);
  float ori_a = col.a;
  col = Exposure(col, 0.0, 0.0,
                 1.0, 1.0);
  col = mix(col, vec4(0, 0, 0, ori_a), 0.7 * GetDark(time));
  col = Exposure(col, 1.2 * scale, 0.0,
                 1.0, 1.0);
  return col;
}

vec4 GlowMask(vec2 tc) {
  vec4 inputColor = INPUT1(tc);

  inputColor.rgb =
      mix(inputColor.rgb, vec3(1.0), 0.5) * inputColor.a;

  float threshold = 1.0 - (float(PREFIX(Radius)) / 100.0) * 0.4;

  vec3 color = vec3(0.0722, 0.7152, 0.2126) * 0.1;
  float r = wes_smooth(inputColor.r, threshold + color.r);
  float g = wes_smooth(inputColor.g, threshold + color.g);
  float b = wes_smooth(inputColor.b, threshold + color.b);
  float a = wes_smooth(inputColor.a, threshold);
  float brightness =
      (r + g + b) / max(inputColor.r + inputColor.g + inputColor.b, EPSILON);
  return vec4(inputColor.rgb * brightness, a);
}

vec4 GaussianBlur(vec2 tc) {
  const int mSize = 25;
  const int kSize = (mSize - 1) / 2;
  const float sigma = 7.0;
  float kernel[mSize];

  vec2 fragCoord = tc * iResolution.xy;

  float blur_size = (float(PREFIX(Size)) / 100.0) * 15.0;

  if (PREFIX(horizontal) == 1) {
    vec3 res = vec3(0.0);

    float Z = 0.0;
    for (int j = 0; j <= kSize; ++j) {
      kernel[kSize + j] = kernel[kSize - j] = normpdf(float(j), sigma);
    }

    for (int j = 0; j < mSize; ++j) {
      Z += kernel[j];
    }

    for (int i = -kSize; i <= kSize; ++i) {
      res += kernel[kSize + i] *
             INPUT2((fragCoord.xy + vec2(float(i) * blur_size, 0.0)) / iResolution.xy).rgb;
    }

    return vec4(res / Z, 1.0);
  } else {

    vec3 res = vec3(0.0);
    float Z = 0.0;
    for (int j = 0; j <= kSize; ++j) {
      kernel[kSize + j] = kernel[kSize - j] = normpdf(float(j), sigma);
    }

    for (int j = 0; j < mSize; ++j) {
      Z += kernel[j];
    }

    for (int i = -kSize; i <= kSize; ++i) {
      res += kernel[kSize + i] *
             INPUT2((fragCoord.xy + vec2(0.0, float(i) * blur_size)) / iResolution.xy).rgb;
    }

    return vec4(res / Z, 1.0);
  }
  return vec4(0.0);
}

#define BlendScreen(base, blend) (1.0 - (1.0 - base) * (1.0 - blend))

vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
vec4 Blend(vec2 tc) {
  float time = PREFIX(global_time);
  float scale = GetExposure(time) * (1.0 - smoothstep(0.5, 0.6, PREFIX(process)));
  vec4 inputColor = INPUT1(tc);
  float sourceOpacity = 0.8 + (smoothstep(0.5, 0.6, PREFIX(process)) * 0.2);

  vec4 bgColor = vec4(0.0, 0.0, 0.0, inputColor.a);
  bgColor = mix(bgColor, inputColor, sourceOpacity);
  bgColor *= 1.0 + 0.25 * scale;

  vec4 blurColor = INPUT2(tc);

  blurColor.rgb *= vec3(255., 255., 44.) / 255.;

  float brightness = float(PREFIX(Glow)) / 100.0;
  blurColor.rgb *= 3.5 * brightness * scale;

  vec4 fgBlurColor = blurColor;
  fgBlurColor = mix(fgBlurColor, mix(fgBlurColor, inputColor, sourceOpacity * (1.0 - smoothstep(0.5, 0.6, PREFIX(process)))),
                    0.5);

  return vec4(BlendScreen(bgColor.rgb, fgBlurColor.rgb), inputColor.a);
}

vec4 FUNCNAME(vec2 tc) {

  vec4 col = vec4(0.);

  int step_ = PREFIX(step_);
  if (step_ == 0) {
    return BaseMove(tc);
  } else if (step_ == 1) {
    return RedLine0(tc);
  } else if (step_ == 2) {
    return RedLine1(tc);
  } else if (step_ == 3) {
    return DirBlur(tc);
  } else if (step_ == 4) {
    return Atmosphere(tc);
  } else if (step_ == 5) {
    return GlowMask(tc);
  } else if (step_ == 6) {
    return GaussianBlur(tc);
  } else if (step_ == 7) {
    return Blend(tc);
  }

  return col;
}

