vec4 ReadLocalTexture1(vec2 tc){
    float aspect = iResolution.x / iResolution.y;
    vec2 uv = vec2(tc.x - 0.5, tc.y - 0.5);
    vec2 texResolution = vec2(800.0, 450.0);
    if(aspect < 1.0){
        uv.x *= (texResolution.y / texResolution.x) * aspect;
    }else{
        uv.y *= (texResolution.x / texResolution.y) * (1.0 / aspect);
    }
    uv = vec2(uv.x + 0.5, uv.y + 0.5);

    return INPUT3(vec2(uv.x,1.0-  uv.y));
}
vec4 ReadLocalTexture2(vec2 tc){
    float aspect = iResolution.x / iResolution.y;
    vec2 uv = vec2(tc.x - 0.5, tc.y - 0.5);
    vec2 texResolution = vec2(450.0, 800.0);
    if(aspect < 1.0){
        uv.x *= (texResolution.y / texResolution.x) * aspect;
    }else{
        uv.y *= (texResolution.x / texResolution.y) * (1.0 / aspect);
    }
    uv = vec2(uv.x + 0.5, uv.y + 0.5);

    return INPUT4(vec2(uv.x,1.0-  uv.y));
}
vec4 step01(vec2 uv, float Itime) {
    vec4 color1 = INPUT1(uv);
    vec4 color2 = INPUT2(uv);
    vec4 res = vec4(0.0);
    float mappedTime = max(0.0, (Itime - 0.35) / 0.65);
    if(mappedTime <= 0.35) {
        res = color1;
    }
    else {
        res = color2;
    }
    return res;

}
vec4 FUNCNAME(vec2 tc)
{

