    if (originalTime < 0.35) {
        return INPUT1(tc);
    }

    float Itime = max(0.0, (originalTime - 0.35) / 0.65); 
    vec4 resColor = vec4(0.0);  

    vec2 uv = tc;
    vec4 back = vec4(0.0);
    if(iResolution.x > iResolution.y){
        back = ReadLocalTexture1(uv);
    }

    else{
        back = ReadLocalTexture2(uv);
    }
    back .rgb *= back.a;

    if (Type == 0) {
        resColor = step01(tc, originalTime);  
    }
    else if (Type == 1) {
        float ine = mix(mix(1.0,2.0,clamp(Itime*5.0, 0.0, 1.0)), 1.0, clamp(Itime*3.0, 0.0, 1.0));
        vec4 color2 = RGBmove(uv,Itime);
        vec4 mes = mix(color2,back,back.a);

        float gray = rgb2gray(mes.rgb);
        mes.rgb = mix(vec3(gray)*ine,mes.rgb,Itime);

        resColor = mes;
    }

    return resColor;
}

