vec2 SetScale(vec2 uv, vec2 center, vec2 scale) {
	uv -= center;
	uv *= scale;
	uv += center;
	return uv;
}

float CalculateLuminance(vec4 color) {
    return dot(color.rgb, vec3(0.299, 0.587, 0.114));
}

vec4 ApplyDiagonalGrid(vec4 baseColor, vec2 uv) {
    float gridLineThickness = 0.005;
    float gridLineSpacing = 0.02;

    float diag1 = mod(uv.x + uv.y, gridLineSpacing);
    float diag2 = mod(uv.x - uv.y + gridLineSpacing, gridLineSpacing);

    float line1 = step(diag1, gridLineThickness);
    float line2 = step(diag2, gridLineThickness);

    float gridMask = max(line1, line2);

    vec4 result = baseColor * 2.0;
    result.rgb = mix(result.rgb, vec3(0.0), gridMask);

    return result;
}

vec4 Lut3DFilter(vec4 textureColor, float opacity, vec3 colorTint){

    float blueColor = textureColor.r * 63.0;

    vec2 quad1;
    quad1.y = floor(floor(blueColor) / 8.0);
    quad1.x = floor(blueColor) - (quad1.y * 8.0);
    vec2 quad2;
    quad2.y = floor(ceil(blueColor) /8.0);
    quad2.x = ceil(blueColor) - (quad2.y * 8.0);
    vec2 texPos1;
    texPos1.x = (quad1.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
    texPos1.y = (quad1.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
    vec2 texPos2;
    texPos2.x = (quad2.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
    texPos2.y = (quad2.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);

    vec4 newColor1 = INPUT6(vec2(texPos1.x, texPos1.y));
    vec4 newColor2 = INPUT6(vec2(texPos2.x, texPos2.y));
    vec4 newColor = mix(newColor1, newColor2, vec4(fract(blueColor)));

    vec4 lutResult = mix(textureColor, vec4(newColor.rgb, textureColor.a), vec4(opacity));

    float luminance = dot(lutResult.rgb, vec3(0.299, 0.587, 0.114));
    vec3 tintedColor = mix(lutResult.rgb, colorTint * luminance * 1.5, vec3(0.4 * opacity));

    vec4 fragOutCol = vec4(tintedColor, lutResult.a);
    fragOutCol.a = textureColor.a;
    fragOutCol.rgb *= fragOutCol.a;
    return fragOutCol;
}

bool IsAboveLine1(vec2 uv) {
    float lineY = 0.5 * uv.x + 0.5;
    return uv.y > lineY;
}

bool IsAboveLine2(vec2 uv) {
    float lineY = -0.5 * uv.x + 0.5;
    return uv.y > lineY;
}

bool IsNearLine1(vec2 uv, float distance) {
    float lineY = 0.5 * uv.x + 0.5;
    float verticalDistance = abs(uv.y - lineY);
    float adjustedDistance = verticalDistance / sqrt(1.0 + 0.5 * 0.5);
    return adjustedDistance < distance;
}

bool IsNearLine2(vec2 uv, float distance) {
    float lineY = -0.5 * uv.x + 0.5;
    float verticalDistance = abs(uv.y - lineY);
    float adjustedDistance = verticalDistance / sqrt(1.0 + (-0.5) * (-0.5));
    return adjustedDistance < distance;
}

float GetDistanceToLine1(vec2 uv) {
    float lineY = 0.5 * uv.x + 0.5;
    float verticalDistance = abs(uv.y - lineY);
    float adjustedDistance = verticalDistance / sqrt(1.0 + 0.5 * 0.5);
    return adjustedDistance;
}

float GetDistanceToLine2(vec2 uv) {
    float lineY = -0.5 * uv.x + 0.5;
    float verticalDistance = abs(uv.y - lineY);
    float adjustedDistance = verticalDistance / sqrt(1.0 + (-0.5) * (-0.5));
    return adjustedDistance;
}

bool IsNearLine(vec2 uv, float distance) {
    return IsNearLine1(uv, distance) || IsNearLine2(uv, distance);
}

float noise(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}

vec4 ApplyInput3Glitch(vec2 tc, float intensity, float speed) {
	float time = PREFIX(uCurTime);
	float y = tc.y;
	float noiseValue = noise(vec2(y * 20.0, time * speed));
	float noiseOffset = (noiseValue * 2.0 - 1.0) * intensity;
	vec2 glitchTc = vec2(tc.x + noiseOffset, tc.y);
	glitchTc = clamp(glitchTc, 0.001, 0.999);
	return INPUT3(glitchTc);
}

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

/*
 * @param aX: 传入时间变量
 * @param p1/p2: 贝塞尔曲线两个控制点
 * 说明: 这个函数以上的其他函数都是本函数使用的辅助函数
 */
float KeySpline(vec4 p, float aX) {
  float mX1 = p.x;
  float mY1 = p.y;
  float mX2 = p.z;
  float mY2 = p.w;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

