					resultColor = mix(INPUT1(tc), INPUT4(tc), INPUT4(tc).a);
				}
			} else if (subCurTime < 0.8) {

				if (IsAboveLine1(tc)) {
					resultColor = mix(INPUT1(tc), humanBlurColorTop, maskTop.r);
				} else {
					if (!IsAboveLine1(tc) && IsAboveLine2(tc)) {
						resultColor = mix(INPUT1(tc), humanBlurColorMiddle, maskMiddle.r);
