					line1Offset = mix(0.00, 0.05, (subCurTime - 0.82) / 0.04);
				} else {
					line1Offset = mix(0.05, 0.0, (subCurTime - 0.86) / 0.04);
				}
				float line2Offset;
				if (subCurTime < 0.85) {
					line2Offset = mix(0.00, -0.05, (subCurTime - 0.82) / 0.04);
				} else {
					line2Offset = mix(-0.05, 0.0, (subCurTime - 0.86) / 0.04);
				}
				vec2 line1NewUVVar = tc + line1Vector * line1Offset;
				vec2 line2NewUVVar = tc + line2Vector * line2Offset;
				if (IsNearLine(line1NewUVVar, featherDistance)) {
