						if (!IsAboveLine2(tc)) {
							resultColor = mix(INPUT1(tc), humanBlurColorBottom, maskBottomVar.r);
						} else {
							resultColor = INPUT1(tc);
						}
					}
				}
			} else {
				resultColor = mix(INPUT1(tc), humanBlurColor, mask.r);
			}
		} else {
			resultColor = INPUT3(tc);
		}
	} else {
		float subCurTime =  (uCurTime - startFlash) / (endFlash - startFlash);
		if (uCurTime < endFlash) {
			vec2 uv = SetScale(tc, vec2(0.5), vec2(mix(1.0, 0.8, uAnimeFg)));
			if (subCurTime >= 0.8 && subCurTime < 0.95) {
