// Cosmic Gallery · frag
// [@规则:R-T01][@规则:R-T05][@规则:R-UV-01][@规则:R-AA-01][@规则:R-ALPHA-01]
// uStep=0 3D 卡片；uStep=1 宇宙黑底；uStep=2 径向/方向模糊+曝光；uStep=3/4 端点；uStep=5 FBO 直出。

customize_in vec2 vUVOverW;
customize_in float vInvW;

// 透视校正 UV：vert 传 UV/w 与 1/w，此处除回，消除倾斜卡片仿射插值的对角弯折。
vec2 cardUV() {
    float invW = vInvW;
    if (invW < 1e-6) {
        invW = 1e-6;
    }
    return vUVOverW / invW;
}

float layerEdgeCoverage(vec2 uv) {
    float sd = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
    float fw = max(length(vec2(dFdx(sd), dFdy(sd))) * 2.0, 1e-5);
    return smoothstep(-fw, fw, sd);
}

vec4 sampleAB(vec2 uv, int texId) {
    vec4 tap = INPUT1(uv);
    if (texId == 1) {
        tap = INPUT2(uv);
    }
    return tap;
}

// [@pass:uStep=0] 孤立 3D 照片卡，FilterData 直采 vUV。
vec4 featureCard(vec2 tc) {
    int texId = PREFIX(uTexId);
    float opacity = PREFIX(uOpacity);
    vec2 uv = cardUV();
    vec4 src = sampleAB(uv, texId);
    float alpha = src.a * opacity;
    if (PREFIX(uEdgeAA) == 1) {
        alpha *= layerEdgeCoverage(uv);
    }
    return vec4(src.rgb * alpha, alpha);
}

// [@pass:uStep=1] 透明底（宇宙空隙留空，透出下方图层）。仅承载 FBO 清空。
vec4 featureBlack(vec2 tc) {
    return vec4(0.0, 0.0, 0.0, 0.0);
}

vec2 clampUv(vec2 uv) {
    return clamp(uv, vec2(0.0), vec2(1.0));
}

// [@pass:uStep=2] 径向 Straight Zoom → 单向运动模糊 → 曝光。径向与方向模糊时间窗几乎不重叠。
vec4 featurePost(vec2 tc) {
    float radialAmt = PREFIX(uRadial);
    float dirAmt = PREFIX(uDirBlur);
    float exposure = PREFIX(uExposure);
    vec4 col = INPUT1(tc);
    int i = 0;

    if (abs(radialAmt) > 0.0005) {
        vec2 center = vec2(0.5, 0.5);
        vec2 delta = (tc - center) * radialAmt;
        vec4 acc = vec4(0.0);
        float wsum = 0.0;
        for (i = 0; i < 10; i++) {
            float t = float(i) / 9.0;
            float w = 1.0 - t * 0.55;
            vec2 uv = clampUv(tc - delta * t);
            acc += INPUT1(uv) * w;
            wsum += w;
        }
        col = acc / max(wsum, 1e-5);
    }

    if (dirAmt > 0.5) {
        float radius = dirAmt / 1000.0;
        float startAngle = radians(-173.0);
        vec2 stepUv = vec2(cos(startAngle), sin(startAngle)) * (radius / 12.0);
        vec4 acc = col;
        float wsum = 1.0;
        for (i = 1; i <= 12; i++) {
            float fi = float(i);
            float w = exp(-0.5 * (fi / 12.0) * (fi / 12.0));
            vec2 uvP = clampUv(tc + stepUv * fi);
            vec2 uvM = clampUv(tc - stepUv * fi);
            acc += INPUT1(uvP) * w;
            acc += INPUT1(uvM) * w;
            wsum += w * 2.0;
        }
        col = acc / max(wsum, 1e-5);
    }

    if (abs(exposure) > 0.001) {
        vec3 lin = pow(max(col.rgb, vec3(0.0)), vec3(2.2));
        lin *= pow(2.0, exposure);
        col.rgb = pow(max(lin, vec3(0.0)), vec3(1.0 / 2.2));
    }
    return col;
}

