float normpdf(float x, float sigma){
	return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

vec4 motionBlur(vec2 tc, vec2 direction, float blur, float scale) {
	float sigma = 28.0;
	float weight = normpdf(0.0, sigma);
    vec2 center = vec2(0.5);
    vec2 uv1 = tc;
    vec2 uv = tc;
    uv1 /= scale;
    vec4 retCol = INPUT3(uv + center);
	retCol *= weight;
	float sum = weight;
	float radius = 0.05 * blur;

	for(float j = 1.0; j < 21.0; j += 1.0)
	{
		weight = normpdf(j / 10.0 * 25.0, sigma);
		float offset = radius * j;
		vec2 uv = uv1 + direction * offset;
		retCol += INPUT3(uv + center) * weight;
		sum += weight;

		uv = uv1 - direction * offset;
		retCol += INPUT3(uv + center) * weight;
		sum += weight;
	}
	retCol /= sum;
	retCol = clamp(retCol, 0.0, 1.0);
	return retCol;
}

vec2 rotate(vec2 uv, float angle) {
    return vec2(uv.x * cos(angle) - uv.y * sin(angle), uv.x * sin(angle) + uv.y * cos(angle));
}

