    fragColor = motionBlur(uv / iResolution.xy, direction, blur, scale);
    // alpha *= (1.0 - time) * 1.2; 
    fragColor.rgb *= alpha;
    return fragColor; 
}

vec2 SetScale(vec2 uv, vec2 center, vec2 scale) {
	uv -= center;
	uv *= scale;
	uv += center;
	return uv;
}

bool IsInBackgroundRangeLR(vec2 uv) {
	vec4 texColor = INPUT5(uv);
	if (texColor.r >= 0.49 && texColor.r <= 0.51 && texColor.g >= 0.49 && texColor.g <= 0.51 && texColor.b >= 0.49 && texColor.b <= 0.51) {
		return true;
	}
	return false;
}

bool IsInBackgroundRangeUD(vec2 uv) {
	vec4 texColor = INPUT6(uv);
	if (texColor.r >= 0.3 && texColor.r <= 0.32 && texColor.g >= 0.49 && texColor.g <= 0.51 && texColor.b >= 0.49 && texColor.b <= 0.51) {
		return true;
	}
	return false;
}

float GetLuminance(vec3 color) {
	return dot(color, vec3(0.299, 0.587, 0.114));
}

vec4 ExtractHighlights(vec2 uv, float threshold) {
	vec4 texColor = INPUT2(uv) * 1.5;
	float luminance = GetLuminance(texColor.rgb);
	if (luminance > threshold) {
		return mix(texColor, vec4(1.0), 0.2);
	}
	return vec4(0.0);
}

float noise(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}

vec4 ApplyInput2Glitch(vec2 tc, float intensity, float speed) {
	float time = PREFIX(uCurTime);
	float y = tc.y;
	float noiseValue = noise(vec2(y * 20.0, time * speed));
	float noiseOffset = (noiseValue * 2.0 - 1.0) * intensity;
	vec2 glitchTc = vec2(tc.x + noiseOffset, tc.y);
	glitchTc = clamp(glitchTc, 0.001, 0.999);
	return INPUT2(glitchTc);
}

vec4 ApplyInput4DiagonalStripes(vec2 uv, float alphaThreshold, float stripeDensity, float stripeIntensity) {
	vec4 originalColor = INPUT4(uv);

	if (originalColor.a > alphaThreshold) {
		float totalLines = stripeDensity;
		float linePos = (uv.x + uv.y) * totalLines;
		int lineIndex = int(floor(linePos));

		int isDarkLine = int(mod(float(lineIndex), 3.0));

		vec4 darkLineColor = vec4(0.0, 0.0, 0.0, mix(0.0, 0.15, stripeIntensity));

		float darkenFactor = mix(0.95, 1.0, 1.0 - stripeIntensity);

		vec4 finalColor;

		if (isDarkLine == 0) {
			finalColor = mix(originalColor, darkLineColor, darkLineColor.a);
		} else {
			finalColor = originalColor * vec4(vec3(darkenFactor), 1.0);
		}

		finalColor.a = originalColor.a;
		return finalColor;
	}

	return originalColor;
}

vec4 FUNCNAME(vec2 tc) {
	float curTime = PREFIX(uCurTime);
	float uAnimeFg = PREFIX(uAnimeFg);
	float uAnimeBg = PREFIX(uAnimeBg);
	float fgAnimeTime0 = 0.05;
	float fgAnimeTime1 = 0.1;
	float fgAnimeTime2 = 0.15;
	float fgAnimeTime3 = 0.2;
	float fgAnimeTime4 = 0.25;
	float fgAnimeTime5 = 0.3;
	float fgAnimeTime6 = 0.35;
	float fgAnimeTime7 = 0.4;
	float fgAnimeTime8 = 0.45;


	if (PREFIX(uStep) == 0) {
		return ExtractHighlights(tc, 0.1);
	} else if (PREFIX(uStep) == 2) {
		return curTime >= 0.47 && curTime <= 0.53 ? ApplyInput2Glitch(tc, 0.1, 0.05) : INPUT2(tc);
	}

	// return clamp(INPUT2(tc) + ApplyInput4DiagonalStripes(tc, 0.5, 200, 0.8), 0.0, 1.0);
	// return INPUT4(tc);
	// return ApplyInput4DiagonalStripes(tc, 0.8, 200, 0.5);

	vec4 resultColor = vec4(0.0);
	if (curTime < 0.5) {
		vec2 st = tc;

		if (curTime >= fgAnimeTime0 && curTime < fgAnimeTime2) {
			resultColor = tc.x < 0.5 ? mix(INPUT1(st), INPUT5(st), INPUT5(st).a) : INPUT1(st);
		} else if (curTime >= fgAnimeTime2 && curTime < fgAnimeTime4) {
			resultColor = mix(INPUT1(st), INPUT5(st), INPUT5(st).a);
		} else if (curTime >= fgAnimeTime4 && curTime < fgAnimeTime6) {
			resultColor = mix(INPUT1(st), INPUT5(st), INPUT5(st).a);
			resultColor = tc.y > 0.5 ? mix(resultColor, INPUT6(st), INPUT6(st).a) : resultColor;
		} else if (curTime >= fgAnimeTime6 && curTime < 0.5) {
			resultColor = mix(INPUT1(st), INPUT5(st), INPUT5(st).a);
			resultColor = mix(resultColor, INPUT6(st), INPUT6(st).a);
		} else if (curTime < fgAnimeTime0) {
			resultColor = INPUT1(st);
		}

		if (IsInBackgroundRangeLR(st)) {
			if (curTime < fgAnimeTime0) {
				resultColor = INPUT1(st);
			} else if (curTime >= fgAnimeTime0 && curTime < fgAnimeTime1) {
				resultColor = tc.x < 0.5 ? clamp(INPUT2(st) * 1.5 + INPUT4(st), 0.0, 1.0) : INPUT1(st);
			} else if (curTime >= fgAnimeTime1 && curTime < fgAnimeTime2) {
				resultColor = tc.x < 0.5 ? INPUT2(st) : INPUT1(st);
			} else if (curTime >= fgAnimeTime2 && curTime < fgAnimeTime3) {
				resultColor = tc.x < 0.5 ? INPUT2(st) : clamp(INPUT2(st) * 1.5 + INPUT4(st), 0.0, 1.0);
			} else if (curTime >= fgAnimeTime3 && curTime < fgAnimeTime4) {
				resultColor = INPUT2(st);
			} else {
				resultColor = INPUT2(st);
			}
		}

		if (IsInBackgroundRangeUD(st)) {
			if (curTime >= fgAnimeTime4 && curTime < fgAnimeTime5) {
				resultColor = tc.y > 0.5 ? clamp(INPUT2(st) * 1.5 + INPUT4(st), 0.0, 1.0) : resultColor;
			} else if (curTime >= fgAnimeTime5 && curTime < fgAnimeTime6) {
				resultColor = tc.y > 0.5 ? INPUT2(st) : resultColor;
			} else if (curTime >= fgAnimeTime6 && curTime < fgAnimeTime7) {
				resultColor = tc.y > 0.5 ? INPUT2(st) : clamp(INPUT2(st) * 1.5 + INPUT4(st), 0.0, 1.0);
			} else if (curTime >= fgAnimeTime7 && curTime < fgAnimeTime8) {
				resultColor = INPUT2(st);
			} else if (curTime >= fgAnimeTime8) {
				resultColor = INPUT2(st);
			}
		}

		resultColor = mix(resultColor, INPUT1(st), INPUT3(st).r);
	} else {
		vec2 st = SetScale(tc, vec2(0.5), vec2(mix(0.95, 1.0, uAnimeBg)));
		if (curTime >= 0.6) {
			resultColor = clamp(INPUT2(st) + ApplyInput4DiagonalStripes(st, 0.5, 200.0, 0.8) * mix(1.0, 0.0, uAnimeBg), 0.0, 1.0);
		} else {
			resultColor = clamp(INPUT2(st) + ApplyInput4DiagonalStripes(st, 0.5, 200.0, 0.8), 0.0, 1.0);
		}
	}

	return resultColor;
}

// ==========================================
// Cross Transition
// Two tilted rectangular strips crossing the
// screen in opposite directions with white borders.
// Strip 1 (INPUT1, +40 deg) moves left to right (top layer).
// Strip 2 (INPUT2, -40 deg) moves right to left (bottom layer).
// ==========================================

vec4 FUNCNAME(vec2 tc) {
    // Animation progress
    float progress1 = PREFIX(Anim01);  // Strip 1: slower
    float progress2 = PREFIX(Anim02);  // Strip 2: faster

    // User parameters
    float scaleParam = float(PREFIX(Scale)) / 100.0;
    float strengthParam = float(PREFIX(Strength)) / 100.0;

    // Aspect ratio & portrait/landscape adaptation
    float aspect = iResolution.x / iResolution.y;
    float refAspect = 16.0 / 9.0;
    float aspectAdj = min(aspect / refAspect, 1.0);  // 1.0 for landscape, <1 for portrait

    // Strip geometry (scaled for consistent screen-width coverage)
    float angle = radians(-20.0);
    float strip1HalfWidth = (0.18 + scaleParam * 0.14) * aspectAdj;   // Strip 1: wider
    float strip2HalfWidth = (0.12 + scaleParam * 0.10) * aspectAdj;   // Strip 2: narrower
    float borderWidth = (0.001 + strengthParam * 0.010) * aspectAdj;   // border scales with strip
    float stripHalfHeight = 2.0;                         // tall enough to always cover screen
    float aaWidth = 1.5 / iResolution.y;                 // ~1.5px anti-aliasing (pixel-based for crisp edges)

    // Movement: off-screen margins must account for rotation
    // A tilted strip's horizontal extent (in tc space) from center =
    //   (halfWidth + |sin(angle)| * 0.5) / (aspect * |cos(angle)|)
    float maxHW = max(strip1HalfWidth, strip2HalfWidth);
    float sinA = abs(sin(angle));
    float cosA = abs(cos(angle));
    float offMargin = (maxHW + sinA * 0.5) / (aspect * cosA) + 0.05;
    float offLeft  = -offMargin;
    float offRight =  1.0 + offMargin;

    float cx1 = mix(offLeft, offRight, progress1);   // Strip 1: left -> right (slower)
    float cx2 = mix(offRight, offLeft, progress2);   // Strip 2: right -> left (faster)

    // --- Background wipe: use Strip 2's left edge as dividing line ---
    // Compute Strip 2's local x coordinate for this pixel
    vec2 d2bg = tc - vec2(cx2, 0.5);
    d2bg.x *= aspect;
    float ca2 = cos(angle);
    float sa2 = sin(angle);
    float wipeLocal = d2bg.x * ca2 - d2bg.y * sa2;

    // Wipe boundary at Strip 2's left edge: right of it -> INPUT2, left -> INPUT1
    float wipeLine = -strip2HalfWidth;
    float wipeBlend = smoothstep(wipeLine - aaWidth, wipeLine + aaWidth, wipeLocal);
    float bgProgress = max(progress1, progress2);
    vec4 result = mix(INPUT1(tc), INPUT2(tc), wipeBlend);

    // --- Strip 2 (INPUT2, bottom layer) ---
    {
        vec2 d = tc - vec2(cx2, 0.5);
        d.x *= aspect;
        float ca = cos(angle);
        float sa = sin(angle);
        vec2 local2 = vec2(d.x * ca - d.y * sa, d.x * sa + d.y * ca);

        float distX = abs(local2.x) - strip2HalfWidth;
        float distY = abs(local2.y) - stripHalfHeight;
        float dist = max(distX, distY);

        if (dist < aaWidth) {
            float alpha = 1.0 - smoothstep(-aaWidth, aaWidth, dist);

            // Border: white at edges of the strip
            float borderDist = abs(local2.x) - (strip2HalfWidth - borderWidth);
            float borderAlpha = smoothstep(-aaWidth, aaWidth, borderDist);

            // Shift UV to the right for offset effect
            vec2 shiftedTC = tc + vec2(0.08, 0.0);
            shiftedTC = clamp(shiftedTC, vec2(0.0), vec2(1.0));
            vec4 stripColor = INPUT4(shiftedTC);  // Blurred INPUT2 with right offset
            vec4 color = mix(stripColor, vec4(1.0, 1.0, 1.0, 1.0), borderAlpha);

            result = mix(result, color, alpha);
        }
    }

    // --- Strip 1 (INPUT1, top layer, rendered last) ---
    {
        vec2 d = tc - vec2(cx1, 0.5);
        d.x *= aspect;
        float ca = cos(-angle);
        float sa = sin(-angle);
        vec2 local1 = vec2(d.x * ca - d.y * sa, d.x * sa + d.y * ca);

        float distX = abs(local1.x) - strip1HalfWidth;
        float distY = abs(local1.y) - stripHalfHeight;
        float dist = max(distX, distY);

        if (dist < aaWidth) {
            float alpha = 1.0 - smoothstep(-aaWidth, aaWidth, dist);

            // Border: white at edges of the strip
            float borderDist = abs(local1.x) - (strip1HalfWidth - borderWidth);
            float borderAlpha = smoothstep(-aaWidth, aaWidth, borderDist);

            // Zoom in (scale from center)
            vec2 zoomedTC = (tc - 0.5) * 0.8 + 0.5;
            zoomedTC = clamp(zoomedTC, vec2(0.0), vec2(1.0));
            vec4 stripColor = INPUT3(zoomedTC);  // Blurred INPUT1 zoomed in
            vec4 color = mix(stripColor, vec4(1.0, 1.0, 1.0, 1.0), borderAlpha);

            result = mix(result, color, alpha);
        }
    }

    return result;
}

#define PI 3.14159265359

// add
float blendAdd(float base, float blend)
{
    return min(base + blend, 1.0);
}

vec3 blendAdd(vec3 base, vec3 blend)
{
    return min(base + blend, vec3(1.0));
}

// average
vec3 blendAverage(vec3 base, vec3 blend)
{
    return (base + blend) / 2.0;
}

// color burn
float blendColorBurn(float base, float blend)
{
    return (blend == 0.0) ? blend : max((1.0 - ((1.0 - base) / blend)), 0.0);
}

vec3 blendColorBurn(vec3 base, vec3 blend)
{
    return vec3(blendColorBurn(base.r, blend.r), blendColorBurn(base.g, blend.g), blendColorBurn(base.b, blend.b));
}

// color dodge
float blendColorDodge(float base, float blend)
{
    return (blend == 1.0) ? blend : min(base / (1.0 - blend), 1.0);
}

vec3 blendColorDodge(vec3 base, vec3 blend)
{
    return vec3(blendColorDodge(base.r, blend.r), blendColorDodge(base.g, blend.g), blendColorDodge(base.b, blend.b));
}

// darken
float blendDarken(float base, float blend)
{
    return min(blend, base);
}

vec3 blendDarken(vec3 base, vec3 blend)
{
    return vec3(blendDarken(base.r, blend.r), blendDarken(base.g, blend.g), blendDarken(base.b, blend.b));
}

// difference
vec3 blendDifference(vec3 base, vec3 blend)
{
    return abs(base - blend);
}

// exclusion
vec3 blendExclusion(vec3 base, vec3 blend)
{
    return base + blend - 2.0 * base * blend;
}

// reflect
float blendReflect(float base, float blend)
{
    return (blend == 1.0) ? blend : min(base * base / (1.0 - blend), 1.0);
}

vec3 blendReflect(vec3 base, vec3 blend)
{
    return vec3(blendReflect(base.r, blend.r), blendReflect(base.g, blend.g), blendReflect(base.b, blend.b));
}

// glow
vec3 blendGlow(vec3 base, vec3 blend)
{
    return blendReflect(blend, base);
}

// hard light
float blendHardLight(float base, float blend)
{
    return base < 0.5 ? (2.0 * base * blend) : (1.0 - 2.0 * (1.0 - base) * (1.0 - blend));
}

vec3 blendHardLight(vec3 base, vec3 blend)
{
    return vec3(blendHardLight(base.r, blend.r), blendHardLight(base.g, blend.g), blendHardLight(base.b, blend.b));
}

// hard mix
float blendHardMix(float base, float blend)
{
    if (blend < 0.5)
    {
        float vividLight = blendColorBurn(base, (2.0 * blend));
        return (vividLight < 0.5) ? 0.0 : 1.0;
    }
    else
    {
        float vividLight = blendColorDodge(base, (2.0 * (blend - 0.5)));
        return (vividLight < 0.5) ? 0.0 : 1.0;
    }
}

vec3 blendHardMix(vec3 base, vec3 blend)
{
    return vec3(blendHardMix(base.r, blend.r), blendHardMix(base.g, blend.g), blendHardMix(base.b, blend.b));
}

// lighten
float blendLighten(float base, float blend)
{
    return max(blend, base);
}

vec3 blendLighten(vec3 base, vec3 blend)
{
    return vec3(blendLighten(base.r, blend.r), blendLighten(base.g, blend.g), blendLighten(base.b, blend.b));
}

// linear burn
float blendLinearBurn(float base, float blend)
{
    return max(base + blend - 1.0, 0.0);
}

vec3 blendLinearBurn(vec3 base, vec3 blend)
{
    return max(base + blend - vec3(1.0), vec3(0.0));
}

// linear dodge
float blendLinearDodge(float base, float blend)
{
    return min(base + blend, 1.0);
}

vec3 blendLinearDodge(vec3 base, vec3 blend)
{
    return min(base + blend, vec3(1.0));
}

// linear light
float blendLinearLight(float base, float blend)
{
    return blend < 0.5 ? blendLinearBurn(base, (2.0 * blend)) : blendLinearDodge(base, (2.0 * (blend - 0.5)));
}

vec3 blendLinearLight(vec3 base, vec3 blend)
{
    return vec3(blendLinearLight(base.r, blend.r), blendLinearLight(base.g, blend.g), blendLinearLight(base.b, blend.b));
}

// multiply
vec3 blendMultiply(vec3 base, vec3 blend)
{
    return base * blend;
}

// negation
vec3 blendNegation(vec3 base, vec3 blend)
{
    return vec3(1.0) - abs(vec3(1.0) - base - blend);
}

// overlay
float blendOverlay(float base, float blend)
{
    return base < 0.5 ? (2.0 * base * blend) : (1.0 - 2.0 * (1.0 - base) * (1.0 - blend));
}

vec3 blendOverlay(vec3 base, vec3 blend)
{
    return vec3(blendOverlay(base.r, blend.r), blendOverlay(base.g, blend.g), blendOverlay(base.b, blend.b));
}

// phoenix
vec3 blendPhoenix(vec3 base, vec3 blend)
{
    return min(base, blend) - max(base, blend) + vec3(1.0);
}

// pin light
float blendPinLight(float base, float blend)
{
    return (blend < 0.5) ? blendDarken(base, (2.0 * blend)) : blendLighten(base, (2.0 * (blend - 0.5)));
}

vec3 blendPinLight(vec3 base, vec3 blend)
{
    return vec3(blendPinLight(base.r, blend.r), blendPinLight(base.g, blend.g), blendPinLight(base.b, blend.b));
}

// screen
float blendScreen(float base, float blend)
{
    return 1.0 - ((1.0 - base) * (1.0 - blend));
}

vec3 blendScreen(vec3 base, vec3 blend)
{
    return vec3(blendScreen(base.r, blend.r), blendScreen(base.g, blend.g), blendScreen(base.b, blend.b));
}

// soft light
float blendSoftLight(float base, float blend)
{
    return (blend < 0.5) ? (2.0 * base * blend + base * base * (1.0 - 2.0 * blend)) : (sqrt(base) * (2.0 * blend - 1.0) + 2.0 * base * (1.0 - blend));
}

vec3 blendSoftLight(vec3 base, vec3 blend)
{
    return vec3(blendSoftLight(base.r, blend.r), blendSoftLight(base.g, blend.g), blendSoftLight(base.b, blend.b));
}

// substract
float blendSubstract(float base, float blend)
{
    return max(base + blend - 1.0, 0.0);
}

vec3 blendSubstract(vec3 base, vec3 blend)
{
    return max(base + blend - vec3(1.0), vec3(0.0));
}

// vivid light
float blendVividLight(float base, float blend)
{
    return (blend < 0.5) ? blendColorBurn(base, (2.0 * blend)) : blendColorDodge(base, (2.0 * (blend - 0.5)));
}

vec3 blendVividLight(vec3 base, vec3 blend)
{
    return vec3(blendVividLight(base.r, blend.r), blendVividLight(base.g, blend.g), blendVividLight(base.b, blend.b));
}

// snow color
vec3 RGBToHSL(vec3 color)
{
    vec3 hsl;
    float fmin = min(min(color.r, color.g), color.b);
    float fmax = max(max(color.r, color.g), color.b);
    float delta = fmax - fmin;

    hsl.z = (fmax + fmin) / 2.0;

    if (delta == 0.0)
    {
        hsl.x = 0.0;
        hsl.y = 0.0;
    }
    else
    {
        if (hsl.z < 0.5)
            hsl.y = delta / (fmax + fmin);
        else
            hsl.y = delta / (2.0 - fmax - fmin);

        float deltaR = (((fmax - color.r) / 6.0) + (delta / 2.0)) / delta;
        float deltaG = (((fmax - color.g) / 6.0) + (delta / 2.0)) / delta;
        float deltaB = (((fmax - color.b) / 6.0) + (delta / 2.0)) / delta;

        if (color.r == fmax)
            hsl.x = deltaB - deltaG;
        else if (color.g == fmax)
            hsl.x = (1.0 / 3.0) + deltaR - deltaB;
        else if (color.b == fmax)
            hsl.x = (2.0 / 3.0) + deltaG - deltaR;

        if (hsl.x < 0.0)
            hsl.x += 1.0;
        else if (hsl.x > 1.0)
            hsl.x -= 1.0;
    }

    return hsl;
}

float HueToRGB(float f1, float f2, float hue)
{
    if (hue < 0.0)
        hue += 1.0;
    else if (hue > 1.0)
        hue -= 1.0;
    float res;
    if ((6.0 * hue) < 1.0)
        res = f1 + (f2 - f1) * 6.0 * hue;
    else if ((2.0 * hue) < 1.0)
        res = f2;
    else if ((3.0 * hue) < 2.0)
        res = f1 + (f2 - f1) * ((2.0 / 3.0) - hue) * 6.0;
    else
        res = f1;
    return res;
}

vec3 HSLToRGB(vec3 hsl)
{
    vec3 rgb;

    if (hsl.y == 0.0)
        rgb = vec3(hsl.z);
    else
    {
        float f2;

        if (hsl.z < 0.5)
            f2 = hsl.z * (1.0 + hsl.y);
        else
            f2 = (hsl.z + hsl.y) - (hsl.y * hsl.z);

        float f1 = 2.0 * hsl.z - f2;

        rgb.r = HueToRGB(f1, f2, hsl.x + (1.0 / 3.0));
        rgb.g = HueToRGB(f1, f2, hsl.x);
        rgb.b = HueToRGB(f1, f2, hsl.x - (1.0 / 3.0));
    }

    return rgb;
}

vec3 blendSnowColor(vec3 blend, vec3 bgColor)
{
    vec3 blendHSL = RGBToHSL(blend);
    vec3 hsl = RGBToHSL(bgColor);
    return HSLToRGB(vec3(blendHSL.r, blendHSL.g, hsl.b));
}

// snow hue
vec3 blendSnowHue(vec3 blend, vec3 bgColor)
{
    vec3 baseHSL = RGBToHSL(bgColor.rgb);
    return HSLToRGB(vec3(RGBToHSL(blend.rgb).r, baseHSL.g, baseHSL.b));
}

vec3 blendFunc(vec3 base, vec3 blend, float opacity, int blendMode)
{
    if (blendMode == 1)
        return (blendAdd(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 2)
        return (blendAverage(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 3)
        return (blendColorBurn(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 4)
        return (blendColorDodge(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 5)
        return (blendDarken(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 6)
        return (blendDifference(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 7)
        return (blendExclusion(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 8)
        return (blendGlow(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 9)
        return (blendHardLight(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 10)
        return (blendHardMix(base, blend) * opacity + base * (1.0 - opacity));
