vec4 shiftColor(vec2 iuv, float iglobalTime)
{
    float Quality = 3.0;
    float Size = 8.0;
    vec2 Radius = Size / iResolution.xy;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 cur_uv = iuv;
    vec4 oriColor = vec4(0.0);
    if(iglobalTime <= 0.5) {
        oriColor = INPUT1(cur_uv);
    } else {
        oriColor = INPUT2(cur_uv);
    }

    // Pixel colour
    vec4 Color = vec4(0.0);
    Color = INPUT3(cur_uv);
    for( float d=0.0; d<3.0; d++)
    {
		for(float i=1.0/Quality; i<=1.0; i+=1.0/Quality)
        {   
            Color += INPUT3(cur_uv+vec2(cos(d),sin(d))*Radius*i) * vec4(oriColor.rgb+vec3(0.5), 1.0);
        }
    }

    // Output to screen
    //Color.a /= Quality * Directions - 15.0;

    return Color;
}

vec4 FUNCNAME(vec2 tc){
    vec2 uv = tc;
    float iGlobalTime = PREFIX(global_time)/PREFIX(total_time);
    float process = min(max(0.0, iGlobalTime - 0.25), 0.5) / 0.5;
    float strength = pow(((1.0-abs(1.0-2.0*process))), 6.0);
    vec2 center = vec2(0.5);

    vec2 zoom_uv = uv;
    zoom_uv -= center;
    zoom_uv *= 1.0 - strength;
    zoom_uv += center;
    vec4 fragOutCol = vec4(0.0);
    if(iGlobalTime < 0.5) {
        fragOutCol = INPUT1(zoom_uv);
    } else {
        fragOutCol = INPUT2(zoom_uv);
    }

    vec3 color = fragOutCol.rgb;
    vec3 luminanceWeighting = vec3(0.2125, 0.7154, 0.0721);
    vec3 brightColor = color + vec3(strength*5.0);
    vec3 contrastColor = brightColor;
    vec3 greyScaleColor = vec3(dot(contrastColor, luminanceWeighting));
    color = vec3(mix(greyScaleColor, contrastColor, 1.0 + strength*10.0));
    vec4 bloom = shiftColor(zoom_uv, process);
    // vec4 bloom = INPUT3(zoom_uv);
    bloom = vec4(bloom.rgb*color+fragOutCol.rgb, fragOutCol.a);
    fragOutCol = mix(fragOutCol, bloom, strength);

    return fragOutCol;
}

customize_in vec2 vUV;
customize_in float vIndex;

// 计算圆角遮罩
// 正确的圆角矩形SDF：到矩形边界的有符号距离，内部<0，外部>0，边界=0
float roundedBoxMask(vec2 uv, float radius, float smoothness) {
    vec2 centered = uv - 0.5;
    // q：以圆角圆心为基准的偏移量
    // q>0 表示在圆角区域（可能在圆角外），q<0 表示在安全矩形内
    vec2 q = abs(centered) - (0.5 - radius);
    // 标准圆角矩形SDF：
    // - 角落区域：length(max(q,0)) - radius（到圆弧的距离）
    // - 直边区域：max(q.x,q.y) - 0（到直边的距离，内部为负）
    // 统一公式：length(max(q,0)) + min(max(q.x,q.y),0.0) - radius
    float sdf = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - radius;
    // sdf<0为内部，sdf=0为边界，sdf>0为外部
    float alpha = 1.0 - smoothstep(-smoothness, smoothness, sdf);

    return alpha;
}

vec4 InputCoordinate(vec2 uv) {

  float transitionProgress = PREFIX(transitionProgress);

  if(vIndex < 1.5){
    if(transitionProgress > 0.55) {
      return vec4(INPUT2(uv).rgb, 1.0);
    } else {
      return vec4(INPUT1(uv).rgb, 1.0);
    }
  }
  else if(vIndex < 2.5){
    if(transitionProgress > 0.65) {
      vec2 flippedUV = vec2(1.0 - uv.x, uv.y); 
      return vec4(INPUT1(flippedUV).rgb, 1.0);}
    else if(transitionProgress > 0.18) {
      vec2 flippedUV = vec2(1.0 - uv.x, uv.y); 
      return vec4(INPUT2(flippedUV).rgb, 1.0);
    } else {
      return vec4(INPUT1(uv).rgb, 1.0);
    }
  }else if(vIndex < 3.5){
    if(transitionProgress > 0.7) {
      return vec4(INPUT2(uv).rgb, 1.0);
    } else {
      return vec4(INPUT1(uv).rgb, 1.0);
    }
  } else if(vIndex < 4.5){
    return vec4(INPUT1(uv).rgb, 1.0);
  } else {
    return vec4(INPUT2(uv).rgb, 1.0);
  }
}

float normpdf(in float x, in float sigma)
{
  return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}

vec4 texture2Dmirror(vec2 uv) {
  uv = mod(uv, 2.0);
  uv = mix(uv, 2.0 - uv, step(vec2(1.0), uv));
  return InputCoordinate(fract(uv));
}

vec4 directionBlurFunc(vec2 tc, float strength, float angle)
{
  float theta = angle* 3.1415926 / 180.0;
  vec2 rect = vec2(min(720.0, 720.0 * iResolution.x / iResolution.y), min(720.0, 720.0 * iResolution.y / iResolution.x));
  vec2 dir = vec2(cos(theta), sin(theta)) / rect;

  float sigma = 4.0;
  float weight = normpdf(0.0, sigma);

  vec4 sum            = vec4(0.0);
  vec4 result         = vec4(0.0);
  vec2 unitUv        = dir * 6.0;
  float gamma         = 1.0;
  vec4 curColor       = InputCoordinate(tc);
  vec4 centerPixel    = pow(curColor, vec4(gamma))*weight;
  float sumWeight    = weight;

  for(int i=1;i<=100;i++)
  {
      if (float(i)>strength) break;
      vec2 curRightCoordinate = tc+float(i)*unitUv;
      vec2 curLeftCoordinate  = tc+float(-i)*unitUv;
      vec4 rightColor = texture2Dmirror(curRightCoordinate);
      vec4 leftColor = texture2Dmirror(curLeftCoordinate);
      weight = normpdf(float(i) / strength * 15.0, sigma);
      sum+=pow(rightColor, vec4(gamma))*weight;
      sum+=pow(leftColor, vec4(gamma))*weight;
      sumWeight+=weight*2.0;
  }
  result = (sum+centerPixel)/sumWeight; 
  result = pow(result, vec4(1.0 / gamma));
  return clamp(result, 0.0, 1.0);
}

vec4 FUNCNAME(vec2 tc)
{
  float blurRotateValue = PREFIX(blurRotateValue);
  float transitionProgress = PREFIX(transitionProgress);
  vec4 color;
  const float EPSILON = 0.001;
  if((vIndex >= 0.5 - EPSILON && vIndex < 1.5 + EPSILON) || vIndex >= 2.5 - EPSILON) {
    color = directionBlurFunc(tc, blurRotateValue, 0.0);
  } else {
    color = InputCoordinate(tc);
  }

  // 0.3之前面1、3、4、5透明度全为0
  if(transitionProgress < 0.3) {
    if((vIndex >= 0.5 - EPSILON && vIndex < 1.5 + EPSILON) ||  // 面1
       (vIndex >= 2.5 - EPSILON && vIndex < 3.5 + EPSILON) ||  // 面3
       (vIndex >= 3.5 - EPSILON && vIndex < 4.5 + EPSILON) ||  // 面4
       (vIndex >= 4.5 - EPSILON)) {                              // 面5
      color.a = 0.0;
    }
  }

  // 应用圆角遮罩：开始时缓慢出现(0~0.25)，结束时缓慢消失(0.75~1.0)
  float cornerRadiusBase = 0.08;  // 圆角半径
  float edgeSmoothness = 0.01; // 边缘平滑度，用于抗锯齿
  float fadeIn = smoothstep(0.0, 0.25, transitionProgress);
  float fadeOut = 1.0 - smoothstep(0.75, 1.0, transitionProgress);
  float cornerRadiusFade = cornerRadiusBase * fadeIn * fadeOut;
  // radius→0 时 SDF 在整边退化，配合 MSAA+混合 在 N 卡上易出现错误透叠；与 Boxed Reality 一致保留最小半径
  float cornerRadius = max(cornerRadiusFade, edgeSmoothness * 1.5);

  float mask = roundedBoxMask(tc, cornerRadius, edgeSmoothness);
  color.a *= mask;

  // Metal + MSAA + Alpha 混合下 discard 易导致整 pass 无有效颜色输出（Blender 报无视频帧）；
  // 与同系列 Boxed Reality 一致：仅用 alpha=0 参与混合，不写 discard。
  return color;
}

// ==========================================
// Depth Slice Transition
// 5 cards with rounded corners on a fan arc.
// Center card is significantly larger (depth effect).
// Cards slide left along the arc by one position,
// size changes synchronously with position.
// Full screen -> fan cards -> arc slide -> zoom back to full.
// ==========================================

// Rounded rectangle SDF
float roundedBoxSDF(vec2 center, vec2 halfSize, float radius) {
    vec2 d = abs(center) - halfSize + radius;
    return length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0) - radius;
}

// Rotate point around pivot
vec2 rotatePoint(vec2 pt, vec2 pivot, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    vec2 d = pt - pivot;
    return vec2(d.x * c - d.y * s, d.x * s + d.y * c) + pivot;
}

vec4 FUNCNAME(vec2 tc) {
    // Animation parameters from effect
    float anim01 = PREFIX(Anim01);   // Phase 1: Full screen -> fan cards
    float anim02 = PREFIX(Anim02);   // Phase 2: Slide along arc
    float anim03 = PREFIX(Anim03);   // Phase 3: Zoom center card to full
    float anim04 = PREFIX(Anim04);   // Phase 4: Settle
    float eItime = PREFIX(eItime);

    // User parameters
    float strength = float(PREFIX(Strength)) / 100.0;
    float scaleParam = float(PREFIX(Scale)) / 100.0;

    float time = float(PREFIX(global_time)) / max(float(PREFIX(total_time)), 1.0);
    float aspect = iResolution.x / iResolution.y;

    // ── Card base dimensions (5 cards, normal aspect ratio) ──
    float cardW = 0.12 + scaleParam * 0.03;    // Half-width in normalized coords
    float cardH = 0.14 + scaleParam * 0.03;    // Half-height
    float cornerRadius = 0.015;

    // Full-screen card dimensions: must cover entire [0,1]² screen for any aspect
    float fullScreenW = max(0.5, 0.5 * aspect);
    float fullScreenH = max(0.5, 0.5 / aspect);

    // ── Fan arc parameters ──
    float arcRadius = 1.8 - strength * 0.5;
    vec2 arcCenter = vec2(0.5, 0.5 - arcRadius);
    float angleSpacing = 0.10 + strength * 0.07;

    // ── Phase logic ──
    float fanAmount   = 0.0;   // 0 = full screen, 1 = fan layout
    float scrollOffset = 0.0;  // 0 = initial, 1 = shifted left by 1 card
    float zoomAmt     = 0.0;   // 0 = card view, 1 = full screen again

    if (time < 0.20) {
        // Phase 1: Full screen shrinks into 5 fan cards
        fanAmount = anim01;
    } else if (time < 0.58) {
        // Phase 2: All cards slide left uniformly by 1 position
        fanAmount = 1.0;
        scrollOffset = anim02;
    } else {
        // Phase 3: Center card zooms back to full screen (0.58-1.0)
        fanAmount = 1.0;
        scrollOffset = 1.0;
        zoomAmt = anim03;
    }

    // ── Early outs ──
    if (zoomAmt > 0.995) {
        return INPUT2(tc);
    }
    if (fanAmount < 0.005 && zoomAmt < 0.005) {
        return INPUT1(tc);
    }

    // Transparent background — lets lower track show through
    vec4 result = vec4(0.0, 0.0, 0.0, 0.0);

    // ══════════════════════════════════════════
    // 6 virtual card slots (0-5)
    // Initially visible: slots 0-4 (5 cards), center = slot 2
    // After scroll by 1: visible slots 1-5, new center = slot 3
    //
    // Always exactly 5 cards visible, no fade in/out.
    // Draw order: depth layers (furthest from center first).
    // ══════════════════════════════════════════

    for (int layer = 3; layer >= 0; layer--) {
        for (int si = 0; si < 6; si++) {
            float fSlot = float(si);

            // Uniform scroll: all cards move at the same rate
            float shiftedSlot = fSlot - scrollOffset;

            // Only draw the 5 cards currently in view
            if (shiftedSlot < -0.5 || shiftedSlot > 4.5) continue;

            // Distance from center position (center = slot 2)
            float posFromCenter = shiftedSlot - 2.0;
            float posAbs = abs(posFromCenter);

            // ── Depth layer check (draw outermost first) ──
            int dl = int(posAbs + 0.5);
            if (dl != layer) continue;

            // ── Arc-based positioning ──
            // Push cards 2,4 away from center, closer to 1,5
            float sign = (posFromCenter >= 0.0) ? 1.0 : -1.0;
            float spread = posAbs + smoothstep(0.0, 1.0, posAbs) * 0.4;
            float theta = sign * spread * angleSpacing;
            float cx = arcCenter.x + arcRadius * sin(theta);
            float cy = arcCenter.y + arcRadius * cos(theta);

            // Card rotation follows arc tangent
            float cardAngle = -theta * 0.65;

            // ── Size variation: smooth transition, center large, edges small ──
            // posAbs=0 → 1.2x (center), posAbs≥1 → 0.7x (sides)
            // Smooth interpolation so size changes fluidly during slide
            float sizeScale = mix(1.2, 0.7, smoothstep(0.0, 1.0, posAbs));

            float scaledCardW = cardW * sizeScale;
            float scaledCardH = cardH * sizeScale;

            // ── Opacity: always fully visible (no fade in/out) ──
            float cardOpacity = 1.0;

            // ── Phase 3: reverse Phase 1 for zoom card ──
            bool isZoomCard = (posAbs < 0.5);
            float effFan = fanAmount;
            if (isZoomCard && zoomAmt > 0.001) {
                effFan = 1.0 - zoomAmt;
            }

            // ── Lerp from full-screen to card layout ──
            vec2 cardPos = mix(vec2(0.5, 0.5), vec2(cx, cy), effFan);
            float cardRot = cardAngle * effFan;
            // Zoom card: target 0.5 so UV naturally converges to tc
            float targetW = (isZoomCard && zoomAmt > 0.001) ? 0.5 : fullScreenW;
            float targetH = (isZoomCard && zoomAmt > 0.001) ? 0.5 : fullScreenH;
            float cardSzW = mix(targetW, scaledCardW, effFan);
            float cardSzH = mix(targetH, scaledCardH, effFan);
            float cRadius = mix(0.0, cornerRadius, effFan);

            // Fade non-zoom cards during zoom-out
            float cAlpha = cardOpacity;
            if (!isZoomCard && zoomAmt > 0.001) {
                cAlpha *= max(1.0 - zoomAmt * 2.0, 0.0);
            }
            if (cAlpha < 0.01) continue;

            // ── Content assignment ──
            // Even slots (0,2,4) → INPUT1;  Odd slots (1,3,5) → INPUT2
            // Initial center (slot2, even) = INPUT1
            // New center after scroll (slot3, odd) = INPUT2  ✓
            bool useInput2 = (mod(fSlot, 2.0) >= 0.5);

            // ── Hit-test: rotate screen coord into card's local space ──
            // Correct for aspect ratio: convert to physical space before rotation
            vec2 tcAspect = vec2((tc.x - cardPos.x) * aspect, tc.y - cardPos.y);
            float cRot = -cardRot;
            float cosR = cos(cRot);
            float sinR = sin(cRot);
            vec2 rotAspect = vec2(tcAspect.x * cosR - tcAspect.y * sinR,
                                  tcAspect.x * sinR + tcAspect.y * cosR);
            // Convert back to normalized space
            vec2 localPos = vec2(rotAspect.x / aspect, rotAspect.y);

            vec2 halfSz = vec2(cardSzW, cardSzH);
            float dist = roundedBoxSDF(localPos, halfSz, cRadius);

            if (dist < 0.015) {
                // ── Map local position to card UV [0,1] — unified for all cards ──
                vec2 cardUV = vec2(localPos.x / cardSzW, localPos.y / cardSzH) * 0.5 + 0.5;

                // Cover-fit: preserve input aspect ratio, crop excess
                float ratio = cardSzW / max(cardSzH, 0.001);
                if (ratio < 1.0) {
                    cardUV.x = (cardUV.x - 0.5) * ratio + 0.5;
                } else {
                    cardUV.y = (cardUV.y - 0.5) / ratio + 0.5;
                }
                cardUV = clamp(cardUV, vec2(0.0), vec2(1.0));

                // ── Sample texture ──
                vec4 texColor = vec4(0.0);
                if (isZoomCard && zoomAmt > 0.001) {
                    texColor = INPUT2(cardUV);
                } else if (useInput2) {
                    texColor = INPUT2(cardUV);
                } else {
                    texColor = INPUT1(cardUV);
                }

                // Depth darkening: edge cards slightly darker
                float depthDarken = mix(0.0, 0.12, smoothstep(0.0, 2.0, posAbs));
                texColor.rgb *= (1.0 - depthDarken);

                // Anti-aliased edge — resolution-based width (compatible with all GPUs)
                float aaWidth = 1.5 / min(iResolution.x, iResolution.y);
                float aa = 1.0 - smoothstep(-aaWidth, aaWidth, dist);
                float finalAlpha = aa * cAlpha * texColor.a;

                result.rgb = mix(result.rgb, texColor.rgb, finalAlpha);
                result.a = result.a + finalAlpha * (1.0 - result.a);
            }
        }
    }

    return result;
}

