  temp /= iResolution.xy;
  c /= iResolution.xy;
  return temp + c;
}

vec2 SetScale(vec2 uv, vec2 c, float scale) {
  uv -= c;
  uv /= max(scale, 0.0001);
  uv += c;
  return uv;
}

