// Diagonal Slice Reveal
// CapCut 参考复刻（纯 Shader，无序列遮罩）：
// 1) 0~0.75：与终段同角度的 UV 对角条带揭示 B
// 2) 0.75~1.0：A 沿同一对角切开并滑离，带与条带轴向一致的方向模糊

float remap01(float a, float b, float v)
{
    return clamp((v - a) / max(b - a, 1e-5), 0.0, 1.0);
}

float easeInOut01(float t)
{
    float x = clamp(t, 0.0, 1.0);
    return x * x * (3.0 - 2.0 * x);
}

float easeOutCubic01(float t)
{
    float x = clamp(t, 0.0, 1.0);
    float inv = 1.0 - x;
    return 1.0 - inv * inv * inv;
}

// 前后段共用：UV 对角 x-y（与后 25% 切开角度一致）
float diagCoord(vec2 tc)
{
    return tc.x - tc.y;
}

// 复刻 Mask 节奏；diagCoord ∈ [-1, 1]
void bandParams(float p, out float center, out float halfW)
{
    const float R = 1.0;
    center = 0.0;
    halfW = 0.0;

    if (p < 0.02) {
        return;
    }

    if (p < 0.22) {
        float t = easeOutCubic01(remap01(0.02, 0.22, p));
        center = mix(-R * 1.02, R * 0.98, t);
        halfW = mix(0.02 * R, 0.34 * R, t);
        return;
    }

    if (p < 0.38) {
        float t = easeInOut01(remap01(0.22, 0.38, p));
        center = mix(R * 0.98, 0.0, t);
        halfW = mix(0.34 * R, 0.36 * R, t);
        return;
    }

    if (p < 0.55) {
        float t = easeInOut01(remap01(0.38, 0.55, p));
        center = 0.0;
        halfW = mix(0.36 * R, 0.50 * R, t);
        return;
    }

    if (p < 0.72) {
        float t = easeInOut01(remap01(0.55, 0.72, p));
        center = 0.0;
        halfW = mix(0.50 * R, 0.0, t);
        return;
    }

    halfW = 0.0;
}

float bandMask(vec2 tc, float center, float halfW)
{
    if (halfW <= 1e-5) {
        return 0.0;
    }
    float v = diagCoord(tc);
    float d = abs(v - center);
    float edge = 0.004;
    return 1.0 - smoothstep(halfW - edge, halfW + edge, d);
}

vec4 sampleA(vec2 uv)
{
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        return vec4(0.0);
    }
    return vec4(INPUT1(uv).rgb, 1.0);
}

vec4 sampleB(vec2 uv)
{
    return vec4(INPUT2(clamp(uv, 0.0, 1.0)).rgb, 1.0);
}

// sideNegative=true → 保留 x<y；false → 保留 x>=y
// 沿滑离方向（与条带扫动同轴）做高斯方向模糊
vec4 slideHalfA(vec2 tc, bool sideNegative, vec2 slideDir, float slideAmt, float blurAmt)
{
    vec2 uv0 = tc - slideDir * slideAmt;
    float split0 = diagCoord(uv0);
    float keep0 = sideNegative ? step(split0, 0.0) : step(0.0, split0);
    if (keep0 < 0.5) {
        return vec4(0.0);
    }

    if (blurAmt < 1e-4) {
        return sampleA(uv0);
    }

    float radius = blurAmt * 0.22;
    float sigma = max(radius / 3.0, 1e-4);
    float sampleCount = mix(8.0, 28.0, clamp(blurAmt, 0.0, 1.0));
    float ds = radius / max(sampleCount, 1.0);

    vec4 c0 = sampleA(uv0);
    vec4 sum = c0;
    float wSum = c0.a;

    for (int i = 1; i <= 28; i++) {
        float fi = float(i);
        if (fi > sampleCount) {
            break;
        }
        float dist = fi * ds;
        float w = exp(-0.5 * (dist * dist) / (sigma * sigma));

        vec2 uvP = uv0 + slideDir * dist;
        vec2 uvM = uv0 - slideDir * dist;
        float keepP = sideNegative ? step(diagCoord(uvP), 0.0) : step(0.0, diagCoord(uvP));
        float keepM = sideNegative ? step(diagCoord(uvM), 0.0) : step(0.0, diagCoord(uvM));

        vec4 cP = sampleA(uvP);
        vec4 cM = sampleA(uvM);
        sum += cP * w * keepP;
        sum += cM * w * keepM;
        wSum += w * cP.a * keepP + w * cM.a * keepM;
    }

    if (wSum < 1e-5) {
        return vec4(0.0);
    }
    vec4 outC = sum / wSum;
    outC.a = 1.0;
    return outC;
}

vec4 FUNCNAME(vec2 tc)
{
    float p = PREFIX(iProgress);

    // [@规则:R-T05] 端点闭合
    if (p <= 0.0) {
        return vec4(INPUT1(tc).rgb, 1.0);
    }
    if (p >= 1.0) {
        return vec4(INPUT2(tc).rgb, 1.0);
    }

    const float splitStart = 0.75;

    // ---- Phase 1：与终段同角度的斜向条带揭示 ----
    if (p < splitStart) {
        float center = 0.0;
        float halfW = 0.0;
        bandParams(p, center, halfW);
        float m = bandMask(tc, center, halfW);
        vec4 colorA = vec4(INPUT1(tc).rgb, 1.0);
        vec4 colorB = vec4(INPUT2(tc).rgb, 1.0);
        return mix(colorA, colorB, m);
    }

    // ---- Phase 2：对角两半滑离 + 沿条带轴向方向模糊 ----
    float localT = remap01(splitStart, 1.0, p);
    float slideEase = easeOutCubic01(localT);
    float slideAmt = slideEase * 1.20;
    // 起步建立拖影，中段最强，末端随出画减弱
    float blurAmt = clamp(slideEase * (1.0 - localT * 0.35) * 1.15, 0.0, 1.0);

    // 与条带扫动同轴：(-1,1) / (1,-1)
    vec2 dirNeg = normalize(vec2(-1.0, 1.0));
    vec2 dirPos = normalize(vec2(1.0, -1.0));

    vec4 outC = sampleB(tc);
    vec4 halfNeg = slideHalfA(tc, true, dirNeg, slideAmt, blurAmt);
    vec4 halfPos = slideHalfA(tc, false, dirPos, slideAmt, blurAmt);

    if (halfNeg.a > 0.01) {
        outC = mix(outC, vec4(halfNeg.rgb, 1.0), halfNeg.a);
    }
    if (halfPos.a > 0.01) {
        outC = mix(outC, vec4(halfPos.rgb, 1.0), halfPos.a);
    }
    outC.a = 1.0;
    return outC;
}

float customStep(float edge0, float edge1, float value) {
    return clamp((value - edge0) / (edge1 - edge0), 0.0, 1.0);
}

float getScale(float p) {
    return customStep(1.0, 0.0, p);
}

vec4 dirBlur1( vec2 uv, vec2 dir, float progress, float u_Size,float Strength)
{
    float sigma = 7.0;
    float weight = 1.0;
    // float u_Size = 0.41;
    // float u_Bright = 3.8;

    float u_SizeScale = getScale(progress);

    vec4 resColor = INPUT1(uv) * weight;
    float sumWeight = weight;
    vec4 maxColor = resColor;
    float curWeight = 1.0;
    float delay = 0.9;
    float delayWight = curWeight;
    for (int i = 1; i <= 16; ++i)
    {
        weight = 1.0;
        delayWight = delay * delayWight;
        vec2 tmpUV = uv + dir * float(i) * u_Size * u_SizeScale;
        vec4 a = INPUT1(tmpUV) * weight;
        tmpUV = uv - dir * float(i) * u_Size * u_SizeScale;
        vec4 b = INPUT1(tmpUV);
        resColor += a + b;
        vec4 c = max(a, b);
        maxColor = max(c, maxColor);
        sumWeight += 2.0 * weight;
    }

    resColor /= sumWeight;
    vec4 color = mix(resColor, maxColor, clamp(resColor * Strength, 0.0, 1.0));
    resColor.rgb = color.rgb;
    return resColor;
}
vec4 step1(vec2 tc){
    float progress = PREFIX(progress);
    float iTime =PREFIX(global_time)/PREFIX(total_time);
    float angle = PREFIX(angle);


    if(progress<0.5){
        progress = 1.0-progress*2.0 ;
    }else{
        progress = progress*2.0-1.0;
    }

    float PI = 3.1415926 ;
    float u_Size = 0.8;

    float Strength = 8.0;

    float theta = angle * PI /180.0;
    vec2 rect = vec2(min(720.0, 720.0 * iResolution.x / iResolution.y), min(720.0, 720.0 * iResolution.y / iResolution.x));
    vec2 dir = vec2(cos(theta), sin(theta)) / rect;


    vec4 color1 = dirBlur1(tc, dir, progress, u_Size, Strength);


    return color1;

}

