vec2 Mirror(vec2 x) { return abs(mod(x-1., 2.)-1.); }
float normpdf(in float x, in float sigma)
{
	return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}
vec4 gaussianBlur(vec2 i_Uv, vec2 i_Dir, float u_Sample)
{
    float sigma = 4.0;
    float weight = normpdf(0.0, sigma);

    vec4 sum            = vec4(0.0);
    vec4 result         = vec4(0.0);
    vec2 unit_uv        = i_Dir * 3.2;
    float gamma         = 1.0;
    vec4 curColor       = INPUT1(i_Uv);
    vec4 centerPixel    = pow(curColor, vec4(gamma))*weight;
    float sum_weight    = weight;
    float u_mirrorEdge = 0.0;

    for(int i=1; i<=200; i++)
    {
        if (float(i)>u_Sample) break;
        vec2 curRightCoordinate = i_Uv+float(i)*unit_uv;
        vec2 curLeftCoordinate  = i_Uv+float(-i)*unit_uv;
        curRightCoordinate = step(u_mirrorEdge, 0.5)*curRightCoordinate + (1.0-step(u_mirrorEdge, 0.5))*Mirror(curRightCoordinate);
        curLeftCoordinate = step(u_mirrorEdge, 0.5)*curLeftCoordinate + (1.0-step(u_mirrorEdge, 0.5))*Mirror(curLeftCoordinate);
        vec4 rightColor = INPUT1(curRightCoordinate);
        vec4 leftColor = INPUT1(curLeftCoordinate);
        weight = normpdf(float(i) / u_Sample * 15.0, sigma);
        sum+=pow(rightColor, vec4(gamma))*weight;
        sum+=pow(leftColor, vec4(gamma))*weight;
        sum_weight+=weight*2.0;
    }
    result = (sum+centerPixel)/sum_weight; 
    result = pow(result, vec4(1.0 / gamma));
    return clamp(result, 0.0, 1.0);
}
vec2 flip_uv(vec2 uv)
{
    return abs(mod(uv + 1., 2.) - 1.0);
}
mat2 rotMat(float angle)
{
    float sinA = sin(angle);
    float cosA = cos(angle);
    return mat2(cosA,-sinA,sinA,cosA);
}
mat2 scale(float scale_X,float scale_Y)
{
    return mat2(1.0/(scale_X + 0.000001),0.,0.,1.0/(scale_Y + 0.000001));
}
vec2 changUV(vec2 uv,vec2 moveSize,vec2 screenSize,vec2 size,float angle)
{
    vec2 newUV = uv;
    newUV-=moveSize/screenSize;
    newUV-=0.5;
    newUV*= scale(size.x,size.y);
    newUV.x*=screenSize.x/screenSize.y;
    float angle_1 = radians(angle);
    newUV*=rotMat(angle_1);
    newUV.x/=screenSize.x/screenSize.y;
    newUV+=0.5;
    return flip_uv(newUV);
}
vec4 DirectionBlur(vec2 uv0, float u_Angle, float u_Sample)
{
    vec2 u_ScreenParams = iResolution.xy;
    vec2 uv = uv0;
    float u_ExpandFlag = 0.5;
    float offset_x = 0.0;
    float offset_y = 0.0;
    float scale_x = 1.0;
    float scale_y = 1.0;
    uv = changUV(uv0,vec2(offset_x,offset_y),vec2(1080.,1920.),vec2(scale_x,scale_y),0.0);
    float theta = u_Angle * 3.1415926 / 180.;
    vec2 ratio = (1.0+u_ExpandFlag*0.4) * 720.0 * u_ScreenParams.xy / min(u_ScreenParams.x, u_ScreenParams.y);
    vec2 dir = vec2(cos(theta), sin(theta)) / ratio;
    vec4 color = gaussianBlur(uv, dir, u_Sample);
    color = clamp(color,0.0,color.a);
    vec4 fragColor = color;
    return fragColor;
}
float easeInQuart(float x){
    return pow(x, 4.0);
}


float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
	vec2 p1 = vec2(p.x, p.y);
	vec2 p2 = vec2(p.z, p.w);
    float mX1 = p1.x;
    float mY1 = p1.y;
    float mX2 = p2.x; 
    float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec2 pinch(vec2 uv, vec2 targetPoint, vec2 vector, float range) 
{ 
    vec2 center = targetPoint + vector;
    float dist = distance(uv, targetPoint);
    vec2 point = targetPoint +  smoothstep(0., 1., dist / range) * vector;
    return uv - center + point;
}
