// Domino Cascade · frag
// [@规则:R-T01][@规则:R-T05][@规则:R-AA-01][@规则:R-UV-01]
// uStep=0 3D 卡片（圆角 + 亮度压暗 + 边覆盖率）；uStep=1 棱镜合成直出

customize_in vec2 vUVOverW;
customize_in float vInvW;

float layerEdgeCoverage(vec2 uv) {
    float sd = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
    float fw = max(length(vec2(dFdx(sd), dFdy(sd))) * 2.0, 1e-5);
    return smoothstep(-fw, fw, sd);
}

float roundedRectMask(vec2 uv, float radiusParam) {
    float minEdge = min(iResolution.x, iResolution.y);
    float halfMinEdge = minEdge * 0.5;
    float radiusPx = halfMinEdge * (radiusParam / 256.0);
    if (radiusPx < 0.5) {
        return 1.0;
    }
    vec2 halfRes = iResolution.xy * 0.5;
    vec2 p = uv * iResolution.xy;
    vec2 d = abs(p - halfRes) - (halfRes - vec2(radiusPx));
    float dist = length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0) - radiusPx;
    float fade0 = -0.1;
    float fade1 = 0.0;
    return smoothstep(fade0, fade1, -dist);
}

vec2 cardUV() {
    float invW = vInvW;
    if (invW < 1e-6) {
        invW = 1e-6;
    }
    return vUVOverW / invW;
}

vec3 applyTone(vec3 rgb, float amount, float whiteLevel) {
    float luma = dot(rgb, vec3(0.299, 0.587, 0.114));
    vec3 mapped = vec3(luma * whiteLevel);
    return mix(rgb, mapped, amount);
}

// [@pass:uStep=0] 孤立卡片：INPUT1=A，INPUT2=B
vec4 featureCard(vec2 tc) {
    vec2 uv = cardUV();
    vec4 colorA = INPUT1(uv);
    vec4 colorB = INPUT2(uv);
    vec4 src = colorA;
    if (PREFIX(uCardId) == 1) {
        src = colorB;
    }
    src.rgb = applyTone(src.rgb, PREFIX(uToneAmount), PREFIX(uToneWhite));
    float alpha = src.a;
    alpha *= roundedRectMask(uv, PREFIX(uCornerRadius));
    if (PREFIX(uEdgeAA) == 1) {
        alpha *= layerEdgeCoverage(uv);
    }
    src.rgb *= alpha;
    src.a = alpha;
    return src;
}

vec2 prismSampleUV(vec2 uv, vec2 center, float scaleAmt) {
    vec2 d = uv - center;
    float s = scaleAmt;
    if (s < 0.0001) {
        s = 0.0001;
    }
    return d / s + center;
}

// [@pass:uStep=1] 全屏棱镜（scaleStart=1.02 / scaleEnd=0.98，3 tap RGB）
vec4 featurePrism(vec2 tc) {
    vec4 src = INPUT1(tc);
    vec4 keepB = INPUT2(tc);
    float g = PREFIX(uPrismG);
    float w = PREFIX(uPrismW);
    float wSqrt = sqrt(clamp(w, 0.0, 1.0));
    vec2 center = mix(vec2(0.5), vec2(0.5), g);
    float sStart = mix(1.0, 1.02, g);
    float sMid = mix(1.0, 1.00, g);
    float sEnd = mix(1.0, 0.98, g);
    vec2 uvR = prismSampleUV(tc, center, sStart);
    vec2 uvG = prismSampleUV(tc, center, sMid);
    vec2 uvB = prismSampleUV(tc, center, sEnd);
    vec4 split = vec4(INPUT1(uvR).r, INPUT1(uvG).g, INPUT1(uvB).b, src.a);
    vec4 outCol = mix(src, split, wSqrt);
    outCol.rgb += keepB.rgb * 0.0;
    return outCol;
}

vec4 FUNCNAME(vec2 tc) {
    int uStep = PREFIX(uStep);
    if (uStep == 0) {
        return featureCard(tc);
    }
    return featurePrism(tc);
}

