customize_in vec2 vUV;

// 逆双线性插值：给定四边形四角(NDC)和屏幕点p(NDC)，求p在四边形内的UV(0-1)
// 返回 vec3(u, v, inside)，inside>0.5 表示在四边形内
// TL=左上, TR=右上, BL=左下, BR=右下 (NDC坐标, y向上)
vec3 inverseBilinear(vec2 p, vec2 TL, vec2 TR, vec2 BL, vec2 BR) {
    vec2 e = TR - TL;
    vec2 f = BL - TL;
    vec2 g = TL - TR + BR - BL;
    vec2 h = p  - TL;

    // 求解 v：k2*v^2 + k1*v + k0 = 0
    float k2 = g.x * f.y - g.y * f.x;
    float k1 = e.x * f.y - e.y * f.x + h.x * g.y - h.y * g.x;
    float k0 = h.x * e.y - h.y * e.x;

    float v;
    if (abs(k2) < 0.0001) {
        v = -k0 / k1;
    } else {
        float disc = k1 * k1 - 4.0 * k0 * k2;
        if (disc < 0.0) return vec3(0.0, 0.0, 0.0);
        float sq = sqrt(disc);
        float v0 = (-k1 - sq) / (2.0 * k2);
        float v1 = (-k1 + sq) / (2.0 * k2);
        // 选在[0,1]内的根
        v = (v0 >= -0.001 && v0 <= 1.001) ? v0 : v1;
    }

    // 由 v 求 u
    float u;
    vec2 denom = e + g * v;
    if (abs(denom.x) > abs(denom.y)) {
        u = (h.x - f.x * v) / denom.x;
    } else {
        u = (h.y - f.y * v) / denom.y;
    }

    float inside = step(-0.001, u) * step(u, 1.001)
                 * step(-0.001, v) * step(v, 1.001);
    return vec3(clamp(u, 0.0, 1.0), clamp(v, 0.0, 1.0), inside);
}

