    if (abs(denom.x) > abs(denom.y)) {
        u = (h.x - f.x * v) / denom.x;
    } else {
        u = (h.y - f.y * v) / denom.y;
    }

    float inside = step(-0.001, u) * step(u, 1.001)
                 * step(-0.001, v) * step(v, 1.001);
    return vec3(clamp(u, 0.0, 1.0), clamp(v, 0.0, 1.0), inside);
}

vec4 FUNCNAME(vec2 tc) {
    int uStep = PREFIX(uStep);

    if (uStep == 0) {
        // 进度≥65%：整屏仅 INPUT2，无四边形/描边/鼠标叠加
        if (PREFIX(uPlainBg) > 0.5) {
            vec2 bgUV = vec2(vUV.x, vUV.y);
            return INPUT1(bgUV);
        }

        // 四角点 (NDC, y向上)
        vec2 TL = PREFIX(uTL);
        vec2 TR = PREFIX(uTR);
        vec2 BL = PREFIX(uBL);
        vec2 BR = PREFIX(uBR);

        // 与 Drag In + TransV 一致：vUV.y=0 为底、1 为顶 → NDC y 向上
        vec2 ndc = vec2(vUV.x * 2.0 - 1.0, vUV.y * 2.0 - 1.0);

        // 逆双线性插值求该像素在四边形内的UV
        vec3 inv = inverseBilinear(ndc, TL, TR, BL, BR);
        float u = inv.x;
        float v = inv.y;
        float inside = inv.z;

        vec2 bgUV = vec2(vUV.x, vUV.y);
        vec4 bgColor = INPUT2(bgUV);

        // 上边(v→0)、左边(u→0)与背景用同一套 AA：smoothstep(0, aaWidth, v) 与 smoothstep(0, aaWidth, u)
        vec2 texelSize = 1.0 / iResolution.xy;
        float aaWidth = length(texelSize) * 2.0;
        float edgeMask = smoothstep(0.0, aaWidth, u) * smoothstep(0.0, aaWidth, v);

        vec4 color;
        if (inside < 0.5) {
            color = bgColor;
        } else {
            // 白色边框（smoothstep软边），受uBorderAlpha控制淡出
            float uBorderAlpha = PREFIX(uBorderAlpha);
            // 左侧 / 上边同一套 smoothstep，宽度可分别设
            float borderLeft = 0.008;
            float borderTop = 0.01;
            float aa = aaWidth * 0.5;
            float innerU = smoothstep(borderLeft - aa, borderLeft + aa, u);
            float innerV = smoothstep(borderTop - aa, borderTop + aa, v);
            float borderMask = (1.0 - (innerU * innerV)) * uBorderAlpha;

            vec2 fgUV = clamp(vec2(u, 1.0 - v), vec2(0.0), vec2(1.0));
            vec4 fgColor = INPUT1(fgUV);
            vec4 quadCol = mix(fgColor, vec4(1.0), borderMask);
            color = mix(bgColor, quadCol, edgeMask);
        }

        // 最上层：Drag Up 2-graph（INPUT3），中心对齐 uCursorPos（可与 uTL 分离）
        vec2 br = PREFIX(uCursorPos);
        vec2 cursorHalf = PREFIX(uCursorHalf);
        vec2 ndcP = vec2(vUV.x * 2.0 - 1.0, vUV.y * 2.0 - 1.0);
        vec2 delta = (ndcP - br) / cursorHalf;
        vec2 ovUV = vec2(delta.x, -delta.y) * 0.5 + 0.5;
        float inOv = step(0.0, ovUV.x) * step(ovUV.x, 1.0) * step(0.0, ovUV.y) * step(ovUV.y, 1.0);
        vec4 ov = INPUT3(ovUV);
        float ovA = min(ov.a, max(max(ov.r, ov.g), ov.b)) * inOv * PREFIX(uBorderAlpha);
        color = mix(color, vec4(ov.rgb, 1.0), ovA);

        return color;
    }

    return vec4(0.0);
}

