#define PI 3.1415926535
mat2 roataionAngle (float a ){
    float s = sin(a * PI / 180.0);
    float c = cos(a * PI / 180.0);
    return mat2(c,-s,s,c);
}
float sdBox( vec2 p, vec2 b, float r)
{
	vec2 d = abs(p) - b+vec2(r);
    return length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0)-r;
}
float sdBox2( vec2 p, vec2 center,float radius)
{
	return length(p - center) - radius;
}
vec2 textureRotationOffset(vec2 uv,float offset,vec2 prop,vec2 add){   
    uv -= add;
    uv *= prop;
    uv = roataionAngle(offset) * uv;
    uv += add;
    return uv;
}
vec4 sum(vec4 l, vec4 k){
	return  vec4(min(1.0, l.r + k.r), min(1.0, l.g + k.g), min(1.0, l.b + k.b), min(1.0, l.a + k.a));
}
vec4 Lut3DFilter(vec4 textureColor, float opacity){

    float blueColor = textureColor.r * 63.0;

    vec2 quad1;
    quad1.y = floor(floor(blueColor) / 8.0);
    quad1.x = floor(blueColor) - (quad1.y * 8.0);
    vec2 quad2;
    quad2.y = floor(ceil(blueColor) /8.0);
    quad2.x = ceil(blueColor) - (quad2.y * 8.0);
    vec2 texPos1;
    texPos1.x = (quad1.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
    texPos1.y = (quad1.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
    vec2 texPos2;
    texPos2.x = (quad2.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
    texPos2.y = (quad2.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);

    vec4 newColor1 = INPUT3(vec2(texPos1.x, texPos1.y));
    vec4 newColor2 = INPUT3(vec2(texPos2.x, texPos2.y));
    vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
    vec4 fragOutCol = mix(textureColor, vec4(newColor.rgb, textureColor.s), opacity);
    fragOutCol.a = textureColor.a;
	fragOutCol.rgb *= fragOutCol.a;
    return fragOutCol;
}
vec4 ReadLocalTexture2(vec2 tc){
    float aspect = iResolution.x / iResolution.y;
    vec2 uv = vec2(tc.x - 0.5, tc.y - 0.5);
    vec2 texResolution = vec2(1280.0, 720.0);
    if(aspect < 1.0){
        uv.x *= (texResolution.y / texResolution.x) * aspect;
    }else{
        uv.y *= (texResolution.x / texResolution.y) * (1.0 / aspect);
    }
    uv = vec2(uv.x + 0.5, uv.y + 0.5);
    return INPUT4(vec2(uv.x,1.0-uv.y));
}
vec4 FUNCNAME(vec2 tc)
{ 
    vec2 prop = vec2(iResolution.x / iResolution.y, 1.0);
    if(iResolution.y > iResolution.x){
        prop = vec2(1.0, iResolution.y / iResolution.x);
    }
    float dfs =(iResolution.x / iResolution.y);
    if(iResolution.y > iResolution.x){
        dfs = iResolution.y / iResolution.x;
    }
    else if(iResolution.y == iResolution.x){
        dfs = 2.0;
    }
    vec4 resColor = vec4(0.0);  
    vec2 offset = vec2(0.5);
    float iTime = PREFIX(Etime);
    float Anim01 = PREFIX(EAnim01);
    float Anim02 = PREFIX(EAnim02);
    float Anim03 = PREFIX(EAnim03);
    float Anim04 = PREFIX(EAnim04);
    float Anim05 = PREFIX(EAnim05);
    float Anim06 = PREFIX(EAnim06);
    float Anim07 = PREFIX(EAnim07);
    vec4 image0;
    vec4 image1;
    vec4 image2;
    vec4 image3;
    vec4 image4;
    vec4 image5;
    vec4 image6;
    vec4 image7;
    vec4 imageOP;
    vec2 UV1 =tc;
    vec2 UV2 =tc;
    vec2 UV3 =tc;
    vec2 UV4 =tc;
    vec2 UV5 =tc;
    vec2 UV6 =tc;
    vec2 UV7 =tc;
    vec4 res ;

    vec2 box01Position = tc;
    vec2 add01 = vec2(mix(1.8*dfs,0.3,Anim01),0.5);
    box01Position = textureRotationOffset(tc,45.0,prop,add01);
    box01Position -= add01;
    vec2 boxSize01 = vec2(1.0,1.0);

    float dist01 = sdBox(box01Position, boxSize01,0.03);
    float transitionWeight01 = smoothstep(0.0, 0.0, dist01);

    vec2 box02Position = tc;
    vec2 add02 = vec2(mix(1.5*dfs,0.2,Anim02),0.5);
    box02Position = textureRotationOffset(tc,45.0,prop,add02);
    box02Position -= add02;
    vec2 boxSize02 = vec2(1.0,1.0);

    float dist02 = sdBox(box02Position, boxSize02,0.03);
    float transitionWeight02 = smoothstep(0.0, 0.0, dist02);

    vec2 box03Position = tc;
    vec2 add03 = vec2(mix(1.55*dfs,0.3,Anim03),0.5);
    box03Position = textureRotationOffset(tc,45.0,prop,add03);
    box03Position -= add03;
    vec2 boxSize03 = vec2(1.0,1.0);

    float dist03 = sdBox(box03Position, boxSize03,0.03);
    float transitionWeight03 = smoothstep(0.0, 0.0, dist03);

    vec2 box04Position = tc;
    vec2 add04 = vec2(mix(1.7*dfs,0.4,Anim04),0.5);
    box04Position = textureRotationOffset(tc,45.0,prop,add04);
    box04Position -= add04;
    vec2 boxSize04 = vec2(1.0,1.0);

    float dist04 = sdBox(box04Position, boxSize04,0.03);
    float transitionWeight04 = smoothstep(0.0, 0.0, dist04);

    vec2 box05Position = tc;
    vec2 add05 = vec2(mix(1.8*dfs,0.5,Anim05),0.5);
    box05Position = textureRotationOffset(tc,45.0,prop,add05);
    box05Position -= add05;
    vec2 boxSize05 = vec2(1.0,1.0);

    float dist05 = sdBox(box05Position, boxSize05,0.03);
    float transitionWeight05 = smoothstep(0.0, 0.0, dist05);

    vec2 box06Position = tc;
    vec2 add06 = vec2(mix(1.3*dfs,0.5,Anim06),0.5);
    box06Position = textureRotationOffset(tc,45.0,prop,add06);
    box06Position -= add06;
    vec2 boxSize06 = vec2(0.3,0.3);

    float dist06 = sdBox(box06Position, boxSize06,0.03);
    float transitionWeight06 = smoothstep(0.0, 0.0, dist06);

    vec2 box07Position = tc;
    vec2 add07 = vec2(mix(1.4*dfs,-0.2,Anim04),0.5);
    box07Position = textureRotationOffset(tc,45.0,prop,add07);
    box07Position -= add07;
    vec2 boxSize07 = vec2(0.2,0.2);

    float dist07 = sdBox(box07Position, boxSize07,0.03);
    float transitionWeight07 = smoothstep(0.0, 0.0, dist07);

    vec2 box08Position = tc;
    vec2 add08;
    float newItime = iTime*2.0;
    if(iTime<=0.5){
        add08 = vec2(mix(1.0,-0.5,newItime),0.8);
    }
    else{
        add08 = vec2(mix(0.8,-0.5,newItime-1.0),mix(0.0,1.0,newItime-1.0));
    }

    box08Position = textureRotationOffset(tc,45.0,prop,add08);
    box08Position -= add08;
    vec2 boxSize08 = vec2(0.1,0.1);

    float dist08 = sdBox2(box08Position, boxSize08,0.2);
    float transitionWeight08 = 1.0-smoothstep(0.0, 0.7, dist08);

    imageOP = INPUT2(tc);
    imageOP = Lut3DFilter(imageOP, 1.0);
    vec4 UVLM= ReadLocalTexture2(tc);
    UVLM.rgb *= UVLM.a*imageOP.a;
    imageOP = sum(imageOP,UVLM)*0.8;

    image0 = INPUT1(tc);
    UV1 = vec2(tc.x+0.1,tc.y);
    image1 = INPUT2(UV1);
    UV2 = vec2(tc.x-0.1,tc.y);
    image2 = INPUT2(UV2);
    image2 = Lut3DFilter(image2, 1.0);
    image2 = sum(image2,UVLM);

    UV3 = vec2(tc.x+mix(0.15,0.0,iTime),tc.y);
    image3 = INPUT2(UV3)*1.5;
    // image3 *= vec4(0.1,0.6,0.7,1.0);
    UV4 = vec2(tc.x-mix(0.0,0.0,iTime),tc.y);
    image4 = INPUT2(UV4);
    // image4 *= vec4(0.1,0.3,0.7,1.0);
    UV5 = vec2(tc.x+mix(0.15,0.0,iTime),tc.y);
    image5 = INPUT2(UV5);
    // image5 *= vec4(0.1,0.1,0.7,1.0);
    UV6 = vec2(tc.x-mix(0.15,0.0,iTime),tc.y);
    image6 = INPUT2(UV6)*1.5;
    // image6 *= vec4(0.1,0.1,0.7,1.0);
    UV7 = vec2(tc.x+mix(0.15,0.0,iTime),tc.y);
    vec4 GlowColor = vec4(0.0,96.0/255.0,255.0/255.0,1.0);
    image7 = vec4(GlowColor.rgb * transitionWeight08, 1.0);
    image7.rgb *= GlowColor.a*0.3*imageOP.a;

    res = mix(imageOP, image0, transitionWeight01);
    res = mix(image1, res, transitionWeight02); 
    res = mix(image2, res, transitionWeight03);
    res = mix(image3, res, transitionWeight04);
    res = mix(image4, res, transitionWeight05);
    res = mix(image5, res, transitionWeight06);
    res = mix(image6, res, transitionWeight07);
    res = sum(res,image7);

    return res;
}

#define PI 3.1415926535
mat2 roataionAngle (float a ){
    float s = sin(a * PI / 180.0);
    float c = cos(a * PI / 180.0);
    return mat2(c,-s,s,c);
}
float sdBox( vec2 p, vec2 b, float r)
{
	vec2 d = abs(p) - b+vec2(r);
    return length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0)-r;
}
float sdBox2( vec2 p, vec2 center,float radius)
{
	return length(p - center) - radius;
}
vec2 textureRotationOffset(vec2 uv,float offset,vec2 prop,vec2 add){   
    uv -= add;
    uv *= prop;
    uv = roataionAngle(offset) * uv;
    uv += add;
    return uv;
}
vec4 sum(vec4 l, vec4 k){
	return  vec4(min(1.0, l.r + k.r), min(1.0, l.g + k.g), min(1.0, l.b + k.b), min(1.0, l.a + k.a));
}
vec4 Lut3DFilter(vec4 textureColor, float opacity){

    float blueColor = textureColor.r * 63.0;

    vec2 quad1;
    quad1.y = floor(floor(blueColor) / 8.0);
    quad1.x = floor(blueColor) - (quad1.y * 8.0);
    vec2 quad2;
    quad2.y = floor(ceil(blueColor) /8.0);
    quad2.x = ceil(blueColor) - (quad2.y * 8.0);
    vec2 texPos1;
    texPos1.x = (quad1.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
    texPos1.y = (quad1.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
    vec2 texPos2;
    texPos2.x = (quad2.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
    texPos2.y = (quad2.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);

    vec4 newColor1 = INPUT3(vec2(texPos1.x, texPos1.y));
    vec4 newColor2 = INPUT3(vec2(texPos2.x, texPos2.y));
    vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
    vec4 fragOutCol = mix(textureColor, vec4(newColor.rgb, textureColor.s), opacity);
    fragOutCol.a = textureColor.a;
	fragOutCol.rgb *= fragOutCol.a;
    return fragOutCol;
}
vec4 ReadLocalTexture2(vec2 tc){
    float aspect = iResolution.x / iResolution.y;
    vec2 uv = vec2(tc.x - 0.5, tc.y - 0.5);
    vec2 texResolution = vec2(1280.0, 720.0);
    if(aspect < 1.0){
        uv.x *= (texResolution.y / texResolution.x) * aspect;
    }else{
        uv.y *= (texResolution.x / texResolution.y) * (1.0 / aspect);
    }
    uv = vec2(uv.x + 0.5, uv.y + 0.5);
    return INPUT4(vec2(uv.x,1.0-uv.y));
}
