#define PI 3.1415926535
mat2 roataionAngle (float a ){
    float s = sin(a * PI / 180.0);
    float c = cos(a * PI / 180.0);
    return mat2(c,-s,s,c);
}
float sdBox( vec2 p, vec2 b, float r)
{
	vec2 d = abs(p) - b+vec2(r);
    return length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0)-r;
}
float sdBox2( vec2 p, vec2 center,float radius)
{
	return length(p - center) - radius;
}
float sdTriangle(vec2 p, vec2 p0, vec2 p1, vec2 p2)
{
    vec2 e0 = p1 - p0;
    vec2 e1 = p2 - p1;
    vec2 e2 = p0 - p2;
    vec2 v0 = p - p0;
    vec2 v1 = p - p1;
    vec2 v2 = p - p2;

    vec2 pq0 = v0 - e0 * clamp(dot(v0, e0) / dot(e0, e0), 0.0, 1.0);
    vec2 pq1 = v1 - e1 * clamp(dot(v1, e1) / dot(e1, e1), 0.0, 1.0);
    vec2 pq2 = v2 - e2 * clamp(dot(v2, e2) / dot(e2, e2), 0.0, 1.0);

    float s = sign(e0.x * e2.y - e0.y * e2.x);
    vec2 d = min(min(vec2(dot(pq0, pq0), s * (v0.x * e0.y - v0.y * e0.x)),
                     vec2(dot(pq1, pq1), s * (v1.x * e1.y - v1.y * e1.x))),
                 vec2(dot(pq2, pq2), s * (v2.x * e2.y - v2.y * e2.x)));

    return -sqrt(d.x) * sign(d.y);
}
vec2 textureRotationOffset(vec2 uv,float offset,vec2 prop,vec2 add){   
    uv -= add;
    uv *= prop;
    uv = roataionAngle(offset) * uv;
    uv += add;
    return uv;
}
