        float layerDelay = 0.10; // 每层延迟
        float layerDuration = 0.7; // 每层动画持续时间

        for(int i = 0; i <= 4; i++) {
            float startTime = float(i) * layerDelay; // 每层开始时间
            float layerProgress = clamp((progressValue - startTime) / (1.0 - startTime), 0.0, 1.0);

            // 使用缓动函数让动画更自然
            //layerProgress = smoothstep(0.0, 1.0, layerProgress); 
            float layerProgress1 = 1.0-pow(1.0-layerProgress, 2.0);
            float layerProgress2 = 1.0-pow(1.0-layerProgress, 3.0);

            // 平滑插值控制旋转和缩放
            float currentRotate = mix(-270.0, 0.0, layerProgress2);
            float currentScale = mix(0.2, 1.0, layerProgress1);

            // 处理UV坐标（3D空间变换）
            vec2 tc_centered = tc - vec2(0.5, 0.5);
            vec2 rotatedUV = rotateAxisY(tc_centered, -currentRotate, 0.0);
            vec2 finalUV = rotatedUV / currentScale + vec2(0.5, 0.5);

            // 计算视觉上恒定宽度的边框
            float angleRad = radians(currentRotate);
            float cosAngle = abs(cos(angleRad));

            // 边框宽度需要同时考虑旋转、缩放和实际屏幕宽高比
            float xBorderWidth = (baseBorderWidth / max(cosAngle, 0.2)) / currentScale;
            float yBorderWidth = (baseBorderWidth * screenAspectRatio) / currentScale;

            // 检查点是否在图像范围内
            bool isInImageBounds = finalUV.x >= 0.0 && finalUV.x <= 1.0 && 
                                  finalUV.y >= 0.0 && finalUV.y <= 1.0;

            // 检查点是否在外边框范围内（图像范围外一定宽度内）
            bool isInOuterBorderX = (finalUV.x >= -xBorderWidth && finalUV.x < 0.0) || 
                                   (finalUV.x > 1.0 && finalUV.x <= 1.0 + xBorderWidth);
            bool isInOuterBorderY = (finalUV.y >= -yBorderWidth && finalUV.y < 0.0) || 
                                   (finalUV.y > 1.0 && finalUV.y <= 1.0 + yBorderWidth);

            // 检查是否在扩展图像边界内（原始图像加上边框宽度）
            bool isInExtendedBounds = (finalUV.x >= -xBorderWidth && finalUV.x <= 1.0 + xBorderWidth) && 
                                     (finalUV.y >= -yBorderWidth && finalUV.y <= 1.0 + yBorderWidth);

            // 外部边框：在扩展边界内但不在原始图像内
            bool isInOuterBorder = isInExtendedBounds && !isInImageBounds &&
                                  (isInOuterBorderX || isInOuterBorderY);

            // 如果在外部边框范围内，绘制边框
            if(isInOuterBorder) {
                resultColor = vec4(1.0, 1.0, 1.0, 1.0);
            } 
            // 如果在原始图像内，绘制图像内容
            else if(isInImageBounds) {
                vec4 currentColor = INPUT2(finalUV);
                if(currentColor.a > 0.01) {
                    resultColor = currentColor;
                }else{
                    currentColor.a=1.0;
                    resultColor=currentColor;
                }
            }
        }

        return resultColor;
    }
    return INPUT1(tc);
}

