#define PI 3.1415926535897932

float normpdf(float x, float sigma){
    return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

vec4 motionBlur(vec2 tc, vec2 direction, float strength) {
    float sigma = 28.0;
    float weight = normpdf(0.0, sigma);
    vec4 retCol = INPUT2(tc);
    retCol *= weight;
    float sum = weight;
    float radius = 0.003 * strength;

    for(float j = 1.0; j < 21.0; j += 1.0)
    {
        weight = normpdf(j / 10.0 * 25.0, sigma);
        float offset = radius * j;
        vec2 uv = tc + direction * offset;
        retCol += INPUT2(uv) * weight;
        sum += weight;

        uv = tc - direction * offset;
        retCol += INPUT2(uv) * weight;
        sum += weight;
    }

    retCol /= sum;
    retCol = clamp(retCol, 0.0, 1.0);

    return retCol;
}


float easeInOutElastic(float x) {
    float c5 = 5.0 * PI / 4.5;

    if (x == 0.0) 
        return 0.0;
    if (x == 1.0) 
        return 1.0;

    if (x < 0.5) {
        return -(pow(2.0, 20.0 * x - 10.0) * sin((20.0 * x - 11.125) * c5)) / 2.0;
    } else {
        return (pow(2.0, -20.0 * x + 10.0) * sin((20.0 * x - 11.125) * c5)) / 2.0 + 1.0;
    }
}

