    if(process < 0.5){
        retCol = INPUT1(uv);
    }else{
        uv.y += (bounce - 1.0);
        retCol = motionBlur(uv, dir, 1.0 - process);
    }

    retCol.rgb *= retCol.a;

    return retCol;
}

#define PI 3.141592653589793

customize_in vec2 vUV;
customize_in float vIndex;

// 计算平行Y轴的褶皱效果
vec2 applyFoldEffect(vec2 uv, float time, float duration, float yNormalized) {
    // 波动参数
    float waveStartTime = 0.131600 * duration;  // 波动开始时间（下方开始）
    float waveTravelTime = 0.25 * duration;      // 波动从下方传递到上方所需时间

    // 计算波动到达当前Y位置的时间
    // 波动从下方（yNormalized=1）开始，传递到上方（yNormalized=0）
    // 使用 1.0 - yNormalized 来反转方向
    float waveArrivalTime = waveStartTime + (1.0 - yNormalized) * waveTravelTime;

    // 添加平滑过渡区域，避免波动边界突然出现
    float transitionWidth = 0.02 * duration;  // 过渡区域宽度
    float waveStartTransition = waveArrivalTime - transitionWidth;

    // 计算波动强度（0到1之间），在过渡区域内平滑过渡
    float waveIntensity = 0.0;
    if(time >= waveStartTransition) {
        if(time < waveArrivalTime) {
            // 在过渡区域内，平滑过渡
            waveIntensity = smoothstep(waveStartTransition, waveArrivalTime, time);
        } else {
            // 波动已完全到达
            waveIntensity = 1.0;
        }
    }

    // 如果波动强度为0，直接返回原始UV
    if(waveIntensity <= 0.0) {
        return uv;
    }

    // 计算波动已经过的时间（从波动到达此位置开始）
    float waveElapsedTime = max(0.0, time - waveArrivalTime);

    // 将UV坐标转换到世界空间（用于波浪计算）
    vec2 worldUV = uv;
    worldUV -= 0.5;
    float aspect = iResolution.x / iResolution.y;
    worldUV.x *= aspect;
    worldUV *= 2.0;

    // 褶皱参数
    float waveAmplitude = 2.0;  // 波浪幅度
    float waveSpeed = 0.8;      // 波浪速度
    float waveFrequency = 0.6;  // 基础波浪频率

    // 完全平行Y轴（无偏转）
    // 使用Y坐标和已经过的时间计算波形
    float coord = worldUV.y;

    // 单个波形，从下方传递到上方
    // 使用waveElapsedTime来计算波动，这样每个位置从波动到达时开始计算
    // 使用 -coord 来反转方向，使波浪从下方（y值大）传递到上方（y值小）
    float wavePhase = (-coord + waveElapsedTime * waveSpeed) * PI * 2.0 * waveFrequency;

    // 使用峰值周围插值的方式扩大凸起区域
    // 方法：在峰值周围使用平滑插值，使峰值区域更宽更平缓
    float sinWave = sin(wavePhase);

    // 峰值扩展参数
    float peakExpansion = 0.6;  // 峰值扩展范围（0-1），值越大凸起区域越宽

    // 检测峰值位置，并在峰值周围进行插值
    float smoothWave;
    float absSin = abs(sinWave);
    float signSin = sign(sinWave);

    // 计算到峰值的距离（0表示在峰值，1表示在谷底）
    float distToPeak = 1.0 - absSin;

    // 在峰值周围进行插值，扩大凸起区域
    if(distToPeak < peakExpansion) {
        // 在峰值附近，使用平滑插值扩大峰值区域
        // 将峰值附近的区域进行平滑扩展
        float t = distToPeak / peakExpansion;  // 归一化到[0,1]
        t = smoothstep(0.0, 1.0, t);  // 平滑插值

        // 在峰值附近，将值插值到峰值
        // 使用平滑的曲线，使峰值区域更宽
        float expandedDist = t * peakExpansion;
        float expandedValue = 1.0 - expandedDist;
        smoothWave = signSin * expandedValue;
    } else {
        // 在峰值之外，保持原始值
        smoothWave = sinWave;
    }

    // 进一步平滑处理，使峰值区域更宽
    // 使用平滑的曲线函数，使峰值附近的值变化更缓慢
    float absWave = abs(smoothWave);
    float signWave = sign(smoothWave);

    // 在峰值周围进行二次插值，进一步扩大峰值区域
    float peakSmooth = 0.5;  // 峰值平滑系数
    if(absWave > 0.5) {
        // 在峰值附近，使用平滑插值
        float t = (absWave - 0.5) / 0.5;  // 归一化到[0,1]
        t = smoothstep(0.0, 1.0, t);  // 平滑插值
        absWave = 0.5 + t * 0.5;  // 插值到峰值
    }

    smoothWave = signWave * absWave;

    float foldWaves = smoothWave * waveAmplitude;

    // 应用波动强度和平滑过渡
    foldWaves *= waveIntensity;

    // 应用褶皱到UV坐标
    // 褶皱主要影响Y方向（因为平行Y轴），X方向有轻微偏移
    vec2 distortedUV = uv;
    float foldOffsetX = foldWaves * 0.01;  // X方向轻微偏移，增强立体感
    float foldOffsetY = foldWaves * 0.02;  // Y方向褶皱偏移

    distortedUV.x += foldOffsetX;
    distortedUV.y += foldOffsetY;

    return distortedUV;
}

