    }

    // 如果波动强度为0，直接返回0
    if(waveIntensity <= 0.0) {
        return 0.0;
    }

    // 计算波动已经过的时间（从波动到达此位置开始）
    float waveElapsedTime = max(0.0, time - waveArrivalTime);

    // 将UV坐标转换到世界空间
    vec2 worldUV = uv;
    worldUV -= 0.5;
    float aspect = iResolution.x / iResolution.y;
    worldUV.x *= aspect;
    worldUV *= 2.0;

    // 波浪参数（与褶皱效果保持一致，使用更大的波长）
    float waveSpeed = 1.2;
    float waveFrequency = 0.3;  // 降低频率，扩大凸起区域

    // 完全平行Y轴的光影（无偏转）
    vec2 dir = vec2(0.0, 1.0);  // 方向向量（完全平行Y轴）

    // 计算平行Y轴的波浪，使用waveElapsedTime
    // 使用 -dot(worldUV, dir) 来反转方向，使波浪从下方传递到上方
    float wavePhase = -dot(worldUV, dir) - waveElapsedTime * 0.75 * waveSpeed;
    float w = sin(wavePhase * PI * 2.0 * waveFrequency);

    // 应用波动强度到光影强度
    float waveHighlight = w * 0.18 * waveIntensity;

    return waveHighlight;
}

vec4 InputCoordinate(vec2 uv) {
  // w值：0.0=back（转场后），1.0=front（转场前）
  if(vIndex < 0.5){
    // back面：显示转场后视频（INPUT2）
    return vec4(INPUT2(uv).rgb, 1.0);
  } else {
    // front面：根据位置判断显示内容
    // 获取动态边框宽度
    float frontBorderY = PREFIX(frontBorderY);
    float frontBorderX = PREFIX(frontBorderX);

    // 计算front面的实际范围（X和Y方向分别计算）
    float frontMinX = -(1.0 + frontBorderX);
    float frontMaxX = 1.0 + frontBorderX;
    float frontRangeX = frontMaxX - frontMinX;

    float frontMinY = -(1.0 + frontBorderY);
    float frontMaxY = 1.0 + frontBorderY;
    float frontRangeY = frontMaxY - frontMinY;

    // 将UV坐标映射回顶点坐标空间
    float x = frontMinX + uv.x * frontRangeX;
    float y = frontMinY + uv.y * frontRangeY;

    // 判断是否在-1~1范围内
    if(x >= -1.0 && x <= 1.0 && y >= -1.0 && y <= 1.0){
      // 在范围内：显示转场前视频（INPUT1）
      // 将-1~1的坐标范围映射到0~1的UV坐标，确保完整显示图片边缘
      vec2 mappedUV = vec2((x + 1.0) / 2.0, (y + 1.0) / 2.0);

      // 获取时间和duration参数
      float transitionProgress = PREFIX(transitionProgress);
      float time = PREFIX(globalTime);
      float duration = PREFIX(duration);

      // 计算Y坐标归一化值（0=上方，1=下方）
      float yNormalized = mappedUV.y;

      // 波动从0.131600*duration开始
      float waveStartTime = 0.131600 * duration;

      vec4 color;
      if(time >= waveStartTime){
        // 0.131600*duration之后：应用褶皱效果（根据位置判断是否已受到波动影响）
        vec2 foldedUV = applyFoldEffect(mappedUV, time, duration, yNormalized);

        // 采样纹理
        color = vec4(INPUT1(foldedUV).rgb, 1.0);

        // 添加褶皱光影效果（根据位置判断是否已受到波动影响）
        float highlight = calculateFoldHighlight(mappedUV, time, duration, yNormalized);
        color.rgb += highlight * 0.3;  // 光影强度
        color = clamp(color, 0.0, 1.0);
      } else {
        // 0.131600*duration之前：不应用褶皱，直接采样
        color = vec4(INPUT1(mappedUV).rgb, 1.0);
      }

      return color;
    } else {
      // 不在范围内：显示白色
      return vec4(1.0, 1.0, 1.0, 1.0);
    }
  }
}

float normpdf(in float x, in float sigma)
{
  return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}

vec4 texture2Dmirror(vec2 uv) {
  uv = mod(uv, 2.0);
  uv = mix(uv, 2.0 - uv, step(vec2(1.0), uv));
  return InputCoordinate(fract(uv));
}

vec4 directionBlurFunc(vec2 tc, float strength, float angle)
{
  float theta = angle* 3.1415926 / 180.0;
  vec2 rect = vec2(min(720.0, 720.0 * iResolution.x / iResolution.y), min(720.0, 720.0 * iResolution.y / iResolution.x));
  vec2 dir = vec2(cos(theta), sin(theta)) / rect;

  float sigma = 4.0;
  float weight = normpdf(0.0, sigma);

  vec4 sum            = vec4(0.0);
  vec4 result         = vec4(0.0);
  vec2 unitUv        = dir * 3.0;  // 缩小采样间距（从6.0改为3.0）
  float gamma         = 1.0;
  vec4 curColor       = InputCoordinate(tc);
  vec4 centerPixel    = pow(curColor, vec4(gamma))*weight;
  float sumWeight    = weight;

  for(int i=1;i<=100;i++)
  {
      if (float(i)>strength) break;
      vec2 curRightCoordinate = tc+float(i)*unitUv;
      vec2 curLeftCoordinate  = tc+float(-i)*unitUv;
      vec4 rightColor = texture2Dmirror(curRightCoordinate);
      vec4 leftColor = texture2Dmirror(curLeftCoordinate);
      weight = normpdf(float(i) / strength * 15.0, sigma);
      sum+=pow(rightColor, vec4(gamma))*weight;
      sum+=pow(leftColor, vec4(gamma))*weight;
      sumWeight+=weight*2.0;
  }
  result = (sum+centerPixel)/sumWeight; 
  result = pow(result, vec4(1.0 / gamma));
  return clamp(result, 0.0, 1.0);
}

