vec4 FUNCNAME(vec2 tc) {
    float p = PREFIX(iProgress);
    vec4 colorA = INPUT1(tc);
    vec4 colorB = INPUT2(tc);

    // [@规则:R-T05] 端点直接闭合，避免螺旋 mod 边界在首尾帧泄漏另一路输入。
    if (p <= 0.0) {
        return colorA;
    }
    if (p >= 1.0) {
        return colorB;
    }

    // [@动画:A-帧进度] 源时间轴在 15%~85% 线性推进 shader progress。
    float animatedProgress = clamp((p - 0.15) / 0.70, 0.0, 1.0);
    float transitionProgress = clamp((animatedProgress - 0.10) / 0.80, 0.0, 1.0);
    vec2 centeredUv = tc - vec2(0.5);
    centeredUv.x *= PREFIX(ratio);

    float radius = length(centeredUv);
    float angle = atan(centeredUv.y, centeredUv.x);
    float armAngle = 6.28318530718 / max(PREFIX(spiralArms), 1.0);
    float spiral = mod(
        angle
        + PREFIX(rotationSpeed) * transitionProgress
        + PREFIX(spiralTightness) * log(radius + 0.0001),
        armAngle
    );
    float threshold = transitionProgress * armAngle;
    float edge = max(PREFIX(edgeSmoothness), 0.0001);
    float keepA = smoothstep(threshold - edge, threshold + edge, spiral);
    vec4 spiralColor = mix(colorB, colorA, keepA);

    float blendIn = smoothstep(0.0, 0.10, animatedProgress);
    float blendOut = smoothstep(0.90, 1.0, animatedProgress);
    vec4 result = mix(colorA, spiralColor, blendIn);
    return mix(result, colorB, blendOut);
}

