vec3 ColourToYPbPr2(vec3 C)
{
  const mat3 Mat = mat3(
    0.299,0.587,0.114,
    -0.168736,-0.331264,0.5,
    0.5,-0.418688,-0.081312);
  return C * Mat;
}
vec3 YPbPrToColour(vec3 YPbPr)
{
  const mat3 Mat = mat3(
    1.0,0.0,1.402,
    1.0,-0.34413,-0.714136,
    1.0,1.772,0.0);
  return YPbPr * Mat;
}
vec3 ColorPreservingNegative(vec3 fragColor)
{
    vec3 ta = ColourToYPbPr2(fragColor);
    ta.x = 1.0 - ta.x + 0.2;
    ta = YPbPrToColour(ta);    

    return ta;
}


