// Simple interpolated noise
vec2 noise2_2(vec2 uv) {
  // vec2 f = fract(uv);
  vec2 f = smoothstep(0.0, 1.0, fract(uv));

  vec2 uv00 = floor(uv);
  vec2 uv01 = uv00 + vec2(0, 1);
  vec2 uv10 = uv00 + vec2(1, 0);
  vec2 uv11 = uv00 + 1.0;
  vec2 v00 = hash2_2(uv00);
  vec2 v01 = hash2_2(uv01);
  vec2 v10 = hash2_2(uv10);
  vec2 v11 = hash2_2(uv11);

  vec2 v0 = mix(v00, v01, f.y);
  vec2 v1 = mix(v10, v11, f.y);
  vec2 v = mix(v0, v1, f.x);

  return v;
}

// 2D (returns 0 - 1)
float random2d(vec2 n) {
  return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}

float randomRange(in vec2 seed, in float min, in float max) {
  return min + random2d(seed) * (max - min);
}

// return 1 if v inside 1d range
float insideRange(float v, float bottom, float top) {
  return step(bottom, v) - step(top, v);
}

vec4 Glitch(vec2 tc, float process, int inputIndex) {
  // randomly offset slices horizontally
  float glitch = 1.5; // 
  if (glitch > 1.0) {
    glitch = pow(glitch, 2.0);
  } else if (glitch < 1.0) {
    glitch = pow(glitch, 0.4);
  }
  float AMT = 0.5 * glitch; // 0 - 1 glitch amount
  float maxOffset = AMT / 6.0;
  vec4 outCol = inputIndex == 1 ? INPUT1(tc) : INPUT2(tc);
  float speed = 0.5 + 0.03; //
  float frequency = process * speed + 0.1;
  frequency = frequency - mod(frequency, 0.0002 / speed);
  frequency = mod(frequency * 123.0, 1.0);

  for (float i = 0.0; i < 1.0 * AMT; i += 1.0) {
    float sliceY = random2d(vec2(frequency, 2345.0 + float(i)));
    float sliceH = random2d(vec2(frequency, 9035.0 + float(i))) * 0.035 * glitch;
    float sliceX = random2d(vec2(frequency, 12345.0 + float(i)));
    float sliceW = random2d(vec2(frequency, 19035.0 + float(i))) * 0.35 * glitch;
    float hOffset =
        randomRange(vec2(frequency, 9625.0 + float(i)), -maxOffset, maxOffset);
    vec2 tcOff = tc;
    tcOff.x += hOffset;
    if (insideRange(tc.y, sliceY, fract(sliceY + sliceH)) == 1.0) {
      if (insideRange(tc.x, sliceX, fract(sliceX + sliceW)) == 1.0) {
        outCol = inputIndex == 1 ? INPUT1(tcOff) : INPUT2(tcOff);
      }
    }

  }

  return outCol;
}

float normpdf(float x, float sigma){
      return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

vec4 motionBlur1(vec2 tc, vec2 direction, float strength) {
    float sigma = 28.0;
    float weight = normpdf(0.0, sigma);
    vec4 retCol = INPUT1(tc);
    retCol *= weight;
    float sum = weight;
    float radius = 0.02 * strength;

    for(float j = 1.0; j < 15.0; j += 1.0)
    {
        weight = normpdf(j / 10.0 * 25.0, sigma);
        float offset = radius * j;
        vec2 uv = tc + direction * offset;
        retCol += INPUT1(uv) * weight;
        sum += weight;

        uv = tc - direction * offset;
        retCol += INPUT1(uv) * weight;
        sum += weight;
    }

    retCol /= sum;
    retCol = clamp(retCol, 0.0, 1.0);

    return retCol;
}

vec4 motionBlur2(vec2 tc, vec2 direction, float strength) {
  float sigma = 28.0;
  float weight = normpdf(0.0, sigma);
  vec4 retCol = INPUT2(tc);
