    // 2. 增加初始震动幅度
    float base_amplitude = 0.03; // 显著增加基础幅度

    // 3. 添加多个频率分量，使震动更自然
    float shake_x = sin(aftershock_process * 40.0) * base_amplitude * decay +
                    sin(aftershock_process * 65.0) * base_amplitude * 0.5 * decay;

    float shake_y = cos(aftershock_process * 50.0) * base_amplitude * 1.2 * decay +
                    cos(aftershock_process * 85.0) * base_amplitude * 0.7 * decay;

    // 4. 添加随机脉冲震动
    if (random2d(vec2(floor(aftershock_process * 30.0))) > 0.8) {
      float pulse = 0.02 * (1.0 - aftershock_process); // 随机脉冲震动
      shake_x += random2d(vec2(aftershock_process * 99.0)) * pulse - pulse * 0.5;
      shake_y += random2d(vec2(aftershock_process * 78.0)) * pulse - pulse * 0.5;
    }

    // 应用更强的震动偏移
    vec2 shake_uv = uv + vec2(shake_x, shake_y);

    // 更频繁地添加Glitch效果增强余震感
    if (random2d(vec2(aftershock_process * 20.0)) > 0.8) { // 增加Glitch的频率
      float glitch_strength = decay * 0.8 + random2d(vec2(aftershock_process)) * 0.3;
      retCol = Glitch(shake_uv, glitch_strength, 2);
    } else {
      retCol = INPUT2(shake_uv);
    }

    // 5. 偶尔添加色彩偏移以增强震动感
    if (random2d(vec2(aftershock_process * 15.7)) > 0.7) {
      vec2 color_shift = vec2(
        sin(aftershock_process * 100.0) * 0.01 * decay,
        cos(aftershock_process * 90.0) * 0.01 * decay
      );
      vec4 shifted_color = INPUT2(shake_uv + color_shift);
      // 仅对RGB通道进行偏移，保持原始Alpha
      retCol.r = mix(retCol.r, shifted_color.r, 0.5);
      retCol.g = mix(retCol.g, shifted_color.g, 0.3);
    }

  }
  // the first stage: Glitch effect + RGB separation of INPUT1
  else if (glitch_process > 0.0 && blur_process <= 0.0) {
    // fixed RGB separation intensity
    float splitIntensity = 0.01; // fixed separation intensity

    // random direction offset
    vec2 rOffset = vec2(splitIntensity * 0.5, splitIntensity * 0.2); // red channel slight offset
    vec2 bOffset = vec2(-splitIntensity * 0.5, -splitIntensity * 0.2); // blue channel reverse offset

    // sample the offset color
    vec4 rColor = INPUT1(uv + rOffset);
    vec4 gColor = INPUT1(uv);
    vec4 bColor = INPUT1(uv + bOffset);

    // combine the color channels
    vec4 baseColor = vec4(rColor.r, gColor.g, bColor.b, gColor.a);

    // apply the Glitch effect
    retCol = Glitch(uv, glitch_process, 1);

    // mix the RGB separation and the Glitch effect
    retCol = mix(baseColor, retCol, glitch_process);

  } 
  // the second stage: blur effect
  else if (blur_process > 0.0) {
    uv.x += blur_process * 0.16; // add the horizontal offset
    uv.y += blur_process * 0.22; // reduce the vertical offset

    if(blur_iPro < 0.5){
      retCol = motionBlur1(uv, vec2(-0.3, -0.95), blur_process);
    }else{
      retCol = motionBlur2(uv, vec2(-0.3, -0.95), blur_process);
    }
  }
  // the first stage: INPUT1 display, add the RGB separation fade-in effect
  else {
    // fade-in process: the separation intensity increases from 0 to the maximum value
    float splitIntensity = smoothstep(0.0, 1.0, progress / start_time) * 0.01; // the maximum separation intensity is 0.01

    // random direction offset
    vec2 rOffset = vec2(splitIntensity * 0.5, splitIntensity * 0.2); // red channel slight offset
    vec2 bOffset = vec2(-splitIntensity * 0.5, -splitIntensity * 0.2); // blue channel reverse offset

    // sample the offset color
    vec4 rColor = INPUT1(uv + rOffset);
    vec4 gColor = INPUT1(uv);
    vec4 bColor = INPUT1(uv + bOffset);

    // combine the color channels
    retCol = vec4(rColor.r, gColor.g, bColor.b, gColor.a);
  }

  return retCol;
}

