// 4阶贝塞尔曲线
float bezier4(float t) {
    if (t == 0.0) {
        return 0.0;
    }
    // 控制点
    vec2 points[5] = vec2[](
        vec2(0.00, 0.00),
        vec2(0.10, 0.50),
        vec2(0.50, 0.50),
        vec2(0.90, 0.50),
        vec2(1.00, 1.00)
    );

    // 计算贝塞尔曲线
    vec2 p = vec2(0.0);
    int n = 4;

    for(int i = 0; i <= 4; i++) {
        float coef = float(1);
        // 计算组合数 C(n,i)
        for(int j = 1; j <= i; j++) {
            coef *= float(n - j + 1) / float(j);
        }
        // 计算贝塞尔多项式
        p += points[i] * coef * pow(1.0 - t, float(n - i)) * pow(t, float(i));
    }

    return p.y;
}

