vec4 lut3DFilter(vec4 textureColor, float opacity){
    // 在标准 3D LUT 约定下，应以 B 通道选择切片
    float blueColor = textureColor.b * 63.0;
    vec2 quad1;
    quad1.y = floor(floor(blueColor) / 8.0);
    quad1.x = floor(blueColor) - (quad1.y * 8.0);
    vec2 quad2;
    quad2.y = floor(ceil(blueColor) /8.0);
    quad2.x = ceil(blueColor) - (quad2.y * 8.0);
    vec2 texPos1;
    texPos1.x = (quad1.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
    texPos1.y = (quad1.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
    vec2 texPos2;
    texPos2.x = (quad2.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
    texPos2.y = (quad2.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
    vec4 newColor1 = INPUT3(vec2(texPos1.x, texPos1.y));
    vec4 newColor2 = INPUT3(vec2(texPos2.x, texPos2.y));

    vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
    vec4 fragOutCol = vec4(mix(textureColor.rgb, newColor.rgb, opacity), textureColor.a);
    fragOutCol.rgb *= fragOutCol.a;
    return fragOutCol;
}

float normpdf(in float x, in float sigma)
{
	return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}

vec4 texture2Dmirror(vec2 uv) {
    uv = mod(uv, 2.0);
    uv = mix(uv, 2.0 - uv, step(vec2(1.0), uv));
    return INPUT1(fract(uv));
}

vec4 gaussianBlur(vec2 tc, float strength, float _signed)
{   
    if(_signed == 0.0){
        return INPUT1(tc);
    }

    float sigma = 4.0;
    float weight = normpdf(0.0, sigma);

    vec4 sum = vec4(0.0);
    vec4 result = vec4(0.0);
    vec4 centerPixel = pow(INPUT1(tc), vec4(1.0)) * weight;
    float sumWeight = weight;

    for(int i = 1; i <= 20; i++)
    {
        if (float(i) > strength) break;
        for(int x = -1; x <= 1; x += 2) {
            for(int y = -1; y <= 1; y += 2) {
                vec2 offset = vec2(float(x*i), float(y*i)) / iResolution.xy * strength;
                vec2 sampleCoord = tc + offset;
                vec4 sampleColor = texture2Dmirror(sampleCoord);

                float dist = length(vec2(x, y) * float(i));
                weight = normpdf(dist / strength * 10.0, sigma);

                sum += pow(sampleColor, vec4(1.0)) * weight;
                sumWeight += weight;
            }
        }
    }

    result = (sum + centerPixel) / sumWeight;
    result = pow(result, vec4(1.0));
    return clamp(result, 0.0, 1.0);
}


