  return retCol;
}
// background
vec4 sampleBackgroundArea(vec2 uv, float repears)
{
  vec4 changeColor = vec4(77.0 / 255.0, 59.0 / 255.0, 40.0 / 255.0, 0.0);
  vec4 retColor = vec4(0.0, 0.0, 0.0, 0.0);
  bool isShow = true;
  float gray = 1.0;
  if (uv.y < 0. || uv.y > 1.0)
  {
    isShow = false;
  }

  if (uv.y > 0. && uv.y < 1.0 && uv.x > 0. && uv.x < 1.0)
  {
    isShow = false;
  }

  if (uv.y > 0. && uv.y < 1.0 && uv.x > 2. && uv.x < 3.0)
  {
    isShow = false;
  }

  if (isShow)
  {
    if (uv.x < 3.0)
    {
      uv.x = checkUvRange(uv.x) ? 1.0 - uv.x : uv.x;
      retColor = motionBlur1(uv, repears);
    }
    else
    {
      uv.x = checkUvRange(uv.x) ? uv.x : 1.0 - uv.x;
      retColor = motionBlur2(uv, repears);
    }
    retColor = lut3DFilter(retColor, gray);
    retColor.rgb *= 1.0;
  }
  return retColor;
}

// foreground
vec4 sampleForegroundArea(vec2 uv, float repears)
{
  vec4 retColor = vec4(0.0, 0.0, 0.0, 0.0);
