vec2 GetRotate(vec2 tc, float theta) {
    vec2 center = vec2(0.5, 0.5);
    vec2 p = tc - center;
    float aspect = iResolution.x / iResolution.y;
    p.x *= aspect;
    float c = cos(theta);
    float s = sin(theta);
    vec2 rotated = vec2(p.x * c + p.y * s, -p.x * s + p.y * c);
    rotated.x /= aspect;
    return rotated + center;
}

