vec4 GetOffsetColor(vec2 uv, float lineNoise, float time){
  vec4 inCol = INPUT1(uv);
  vec2 tempUV = uv + vec2(lineNoise*0.02*(randomNoise(7.0, time)*2.0-1.0), 0.0);
  vec4 color = INPUT1(tempUV)*inCol.a;
  return color;
}

vec4 GetGlitchColor(vec2 uv, float lineNoise, float time){
  vec4 inCol = INPUT1(uv);
  vec4 colorR = inCol*inCol.a;
  vec2 tempUV = uv + vec2(lineNoise*0.05*randomNoise(7.0, time), 0.0);
  vec4 colorG = INPUT1(tempUV)*inCol.a;
  tempUV = uv - vec2(lineNoise*0.07*randomNoise(23.0, time), 0.0);
  vec4 colorB = INPUT1(tempUV)*inCol.a;
  return vec4(colorR.r, colorG.g, colorB.b, inCol.a);
}

vec4 GlitchImageBlock(vec2 uv, float time) {
  float _BlockLayer1_U = 4.0;
  float _BlockLayer1_V = 6.0;
  float _BlockLayer2_U = 6.0;
  float _BlockLayer2_V = 20.0;

  vec2 blockLayer1 = floor(uv * vec2(_BlockLayer1_U, _BlockLayer1_V));
  vec2 blockLayer2 = floor(uv * vec2(_BlockLayer2_U, _BlockLayer2_V));

  float _BlockLayer1_Indensity = 6.0;
  float _BlockLayer2_Indensity = 8.0;
  float _Offset = 6.0;

  float lineNoise1 = pow(randomNoiseV2(blockLayer1, time), _BlockLayer1_Indensity);
  int randomColor = int(16777215.0*lineNoise1);

  float lineNoise2 = pow(randomNoiseV2(blockLayer2, time), _BlockLayer2_Indensity);
  float lineNoise = lineNoise1 * lineNoise2 * _Offset;

  vec4 retCol = vec4(0.0);

  if(time < 0.5){
    if(lineNoise > 0.9){
      retCol =  GetGlitchColor(uv, lineNoise, time);
    }else if(lineNoise > 0.7 && lineNoise < 0.8){
      vec2 tempUV = uv - vec2(lineNoise*0.08*randomNoise(34.0, time)*2.0-1.0, 0.0);
      retCol = INPUT1(tempUV);
    }else{
      retCol = vec4(step(0.8, lineNoise))*(step(0.0, random(time*77.7)*2.0-1.0))*
               vec4(GetColor(randomColor), 1.0)*lineNoise2*1.5;
    }
  }else{
    retCol = GetOffsetColor(uv, lineNoise, time);
  }

  return retCol;
}

float squareWave(float x){
  return step(0.5, mod(x, 1.0));
}

vec4 Lut2DFilter(vec4 textureColor, float opacity){
  vec3 newColor;
  newColor.r = INPUT2(vec2(textureColor.r, .16666)).r;
  newColor.g = INPUT2(vec2(textureColor.g, .5)).g;
  newColor.b = INPUT2(vec2(textureColor.b, .83333)).b;

  vec4 fragOutCol = vec4(mix(textureColor.rgb, newColor.rgb, opacity), textureColor.a);
  fragOutCol.rgb *= fragOutCol.a;

  return fragOutCol;
}

vec2 hash21(float p){
  vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
  p3 += dot(p3, p3.yzx + 33.33);

  return fract((p3.xx+p3.yz)*p3.zy);
}

vec2 fbmNoise(float p){
  vec2 value = vec2(0.0);
  float freq = 1.13;
  float amp = 0.57;
  const int octaves = 3;

  for (int i = 0; i < octaves; i++){
    value += amp * (hash21((p - 1.0) * freq)*2.0-1.0);
    freq *= 1.61;
    amp *= 0.47;
  }

  return value;
}

