vec4 RGBSplit(vec2 uv, vec2 offset){
  offset = clamp(offset, 0.0, 1.0)*0.3;
  vec2 uvSplit = uv+offset;
  vec4 retColor = vec4(0.0);
  retColor.r = INPUT1(uvSplit).r;
  retColor.gba = INPUT1(uv).gba;

  return retColor*retColor.a;
}

vec4 DirectBlur(vec2 uv, float blurRadius, float rotateRad, int iteration, vec2 offset){
  float sinVal = sin(rotateRad)*blurRadius*0.05 / float(iteration);
  float cosVal = cos(rotateRad)*blurRadius*0.05 / float(iteration);
  vec2  direction = vec2(cosVal,sinVal);

  vec4 color = vec4(0.0);
  color = INPUT1(uv);

  for (int k = 1; k < iteration; k++){
    vec2 curUV = uv-direction*float(k);
    vec2 curUV2 = uv+direction*float(k);
    color += RGBSplit(curUV, offset);
    color += RGBSplit(curUV2, offset);
  }

  vec4 finalColor = color / (float(iteration)*2.0-1.0);
  return finalColor;
}

float atanFunc(vec2 dxy){
  if(dxy.x == 0.0){
    if(dxy.y > 0.0){
      return PI / 2.0;
    }else if(dxy.y < 0.0){
      return -PI / 2.0;
    }else{
      return 0.0;
    }
  }else{
    return atan(dxy.y, dxy.x);
  }
}

