#define PI 3.1415926535897932384626433832795
#define u_ScreenParams iResolution.xy
#define grayFactor  vec3(76.5/255.0, 150.0/255.0, 28.5/255.0)
float normpdf(in float x, in float sigma)
{
	return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}
vec4 encode(float gray)
{
    vec4 res = vec4(0.0, 0.0, 0.0, 0.0);
    gray *= 255.0;
    res.x = floor(gray) / 255.0;

    gray = fract(gray);
    gray *= 255.0;
    res.y = floor(gray) / 255.0;

    gray = fract(gray);
    gray *= 255.0;
    res.z = floor(gray) / 255.0;

    // gray = fract(gray);
    // gray *= 255.0;
    gray = fract(gray);
    res.w = gray;
    return res;
}
float decode(vec4 g)
{
    float ret = 0.0;
    ret = g.x + g.y / 255.0 + g.z / (65025.0) + g.w / (16581375.0);
    return ret;
}
vec4 gaussianBlur(vec2 i_Uv, vec2 i_Dir, float i_Strength)
{
    const int  radius = 32;
    float s = i_Strength;
    float sigma = 4.0;
    float first = normpdf(0.0, sigma);
    float weight = 0.5 * 1.02 + 0.5;
    weight = first;
    vec4 sum            = vec4(0.0);
    vec4 result         = vec4(0.0);
    vec2 unit_uv        = i_Dir;
    vec4 curColor       = INPUT1(i_Uv);
    float gamma = 2.4;
    float g = decode(curColor);
    // g = curColor.r;
    g = pow(g, gamma);
    float centerg = g * weight;
    float sum_weight    = weight;
    float sumg = 0.0;
    for(float i=1.;i<=1024.;i+=1.0)
    {
        if (i > abs(s)) break;
        vec2 curRightCoordinate = i_Uv+float(i)*unit_uv;
        vec2 curLeftCoordinate  = i_Uv+float(-i)*unit_uv;
        vec4 rightColor = INPUT1(curRightCoordinate);
        vec4 leftColor = INPUT1(curLeftCoordinate);
        float rg = decode(rightColor);
        rg = pow(rg, gamma);
        // rg = rightColor.r;
        float lg = decode(leftColor);
        lg = pow(lg, gamma);
        // lg = leftColor.r;
        // weight = (normpdf(float(i) / s * 15.0, sigma) / first - 0.5) * 1.02 + 0.5;
        weight = normpdf(float(i) / s * 15.0, sigma);
        sumg += (rg + lg) * weight;
        sum_weight+=weight*2.0;
    }
    g = (centerg + sumg) / sum_weight;
    return vec4(pow(g, 1. / gamma));
    // return pow(clamp(result, 0.0, 1.0), vec4(1.0));
}
vec4 GetGaussBlur(vec2 uv0){
    float u_Angle = 0.0;
    float u_Strength = 1.0;
    float theta = u_Angle * 3.1415926 / 180.;
    vec2 ratio = vec2(720.0) * u_ScreenParams.xy / min(u_ScreenParams.x, u_ScreenParams.y);
    float rescale = min(u_ScreenParams.x, u_ScreenParams.y) / 180.;
    vec2 dir = vec2(cos(theta), sin(theta)) / u_ScreenParams.xy;
    vec4 color = gaussianBlur(uv0, dir, u_Strength * rescale);
    color = encode(color.r);
    return color;
}


vec2 rotate(vec2 uv, float t)
{
    float sint = sin(t);
    float cost = cos(t);
    mat2 rot = mat2(
        cost, -sint,
        sint, cost
    );
    return rot * uv;
}

vec4 GetMaskTex(vec2 uv0){
    float u_Angle = 0.0;
    float u_Amount = 12.0;
    float u_YScale = 1.0;
    float u_XScale = 1.0;
    float u_Gap = 1.2;

    vec2 uv = vec2(uv0.x, uv0.y);
    vec2 uvx = vec2(1.0 / u_ScreenParams.x, 0.0);
    vec2 uvy = vec2(0.0, 1.0 / u_ScreenParams.y);
    vec2 uvt = vec2(1.0 / u_ScreenParams.xy);
    float dx = 0.0;   
    float dy = 0.0;
    float sum_weight = 0.0;
    vec4 g = (INPUT1(uv));
    g.r = decode(g);

    float fx1 = 0.0;
    float fx2 = 0.0;
    float fy1 = 0.0;
    float fy2 = 0.0;
    vec4 c = INPUT1(uv + uvx);
    fx1 = decode(c);
    c = INPUT1(uv - uvx);
    fx2 = decode(c);
    c = INPUT1(uv + uvy);
    fy1 = decode(c);
    c = INPUT1(uv - uvy);
    fy2 = decode(c);
    dx += (fx1 - fx2) / (2.);
    dy += (fy1 - fy2) / (2.);
    sum_weight += 1.0;

    vec2 n = vec2(dx, dy) / sum_weight;
    float theta = u_Angle * PI / 180.0;
    n = rotate(n, theta);
    vec2 gradient = n;
    vec4 resColor = INPUT2(uv0);
    vec2 ratio = 720.0 * u_ScreenParams.xy / min(u_ScreenParams.x, u_ScreenParams.y) * 720.0 / min(u_ScreenParams.x, u_ScreenParams.y);
    gradient *= 255.0 / ratio;
    gradient *= vec2(u_XScale, u_YScale);
    float sumWeight = 1.0;
    // vec4 colorFaceMask = texture2D(u_faceMaskTex, uv0);
    // float blurStrength = .5 + colorFaceMask.g / 2.;
    for(float i = 1.0; i <= 100.; i += 1.0)
    {
        if (i > abs(u_Amount * .5)) break;
        vec2 uvl = uv0 - i * gradient * 2.0 * u_Gap;
        vec2 uvr = uv0 + i * gradient * 2.0 * u_Gap;
        resColor += INPUT2(uvl);
        resColor += INPUT2(uvr);
        sumWeight += 2.0;
    }
    resColor /= sumWeight;
    return resColor;
}
float remap01(float a, float b, float x)
{
    float res = (x-a)/(b-a + 0.00001);
    res = smoothstep(a, b, x);
    return clamp(res, 0., 1.);
}

vec4 RadiusBlur(vec2 uv0, float Blur){
    vec2 u_Center = vec2(0.5, 0.5);
    float u_Amount = Blur;
    float u_Quality = 23.0;
    const int SAMPLES = 32;
    float quality = clamp(u_Quality * 0.01, 0.1, 1.0) * 1.6;
    float amount = u_Amount * u_ScreenParams.x / 720.0 * 1.6;
    vec2 uv = uv0;
    vec2 dir = (uv - u_Center);
    float x = length(uv - u_Center);
    dir = dir / u_ScreenParams.x * (amount) * 1.2;
    float weight = 1.0;
    vec4  res = INPUT2(uv) * weight;
    float sumWeight = weight;
    float s = (1.0 + abs(amount) * quality * x);
    vec2 d = dir / floor(s);
    for (float i = -1.0; i > -500.0; i -= 1.0) 
    {
        if (i <= -s) break;
        weight = 1.0;
        vec4 tmp = (INPUT2(uv - float(i) * d)) * weight;
        res += tmp;
        sumWeight += weight;
    }

    for (float i = 1.0; i < 500.0; i += 1.0) 
    {
        if (i >= s) break;
        weight = 1.0;
        vec4 tmp = (INPUT2(uv - float(i) * d)) * weight;
        res += tmp;
        sumWeight += weight;
    }

    return vec4(res / sumWeight);
}

vec4 GetMaskTexture(vec2 uv0, float range){
    float u_BlackField = 0.0;
    float u_BlackSoft = 0.0;
    float u_WhiteField = 1.0/255.0;
    float u_WhiteSoft = 0.0;
    float rangeIntensity = range;
    float u_Reverse = 0.0;

    float u_BlackField1 = u_BlackField;
    float u_BlackSoft1 = u_BlackSoft;
    float u_WhiteField1 = u_WhiteField;
    float u_WhiteSoft1 = u_WhiteSoft;
    u_BlackField1 = (203. - 203. * rangeIntensity) / 255.;
    u_BlackSoft1 = u_BlackSoft * 1.;
    u_WhiteField1 = (255. - 223. * rangeIntensity) / 255.;
    u_WhiteSoft1 = u_WhiteSoft * 1.;
    vec4 oriColor = INPUT1(uv0);
    oriColor.rgb = oriColor.rgb / (oriColor.a+0.0001);

    float gray = dot(oriColor.rgb, grayFactor);
    float mask = remap01(u_BlackField1 - u_BlackSoft1, u_BlackField1, gray) * (1. - remap01(u_WhiteField1, u_WhiteField1 + u_WhiteSoft1, gray));
    mask = abs(u_Reverse-mask);
    return vec4(oriColor) * mask;
}


vec4 GetBandColor(vec2 uv){
    vec3 rainbowColor = vec3(0.0);
    if (uv.x < 1.0/10.0) {
        rainbowColor =mix(vec3(0.0, 0.0, 1.0), vec3(0.0, 1.0, 0.0), uv.x * 10.0);
    } else if (uv.x < 2.0/10.0) {
        rainbowColor = mix(vec3(0.0, 1.0, 0.0), vec3(0.0, 0.5, 0.0), (uv.x - 1.0/10.0) * 10.0);
    } else if (uv.x < 3.0/10.0) {
        rainbowColor = mix(vec3(0.0, 0.5,0.0), vec3(1.0, 1.0, 0.0), (uv.x - 2.0/10.0) * 10.0);
    } else if (uv.x < 4.0/10.0) {
        rainbowColor = mix(vec3(1.0, 1.0, 0.0), vec3(1.0, 0.5, 0.0), (uv.x - 3.0/10.0) * 10.0);
    } else if (uv.x < 5.0/10.0) {
        rainbowColor = mix(vec3(1.0, 0.5, 0.0),vec3(1.0, 0.0, 0.0), (uv.x - 4.0/10.0) * 10.0);
    } else if (uv.x < 6.0/10.0) {
        rainbowColor = mix(vec3(1.0, 0.0, 0.0), vec3(0.5, 0.0, 0.0), (uv.x - 5.0/10.0) * 10.0);} else if (uv.x < 7.0/10.0) {
        rainbowColor = mix(vec3(0.5, 0.0, 0.0), vec3(1.0, 0.0, 1.0), (uv.x - 6.0/10.0) * 10.0);
    } else if (uv.x < 8.0/10.0) {
        rainbowColor = mix(vec3(1.0, 0.0, 1.0), vec3(0.5,0.0, 0.5), (uv.x - 7.0/10.0) * 10.0);
    } else if (uv.x < 9.0/10.0) {
        rainbowColor = mix(vec3(0.5, 0.0,0.5), vec3(0.2, 0.0, 0.2), (uv.x - 8.0/10.0) * 10.0);
    } else {
        rainbowColor =mix(vec3(0.2, 0.0, 0.2), vec3(0.0, 0.0, 1.0), (uv.x- 9.0/10.0) * 10.0);
    }
    return vec4(sqrt(rainbowColor), 1.0);
}

vec4 GetRipple(vec2 uv, float Dis){
    float iTime = PREFIX(global_time);
    vec2 cPos = -1.0 + 2.0 * uv;

    // distance of current pixel from center
