    vec3 straight = clamp(c.rgb / max(a, 1e-4), 0.0, 1.0);

    if (a < 0.003)
        return vec4(c.rgb, 1.0);

    if (a < 0.70 && aMax > 0.80)
        return vec4(straight, 1.0);
    if (a < 0.60 && aMax > 0.68 && (aMax - a) > 0.035)
        return vec4(straight, 1.0);

    if (a < 0.56 && mx < 0.52 && lum < 0.44)
        return vec4(straight, 1.0);

    if (a < 0.97 && lum < 0.24 && mx < 0.30)
        return vec4(straight, 1.0);

    if (a < 0.72 && lum > 0.82 && mx > 0.78)
        return vec4(straight, 1.0);

    return c;
}

// ---- shading helpers ----------------------------------------
vec4 _seeThroughWithShadow(float yc, vec2 p, vec3 pt, float amount,
                           vec2 uv, float dirRad, bool inFrame,
                           float cylAngle, float cylCenter,
                           mat3 rot, mat3 rrot)
{
    return inFrame ? _pageSrc(uv) : vec4(0.0);
}

vec4 _backside(float yc, vec3 pt, float dirRad)
{
    // Rotate hit-point back to original space before sampling
    vec2 sampleUV = _rotUV(pt.xy, -dirRad);
    return _pageSrc(sampleUV);
}

// ---- main cylinder-curl compositing -------------------------
vec4 _curlPage(vec2 uv, float amount, float dirRad, bool inFrame)
{
    float cylCenter = amount;
    float cylAngle  = 2.0 * _PI * amount;

    vec2 uvCurl = _rotUV(uv, dirRad);

    // Fixed 30-degree tilt within curl-space
    const float tilt = 30.0 * _PI / 180.0;
    float c = cos(-tilt);
    float s = sin(-tilt);
    mat3 rotation  = mat3(c,  s, 0.0,
                         -s,  c, 0.0,
                          0.12, 0.258, 1.0);
    c = cos(tilt);
    s = sin(tilt);
    mat3 rrotation = mat3(c,  s, 0.0,
                         -s,  c, 0.0,
                          0.15, -0.5, 1.0);

    vec3 pt  = rotation * vec3(uvCurl, 1.0);
    float yc = pt.y - cylCenter;

    vec4 color;

    if (yc < -_cylinderRadius)
    {
        // fully behind cylinder — transparent
        color = vec4(0.0);
    }
    else if (yc > _cylinderRadius)
    {
        // flat surface in front — only show within the original frame
        color = inFrame ? _pageSrc(uv) : vec4(0.0);
    }
    else
    {
        float hitAngle    = (acos(yc / _cylinderRadius) + cylAngle) - _PI;
        float hitAngleMod = mod(hitAngle, 2.0 * _PI);

        if ((hitAngleMod > _PI && amount < 0.5) ||
            (hitAngleMod > _PI / 2.0 && amount < 0.0))
        {
            // Single-page unfurl: this zone is the flat page surface, not a ghost layer
            color = inFrame ? _pageSrc(uv) : vec4(0.0);
        }
        else
        {
            pt = _hitPoint(hitAngle, yc, pt, rrotation);

            // Boundary check in original space to avoid false out-of-bounds
            vec2 ptOrig = _rotUV(pt.xy, -dirRad);
            if (ptOrig.x < 0.0 || ptOrig.y < 0.0 || ptOrig.x > 1.0 || ptOrig.y > 1.0)
            {
                color = _seeThroughWithShadow(yc, uvCurl, pt, amount,
                                              uv, dirRad, inFrame,
                                              cylAngle, cylCenter,
                                              rotation, rrotation);
            }
            else
            {
                color = _backside(yc, pt, dirRad);

                vec4 otherColor;
                if (yc < 0.0)
                {
                    // Shadow uses original-space distance from center
                    float shado = 1.0 - (sqrt(pow(ptOrig.x - 0.5, 2.0) +
                                              pow(ptOrig.y - 0.5, 2.0)) / 0.71);
                    shado *= pow(-yc / _cylinderRadius, 3.0);
                    shado *= 0.5;
                    otherColor = vec4(0.0, 0.0, 0.0, shado);
                }
                else
                {
                    otherColor = _pageSrc(uv);
                }
                color = _antiAlias(color, otherColor,
                                   _cylinderRadius - abs(yc));
            }
        }
    }

    return color;
}

// ---- curl shadow helper -------------------------------------

float _curlSpaceYc(vec2 uvCurl, float cylCenter)
{
    const float tilt = 30.0 * _PI / 180.0;
    float c = cos(-tilt), s = sin(-tilt);
    mat3 rot = mat3(c, s, 0.0, -s, c, 0.0, 0.12, 0.258, 1.0);
    vec3 pt = rot * vec3(uvCurl, 1.0);
    return pt.y - cylCenter;
}

// ---- entry point --------------------------------------------

vec4 FUNCNAME(vec2 tc)
{
    int passStage = PREFIX(passStage);
    if (passStage == 0)
        return INPUT1(tc);

    float amount      = PREFIX(amount);
    float dirRad      = PREFIX(dirRad);
    float uScale      = PREFIX(uScale);
    float shadowScale = PREFIX(shadowScale);  // 0.0~1.0, default 0.5

    vec2 scaledTC = (tc - 0.5) / uScale + 0.5;

    bool inFrame = (scaledTC.x >= 0.0 && scaledTC.x <= 1.0 &&
                    scaledTC.y >= 0.0 && scaledTC.y <= 1.0);

    const float clipMargin = 0.25;
    if (scaledTC.x < -clipMargin || scaledTC.x > 1.0 + clipMargin ||
        scaledTC.y < -clipMargin || scaledTC.y > 1.0 + clipMargin)
        return INPUT1(tc);

    vec4 color = _curlPage(scaledTC, amount, dirRad, inFrame);
    float curlProgress = clamp((amount + 0.16) / (1.3 + 0.16), 0.0, 1.0);

    // Shadow grows as page unfurls (curlProgress: 1=curled, 0=flat)
    float shadowProgress = 1.0 - curlProgress;

    // 平铺收尾（卷曲度趋近 0）：按 amount 进度收阴影，与片段总时长无关
    const float curlShadowTailEnd = 0.4;
    float flatEndShadowFade = smoothstep(0.0, curlShadowTailEnd, curlProgress);

    if (shadowProgress > 0.01 && flatEndShadowFade > 0.001)
    {
        vec2 uvCurl   = _rotUV(scaledTC, dirRad);
        float yc      = _curlSpaceYc(uvCurl, amount);

        // Signed distance behind the curl edge (positive = in shadow zone)
        float distBehind = -_cylinderRadius - yc;

        // Shadow band — Gaussian falloff from curl edge
        float spread    = 0.15 + shadowProgress * 0.25;
        float peakAlpha = shadowProgress * 0.7 * shadowScale * 2.0 * flatEndShadowFade;

        float t           = distBehind / spread;
        float shadowAlpha = peakAlpha * exp(-t * t * 1.0);
        shadowAlpha       = clamp(shadowAlpha, 0.0, 1.0);

        const float expand    = 0.05;
        const float fadeWidth = 0.08;
        float ex = min(scaledTC.x + expand, 1.0 + expand - scaledTC.x) / fadeWidth;
        float ey = min(scaledTC.y + expand, 1.0 + expand - scaledTC.y) / fadeWidth;
        float edgeFade = clamp(ex, 0.0, 1.0) * clamp(ey, 0.0, 1.0);
        edgeFade = edgeFade * edgeFade * (3.0 - 2.0 * edgeFade);

        shadowAlpha *= edgeFade;

        bool inShadowRegion = (scaledTC.x >= -expand && scaledTC.x <= 1.0 + expand &&
                               scaledTC.y >= -expand && scaledTC.y <= 1.0 + expand);
        if (shadowAlpha > 0.005 && inShadowRegion)
        {
            if (color.a < 0.02)
                color = vec4(0.0, 0.0, 0.0, shadowAlpha);
            else
                color.rgb *= 1.0 - shadowAlpha * 0.85;
        }
    }

    // Porter-Duff over：保留合成后的 alpha，不强制为 1（底层半透明时仍正确）
    vec4 base = INPUT1(tc);
    float ba = base.a;
    float ca = color.a;
    vec3 outPm = color.rgb * ca + base.rgb * ba * (1.0 - ca);
    float outA = ca + ba * (1.0 - ca);
    if (outA > 1e-5)
    {
        vec3 outRgb = clamp(outPm / outA, 0.0, 1.0);
        color = vec4(outRgb, outA);
    }
    else
        color = vec4(0.0);
    return color;
}

#define u_inCornerPosition vec2(0.0, 0.0)
#define u_classicUi 0.0
#define PI 3.14159265359
#define EPSILON 1e-8

float normpdf(float x, float sigma)
{
    return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

vec4 motionBlurfg(vec2 tc, float angle, float blur, float repears)
{
    float sigma = 28.0;
    float theta = radians(angle);
    vec2 direction = vec2(sin(theta), cos(theta));
    float weight = normpdf(0.0, sigma);
    vec4 retCol = INPUT1(tc);
    retCol *= weight;
    float sum = weight;
    float radius = 0.03 * blur;

    for (float j = 1.0; j < repears; j += 1.0)
    {
        weight = normpdf(j / 10.0 * 25.0, sigma);
        float offset = radius * j;
        vec2 uv = tc + direction * offset;
        retCol += INPUT1(uv) * weight;
        sum += weight;

        uv = tc - direction * offset;
        retCol += INPUT1(uv) * weight;
        sum += weight;
    }

    retCol /= sum;
    retCol = clamp(retCol, 0.0, 1.0);
    return retCol;
}
vec4 motionBlurbg(vec2 tc, float angle, float blur, float repears)
{
    float sigma = 28.0;
    float theta = radians(angle);
    vec2 direction = vec2(sin(theta), cos(theta));
    float weight = normpdf(0.0, sigma);
    vec4 retCol = INPUT2(tc);
    retCol *= weight;
    float sum = weight;
    float radius = 0.03 * blur;

    for (float j = 1.0; j < repears; j += 1.0)
    {
        weight = normpdf(j / 10.0 * 25.0, sigma);
        float offset = radius * j;
        vec2 uv = tc + direction * offset;
        retCol += INPUT2(uv) * weight;
        sum += weight;

        uv = tc - direction * offset;
        retCol += INPUT2(uv) * weight;
        sum += weight;
    }

    retCol /= sum;
    retCol = clamp(retCol, 0.0, 1.0);
    return retCol;
}

float cut(vec2 u)
{
    return step(0., u.x) * step(u.x, 1.) * step(0., u.y) * step(u.y, 1.);
}

float cross(vec2 a, vec2 b)
{
    return a.x * b.y - a.y * b.x;
}

float distancePtToLine(vec2 pt, vec3 line)
{
    return abs(line.x * pt.x + line.y * pt.y + line.z) / sqrt(line.x * line.x + line.y * line.y);
}

vec2 symmetryPtByLine(vec2 pt, vec3 line)
{
    float a = line.x;
    float b = line.y;
    float c = line.z;
    float x = ((b * b - a * a) * pt.x - 2. * a * (b * pt.y + c)) / (a * a + b * b);
    float y = ((a * a - b * b) * pt.y - 2. * b * (a * pt.x + c)) / (a * a + b * b);
    return vec2(x, y);
}

vec3 getLineFrom2Pts(vec2 p1, vec2 p2)
{ //
    float a = p1.y - p2.y;
    float b = p2.x - p1.x;
    float c = p1.x * p2.y - p1.y * p2.x;
    return vec3(a, b, c);
}

vec4 getParallelLineFromDistance(vec3 line, float dist)
{
    float a = line.x;
    float b = line.y;
    float c = line.z;
    float tmp = sqrt(a * a + b * b);
    float upLineC = dist * tmp + c;
    float downLineC = c - dist * tmp;
    return vec4(a, b, upLineC, downLineC);
}

// DEBUG drawing
#define LINE_WIDTH 0.001
vec4 drawLine(vec2 u, vec3 line, vec3 col, float lineWidth, vec4 res)
{
    float d = distancePtToLine(u, line);
    d = step(d, lineWidth);
    res += vec4(vec3(d) * col, d);
    return res;
}

/*
    [cylinder mapping],
    by cornerPos, foldPos, foldRadius
    classicUi for ae type
*/
vec4 cylinderMapping(int number, vec2 i_uv, vec2 cornerPos, vec2 foldPos, float foldRadius, float classicUi)
{
    float process = PREFIX(process);
    vec2 uv = i_uv;

    vec2 cp = cornerPos;
    vec2 fp = vec2(foldPos.x + EPSILON, foldPos.y + EPSILON);

    if (cp.y >= 1.)
    {
        cp.y = max(fp.y + 0.001, cp.y);
    }
    if (cp.y <= 0.)
    {
        cp.y = min(fp.y - 0.001, cp.y);
    }
    if (cp.x >= 1.)
    {
        cp.x = max(fp.x + 0.001, cp.x);
    }
    if (cp.x <= 0.)
    {
        cp.x = min(fp.x - 0.001, cp.x);
    }
    float fr = max(foldRadius, EPSILON);
    vec2 foldDir = normalize(fp - cp);

    vec2 centerPt = (cp + fp) * 0.5;

    // //////////////////////// Basic Line //////////////////////////
    float foldLength = PI * fr * 0.5;

    vec3 line1 = getLineFrom2Pts(cp, fp); // ax+by+c=0
    vec3 line4Fp = vec3(line1.y, -line1.x, line1.x * fp.y - line1.y * fp.x);
    float k = sign(line4Fp.x / (line4Fp.y + EPSILON)); // >0=>\, <0=>/

    vec3 line2 = vec3(line1.y, -line1.x, line1.x * centerPt.y - line1.y * centerPt.x);
    if (classicUi > 0.5)
    {
        line4Fp = getParallelLineFromDistance(line2, 0.).xyw;
    }

    vec3 lineCurl1 = getParallelLineFromDistance(line2, foldLength).xyw;
    vec3 lineCurl2 = getParallelLineFromDistance(lineCurl1, fr).xyz;

    float foldOuter = 0.;
    if (k < 0.)
    { // line for /
        if (line4Fp.z - lineCurl1.z > 0.)
        {
            lineCurl1.z = line4Fp.z;
            lineCurl2 = getParallelLineFromDistance(lineCurl1, fr).xyz;
            foldOuter = 1.;
        }
    }
    else
    {
        if (lineCurl1.z - line4Fp.z < 0.)
        {
            lineCurl1.z = line4Fp.z;
            lineCurl2 = getParallelLineFromDistance(lineCurl1, fr).xyz;
            foldOuter = 1.;
        }
    }
    vec2 p1 = vec2((-lineCurl1.z - lineCurl1.y * cp.y) / (lineCurl1.x + EPSILON), cp.y);
    vec2 p2 = vec2(cp.x, (-lineCurl1.z - lineCurl1.x * cp.x) / (lineCurl1.y + EPSILON));
    if (k > 0.)
    {
        vec2 t = p1;
        p1 = p2;
        p2 = t;
    }
    float bottomFlatMask = cross(p1 - p2, p1 - uv) > 0. ? 1. : 0.;

    // //////////////////// Bottom Curl Uv Mapping && Texturing /////////////////////////////////
    float dFromCurlLine1 = distancePtToLine(uv, lineCurl1);
    float theta = asin(dFromCurlLine1 / fr) * step(dFromCurlLine1, fr + 0.001);
    float curlLength = theta * fr;
    vec2 curlUv = uv + normalize(-foldDir) * (curlLength - dFromCurlLine1);
    curlUv = clamp(curlUv, vec2(-10.), vec2(10.));

    vec2 bottomUv = mix(curlUv * cut(curlUv), uv, bottomFlatMask);
    vec4 bottomCol = number > 0 ? INPUT2(bottomUv) : INPUT1(bottomUv);
    bottomCol *= clamp(bottomFlatMask + cut(curlUv), 0.0, 1.);
    bottomCol = mix(bottomCol * bottomFlatMask, bottomCol * step(dFromCurlLine1, fr + 0.0001),
                    (bottomCol * step(dFromCurlLine1, fr + 0.0001)).a);

    vec3 foldLine = line2;
    if (foldOuter > 0.5)
    {
        foldLine = getParallelLineFromDistance(lineCurl1, foldLength).xyz;
    }
    vec2 mirrorUv = symmetryPtByLine(uv, foldLine);
    float mirrorMask = bottomFlatMask * cut(mirrorUv);

    vec2 mirrorUpsideCurlUv = symmetryPtByLine(curlUv, foldLine);
    float mirrorUpsideMask = cut(mirrorUpsideCurlUv) * (1. - bottomFlatMask);
    mirrorUpsideMask *= step(dFromCurlLine1, fr + 0.001);

    vec2 upsideUv = mix(mirrorUv, mirrorUpsideCurlUv, mirrorUpsideMask);
    vec4 upsideCol = number > 0 ? INPUT2(upsideUv) : INPUT1(upsideUv);
    upsideCol *= clamp(mirrorUpsideMask + mirrorMask, 0.0, 1.);

    upsideCol.rgb *= 0.7;

    vec4 io_res = vec4(0.0);
    if (process < 0.1)
    {
        io_res = vec4(vec3(cut(uv)), 0.0);
    }
    else
    {
        io_res = vec4(vec3(cut(curlUv)), 0.0);
    }

    io_res.a = io_res.b;
    io_res.rgb *= io_res.a;
    if (io_res.r > 0.0)
    {
        io_res.rgb = vec3(0.0, 0.0, 0.0);
    }
    io_res.rgb = mix(io_res.rgb, bottomCol.rgb, bottomCol.a);
    io_res.rgb = mix(io_res.rgb, upsideCol.rgb, upsideCol.a);
    return io_res;
}

vec4 FUNCNAME(vec2 tc)
{
    vec2 uv1 = tc;
    vec2 uv = tc;

    float uOffsetXY = PREFIX(uOffsetXY);
    uv += vec2(uOffsetXY, uOffsetXY);

    float uFoldRadius1 = PREFIX(uFoldRadius1);
    float uFoldRadius2 = PREFIX(uFoldRadius2);
    float uFoldRadius3 = PREFIX(uFoldRadius3);
    vec2 u_inFoldPositions1 = PREFIX(u_inFoldPosition1);
    vec2 u_inFoldPositions2 = PREFIX(u_inFoldPosition2);
    vec2 u_inFoldPositions3 = PREFIX(u_inFoldPosition3);
    vec4 res = vec4(0.0);

    // motion blur params
    float uDirection = 6.0;
    float uStrength = PREFIX(uBlurStrength) * 0.01;
    float uSampleCount = 0.35;
    float angle = uDirection * 360.0;
    float blur = uStrength * 0.2;
    float repeat = uSampleCount * 61.0;

    if (PREFIX(stepType) == 0)
    {
        res = motionBlurfg(tc, angle, blur, repeat);
    }
    else if (PREFIX(stepType) == 1)
    {
        res = motionBlurbg(tc, angle, blur, repeat);
    }
    else if (PREFIX(stepType) == 2)
    {
        vec4 imgStatic = INPUT2(uv);
        vec4 baseColor1 = cylinderMapping(0, uv1, u_inCornerPosition, u_inFoldPositions1, uFoldRadius1, u_classicUi);
        vec4 baseColor2 = cylinderMapping(0, uv1, u_inCornerPosition, u_inFoldPositions2, uFoldRadius2, u_classicUi);
        vec4 backColor = cylinderMapping(1, uv1, u_inCornerPosition, u_inFoldPositions3, uFoldRadius3, u_classicUi);
        res = mix(baseColor2, baseColor1, baseColor1.a);
        res = mix(backColor, res, res.a);
        res = mix(imgStatic, res, res.a);
        res *= cut(uv1);
    }
    else if (PREFIX(stepType) == 3)
    {
        res = motionBlurfg(tc, angle, blur, repeat);
    }

    return res;
}

vec2 rotate(vec2 v, vec2 o, float a) {
    float s = sin(a);
    float c = cos(a);
    mat2 m = mat2(c, -s, s, c);
    return m * (v-o) + o;
}

vec2 TransformPlane(vec2 uv, vec2 center, float XRot, float YRot) {
  uv = uv*2.0-1.0;
  center = center*2.0-1.0;
  // First Rotate around Y axis
  vec2 RayDirection =  vec2(uv.x, 0.0);
  vec2 A1 = vec2(0.0, -1.0);
//   vec2 A1 = vec2(-1.0, 0.0);
  vec2 B1 = RayDirection - A1;
  vec2 C1 = rotate(vec2(-1.0, 0.0), vec2(center.x, 0.0), YRot);
  vec2 D1 = rotate(vec2( 1.0, 0.0), vec2(center.x, 0.0), YRot) - C1;
  // calculate intersection point
  float u = ( (C1.y + 1.0) * D1.x - C1.x * D1.y ) / (D1.x*B1.y-D1.y*B1.x);
  // position on the plane:
  float sx = u * B1.x;
  float sy = u * uv.y;
  // Now Rotate around X axis
  if(XRot == 0.0){
    return vec2(sx, sy)*0.5+0.5;
  }
  RayDirection = vec2(sy, 0.0);
  vec2 B2 = RayDirection - A1;
  vec2 C2 = rotate(vec2(-1.0, 0.0), vec2(center.y, 0.0), XRot);
  vec2 D2 = rotate(vec2( 1.0, 0.0), vec2(center.y, 0.0), XRot) - C2;
  // calculate intersection point
  float v = ( (C2.y + 1.0) * D2.x - C2.x * D2.y ) / (D2.x*B2.y-D2.y*B2.x);
  // final position on the plane:
  return vec2(v * sx, v * B2.x )*0.5+0.5; 
}

