#define PI 3.14159265358979323846
#define EPSILON 1e-5
#define FLIP_DURATION 0.3
#define MID_SECTION_SLOW_POWER 1.7

float saturate(float value) {
    return clamp(value, 0.0, 1.0);
}

float bandFalloff(float coord, float center, float width) {
    float normalized = (coord - center) / max(width, EPSILON);
    return exp(-normalized * normalized);
}

float remapFlipProgressForMidSection(float value) {
    float centered = saturate(value) * 2.0 - 1.0;
    float curved = sign(centered) * pow(abs(centered), MID_SECTION_SLOW_POWER);
    return saturate(0.5 + 0.5 * curved);
}

float insideRect(vec2 uv) {
    return step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
}

vec4 sampleOriginal(vec2 uv) {
