    float panelEdgeShade = 0.075 * sideFalloff * fold;

    color.rgb *= 1.0 - hingeShade;
    color.rgb *= 1.0 - faceShade;
    color.rgb *= 1.0 - foldCreaseShade;
    color.rgb *= 1.0 - foldEdgeOcclusion;
    color.rgb *= 1.0 - panelEdgeShade;
    color.rgb += (edgeHighlight + rimHighlight + panelCenterLift) * color.a;
    return color;
}

// Cast shadow from fold crease onto background page.
// coord: pixel position along fold axis (uv.x or uv.y)
// edge: position of fold crease
// awayDir: +1 if background is in +coord direction from edge, -1 if in -coord direction
vec4 applyFoldCastShadow(vec4 color, float coord, float edge, float awayDir, float foldStrength) {
    float shadowPresence = smoothstep(0.02, 0.10, foldStrength);
    float shadowFade = 1.0 - smoothstep(0.28, 0.92, foldStrength);
    float earlySoftener = mix(0.70, 1.0, smoothstep(0.14, 0.34, foldStrength));
    float shadowStrength = shadowPresence * shadowFade * earlySoftener;
    float edgeFalloff = mix(5.6, 12.5, foldStrength);
    float contactWidth = mix(0.045, 0.024, foldStrength);
    float castOffset = mix(0.075, 0.022, foldStrength);
    float castWidth = mix(0.13, 0.055, foldStrength);

    float d = (coord - edge) * awayDir;
    float shadow = exp(-max(d, 0.0) * edgeFalloff) * 0.20 * shadowStrength
                 + bandFalloff(coord, edge, contactWidth) * 0.12 * shadowStrength
                 + bandFalloff(coord, edge + castOffset * awayDir, castWidth) * 0.13 * shadowStrength;
    shadow = clamp(shadow, 0.0, 0.80);
    color.rgb *= 1.0 - shadow;
    return color;
}

// ============ 顶部翻起的折叠面（原始画面被向上翻）============
vec4 sampleTopFoldFront(vec2 uv, float visibleHeight, float foldStrength) {
    float cosTheta = max(visibleHeight / 0.5, EPSILON);
    float sourceY = 0.5 - (0.5 - uv.y) / cosTheta;
    sourceY = clamp(sourceY, 0.0, 0.5);

    vec4 color = sampleOriginal(vec2(uv.x, sourceY));
    float local = saturate((0.5 - uv.y) / max(visibleHeight, EPSILON));
    color = applyFoldDoorLighting(color, local, uv.x, foldStrength);
    return applyFoldCastShadow(color, uv.y, 0.5, -1.0, foldStrength);
}

// ============ 底部翻入（目标画面从下方翻进来）============
vec4 sampleBottomFlipIn(vec2 uv, float coverBottom, float visibleHeight, float foldStrength) {
    float cosTheta = max(visibleHeight / 0.5, EPSILON);
    float sourceY = 0.5 + (uv.y - 0.5) / cosTheta;
    sourceY = clamp(sourceY, 0.5, 1.0);

    vec4 color = sampleTarget(vec2(uv.x, sourceY));
    float local = saturate((coverBottom - uv.y) / max(visibleHeight, EPSILON));
    color = applyFoldDoorLighting(color, local, uv.x, foldStrength);
    return applyFoldCastShadow(color, uv.y, 0.5, 1.0, foldStrength);
}

// INPUT2 top background — receives shadow from phase2 hinge at 0.5, falling upward
vec4 sampleTargetWithShadowTop(vec2 uv, float foldStrength) {
    vec4 color = sampleTarget(uv);
    return applyFoldCastShadow(color, uv.y, 0.5, -1.0, foldStrength);
}

// INPUT1 bottom background — receives shadow from phase1 hinge at 0.5, falling downward
vec4 sampleOriginalBottomStable(vec2 uv, float foldStrength) {
    vec4 color = sampleOriginal(uv);
    return applyFoldCastShadow(color, uv.y, 0.5, 1.0, foldStrength);
}

// ============ 主函数：从上向下翻页 ============
vec4 FUNCNAME(vec2 tc) {
    float progress = saturate(PREFIX(transitionProgress));
    float flipStart = 0.5 - 0.5 * FLIP_DURATION;
    float flipEnd = flipStart + FLIP_DURATION;

    if (progress <= 0.001 || progress <= flipStart) {
        return INPUT1(tc);
    }
    if (progress >= 0.999 || progress >= flipEnd) {
        return INPUT2(tc);
    }

    float flipWindowProgress = saturate((progress - flipStart) / max(FLIP_DURATION, EPSILON));
    float flipProgress = remapFlipProgressForMidSection(flipWindowProgress);

    // Phase 1: 顶部向上翻起
    float phase1 = saturate(flipProgress * 2.0);
    float visibleHeight1 = 0.5 * (1.0 - phase1);
    float foldStrength1 = phase1;
    float revealEnd1 = 0.5 - visibleHeight1;

    // Phase 2: 底部向上翻入
    float phase2 = saturate(flipProgress * 2.0 - 1.0);
    float visibleHeight2 = 0.5 * phase2;
    float coverBottom = 0.5 + visibleHeight2;
    float foldStrength2 = phase2;

    bool isPortrait = iResolution.x < iResolution.y;

    // ========= 处理上半区域（顶部翻起）=========
    if (tc.y < 0.5) {
        // INPUT2 top background: shadow from phase2 hinge at 0.5, falling upward
        if (isPortrait) {
            vec4 base = sampleTargetWithShadowTop(tc, foldStrength2);
            if (visibleHeight1 > EPSILON && tc.y > revealEnd1) {
                vec4 fold = sampleTopFoldFront(tc, visibleHeight1, foldStrength1);
                vec3 rgb = fold.rgb * fold.a + base.rgb * (1.0 - fold.a);
                return vec4(rgb, max(fold.a, base.a));
            }
            return base;
        } else {
            if (visibleHeight1 > EPSILON && tc.y > revealEnd1) {
                return sampleTopFoldFront(tc, visibleHeight1, foldStrength1);
            }
            return sampleTargetWithShadowTop(tc, foldStrength2);
        }
    }

    // ========= 处理下半区域：底部翻入 =========
    // INPUT1 bottom background: shadow from phase1 hinge at 0.5, falling downward
    if (isPortrait) {
        vec4 base = sampleOriginalBottomStable(tc, foldStrength1);
        if (visibleHeight2 > EPSILON && tc.y <= coverBottom) {
            vec4 fold = sampleBottomFlipIn(tc, coverBottom, visibleHeight2, foldStrength2);
            vec3 rgb = fold.rgb * fold.a + base.rgb * (1.0 - fold.a);
            return vec4(rgb, max(fold.a, base.a));
        }
        return base;
    } else {
        if (visibleHeight2 > EPSILON && tc.y <= coverBottom) {
            return sampleBottomFlipIn(tc, coverBottom, visibleHeight2, foldStrength2);
        }
        return sampleOriginalBottomStable(tc, foldStrength1);
    }
}

#define EPSILON 1e-5
#define FLIP_DURATION 0.5
#define MID_SECTION_SLOW_POWER 1.7
#define AXIS_X 0
#define AXIS_Y 1
#define FLOW_LOW_TO_HIGH 0
#define FLOW_HIGH_TO_LOW 1

float saturate(float value) {
    return clamp(value, 0.0, 1.0);
}

float remapFlipProgressForMidSection(float value) {
    float centered = saturate(value) * 2.0 - 1.0;
    float curved = sign(centered) * pow(abs(centered), MID_SECTION_SLOW_POWER);
    return saturate(0.5 + 0.5 * curved);
}

float insideRect(vec2 uv) {
    return step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
}

vec4 sampleOriginal(vec2 uv) {
    return INPUT1(uv) * insideRect(uv);
}

vec4 sampleTarget(vec2 uv) {
    return INPUT2(uv) * insideRect(uv);
}

vec2 getRegionSize(vec4 region) {
    return max(region.zw - region.xy, vec2(EPSILON, EPSILON));
}

vec2 toLocalUV(vec2 uv, vec4 region) {
    return (uv - region.xy) / getRegionSize(region);
}

vec2 toGlobalUV(vec2 localUV, vec4 region) {
    return region.xy + localUV * getRegionSize(region);
}

vec4 sampleTargetRegion(vec2 localUV, vec4 region) {
    return sampleTarget(toGlobalUV(localUV, region)) * insideRect(localUV);
}

float getAxisCoord(vec2 uv, int axis) {
    if (axis == AXIS_X) {
        return uv.x;
    }
    return uv.y;
}

vec2 setAxisCoord(vec2 uv, int axis, float value) {
    if (axis == AXIS_X) {
        return vec2(value, uv.y);
    }
    return vec2(uv.x, value);
}

vec4 applyFoldFrontLighting(vec4 color, float local, float foldStrength) {
    float edgeShade = 0.20 * (1.0 - local) * foldStrength;
    float farEdgeShade = 0.10 * local * foldStrength;
    float centerHighlight = 0.06 * pow(local, 1.5) * foldStrength;

    color.rgb *= 1.0 - edgeShade;
    color.rgb *= 1.0 - farEdgeShade;
    color.rgb += centerHighlight;
    return color;
}

vec4 applyFlipInLighting(vec4 color, float local, float foldStrength) {
    float hingeShade = 0.22 * local * foldStrength;
    float farEdgeShade = 0.10 * (1.0 - local) * foldStrength;
    float highlight = 0.08 * pow(1.0 - local, 1.5) * foldStrength;

    color.rgb *= 1.0 - hingeShade;
    color.rgb *= 1.0 - farEdgeShade;
    color.rgb += highlight;
    return color;
}

vec4 applyStableShadow(vec4 color, float coord, float coverCoord, float foldStrength, float shadowMask) {
    float shadow = exp(-abs(coord - coverCoord) * 30.0) * 0.16 * foldStrength * shadowMask;
    color.rgb *= 1.0 - shadow;
    return color;
}

vec4 sampleTargetFlipInDirectional(int axis, int flow, vec2 uv, vec4 region, float coverCoord, float visibleExtent, float foldStrength) {
    float cosTheta = max(visibleExtent / 0.5, EPSILON);
    float coord = getAxisCoord(uv, axis);
    float sourceCoord = 0.0;
    float local = 0.0;

    if (flow == FLOW_LOW_TO_HIGH) {
        sourceCoord = 0.5 + (coord - 0.5) / cosTheta;
        sourceCoord = clamp(sourceCoord, 0.5, 1.0);
        local = saturate((coverCoord - coord) / max(visibleExtent, EPSILON));
    } else {
        sourceCoord = 0.5 - (0.5 - coord) / cosTheta;
        sourceCoord = clamp(sourceCoord, 0.0, 0.5);
        local = saturate((coord - coverCoord) / max(visibleExtent, EPSILON));
    }

    vec4 color = sampleTargetRegion(setAxisCoord(uv, axis, sourceCoord), region);
    return applyFlipInLighting(color, local, foldStrength);
}

vec4 sampleCommittedAfterStage1(vec2 uv) {
    if (uv.y >= 0.5 && uv.x >= 0.5) {
        return sampleTarget(uv);
    }
    return sampleOriginal(uv);
}

vec4 sampleCommittedAfterStage2(vec2 uv) {
    if (uv.x >= 0.5) {
        return sampleTarget(uv);
    }
    return sampleOriginal(uv);
}

vec4 sampleCommittedAfterStage3(vec2 uv) {
    if (uv.x >= 0.5 || uv.y < 0.5) {
        return sampleTarget(uv);
    }
    return sampleOriginal(uv);
}

vec4 sampleStageBase(int stageIndex, vec2 uv) {
    if (stageIndex <= 0) {
        return sampleOriginal(uv);
    }
    if (stageIndex == 1) {
        return sampleCommittedAfterStage1(uv);
    }
    if (stageIndex == 2) {
        return sampleCommittedAfterStage2(uv);
    }
    return sampleCommittedAfterStage3(uv);
}

vec4 sampleStageBaseRegion(int stageIndex, vec2 localUV, vec4 region) {
    return sampleStageBase(stageIndex, toGlobalUV(localUV, region)) * insideRect(localUV);
}

vec4 sampleBaseFoldFrontDirectional(int stageIndex, int axis, int flow, vec2 uv, vec4 region, float visibleExtent, float foldStrength) {
    float cosTheta = max(visibleExtent / 0.5, EPSILON);
    float coord = getAxisCoord(uv, axis);
    float sourceCoord = 0.0;
    float local = 0.0;

    if (flow == FLOW_LOW_TO_HIGH) {
        sourceCoord = 0.5 - (0.5 - coord) / cosTheta;
        sourceCoord = clamp(sourceCoord, 0.0, 0.5);
        local = saturate((0.5 - coord) / max(visibleExtent, EPSILON));
    } else {
        sourceCoord = 0.5 + (coord - 0.5) / cosTheta;
        sourceCoord = clamp(sourceCoord, 0.5, 1.0);
        local = saturate((coord - 0.5) / max(visibleExtent, EPSILON));
    }

    vec4 color = sampleStageBaseRegion(stageIndex, setAxisCoord(uv, axis, sourceCoord), region);
    return applyFoldFrontLighting(color, local, foldStrength);
}

vec4 sampleBaseStableDirectional(int stageIndex, int axis, int flow, vec2 uv, vec4 region, float coverCoord, float foldStrength) {
    vec4 color = sampleStageBaseRegion(stageIndex, uv, region);
    float coord = getAxisCoord(uv, axis);
    float shadowMask = 0.0;

    if (flow == FLOW_LOW_TO_HIGH) {
        shadowMask = step(coverCoord, coord);
    } else {
        shadowMask = step(coord, coverCoord);
    }

    return applyStableShadow(color, coord, coverCoord, foldStrength, shadowMask);
}

vec4 compositeFoldOverBase(vec4 fold, vec4 base) {
    vec3 rgb = fold.rgb * fold.a + base.rgb * (1.0 - fold.a);
    return vec4(rgb, max(fold.a, base.a));
}

vec4 renderPartialDirectional(int stageIndex, int axis, int flow, vec2 globalUV, vec4 region, float foldProgress, bool mixFoldFace) {
    vec2 uv = toLocalUV(globalUV, region);
    float coord = getAxisCoord(uv, axis);

    float phase1 = saturate(foldProgress * 2.0);
    float visibleExtent1 = 0.5 * (1.0 - phase1);
    float foldStrength1 = phase1;

    float phase2 = saturate(foldProgress * 2.0 - 1.0);
    float visibleExtent2 = 0.5 * phase2;
    float foldStrength2 = phase2;

    float revealCoord = 0.0;
    float coverCoord = 0.0;

    if (flow == FLOW_LOW_TO_HIGH) {
        revealCoord = 0.5 - visibleExtent1;
        coverCoord = 0.5 + visibleExtent2;

        if (coord < 0.5) {
            if (visibleExtent1 > EPSILON && coord > revealCoord) {
                vec4 fold = sampleBaseFoldFrontDirectional(stageIndex, axis, flow, uv, region, visibleExtent1, foldStrength1);
                if (mixFoldFace) {
                    vec4 base = sampleStageBase(stageIndex, globalUV);
                    return compositeFoldOverBase(fold, base);
                }
                return fold;
            }
            return sampleStageBase(stageIndex, globalUV);
        }

        if (visibleExtent2 > EPSILON && coord <= coverCoord) {
            vec4 fold = sampleTargetFlipInDirectional(axis, flow, uv, region, coverCoord, visibleExtent2, foldStrength2);
            if (mixFoldFace) {
                vec4 base = sampleStageBase(stageIndex, globalUV);
                return compositeFoldOverBase(fold, base);
            }
            return fold;
        }
    } else {
        revealCoord = 0.5 + visibleExtent1;
        coverCoord = 0.5 - visibleExtent2;

        if (coord >= 0.5) {
            if (visibleExtent1 > EPSILON && coord < revealCoord) {
                vec4 fold = sampleBaseFoldFrontDirectional(stageIndex, axis, flow, uv, region, visibleExtent1, foldStrength1);
                if (mixFoldFace) {
                    vec4 base = sampleStageBase(stageIndex, globalUV);
                    return compositeFoldOverBase(fold, base);
                }
                return fold;
            }
            return sampleStageBase(stageIndex, globalUV);
        }

        if (visibleExtent2 > EPSILON && coord >= coverCoord) {
            vec4 fold = sampleTargetFlipInDirectional(axis, flow, uv, region, coverCoord, visibleExtent2, foldStrength2);
            if (mixFoldFace) {
                vec4 base = sampleStageBase(stageIndex, globalUV);
                return compositeFoldOverBase(fold, base);
            }
            return fold;
        }
    }

    return sampleBaseStableDirectional(stageIndex, axis, flow, uv, region, coverCoord, max(foldStrength1, foldStrength2));
}

vec4 FUNCNAME(vec2 tc) {
    float progress = saturate(PREFIX(transitionProgress));
    float flipStart = 0.5 - 0.5 * FLIP_DURATION;
    float flipEnd = flipStart + FLIP_DURATION;

    if (progress <= 0.001 || progress <= flipStart) {
        return INPUT1(tc);
    }
    if (progress >= 0.999 || progress >= flipEnd) {
        return INPUT2(tc);
    }

    float flipWindowProgress = saturate((progress - flipStart) / max(FLIP_DURATION, EPSILON));
    float stagedProgress = flipWindowProgress * 4.0;

    vec4 topHalfRegion = vec4(0.0, 0.5, 1.0, 1.0);
    vec4 rightHalfRegion = vec4(0.5, 0.0, 1.0, 1.0);
    vec4 bottomHalfRegion = vec4(0.0, 0.0, 1.0, 0.5);
    vec4 leftHalfRegion = vec4(0.0, 0.0, 0.5, 1.0);
    bool isPortrait = iResolution.y > iResolution.x;
    bool mixHorizontalFold = !isPortrait;
    bool mixVerticalFold = isPortrait;

    if (stagedProgress < 1.0) {
        float stageProgress = remapFlipProgressForMidSection(saturate(stagedProgress));
        if (tc.y >= 0.5) {
            return renderPartialDirectional(0, AXIS_X, FLOW_LOW_TO_HIGH, tc, topHalfRegion, stageProgress, mixHorizontalFold);
        }
        return sampleStageBase(0, tc);
    }

    if (stagedProgress < 2.0) {
        float stageProgress = remapFlipProgressForMidSection(saturate(stagedProgress - 1.0));
        if (tc.x >= 0.5) {
            return renderPartialDirectional(1, AXIS_Y, FLOW_HIGH_TO_LOW, tc, rightHalfRegion, stageProgress, mixVerticalFold);
        }
        return sampleStageBase(1, tc);
    }

    if (stagedProgress < 3.0) {
        float stageProgress = remapFlipProgressForMidSection(saturate(stagedProgress - 2.0));
        if (tc.y < 0.5) {
            return renderPartialDirectional(2, AXIS_X, FLOW_HIGH_TO_LOW, tc, bottomHalfRegion, stageProgress, mixHorizontalFold);
        }
        return sampleStageBase(2, tc);
    }

    float stageProgress = remapFlipProgressForMidSection(saturate(stagedProgress - 3.0));
    if (tc.x < 0.5) {
        return renderPartialDirectional(3, AXIS_Y, FLOW_LOW_TO_HIGH, tc, leftHalfRegion, stageProgress, mixVerticalFold);
    }
    return sampleStageBase(3, tc);
}

#define PI 3.14159265358979323846
#define EPSILON 1e-5
#define FLIP_EASE_OUT_POWER 5.0
#define ROTATE_Y 0
#define ROTATE_X 1
#define CAMERA_DISTANCE 2.0

float saturate(float value) {
    return clamp(value, 0.0, 1.0);
}

float remapFlipProgressForMidSection(float value) {
    float t = saturate(value);
    return 1.0 - pow(1.0 - t, FLIP_EASE_OUT_POWER);
}

float insideRect(vec2 uv) {
    return step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
}

vec4 sampleOriginal(vec2 uv) {
    return INPUT1(uv) * insideRect(uv);
}

vec4 sampleTarget(vec2 uv) {
    return INPUT2(uv) * insideRect(uv);
}

vec4 sampleBlack(vec2 uv) {
    return vec4(0.0, 0.0, 0.0, insideRect(uv));
}

vec2 getRegionSize(vec4 region) {
    return max(region.zw - region.xy, vec2(EPSILON, EPSILON));
}

vec2 toLocalUV(vec2 uv, vec4 region) {
    return (uv - region.xy) / getRegionSize(region);
}

vec2 toGlobalUV(vec2 localUV, vec4 region) {
    return region.xy + localUV * getRegionSize(region);
}

vec2 toWorldXY(vec2 uv) {
    return uv - 0.5;
}

vec2 mirrorBackFaceUV(vec2 planeUV, int rotationAxis) {
    if (rotationAxis == ROTATE_Y) {
        return vec2(1.0 - planeUV.x, planeUV.y);
    }
    return vec2(planeUV.x, 1.0 - planeUV.y);
}

vec4 sampleFlipFace(vec2 planeUV, vec4 region, int rotationAxis, float backFace) {
    vec2 sampleUV = planeUV;
    if (backFace > 0.5) {
        sampleUV = mirrorBackFaceUV(sampleUV, rotationAxis);
        return sampleTarget(toGlobalUV(sampleUV, region));
    }
    return sampleOriginal(toGlobalUV(sampleUV, region));
}

vec4 applyFlipLighting(vec4 color, vec2 planeUV, int rotationAxis, float turnSign, float angle, float backFace) {
    float flipStrength = sin(angle);
    float coord = rotationAxis == ROTATE_Y ? planeUV.x : planeUV.y;
    float nearSide = turnSign > 0.0 ? coord : 1.0 - coord;
    float farSide = 1.0 - nearSide;

    float overallDarken = mix(0.10, 0.18, backFace) * flipStrength;
    float farShade = 0.18 * farSide * flipStrength;
    float backFaceShade = 0.08 * (1.0 - abs(cos(angle))) * backFace;
    float nearHighlight = 0.10 * pow(nearSide, 1.5) * flipStrength * (1.0 - 0.35 * backFace);

    color.rgb *= 1.0 - overallDarken;
    color.rgb *= 1.0 - farShade;
    color.rgb *= 1.0 - backFaceShade;
    color.rgb += nearHighlight;
    return color;
}

float tryRenderSpatialFlipRegion(
    vec2 globalUV,
    vec4 region,
    int rotationAxis,
    float turnSign,
    float flipProgress,
    out vec4 color,
    out float depth
) {
    vec2 regionSize = getRegionSize(region);
    vec2 regionCenterUV = 0.5 * (region.xy + region.zw);
    vec2 regionCenterXY = toWorldXY(regionCenterUV);
    float angle = PI * flipProgress;
    float sinTheta = sin(angle);
    float cosTheta = cos(angle);
    vec3 eye = vec3(0.0, 0.0, CAMERA_DISTANCE);
    vec3 screenSample = vec3(toWorldXY(globalUV), 0.0);
    vec3 rayDir = screenSample - eye;
    vec3 planeOrigin = vec3(regionCenterXY, 0.0);
    vec3 basisU = vec3(regionSize.x, 0.0, 0.0);
    vec3 basisV = vec3(0.0, regionSize.y, 0.0);

    if (rotationAxis == ROTATE_Y) {
        basisU = regionSize.x * vec3(cosTheta, 0.0, turnSign * sinTheta);
    } else {
        basisV = regionSize.y * vec3(0.0, cosTheta, turnSign * sinTheta);
    }

    vec3 planeNormal = cross(basisU, basisV);
    float planeDenom = dot(planeNormal, rayDir);
    vec2 planePoint = vec2(2.0, 2.0);
    float valid = 0.0;
    depth = -1e20;

    // Intersect the shared camera ray with the rotated panel in global space,
    // then project the hit point back into the panel's own [-0.5, 0.5] plane.
    if (abs(planeDenom) > EPSILON) {
        float rayT = dot(planeNormal, planeOrigin - eye) / planeDenom;
        if (rayT > EPSILON) {
            vec3 hitPoint = eye + rayDir * rayT;
            vec3 localHit = hitPoint - planeOrigin;
            float planeX = dot(localHit, basisU) / max(dot(basisU, basisU), EPSILON);
            float planeY = dot(localHit, basisV) / max(dot(basisV, basisV), EPSILON);
            planePoint = vec2(planeX, planeY);
            valid = insideRect(planePoint + 0.5);
            if (valid > 0.5) {
                depth = hitPoint.z;
            }
        }
    }

    if (valid < 0.5) {
        return 0.0;
    }

    vec2 planeUV = planePoint + 0.5;
    float backFace = step(cosTheta, 0.0);
    color = applyFlipLighting(sampleFlipFace(planeUV, region, rotationAxis, backFace), planeUV, rotationAxis, turnSign, angle, backFace);
    return 1.0;
}

void accumulateSpatialFlipRegion(
    vec2 globalUV,
    vec4 region,
    int rotationAxis,
    float turnSign,
    float flipProgress,
    inout vec4 bestColor,
    inout float bestDepth
) {
    vec4 candidateColor = vec4(0.0);
    float candidateDepth = -1e20;
    float covered = tryRenderSpatialFlipRegion(globalUV, region, rotationAxis, turnSign, flipProgress, candidateColor, candidateDepth);
    if (covered > 0.5 && candidateDepth > bestDepth) {
        bestDepth = candidateDepth;
        bestColor = candidateColor;
    }
}

vec4 FUNCNAME(vec2 tc) {
    float progress = saturate(PREFIX(transitionProgress));

    if (progress <= 0.001) {
        return INPUT1(tc);
    }
    if (progress >= 0.999) {
        return INPUT2(tc);
    }

    float flipProgress = remapFlipProgressForMidSection(progress);

    vec4 topLeftRegion = vec4(0.0, 0.5, 0.5, 1.0);
    vec4 topRightRegion = vec4(0.5, 0.5, 1.0, 1.0);
    vec4 bottomLeftRegion = vec4(0.0, 0.0, 0.5, 0.5);
    vec4 bottomRightRegion = vec4(0.5, 0.0, 1.0, 0.5);

    vec4 result = sampleBlack(tc);
    float bestDepth = -1e20;

    accumulateSpatialFlipRegion(tc, topLeftRegion, ROTATE_Y, -1.0, flipProgress, result, bestDepth);
    accumulateSpatialFlipRegion(tc, topRightRegion, ROTATE_X, 1.0, flipProgress, result, bestDepth);
    accumulateSpatialFlipRegion(tc, bottomLeftRegion, ROTATE_X, -1.0, flipProgress, result, bestDepth);
    accumulateSpatialFlipRegion(tc, bottomRightRegion, ROTATE_Y, 1.0, flipProgress, result, bestDepth);

    return result;
}

#define EPSILON 1e-5
#define LEAD_HOLD_DURATION 0.3
#define OPEN_WINDOW_DURATION 0.4
float saturate(float value) {
    return clamp(value, 0.0, 1.0);
}

float bandFalloff(float coord, float center, float width) {
    float normalized = (coord - center) / max(width, EPSILON);
    return exp(-normalized * normalized);
}

float insideRect(vec2 uv) {
    return step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
}

vec4 sampleOriginal(vec2 uv) {
    return INPUT1(uv) * insideRect(uv);
}

vec4 sampleTarget(vec2 uv) {
    return INPUT2(uv) * insideRect(uv);
}

vec2 getRegionSize(vec4 region) {
    return max(region.zw - region.xy, vec2(EPSILON, EPSILON));
}

vec2 toLocalUV(vec2 uv, vec4 region) {
    return (uv - region.xy) / getRegionSize(region);
}

vec2 toGlobalUV(vec2 localUV, vec4 region) {
    return region.xy + localUV * getRegionSize(region);
}

vec4 sampleOriginalRegion(vec2 localUV, vec4 region) {
    return sampleOriginal(toGlobalUV(localUV, region)) * insideRect(localUV);
}

vec4 sampleTargetRegion(vec2 localUV, vec4 region) {
    return sampleTarget(toGlobalUV(localUV, region)) * insideRect(localUV);
}

vec4 applyFoldDoorLighting(vec4 color, float local, float crossCoord, float foldStrength) {
    float fold = smoothstep(0.0, 1.0, foldStrength);
    float sideFalloff = pow(abs(crossCoord * 2.0 - 1.0), 1.3);
    float hingeShade = 0.14 * (1.0 - local) * fold;
    float faceShade = 0.28 * pow(local, 0.70) * fold;
    float foldCreaseShade = 0.19 * bandFalloff(local, 0.82, 0.18) * fold;
    float foldEdgeOcclusion = 0.16 * bandFalloff(local, 0.96, 0.07) * fold;
    float edgeHighlight = 0.055 * bandFalloff(local, 0.68, 0.12) * fold;
    float rimHighlight = 0.018 * bandFalloff(local, 0.91, 0.045) * fold;
    float panelCenterLift = 0.012 * (1.0 - sideFalloff) * fold;
    float panelEdgeShade = 0.075 * sideFalloff * fold;

    color.rgb *= 1.0 - hingeShade;
    color.rgb *= 1.0 - faceShade;
    color.rgb *= 1.0 - foldCreaseShade;
    color.rgb *= 1.0 - foldEdgeOcclusion;
    color.rgb *= 1.0 - panelEdgeShade;
    color.rgb += edgeHighlight;
    color.rgb += rimHighlight;
    color.rgb += panelCenterLift;
    return color;
}

vec4 applyCenterRevealShadow(vec4 color, float coord, float leftEdge, float rightEdge, float foldStrength) {
    float revealHalfWidth = max(0.5 * (rightEdge - leftEdge), EPSILON);
    float shadowPresence = smoothstep(0.02, 0.10, foldStrength);
    float shadowFade = 1.0 - smoothstep(0.28, 0.92, foldStrength);
    float earlyShadowSoftener = mix(0.70, 1.0, smoothstep(0.14, 0.34, foldStrength));
    float shadowStrength = shadowPresence * shadowFade * earlyShadowSoftener;
    float revealCenter = saturate(1.0 - abs(coord - 0.5) / revealHalfWidth);
    float centerDepth = pow(revealCenter, 5.0);
    float castOffset = mix(0.075, 0.022, foldStrength);
    float castWidth = mix(0.13, 0.055, foldStrength);
    float edgeFalloff = mix(5.6, 12.5, foldStrength);
    float contactWidth = mix(0.045, 0.024, foldStrength);
    float leftShadow = exp(-max(coord - leftEdge, 0.0) * edgeFalloff) * 0.20 * shadowStrength;
    float rightShadow = exp(-max(rightEdge - coord, 0.0) * edgeFalloff) * 0.20 * shadowStrength;
    float leftContactShadow = bandFalloff(coord, leftEdge, contactWidth) * 0.12 * shadowStrength;
    float rightContactShadow = bandFalloff(coord, rightEdge, contactWidth) * 0.12 * shadowStrength;
    float leftCastShadow = bandFalloff(coord, leftEdge + castOffset, castWidth) * 0.13 * shadowStrength;
    float rightCastShadow = bandFalloff(coord, rightEdge - castOffset, castWidth) * 0.13 * shadowStrength;
    float centerDepthShadow = 0.30 * centerDepth * shadowStrength;
    float centerCoreShadow = bandFalloff(coord, 0.5, max(revealHalfWidth * 0.46, 0.032)) * 0.13 * shadowStrength;
    float ambientShade = 0.015 * shadowStrength;
    float centerLift = 0.0015 * pow(revealCenter, 1.9) * shadowFade;
    float shadow = clamp(
        leftShadow + rightShadow +
        leftContactShadow + rightContactShadow +
        leftCastShadow + rightCastShadow +
        centerDepthShadow + centerCoreShadow + ambientShade,
        0.0,
        0.80
    );

    color.rgb *= 1.0 - shadow;
    color.rgb += centerLift;
    return color;
}

vec4 sampleLeftDoor(vec2 localUV, vec4 region, float visibleWidth, float foldStrength) {
    float cosTheta = max(visibleWidth / 0.5, EPSILON);
    float sourceX = clamp(localUV.x / cosTheta, 0.0, 0.5);
    vec4 color = sampleOriginalRegion(vec2(sourceX, localUV.y), region);
    float local = saturate(localUV.x / max(visibleWidth, EPSILON));
    return applyFoldDoorLighting(color, local, localUV.y, foldStrength);
}

vec4 sampleRightDoor(vec2 localUV, vec4 region, float visibleWidth, float foldStrength) {
    float cosTheta = max(visibleWidth / 0.5, EPSILON);
    float sourceX = clamp(1.0 - (1.0 - localUV.x) / cosTheta, 0.5, 1.0);
    vec4 color = sampleOriginalRegion(vec2(sourceX, localUV.y), region);
    float local = saturate((1.0 - localUV.x) / max(visibleWidth, EPSILON));
    return applyFoldDoorLighting(color, local, localUV.y, foldStrength);
}

vec4 sampleCenterReveal(vec2 localUV, vec4 region, float visibleWidth, float foldStrength) {
    float leftEdge = visibleWidth;
    float rightEdge = 1.0 - visibleWidth;
    float centerWidth = max(rightEdge - leftEdge, EPSILON);
    float stretchedX = saturate((localUV.x - leftEdge) / centerWidth);
    vec4 color = sampleTargetRegion(vec2(stretchedX, localUV.y), region);
    return applyCenterRevealShadow(color, localUV.x, leftEdge, rightEdge, foldStrength);
}

vec4 renderOpeningHalf(vec2 globalUV, vec4 region, float openProgress) {
    if (openProgress <= 0.001) {
        return sampleOriginal(globalUV);
    }
    if (openProgress >= 0.999) {
        return sampleTarget(globalUV);
    }

    vec2 localUV = toLocalUV(globalUV, region);
    float visibleWidth = 0.5 * (1.0 - openProgress);
    float rightStart = 1.0 - visibleWidth;

    if (localUV.x <= visibleWidth) {
        return sampleLeftDoor(localUV, region, visibleWidth, openProgress);
    }
    if (localUV.x >= rightStart) {
        return sampleRightDoor(localUV, region, visibleWidth, openProgress);
    }

    return sampleCenterReveal(localUV, region, visibleWidth, openProgress);
}

vec4 FUNCNAME(vec2 tc) {
    float progress = saturate(PREFIX(transitionProgress));
    float openStart = LEAD_HOLD_DURATION;
    float openEnd = LEAD_HOLD_DURATION + OPEN_WINDOW_DURATION;
    float topPhaseStart = openStart;
    float topPhaseEnd = openStart + 0.5 * OPEN_WINDOW_DURATION;
    float bottomPhaseStart = topPhaseEnd;
    float bottomPhaseEnd = openEnd;
    float topProgress = saturate((progress - topPhaseStart) / max(topPhaseEnd - topPhaseStart, EPSILON));
    float bottomProgress = saturate((progress - bottomPhaseStart) / max(bottomPhaseEnd - bottomPhaseStart, EPSILON));

    vec4 topHalfRegion = vec4(0.0, 0.5, 1.0, 1.0);
    vec4 bottomHalfRegion = vec4(0.0, 0.0, 1.0, 0.5);

    if (tc.y >= 0.5) {
        if (progress < topPhaseStart) {
            return sampleOriginal(tc);
        }
        if (progress < topPhaseEnd) {
            return renderOpeningHalf(tc, topHalfRegion, topProgress);
        }
        return sampleTarget(tc);
    }

    if (progress < bottomPhaseStart) {
        return sampleOriginal(tc);
    }
    if (progress >= bottomPhaseEnd) {
        return sampleTarget(tc);
    }
    return renderOpeningHalf(tc, bottomHalfRegion, bottomProgress);
}

#define EPSILON 1e-5
#define FLIP_DURATION 0.9
#define MID_SECTION_SLOW_POWER 1.7
#define PANEL_WIDTH (1.0 / 3.0)
#define AXIS_X 0
#define AXIS_Y 1
#define FLOW_LOW_TO_HIGH 0
#define FLOW_HIGH_TO_LOW 1

float saturate(float value) {
    return clamp(value, 0.0, 1.0);
}

float bandFalloff(float coord, float center, float width) {
    float normalized = (coord - center) / max(width, EPSILON);
    return exp(-normalized * normalized);
}

float remapFlipProgressForMidSection(float value) {
    float centered = saturate(value) * 2.0 - 1.0;
    float curved = sign(centered) * pow(abs(centered), MID_SECTION_SLOW_POWER);
    return saturate(0.5 + 0.5 * curved);
}

float insideRect(vec2 uv) {
    return step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
}

vec4 sampleOriginal(vec2 uv) {
    return INPUT1(uv) * insideRect(uv);
}

vec4 sampleTarget(vec2 uv) {
    return INPUT2(uv) * insideRect(uv);
}

vec2 getRegionSize(vec4 region) {
    return max(region.zw - region.xy, vec2(EPSILON, EPSILON));
}

vec2 toLocalUV(vec2 uv, vec4 region) {
    return (uv - region.xy) / getRegionSize(region);
}

vec2 toGlobalUV(vec2 localUV, vec4 region) {
    return region.xy + localUV * getRegionSize(region);
}

vec4 sampleTargetRegion(vec2 localUV, vec4 region) {
    return sampleTarget(toGlobalUV(localUV, region)) * insideRect(localUV);
}

float getAxisCoord(vec2 uv, int axis) {
    if (axis == AXIS_X) {
        return uv.x;
    }
    return uv.y;
}

vec2 setAxisCoord(vec2 uv, int axis, float value) {
    if (axis == AXIS_X) {
        return vec2(value, uv.y);
    }
    return vec2(uv.x, value);
}

float getFoldCenterShadowStrength(float foldStrength) {
    float shadowPresence = smoothstep(0.02, 0.10, foldStrength);
    float shadowFade = 1.0 - smoothstep(0.28, 0.92, foldStrength);
    float earlyShadowSoftener = mix(0.76, 1.0, smoothstep(0.14, 0.34, foldStrength));
    return shadowPresence * shadowFade * earlyShadowSoftener;
}

vec4 applyFoldCenterShadow(vec4 color, float coord, float foldStrength, float shadowMask) {
    float shadowStrength = getFoldCenterShadowStrength(foldStrength) * shadowMask;
    float centerProximity = saturate(1.0 - abs(coord - 0.5) / 0.5);
    float centerDepth = pow(centerProximity, 4.8);
    float coreWidth = mix(0.12, 0.06, foldStrength);
    float spreadRate = mix(5.5, 10.5, foldStrength);
    float edgeSoftener = 1.0 - pow(centerProximity, 0.65);
    float centerCoreShadow = bandFalloff(coord, 0.5, coreWidth) * 0.18 * shadowStrength;
    float centerSpreadShadow = exp(-abs(coord - 0.5) * spreadRate) * 0.24 * shadowStrength;
    float centerDepthShadow = 0.18 * centerDepth * shadowStrength;
    float edgeFade = 0.04 * edgeSoftener * shadowStrength;
    float shadow = clamp(centerCoreShadow + centerSpreadShadow + centerDepthShadow - edgeFade, 0.0, 0.72);

    color.rgb *= 1.0 - shadow;
    return color;
}

vec4 applyFoldFrontLighting(vec4 color, float local, float coord, float foldStrength) {
    float edgeShade = 0.20 * (1.0 - local) * foldStrength;
    float farEdgeShade = 0.10 * local * foldStrength;
    float centerHighlight = 0.06 * pow(local, 1.5) * foldStrength;

    color.rgb *= 1.0 - edgeShade;
    color.rgb *= 1.0 - farEdgeShade;
    color.rgb += centerHighlight;
    return color;
}

vec4 applyFlipInLighting(vec4 color, float local, float coord, float foldStrength) {
    float hingeShade = 0.22 * local * foldStrength;
    float farEdgeShade = 0.10 * (1.0 - local) * foldStrength;
    float highlight = 0.08 * pow(1.0 - local, 1.5) * foldStrength;

    color.rgb *= 1.0 - hingeShade;
    color.rgb *= 1.0 - farEdgeShade;
    color.rgb += highlight;
    return applyFoldCenterShadow(color, coord, foldStrength, 1.0);
}

vec4 applyStableShadow(vec4 color, float coord, float foldStrength, float shadowMask) {
    return applyFoldCenterShadow(color, coord, foldStrength, shadowMask);
}

vec4 sampleTargetFlipInDirectional(int axis, int flow, vec2 uv, vec4 region, float coverCoord, float visibleExtent, float foldStrength) {
    float cosTheta = max(visibleExtent / 0.5, EPSILON);
    float coord = getAxisCoord(uv, axis);
    float sourceCoord = 0.0;
    float local = 0.0;

    if (flow == FLOW_LOW_TO_HIGH) {
        sourceCoord = 0.5 + (coord - 0.5) / cosTheta;
        sourceCoord = clamp(sourceCoord, 0.5, 1.0);
        local = saturate((coverCoord - coord) / max(visibleExtent, EPSILON));
    } else {
        sourceCoord = 0.5 - (0.5 - coord) / cosTheta;
        sourceCoord = clamp(sourceCoord, 0.0, 0.5);
        local = saturate((coord - coverCoord) / max(visibleExtent, EPSILON));
    }

    vec4 color = sampleTargetRegion(setAxisCoord(uv, axis, sourceCoord), region);
    return applyFlipInLighting(color, local, coord, foldStrength);
}

vec4 sampleCommittedAfterStage1(vec2 uv) {
    if (uv.x < PANEL_WIDTH) {
        return sampleTarget(uv);
    }
    return sampleOriginal(uv);
}

vec4 sampleCommittedAfterStage2(vec2 uv) {
    if (uv.x < PANEL_WIDTH * 2.0) {
        return sampleTarget(uv);
    }
    return sampleOriginal(uv);
}

vec4 sampleStageBase(int stageIndex, vec2 uv) {
    if (stageIndex <= 0) {
        return sampleOriginal(uv);
    }
    if (stageIndex == 1) {
        return sampleCommittedAfterStage1(uv);
    }
    return sampleCommittedAfterStage2(uv);
}

vec4 sampleStageBaseRegion(int stageIndex, vec2 localUV, vec4 region) {
    return sampleStageBase(stageIndex, toGlobalUV(localUV, region)) * insideRect(localUV);
}

vec4 sampleBaseFoldFrontDirectional(int stageIndex, int axis, int flow, vec2 uv, vec4 region, float visibleExtent, float foldStrength) {
    float cosTheta = max(visibleExtent / 0.5, EPSILON);
    float coord = getAxisCoord(uv, axis);
    float sourceCoord = 0.0;
    float local = 0.0;

    if (flow == FLOW_LOW_TO_HIGH) {
        sourceCoord = 0.5 - (0.5 - coord) / cosTheta;
        sourceCoord = clamp(sourceCoord, 0.0, 0.5);
        local = saturate((0.5 - coord) / max(visibleExtent, EPSILON));
    } else {
        sourceCoord = 0.5 + (coord - 0.5) / cosTheta;
        sourceCoord = clamp(sourceCoord, 0.5, 1.0);
        local = saturate((coord - 0.5) / max(visibleExtent, EPSILON));
    }

    vec4 color = sampleStageBaseRegion(stageIndex, setAxisCoord(uv, axis, sourceCoord), region);
    return applyFoldFrontLighting(color, local, coord, foldStrength);
}

vec4 sampleBaseStableDirectional(int stageIndex, int axis, int flow, vec2 uv, vec4 region, float coverCoord, float foldStrength) {
    vec4 color = sampleStageBaseRegion(stageIndex, uv, region);
    float coord = getAxisCoord(uv, axis);
    float shadowMask = 0.0;

    if (flow == FLOW_LOW_TO_HIGH) {
        shadowMask = step(coverCoord, coord);
    } else {
        shadowMask = step(coord, coverCoord);
    }

    return applyStableShadow(color, coord, foldStrength, shadowMask);
}

vec4 renderPartialDirectional(int stageIndex, int axis, int flow, vec2 globalUV, vec4 region, float foldProgress) {
    vec2 uv = toLocalUV(globalUV, region);
    float coord = getAxisCoord(uv, axis);

    float phase1 = saturate(foldProgress * 2.0);
    float visibleExtent1 = 0.5 * (1.0 - phase1);
    float foldStrength1 = phase1;

    float phase2 = saturate(foldProgress * 2.0 - 1.0);
    float visibleExtent2 = 0.5 * phase2;
    float foldStrength2 = phase2;

    float revealCoord = 0.0;
    float coverCoord = 0.0;

    if (flow == FLOW_LOW_TO_HIGH) {
        revealCoord = 0.5 - visibleExtent1;
        coverCoord = 0.5 + visibleExtent2;

        if (coord < 0.5) {
            if (visibleExtent1 > EPSILON && coord > revealCoord) {
                return sampleBaseFoldFrontDirectional(stageIndex, axis, flow, uv, region, visibleExtent1, foldStrength1);
            }
            return sampleStageBase(stageIndex, globalUV);
        }

        if (visibleExtent2 > EPSILON && coord <= coverCoord) {
            return sampleTargetFlipInDirectional(axis, flow, uv, region, coverCoord, visibleExtent2, foldStrength2);
        }
    } else {
        revealCoord = 0.5 + visibleExtent1;
        coverCoord = 0.5 - visibleExtent2;

        if (coord >= 0.5) {
            if (visibleExtent1 > EPSILON && coord < revealCoord) {
                return sampleBaseFoldFrontDirectional(stageIndex, axis, flow, uv, region, visibleExtent1, foldStrength1);
            }
            return sampleStageBase(stageIndex, globalUV);
        }

        if (visibleExtent2 > EPSILON && coord >= coverCoord) {
            return sampleTargetFlipInDirectional(axis, flow, uv, region, coverCoord, visibleExtent2, foldStrength2);
        }
    }

    float stableFoldStrength = max(foldStrength1, foldStrength2);
    if (stageIndex == 0 && phase2 <= EPSILON) {
        stableFoldStrength = 0.0;
    }

    return sampleBaseStableDirectional(stageIndex, axis, flow, uv, region, coverCoord, stableFoldStrength);
}

vec4 FUNCNAME(vec2 tc) {
    float progress = saturate(PREFIX(transitionProgress));
    float flipStart = 0.5 - 0.5 * FLIP_DURATION;
    float flipEnd = flipStart + FLIP_DURATION;

    if (progress <= 0.001 || progress <= flipStart) {
        return INPUT1(tc);
    }
    if (progress >= 0.999 || progress >= flipEnd) {
        return INPUT2(tc);
    }

    float flipWindowProgress = saturate((progress - flipStart) / max(FLIP_DURATION, EPSILON));
    float stagedProgress = flipWindowProgress * 3.0;

    vec4 leftStageRegion = vec4(-PANEL_WIDTH, 0.0, PANEL_WIDTH, 1.0);
    vec4 centerStageRegion = vec4(0.0, 0.0, PANEL_WIDTH * 2.0, 1.0);
    vec4 rightStageRegion = vec4(PANEL_WIDTH, 0.0, 1.0, 1.0);

    if (stagedProgress < 1.0) {
        float stageProgress = remapFlipProgressForMidSection(saturate(stagedProgress));
        if (tc.x < PANEL_WIDTH) {
            return renderPartialDirectional(0, AXIS_X, FLOW_LOW_TO_HIGH, tc, leftStageRegion, stageProgress);
        }
        return sampleStageBase(0, tc);
    }

    if (stagedProgress < 2.0) {
        float stageProgress = remapFlipProgressForMidSection(saturate(stagedProgress - 1.0));
        if (tc.x < PANEL_WIDTH * 2.0) {
            return renderPartialDirectional(1, AXIS_X, FLOW_LOW_TO_HIGH, tc, centerStageRegion, stageProgress);
        }
        return sampleStageBase(1, tc);
    }

    float stageProgress = remapFlipProgressForMidSection(saturate(stagedProgress - 2.0));
    if (tc.x >= PANEL_WIDTH) {
        return renderPartialDirectional(2, AXIS_X, FLOW_LOW_TO_HIGH, tc, rightStageRegion, stageProgress);
    }
    return sampleStageBase(2, tc);
}

// Frame Swipe
// A 放大后左滑退出，B 放大进入回落。
// 模糊：水平方向高斯，与 A/B 放大同起点同节奏增强/减弱。
// 上下黑条：1/10 淡入 → 推进至 1/7 → 回缩 → 淡出；放大伴随轻微曝光；非 A/B 素材区域 alpha 为 0。

float easeInOut01(float t)
{
    float x = clamp(t, 0.0, 1.0);
    return x * x * (3.0 - 2.0 * x);
}

float easeOut01(float t)
{
    float x = clamp(t, 0.0, 1.0);
    float inv = 1.0 - x;
    return 1.0 - inv * inv;
}

float remap01(float a, float b, float v)
{
    return clamp((v - a) / max(b - a, 1e-5), 0.0, 1.0);
}

vec2 transformUV(vec2 tc, float iscale, vec2 offset)
{
    return (tc - vec2(0.5) - offset) / max(iscale, 1e-5) + vec2(0.5);
}

vec4 sampleLayer(vec2 uv, int which)
{
    // 超过 0~1 的区域不属于 A/B 素材，保持透明
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        return vec4(0.0);
    }
    return (which == 0) ? INPUT1(uv) : INPUT2(uv);
}

vec4 composeAB(vec2 tc, float aScale, vec2 aOffset, float bScale, float bVisible)
{
    vec4 colorA = sampleLayer(transformUV(tc, aScale, aOffset), 0);
    vec4 colorB = sampleLayer(transformUV(tc, bScale, vec2(0.0)), 1);
    if (bVisible > 0.5) {
        return colorB;
    }
    return colorA;
}

float blackBarMask(vec2 tc, float coverH)
{
    float h = clamp(coverH, 0.0, 0.5);
    if (h <= 1e-5) {
        return 0.0;
    }
    float topBar = 1.0 - smoothstep(h - 0.002, h + 0.002, tc.y);
    float botBar = smoothstep((1.0 - h) - 0.002, (1.0 - h) + 0.002, tc.y);
    return max(topBar, botBar);
}

// CapCut LumiDirectionalBlurs：angle=90 → 沿 X 的高斯方向模糊
// radius = intensity/1000；采样密度对齐 getSampleNum（峰值约 90+）避免分层拖影
vec4 directionalBlurH(vec2 tc, float aScale, vec2 aOffset, float bScale, float bVisible, float intensity01)
{
    if (intensity01 < 1e-4) {
        return composeAB(tc, aScale, aOffset, bScale, bVisible);
    }
    float radius = intensity01 * 0.30;
    float sigma = max(radius / 3.0, 1e-4);
    // 加密采样：弱模糊约 24，峰值约 64（CapCut 峰值 sample≈90 的可运行近似）
    float sampleCount = mix(24.0, 64.0, intensity01);
    float ds = radius / max(sampleCount, 1.0);

    float w0 = 1.0;
    vec4 sum = composeAB(tc, aScale, aOffset, bScale, bVisible) * w0;
    float wSum = w0;

    for (int i = 1; i <= 64; i++) {
        float fi = float(i);
        if (fi > sampleCount) {
            break;
        }
        float dist = fi * ds;
        float w = exp(-0.5 * (dist * dist) / (sigma * sigma));
        sum += composeAB(tc + vec2(dist, 0.0), aScale, aOffset, bScale, bVisible) * w;
        sum += composeAB(tc - vec2(dist, 0.0), aScale, aOffset, bScale, bVisible) * w;
        wSum += 2.0 * w;
    }
    return sum / max(wSum, 1e-5);
}

vec4 FUNCNAME(vec2 tc)
{
    float p = PREFIX(iProgress);

    // [@规则:R-T05] 端点闭合
    if (p <= 0.0) {
        return INPUT1(tc);
    }
    if (p >= 1.0) {
        return INPUT2(tc);
    }

    // ---- A / B 变换（保持原缩放与滑动，不做速率耦合模糊）----
    float aScale = mix(1.02, 1.30, easeInOut01(remap01(0.0, 0.48, p)));
    float aSlideX = mix(0.0, -0.365, easeInOut01(remap01(0.40, 0.54, p)));
    vec2 aOffset = vec2(aSlideX, 0.0);
    float bVisible = step(0.50, p);
    float bScale = mix(1.30, 1.00, easeInOut01(remap01(0.50, 0.98, p)));

    // ---- 模糊与放大同步增强：A 放大段升起，B 回落段降下 ----
    float blurIntensity01 = 0.0;
    if (p < 0.50) {
        // 与 A 缩放 0~0.48 同起点、同节奏升到峰值
        blurIntensity01 = easeInOut01(remap01(0.0, 0.48, p));
    } else {
        // 与 B 缩放回落同段降下
        blurIntensity01 = 1.0 - easeInOut01(remap01(0.50, 0.98, p));
    }

    vec4 base = directionalBlurH(tc, aScale, aOffset, bScale, bVisible, blurIntensity01);

    // ---- 伴随放大的轻微曝光（缩放越大越亮，峰值 +30%）----
    float curScale = (bVisible > 0.5) ? bScale : aScale;
    float zoomAmt = clamp((curScale - 1.0) / 0.30, 0.0, 1.0);
    float exposure = 1.0 + zoomAmt * 0.30;
    base.rgb = clamp(base.rgb * exposure, 0.0, 1.0);

    // ---- 黑条节奏（总 50 帧 → progress 0~1）----
    // 淡入 0~10；推进 10~25；转场后对称：回缩 25~40；淡出 40~50
    const float coverFade = 0.1;      // 1/10
    const float coverMax = 0.142857;  // 1/7
    const float tFadeIn1 = 10.0 / 50.0;  // 0.20
    const float tExpand1 = 25.0 / 50.0;  // 0.50
    const float tShrink1 = 40.0 / 50.0;  // 0.80
    // tFadeOut1 = 1.0

    float coverH = 0.0;
    float barOpac = 0.0;
    if (p < tFadeIn1) {
        // 0~10：上下 1/10 区透明 → 全黑
        coverH = coverFade;
        barOpac = easeInOut01(remap01(0.0, tFadeIn1, p));
    } else if (p < tExpand1) {
        // 10~25：向中心推进至 1/7
        coverH = mix(coverFade, coverMax, easeOut01(remap01(tFadeIn1, tExpand1, p)));
        barOpac = 1.0;
    } else if (p < tShrink1) {
        // 25~40：对称回缩至 1/10
        coverH = mix(coverMax, coverFade, easeInOut01(remap01(tExpand1, tShrink1, p)));
        barOpac = 1.0;
    } else {
        // 40~50：全黑 → 透明消失
        coverH = coverFade;
        barOpac = 1.0 - easeInOut01(remap01(tShrink1, 1.0, p));
    }

    float bar = blackBarMask(tc, coverH) * barOpac;
    base = mix(base, vec4(0.0, 0.0, 0.0, base.a), clamp(bar, 0.0, 1.0));

    return base;
}

