float rgb2grey(vec3 rgbColor){
    return (rgbColor.r * 0.299 + rgbColor.g * 0.587 + rgbColor.b * 0.114);
}
vec3 selfGlowColor(vec4 curColor, float threshold) {
	vec4 resultColor=curColor;
	float t=clamp(threshold,.01,1.);
	resultColor.rgb=smoothstep(t - 0.065 * threshold, t + .065, resultColor.rgb);
	float gamma = 2.2;
	return pow(resultColor.rgb, vec3(1. / gamma));
}
vec3 abGlowColor(vec4 curColor, float threshold){
	float t = clamp(threshold, .01, 1.);
	float grey = rgb2grey(curColor.rgb);
	vec3 resultColor = smoothstep(t - .065 * threshold, t + .065, vec3(grey)); 
	return resultColor;
}
vec4 stepHighlight(vec2 uv, float Range)
{
    float flagGlowColor = 1.0;
    // float threshold = 1.0 - (0.1 + 0.25*Afterimage )*iPro;
    float threshold = 1.0 - 0.5*Range;
    // vec4 curColor = INPUT1(uv);
    vec4 curColor = vec4(0.0);
	// curColor = INPUT1(uv);
    if(INPUT1(uv).r > 0.68 - 0.4*Range){
        curColor = INPUT2(uv);
    }
    // if(rgb2grey(INPUT1(uv).rgb) > Range){
    //     curColor = INPUT2(uv);
    // }
	vec4 SelfGlowColor = curColor;
	SelfGlowColor.rgb = selfGlowColor(curColor, threshold);
	vec4 sourceColor = curColor;
	sourceColor.rgb = abGlowColor(curColor, threshold);
	vec4 ABColor = sourceColor;
	vec4 ABAColor = sourceColor;
	vec4 resultColor = vec4(0.);
	if (flagGlowColor < .5) resultColor = SelfGlowColor;
	else if (flagGlowColor < 1.5) resultColor = ABColor;
	else resultColor = ABAColor;
	return resultColor;
}



