float rnd(vec3 scale, float seed, vec3 uv) {
  return fract(sin(dot(uv + seed, scale)) * 43758.5453 + seed);
}
vec4 radial_blur1(vec2 fc, vec2 radialCenter, float radialBlur, int iteration, float glowIntensity){
  vec2 fcc = fc - radialCenter;
  vec4 destColor = vec4(0.0);
  float random = rnd(vec3(12.9898, 78.233, 151.7182), 0.0, vec3(fc, 0.0));
  float totalWeight = 0.0;
  float nFrag = 1.0 / float(iteration);
  for (int i = 0; i <= iteration; i+=1) {
    float percent = (float(i) + random) * nFrag;
    float weight = percent - percent * percent;
    vec2 t = fc - fcc * percent * radialBlur * nFrag;
    destColor += INPUT1(t) * weight;
    totalWeight += weight;
  }
  return destColor / (totalWeight * glowIntensity) ;
}
vec4 Blur1(vec2 tc, float process)
{ 
    vec4 fragColor = vec4(0.0);
    vec2 radialCenter = vec2(0.5); 
    float maxRotateRad = radians(-20.0);
    float maxRadialRadius = 16.0;
    int iteration = 15; 

    float curPro = process * 0.05;   
    float curRotateRad = maxRotateRad*curPro;    
    float curRadialRadius = mix(0.0, maxRadialRadius, curPro);
    fragColor = radial_blur1(tc, radialCenter, curRadialRadius, iteration, 1.0 );
	return fragColor;	
}


