#define PI 3.14159265

float sdf(vec2 uv){
    float trueRatio = max(iResolution.x, iResolution.y) / min(iResolution.x, iResolution.y);
    float ratio = max(max(iResolution.x, iResolution.y) / min(iResolution.x, iResolution.y), 1.4);
    float progress = PREFIX(iglobaltime) + 0.1;
    float sdfSize = (0.9*progress*mix(1.0, 0.75, max(16.0/9.0-trueRatio, 0.0)/0.778)) / mix(52.0, 47.0, max(2.0*progress-1.0, 0.0));
    float sdfSize1 = sdfSize * sqrt(1.0 + ratio*ratio) / 2.0397;
    sdfSize = sqrt(max(sdfSize, 0.0));

    if (sdfSize1 <= 0.0) return 0.0;

    vec2 uv1 = vec2(uv.x , uv.y);
    uv1 -= 0.5;
    uv1 /= sdfSize1; 
    float inputRatio = iResolution.x / iResolution.y;
    if(inputRatio < 1.0) {
        float myinputRatio = 1.0 / inputRatio;
        uv1.y *= myinputRatio;
        uv1.y /= pow(myinputRatio,0.1);
    }
    if(inputRatio > 1.0) {
        uv1.x *= inputRatio;
        uv1.x /= pow(inputRatio,0.1);
    }
    float powins = 0.75;
    float temp = pow(sdfSize1, powins);
    float d = smoothstep(60.0 - 1.0/temp, 60.0 + 1.0/temp,length(uv1))*
                    smoothstep(60.0 + 1.0/temp, 60.0 - 1.0/temp,length(uv1));

    return d;
}

vec4 enCode(float a) {
    float a1 = floor(a*255.0);
    float b1 = fract(a*255.0);
    float a2 = floor(b1*255.0);
    float b2 = fract(b1*255.0);
    float a3 = floor(b2*255.0);
    float b3 = fract(b2*255.0);

    return vec4(a1/255.0, a2/255.0, a3/255.0, b3);
}

float deCode(vec4 a) {
    return a.x+a.y/255.0+a.z/(255.0*255.0)+a.w/(255.0*255.0*255.0);
}

float mirror11(float x) {
    return abs(mod(x-1.0,2.0)-1.0);
}

vec2 mirror(vec2 uv) {
    return vec2(mirror11(uv.x),mirror11(uv.y));
}

vec2 irotate(vec2 point, float angle, vec2 center) {
    float anglePI = angle * PI / 180.0;
    mat2 rot = mat2( cos(anglePI), sin(anglePI), 
                    -sin(anglePI), cos(anglePI) );
    point -= center;
    point.y *= float(iResolution.y) / float(iResolution.x);
    point = rot * point;
    point.y /= float(iResolution.y) / float(iResolution.x);
    point += center;

    return point ;
}

vec4 rotateBlur(vec2 uv, float range, vec2 center) {
    vec4 result = vec4(0.0);
    vec2 OffsetL = vec2(0.0);
    vec2 OffsetR = vec2(0.0);
    float sum_weights = 0.0;
    int sampleCount = 10;
    float SQRT2 = 1.414214;

    vec4 src = INPUT1(uv);
    result = INPUT1(uv);
    sum_weights += 1.0;

    OffsetL = irotate(uv, range / float(sampleCount), center);
    OffsetR = irotate(uv, -range / float(sampleCount), center);
    float _rotateAlpha = 1.0;
    for (int i = 1; i < sampleCount; ++i) {
        result +=  INPUT1(OffsetL) * _rotateAlpha;
        result +=  INPUT1(OffsetR) * _rotateAlpha;
        OffsetL = irotate(OffsetL, range / float(sampleCount) , center);
        OffsetR = irotate(OffsetR, -range / float(sampleCount) , center);
        sum_weights += 2.0 * _rotateAlpha;
        _rotateAlpha *= 0.9 ;
    }

    result /= sum_weights;
    float baseRatio = float(iResolution.x) / float(iResolution.y);
    uv -= 0.5;
    uv.y /= baseRatio;
    uv += 0.5;
    float radius = length(uv - center);
    result = mix(src, result, 0.95);
    float k = smoothstep(-0.2, 0.1 , radius/SQRT2);
    result = mix(src, result, k);
    result.a = 1.0;

    return result;
}

vec2 hash22(vec2 p) {
  p = vec2(dot(p,vec2(127.1, 311.7)), dot(p,vec2(269.5, 183.3)));

  return -1.0 + 2.0 * fract(sin(p)*43758.5453123);
}

float perlin_noise(vec2 p) {
  vec2 pi = floor(p);
  vec2 pf = p - pi;
  vec2 w = pf * pf * (3.0 - 2.0 * pf);

  return mix(mix(dot(hash22(pi + vec2(0.0, 0.0)), pf - vec2(0.0, 0.0)), 
                  dot(hash22(pi + vec2(1.0, 0.0)), pf - vec2(1.0, 0.0)), w.x), 
              mix(dot(hash22(pi + vec2(0.0, 1.0)), pf - vec2(0.0, 1.0)), 
                  dot(hash22(pi + vec2(1.0, 1.0)), pf - vec2(1.0, 1.0)), w.x),
              w.y);
}

float noise_sum(vec2 p) {
  float pf = 0.0;
  p = p * 10.0;
  pf += 1.0000 * perlin_noise(p); p = 2.0 * p;
  pf += 0.5000 * perlin_noise(p); p = 2.0 * p;

  return pf;
}

vec4 FUNCNAME(vec2 tc) {
    vec2 uv = tc;
    float iGlobalTime = PREFIX(iglobaltime);
    vec4 fragOutCol = vec4(0.0);
    vec2 center = vec2(0.5);
    vec4 texture = INPUT2(vec2(uv.x, 1.0-uv.y));
    vec2 onePixel = 1.0 / iResolution.xy;

    float trueRatio = max(iResolution.x, iResolution.y) / min(iResolution.x, iResolution.y);
    float ratio = max(max(iResolution.x, iResolution.y) / min(iResolution.x, iResolution.y), 1.4);
    float progress = iGlobalTime + 0.1;
    float sdfSize = (0.9*progress*mix(1.0, 0.75, max(16.0/9.0-trueRatio, 0.0)/0.778)) / mix(52.0, 47.0, max(2.0*progress-1.0, 0.0));
    float sdfSize1 = sdfSize * sqrt(1.0 + ratio*ratio) / 2.0397;

    if (iGlobalTime < 0.0001) {
        return INPUT1(uv);
    }

    if (PREFIX(StepType) == 1) {
        // SDF
        vec2 uv1 = uv;
        uv1 -= 0.5;
        uv1  /= sdfSize1; 
        float inputRatio = iResolution.x / iResolution.y;
        if(inputRatio < 1.0) {
            uv1.y /= inputRatio;
        }
        if(inputRatio > 1.0) {
            uv1.x *= inputRatio;
        }
        float powins = 0.75;
        float temp = pow(sdfSize1, powins);
        float d = smoothstep(60.0 - 1.0/temp, 60.0 + 1.0/temp,length(uv1))*
                    smoothstep(60.0 + 1.0/temp, 60.0 - 1.0/temp,length(uv1));

        fragOutCol = vec4(enCode(clamp(d, 0.0, 1.0)));
    } else if (PREFIX(StepType) == 2) {
        float dis = distance(uv, center);
        float longest = min(1.0, dis / distance(vec2(0.25), center));
        uv -= center;
        uv *= mix(1.0, 0.8, (1.0 - longest) * (PREFIX(convexProcess)));
        uv += center;

        float shake = 5.0;
        vec2 shake_uv = uv;
        shake_uv.y += sin(shake*iGlobalTime*3.14159265) * 0.05 * PREFIX(mixProcess);
        vec4 oriCol = INPUT1(shake_uv);

        uv -= center;
        uv *= 0.5 + 0.5 * PREFIX(zoomProcess);
        uv += center;
        float mask = INPUT2(uv).a;
        mask = step(0.25, mask);
        vec4 human_mask = INPUT1(uv) * mask;
        human_mask = mix(human_mask, vec4(mask * 0.9), mask * PREFIX(mixProcess));

        fragOutCol = mix(oriCol, human_mask, human_mask.a);
    } else if (PREFIX(StepType) == 3) {
        // // Zoom
        float dis = distance(uv, center);
        // Distort
        vec2 dis_uv1 = uv;
        vec2 dis_uv2 = uv;

        vec2 screenSize = iResolution.xy / (min(iResolution.x, iResolution.y) / 720.0);
        if (iResolution.y < iResolution.x) {
        dis_uv2.x = (dis_uv2.x - 0.5) / (iResolution.y / iResolution.x) + 0.5;
        } else {
        dis_uv2.y = (dis_uv2.y - 0.5) / (iResolution.x / iResolution.y) + 0.5;
        }
        float noise0 = noise_sum((dis_uv2 - 0.5) * (1.0));
        float noise1 = noise_sum((dis_uv2 - 0.5) * (-(1.0)));

        vec2 n = vec2(noise0, noise1);
        dis_uv1.x += (n.x) * 500.0 / screenSize.x * dis * 0.5;
        dis_uv1.y += (n.y) * 500.0 / screenSize.y * dis * 0.5;
        if (dis_uv1.x < 0.) dis_uv1.x = -dis_uv1.x;
