        vec2 offset = vec2(1.5) / mySize;
        float gray1 = sdf(uv+vec2(1,0)*offset);
        float gray11 = sdf(uv-vec2(1,0)*offset);
        float gray2 = sdf(uv+vec2(0,1)*offset);
        float gray22 = sdf(uv-vec2(0,1)*offset);

        vec2 grad=vec2(gray11-gray1,gray22-gray2)*255.0;
        vec2 lastUV = mirror(uv+mix(1.3,1.0,clamp(sdfSize-1.0,0.0,1.0))*100.0*grad*offset*5.0*deCode(INPUT2(dis_uv1)));
