            b = INPUT2(uv + shiftStrength).ra;
            vec3 col = vec3(b.x, g.x, r.x);
            fragOutCol.rgb = col;
            fragOutCol.a = max(r.y, max(g.y, b.y));
        }
    }

    return fragOutCol;
}

