// Glitch Bar Drop · Transition
// 源 shaderFrag.js：水平切片自上而下级联，A/B 沿 X 错开 1.2 屏宽，中段 RGB 分离 + 霓虹辉光。

float insideHorizontal(float x) {
    return step(0.0, x) * step(x, 1.0);
}

vec4 sampleGlitchA(vec2 uv, float channelOffset) {
    float mask = insideHorizontal(uv.x);
    float r = INPUT1(uv + vec2(channelOffset, 0.0)).r;
    float g = INPUT1(uv).g;
    float b = INPUT1(uv - vec2(channelOffset, 0.0)).b;
    return vec4(r, g, b, 1.0) * mask;
}

vec4 sampleGlitchB(vec2 uv, float channelOffset) {
    float mask = insideHorizontal(uv.x);
    float r = INPUT2(uv + vec2(channelOffset, 0.0)).r;
    float g = INPUT2(uv).g;
    float b = INPUT2(uv - vec2(channelOffset, 0.0)).b;
    return vec4(r, g, b, 1.0) * mask;
}

// [@规则:R-UV-01] 切片与水平偏移写在 Blit tc 空间（与源 vUv 同向：底=0、顶=1）。
vec4 slicedGlitch(vec2 tc, float progress) {
    float sliceCount = 12.0;
    float glitchIntensity = 0.15;
    float glowIntensity = 0.40;
    vec3 glowColor = vec3(0.80, 0.20, 1.00);

    float sliceIndex = floor((1.0 - tc.y) * sliceCount);
    float sliceProgress = clamp((progress - sliceIndex / sliceCount) * sliceCount, 0.0, 1.0);
    float offset = sliceProgress * 1.20;
    vec2 uvA = vec2(tc.x - offset, tc.y);
    vec2 uvB = vec2(tc.x + 1.20 - offset, tc.y);

    float pulse = 1.0 - abs(sliceProgress * 2.0 - 1.0);
    float channelOffset = glitchIntensity * pulse;

    vec4 colorA = sampleGlitchA(uvA, channelOffset);
    colorA.rgb *= 1.0 - sliceProgress;
    vec4 colorB = sampleGlitchB(uvB, channelOffset);

    float mixFactor = smoothstep(0.30, 0.70, sliceProgress);
    vec4 result = mix(colorA, colorB, mixFactor);
    result.rgb += glowColor * (glowIntensity * pulse);
    result.rgb = clamp(result.rgb, 0.0, 1.0);
    return result;
}

vec4 FUNCNAME(vec2 tc) {
    float p = PREFIX(iProgress);
    vec4 colorA = INPUT1(tc);
    vec4 colorB = INPUT2(tc);

    // [@规则:R-T01][@规则:R-T05]
    if (p <= 0.0) {
        return colorA;
    }
    if (p >= 1.0) {
        return colorB;
    }

    float transitionProgress = clamp((p - 0.10) / 0.80, 0.0, 1.0);
    vec4 transitionColor = slicedGlitch(tc, transitionProgress);
    float blendIn = smoothstep(0.0, 0.10, p);
    float blendOut = smoothstep(0.90, 1.0, p);
    vec4 result = mix(colorA, transitionColor, blendIn);
    return mix(result, colorB, blendOut);
}

