vec4 Lut3DFilter(vec4 textureColor, float opacity){
  float blueColor = textureColor.r * 63.0;
  vec2 quad1;
  quad1.y = floor(floor(blueColor) / 8.0);
  quad1.x = floor(blueColor) - (quad1.y * 8.0);
  vec2 quad2;
  quad2.y = floor(ceil(blueColor) /8.0);
  quad2.x = ceil(blueColor) - (quad2.y * 8.0);
  vec2 texPos1;
  texPos1.x = (quad1.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
  texPos1.y = (quad1.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
  vec2 texPos2;
  texPos2.x = (quad2.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
  texPos2.y = (quad2.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
  vec4 newColor1 = INPUT3(texPos1);
  vec4 newColor2 = INPUT3(texPos2);
  vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
  vec4 fragOutCol = vec4(mix(textureColor.rgb, newColor.rgb, opacity), 1.0);
  fragOutCol.a = textureColor.a;
  fragOutCol.rgb *= fragOutCol.a;
  return fragOutCol;
}
vec4 Lut3DFilter2(vec4 textureColor, float opacity){
  float blueColor = textureColor.r * 63.0;
  vec2 quad1;
  quad1.y = floor(floor(blueColor) / 8.0);
  quad1.x = floor(blueColor) - (quad1.y * 8.0);
  vec2 quad2;
  quad2.y = floor(ceil(blueColor) /8.0);
  quad2.x = ceil(blueColor) - (quad2.y * 8.0);
  vec2 texPos1;
  texPos1.x = (quad1.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
  texPos1.y = (quad1.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
  vec2 texPos2;
  texPos2.x = (quad2.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
  texPos2.y = (quad2.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
  vec4 newColor1 = INPUT4(texPos1);
  vec4 newColor2 = INPUT4(texPos2);
  vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
  vec4 fragOutCol = vec4(mix(textureColor.rgb, newColor.rgb, opacity), 1.0);
  fragOutCol.a = textureColor.a;
  fragOutCol.rgb *= fragOutCol.a;
  return fragOutCol;
}


vec2 Mirror(vec2 x) { return abs(mod(x-1., 2.)-1.); }
float normpdf(in float x, in float sigma)
{
	return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}
vec4 gaussianBlur(vec2 i_Uv, vec2 i_Dir, float u_Sample)
{
    float sigma = 4.0;
    float weight = normpdf(0.0, sigma);

    vec4 sum            = vec4(0.0);
    vec4 result         = vec4(0.0);
    vec2 unit_uv        = i_Dir * 2.2;
    float gamma         = 1.0;
    vec4 curColor       = INPUT1(i_Uv);
    vec4 centerPixel    = pow(curColor, vec4(gamma))*weight;
    float sum_weight    = weight;
    float u_mirrorEdge = 0.0;

    for(int i=1; i<=200; i++)
    {
        if (float(i)>u_Sample) break;
        vec2 curRightCoordinate = i_Uv+float(i)*unit_uv;
        vec2 curLeftCoordinate  = i_Uv+float(-i)*unit_uv;
        curRightCoordinate = step(u_mirrorEdge, 0.5)*curRightCoordinate + (1.0-step(u_mirrorEdge, 0.5))*Mirror(curRightCoordinate);
        curLeftCoordinate = step(u_mirrorEdge, 0.5)*curLeftCoordinate + (1.0-step(u_mirrorEdge, 0.5))*Mirror(curLeftCoordinate);
        vec4 rightColor = INPUT1(curRightCoordinate);
        vec4 leftColor = INPUT1(curLeftCoordinate);
        weight = normpdf(float(i) / u_Sample * 15.0, sigma);
        sum+=pow(rightColor, vec4(gamma))*weight;
        sum+=pow(leftColor, vec4(gamma))*weight;
        sum_weight+=weight*2.0;
    }
    result = (sum+centerPixel)/sum_weight; 
    result = pow(result, vec4(1.0 / gamma));
    return clamp(result, 0.0, 1.0);
}
vec2 flip_uv(vec2 uv)
{
    return abs(mod(uv + 1., 2.) - 1.0);
}
mat2 rotMat(float angle)
{
    float sinA = sin(angle);
    float cosA = cos(angle);
    return mat2(cosA,-sinA,sinA,cosA);
}
mat2 scale(float scale_X,float scale_Y)
{
    return mat2(1.0/(scale_X + 0.000001),0.,0.,1.0/(scale_Y + 0.000001));
}
vec2 changUV(vec2 uv,vec2 moveSize,vec2 screenSize,vec2 size,float angle)
{
    vec2 newUV = uv;
    newUV-=moveSize/screenSize;
    // newUV=(newUV-0.5)/size+0.5;
    newUV-=0.5;
    newUV*= scale(size.x,size.y);
    newUV.x*=screenSize.x/screenSize.y;
    float angle_1 = radians(angle);
    newUV*=rotMat(angle_1);
    newUV.x/=screenSize.x/screenSize.y;
    newUV+=0.5;
    return flip_uv(newUV);
}
vec4 DirectionBlur(vec2 uv0, float u_Angle, float u_Sample)
{
    vec2 u_ScreenParams = iResolution.xy;
    vec2 uv = uv0;
    float u_ExpandFlag = 0.0;
    float offset_x = 0.0;
    float offset_y = 0.0;
    float scale_x = 1.0;
    float scale_y = 1.0;
    uv = changUV(uv0,vec2(offset_x,offset_y),vec2(1080.,1920.),vec2(scale_x,scale_y),0.0);
    float theta = u_Angle * 3.1415926 / 180.;
    vec2 ratio = (1.0+u_ExpandFlag*0.4) * 720.0 * u_ScreenParams.xy / min(u_ScreenParams.x, u_ScreenParams.y);
    vec2 dir = vec2(cos(theta), sin(theta)) / ratio;
    vec4 color = gaussianBlur(uv, dir, u_Sample);
    color = clamp(color,0.0,color.a);
    vec4 fragColor = color;
    return fragColor;
}




float cross2d(vec2 a, vec2 b) { return a.x * b.y - a.y * b.x; }
vec2 invBilinear(vec2 p, vec2 a, vec2 b, vec2 c, vec2 d) {
  vec2 res = vec2(-1.0);
  vec2 e = b - a;
  vec2 f = d - a;
  vec2 g = a - b + c - d;
  vec2 h = p - a;
  float k2 = cross2d(g, f);
  float k1 = cross2d(e, f) + cross2d(h, g);
  float k0 = cross2d(h, e);
  // if edges are parallel, this is a linear equation
  if (abs(k2) < 0.001) {
    res = vec2((h.x * k1 + f.x * k0) / (e.x * k1 - g.x * k0), -k0 / k1);
  }
  // otherwise, it's a quadratic
  else {
    float w = k1 * k1 - 4.0 * k0 * k2;
    if (w < 0.0)
      return vec2(-1.0);
    w = sqrt(w);

    float ik2 = 0.5 / k2;
    float v = (-k1 - w) * ik2;
    float u = (h.x - f.x * v) / (e.x + g.x * v);

    if (u < 0.0 || u > 1.0 || v < 0.0 || v > 1.0) {
      v = (-k1 + w) * ik2;
      u = (h.x - f.x * v) / (e.x + g.x * v);
    }
    res = vec2(u, v);
  }

  return res;
}
vec4 CornerPin(vec2 tc, float UpperLeftX, float UpperRightX) // [-1,1]
{
    float UpperLeftY = 0.0;
    float UpperRightY = 0.0;
    float LowerLeftX = 0.0;
    float LowerLeftY = 0.0;
    float LowerRightX = 0.0;
    float LowerRightY = 0.0;
    vec2 upper_left = vec2((UpperLeftX), 1.0 + (UpperLeftY));
    vec2 upper_right = vec2(1.0 + (UpperRightX), 1.0 + (UpperRightY));
    vec2 lower_left = vec2((LowerLeftX), (LowerLeftY));
    vec2 lower_right = vec2(1.0 + (LowerRightX), (LowerRightY));
    // area of the quad
    vec2 uv = invBilinear(tc, lower_left, lower_right, upper_right, upper_left);
    // vec4 col = INPUT1(uv) * step(max(abs(uv.x - 0.5), abs(uv.y - 0.5)), 0.5);
    vec4 col = INPUT1(uv);
    return col;
}


vec3 getNegativeColor(vec3 oriColor) {
    return 1. - oriColor;
}
vec4 NegativeEffect(vec2 fragCoord, float negativeAlpha)
{
    vec2 uv0 = fragCoord;
    vec4 curColor = INPUT1(uv0);
    vec4 negativeColor = curColor;
    negativeColor.rgb = getNegativeColor(negativeColor.rgb);
