float easeOutQuart(float x){
    return 1.0 - pow(1.0 - x, 4.0);
}


vec4 Exposure(vec4 col, float _intensity, float _offset, float _gray_scale_correct, float _linear){
    if(_linear<0.5) col.rgb = pow(col.rgb, vec3(2.2));
    col.rgb *= pow(2.0, _intensity);
    col.rgb += _offset;
    vec3 s = sign(col.rgb);
    col.rgb = pow(abs(col.rgb), vec3(1.0 / _gray_scale_correct)) * s;
    s = sign(col.rgb);
    if (_linear<0.5) col.rgb = pow(abs(col.rgb), vec3(0.454545454545)) * s;
    return col;
}
vec4 lm_take_effect_filter(vec4 inputColor,float uniAlpha)
{
    vec4 textureColor= inputColor; 
    float blueColor=textureColor.b*63.;

    vec2 quad1;
    quad1.y=floor(floor(blueColor)/8.);
    quad1.x=floor(blueColor)-(quad1.y*8.);

    vec2 quad2;
    quad2.y=floor(ceil(blueColor)/8.);
    quad2.x=ceil(blueColor)-(quad2.y*8.);

    vec2 texPos1;
    texPos1.x=(quad1.x*1./8.)+.5/512.+((1./8.-1./512.)*textureColor.r);
    texPos1.y=(quad1.y*1./8.)+.5/512.+((1./8.-1./512.)*textureColor.g);

    vec2 texPos2;
    texPos2.x=(quad2.x*1./8.)+.5/512.+((1./8.-1./512.)*textureColor.r);
    texPos2.y=(quad2.y*1./8.)+.5/512.+((1./8.-1./512.)*textureColor.g);

    vec4 newColor1 = INPUT5(texPos1);
    vec4 newColor2 = INPUT5(texPos2);
    vec4 newColor=mix(newColor1,newColor2,fract(blueColor));
    newColor = mix(textureColor,vec4(newColor.rgb,textureColor.w),uniAlpha);

    return newColor;
}
vec4 lutExposure(vec2 uv0)
{
    float opacity_1 = 1.0;
    float u_Intensity = 0.0;
    float u_Offset = 0.0;
    float u_GrayscaleCorrect = 1.0;
    float use_linear_light = 0.0;

    vec4 res = INPUT1(uv0);
    vec4 resultColor = Exposure(res, u_Intensity, u_Offset, u_GrayscaleCorrect, use_linear_light);
    resultColor.rgb = clamp(resultColor.rgb, 0.0, resultColor.a);
    vec4 fragColor = lm_take_effect_filter(resultColor, opacity_1*resultColor.a);
    return fragColor;
}


vec4 FUNCNAME(vec2 tc) {
    float Glow = 1.0;
    float Strength = 1.0;
    float iPro = PREFIX(iPro);
    int stepType = PREFIX(stepType);
    if(stepType == 1){
        vec2 uv = tc;
        if(iPro > 0.03 && iPro < 0.07){
            float progress = clamp((iPro - 0.03)/0.04, 0.0, 1.0);
            uv = (uv - vec2(0.5))*(1.0 - Strength*0.15*2.0*(0.5 - abs(0.5 - progress))) + vec2(0.5);
        }
        if(iPro > 0.20 && iPro < 0.45){
            float progress = clamp((iPro - 0.25)/0.25, 0.0, 1.0);
            uv = (uv - vec2(0.5))*(1.0 - Strength*0.3*2.0*(0.5 - abs(0.5 - progress))) + vec2(0.5);
        }
        if(iPro > 0.42 && iPro < 0.51){
            float progress = clamp((iPro - 0.42)/0.09, 0.0, 1.0);
            progress = Strength*0.1*2.0*(0.5 - abs(0.5 - progress));
            uv += vec2(-progress, progress);
        }
        if(iPro >= 0.51 && iPro <= 0.55){
            float progress = clamp((iPro - 0.51)/0.04, 0.0, 1.0);
            progress = Strength*0.05*2.0*(0.5 - abs(0.5 - progress));
            uv += vec2(-progress, -progress);
        }
        if(iPro > 0.63 && iPro < 0.73){
            float progress = clamp((iPro - 0.63)/0.1, 0.0, 1.0);
            progress = Strength*0.3*2.0*(0.5 - abs(0.5 - progress));  
            uv = (uv - vec2(0.5))*(1.0 - progress) + vec2(0.5);
            progress *= 0.3;
            uv += vec2(progress, progress);                     
        }
        vec4 fragColor = INPUT1(uv);
        fragColor = Lut3DFilter(fragColor, Glow*1.0);
        vec4 human = Lut3DFilter2(fragColor, Glow*0.7);
        fragColor.rgb = mix(fragColor.rgb, human.rgb, INPUT2(uv).a);
        return fragColor;
    }
    else if(stepType == 2){
        vec4 fragColor = INPUT1(tc);
        if(iPro > 0.13 && iPro < 0.9){
            if(iPro > 0.22 && iPro < 0.44){
                float progress = clamp((iPro - 0.22)/0.22, 0.0, 1.0);
                float angle = 30.0 + 160.0*progress;
                progress = 2.0*(0.5 - abs(0.5 - progress));  
                fragColor = DirectionBlur(tc, angle, 70.0*progress);            
            }
            else if(iPro > 0.63 && iPro < 0.73){
                float progress = clamp((iPro - 0.63)/0.1, 0.0, 1.0);
                float angle = -90.0 + 110.0*progress;
                progress = 2.0*(0.5 - abs(0.5 - progress));  
                fragColor = DirectionBlur(tc, angle, 70.0*progress);            
            }
            else{
                fragColor = DirectionBlur(tc, 0.0, 8.0);  
            }
        }
        return fragColor;
    }
    else if(stepType == 3){
        vec4 fragColor = INPUT1(tc);
        if(iPro > 0.13 && iPro < 0.17){
            float progress = clamp((iPro - 0.33)/0.04, 0.0, 1.0);
            fragColor = lutExposure(tc);
        }
        if(iPro > 0.34 && iPro <= 0.40){
            float progress = clamp((iPro - 0.34)/0.06, 0.0, 1.0);
            progress = Strength*sin(PI*progress);
            fragColor = CornerPin(tc, -0.4*progress, -0.4*progress);
        }
        else if(iPro > 0.53 && iPro <= 0.59){
            float progress = clamp((iPro - 0.53)/0.06, 0.0, 1.0);
            progress = Strength*sin(PI*progress);
            fragColor = CornerPin(tc, 0.35*progress, 0.35*progress);
        }
        else if(iPro >= 0.59 && iPro <= 0.61){
            float progress = clamp((iPro - 0.59)/0.02, 0.0, 1.0);
            fragColor = NegativeEffect(tc, progress);
        }
        else if(iPro >= 0.74 && iPro <= 0.78){
            float progress = clamp((iPro - 0.74)/0.04, 0.0, 1.0);
            fragColor = NegativeEffect(tc, progress);
        }
        else if(iPro > 0.79 && iPro <= 0.85){
            float progress = clamp((iPro - 0.79)/0.06, 0.0, 1.0);
            progress = Strength*sin(PI*progress);
            fragColor = CornerPin(tc, 0.3*progress, 0.3*progress);
        }
        else if(iPro >= 0.90 && iPro <= 0.94){
            float progress = clamp((iPro - 0.90)/0.04, 0.0, 1.0);
            progress = Glow*sin(PI*progress);
            fragColor.rgb *= (1.0 + 1.5*progress);
        }
        return fragColor;
    }
}

