float rgb2grey(vec3 rgbColor) {
    return (rgbColor.r*0.299 + rgbColor.g*0.587 + rgbColor.b*0.114);
}

vec3 RadialBlur(vec2 iuv, float iprocess, float strength)
{	
    int NUM_SAMPLES = 25;
    float WEIGHT = strength * iprocess;

    vec2 currentPosition = iuv;
    float stepSize = 0.1 / float(NUM_SAMPLES);

    vec3 color = INPUT3(currentPosition).rgb;

    for (int i = 0; i < NUM_SAMPLES; i++) {
    	currentPosition.y += stepSize * WEIGHT;
        vec3 smp = INPUT3(currentPosition).rgb;
        color += smp;
    }

    color /= vec3(float(NUM_SAMPLES) + 1.0);


    return vec3(step(0.1, color.r) * color.r);
}

vec2 Random22(vec2 p) {
    return  -1.0+2.0*fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p, vec2(269.5,183.3)))) * 43758.5453);
}

float NoisePerlin12(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    float a = dot(Random22(i),f); 
    float b = dot(Random22(i+vec2(1.,0.)),f-vec2(1.,0.));
    float c = dot(Random22(i+vec2(0.,1.)),f-vec2(0.,1.));
    float d = dot(Random22(i+vec2(1.,1.)),f-vec2(1.,1.));

    vec2 u = smoothstep(0.,1.,f);

    return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}

