vec4 glitchSwing(vec2 tc, float progress)
{
    float stripCount = max(PREFIX(stripCount), 1.0);
    float glitchIntensity = max(PREFIX(glitchIntensity), 0.0);
    float rgbSplitAmount = max(PREFIX(rgbSplitAmount), 0.0);

    float stripId = floor(tc.x * stripCount);
    float isOdd = mod(stripId, 2.0);
    float anim = smoothstep(0.0, 1.0, progress);
    float moveScale = 2.0 * glitchIntensity;

    float aDirection = (isOdd < 0.5) ? -1.0 : 1.0;
    float bDirection = -aDirection;
    vec2 aUv = tc + vec2(0.0, aDirection * anim * anim * moveScale);
    vec2 bUv = tc + vec2(0.0, bDirection * (1.0 - anim) * (1.0 - anim) * moveScale);

    float split = rgbSplitAmount * sin(anim * 3.1415926) * glitchIntensity;
    vec4 aColor = sampleRgbSplitA(aUv, split);
    vec4 bColor = sampleRgbSplitB(bUv, split);

    float overlap = aColor.a * bColor.a;
    float noise = fract(sin(dot(tc + vec2(anim, anim), vec2(12.9898, 78.233))) * 43758.5453);
    vec3 noiseColor = vec3(step(0.8, noise), step(0.8, noise), step(0.8, noise));
    noiseColor *= overlap * sin(anim * 3.1415926) * glitchIntensity;

    float edgePos = fract(tc.x * stripCount);
    float edgeMask = 1.0 - smoothstep(0.0, 0.02, edgePos) * (1.0 - smoothstep(0.98, 1.0, edgePos));
    vec3 glowColor = (isOdd < 0.5) ? vec3(0.2, 0.5, 1.0) : vec3(1.0, 0.2, 0.8);
    vec3 glow = glowColor * edgeMask * sin(anim * 3.1415926) * 0.5 * glitchIntensity;

    vec4 finalColor = mix(aColor, bColor, anim);
    finalColor.rgb = clamp(finalColor.rgb + noiseColor + glow, 0.0, 1.0);
    return finalColor;
}

vec4 FUNCNAME(vec2 tc)
{
    float progress = clamp(PREFIX(iProgress), 0.0, 1.0);
    if (progress <= 0.0) return INPUT1(tc);
    if (progress >= 1.0) return INPUT2(tc);

    // [@动画:A-帧进度] 源资源前各留 15%，中间 70% 线性推进。
    float timelineProgress = clamp((progress - 0.15) / 0.70, 0.0, 1.0);
    float transitionProgress = clamp((timelineProgress - 0.10) / 0.80, 0.0, 1.0);

    vec4 colorA = INPUT1(tc);
    vec4 colorB = INPUT2(tc);
    vec4 transitionColor = glitchSwing(tc, transitionProgress);
    float blendInFactor = smoothstep(0.0, 0.10, timelineProgress);
    float blendOutFactor = smoothstep(0.90, 1.0, timelineProgress);
    vec4 finalColor = mix(colorA, transitionColor, blendInFactor);
    finalColor = mix(finalColor, colorB, blendOutFactor);

    // [@规则:R-T05] iProgress=0 只显示 A，iProgress=1 只显示 B。
    return finalColor;
}

