#define NOISE_SIMPLEX_1_DIV_289 0.00346020761245674740484429065744
#define PI 3.14159265359

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
	vec2 p1 = vec2(p.x, p.y);
	vec2 p2 = vec2(p.z, p.w);
    float mX1 = p1.x;
    float mY1 = p1.y;
    float mX2 = p2.x; 
    float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec4 screen(vec4 src, vec4 blend){
  return 1.0-(1.0-src)*(1.0-blend);
}

vec2 mod289(vec2 x){
	return x - floor(x * NOISE_SIMPLEX_1_DIV_289) * 289.0;
}

vec3 mod289(vec3 x){
	return x - floor(x * NOISE_SIMPLEX_1_DIV_289) * 289.0;
}

vec3 permute(vec3 x){
	return mod289(x * x * 34.0 + x);
}

vec3 taylorInvSqrt(vec3 r){
	return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec2 v){
	const vec4 C = vec4(0.211324865405187,    // (3.0-sqrt(3.0))/6.0
                      0.366025403784439,    // 0.5*(sqrt(3.0)-1.0)
                      -0.577350269189626,  // -1.0 + 2.0 * C.x
                      0.024390243902439);   // 1.0 / 41.0
	// First corner
	vec2 i = floor(v + dot(v, C.yy));
	vec2 x0 = v - i + dot(i, C.xx);

	// Other corners
	vec2 i1;
	i1.x = step(x0.y, x0.x);
	i1.y = 1.0 - i1.x;

	vec2 x1 = x0 + C.xx - i1;
	vec2 x2 = x0 + C.zz;

	// Permutations
	i = mod289(i); // Avoid truncation effects in permutation
	vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));

	vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x1, x1), dot(x2, x2)), 0.0);
	m = m * m;
	m = m * m;

	// Gradients: 41 points uniformly over a line, mapped onto a diamond.
	// The ring size 17*17 = 289 is close to a multiple of 41 (41*7 = 287)
	vec3 x = 2.0 * fract(p * C.www) - 1.0;
	vec3 h = abs(x) - 0.5;
	vec3 ox = floor(x + 0.5);
	vec3 a0 = x - ox;

	// Normalise gradients implicitly by scaling m
	m *= taylorInvSqrt(a0 * a0 + h * h);

	// Compute final noise value at P
	vec3 g;
	g.x = a0.x * x0.x + h.x * x0.y;
	g.y = a0.y * x1.x + h.y * x1.y;
	g.z = a0.z * x2.x + h.z * x2.y;
	return 130.0 * dot(m, g);
}

float Wave_Jitter_Glitch(vec2 i, float _Time){
  float _Frequency = PI;
  float _Strength = sin(_Time * _Frequency);

  vec2 _Resolution = iResolution;
  float _Speed = 0.5;
  float _Amount = 1.0;
  // Prepare UV
  float uv_y = i.y * _Resolution.y;
  float noise_wave_1 = snoise(vec2(uv_y * 0.01, _Time * _Speed * 20.0)) * (_Strength * _Amount * 32.0);
  float noise_wave_2 = snoise(vec2(uv_y * 0.02, _Time * _Speed * 10.0)) * (_Strength * _Amount * 4.0);
  float noise_wave_x = noise_wave_1 * noise_wave_2 / _Resolution.x;
  return noise_wave_x;
}

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

float showBound(vec2 tc){
  return max(max(step(tc.y,0.1), step(0.35, tc.y)*step(tc.y, 0.65)),step(0.9, tc.y));
}

float showScanLine(vec2 tc){
  return max(step(0.4, tc.y)*step(tc.y, 0.65), step(tc.y, 0.1));
}

float scanLineJitterGlitchX(vec2 tc, float t, float strength){
  float iAmount = 1.0;
	float iStrength = strength;
	float iFrequency = 1.0;
  float iGlobalTime = t;

  vec4 retCol = vec4(0.0);
	float curve = 0.5;
  float offset = random(vec2(tc.y * 100.0, iGlobalTime * 100.0)) * 2.0 - 1.0;
  offset *= step(1.0 - iAmount, abs(offset));
  offset *= pow(random(vec2(0.04 * 200.0)), 10.0 - 8.0 * iFrequency) * iStrength * curve;
  offset *= iStrength * curve;
  return offset*showBound(tc);
}

vec4 color_glitch(float t){
  vec4 green = vec4(213,252,191,255)/255.0;
  vec4 pink = vec4(244,185,229,255)/255.0;
  if(t < 0.34){
    return mix(vec4(1.0), pink, t/0.34);
  }else if(t < 0.66){
    return green;
  }else{
    return mix(pink, vec4(1.0), (t-0.66)/(1.0-0.66));
  }
}

float ramp(float y, float start, float end){
	float inside = step(start,y) - step(end,y);
	float fact = (y-start)/(end-start)*inside;
	return (1.-fact) * inside;	
}

float stripes(vec2 uv, float iTime){	
	float noi = random(uv*vec2(0.5,1.) + vec2(1.,3.));
  float inx = floor(uv.y*100.0);
  float yOff = random(vec2(inx,0.0))*0.1*random(vec2(0.0, iTime));
	return ramp(mod(uv.y*100.0 + iTime/2.+sin(iTime + sin(iTime*0.63)),1.0),0.0,1.0)*noi
         * clamp((abs(sin((uv.x-yOff)*400.0))-0.1)*1.2,-1.0,1.0)*step(0.4,yOff*10.0)*showScanLine(uv);
}

vec3 texSample(int x, int y, vec2 fragCoord, int n)
{
	vec2 uv = fragCoord.xy;
	uv = (uv + vec2(x, y)) / iResolution.xy;
	if(n == 1)
		return INPUT1(uv).xyz;       
	else
		return INPUT2(uv).xyz;  
}          

vec3 sharpenFilter(vec2 fragCoord, float strength, int n)
{
	vec3 f =
	texSample(-1,-1, fragCoord, n) *  -1. +                     
	texSample( 0,-1, fragCoord, n) *  -1. +                    
	texSample( 1,-1, fragCoord, n) *  -1. +                      
	texSample(-1, 0, fragCoord, n) *  -1. +                    
	texSample( 0, 0, fragCoord, n) *   9. +                     
	texSample( 1, 0, fragCoord, n) *  -1. +                      
	texSample(-1, 1, fragCoord, n) *  -1. +                     
	texSample( 0, 1, fragCoord, n) *  -1. +                     
	texSample( 1, 1, fragCoord, n) *  -1.
	;                                              
	return mix(texSample(0, 0, fragCoord, n), f , strength);    
}

float exposure(float t){
  if(t<0.4){
    return 1.0;
  }else if(t<0.55){
    return 1.5;
  }else{
    return 1.0;
  }
}

vec4 FUNCNAME(vec2 tc)
{
	float iGlobalTime = PREFIX(global_time);
	float totalTime = PREFIX(total_time);
	float process = min(iGlobalTime / totalTime, 1.0);

  vec4 fragColor = vec4(0.0);
  float strengthVal = 0.7;

  if(process < 0.5){
    vec4 p = vec4(.7,.2,.9,.45);
    float normPro = process*2.0;
    float curPro = KeySpline(p, normPro);
    float strength = strengthVal*random(vec2(curPro,0.0));
    float offset = scanLineJitterGlitchX(tc, process, strength)+Wave_Jitter_Glitch(tc,process)*curPro;
    vec2 uv = vec2(tc.x-offset, tc.y)*iResolution;
    float alpha = INPUT1(tc).w;
    fragColor = vec4(sharpenFilter(uv, 1.0, 1), alpha)*color_glitch(process)+stripes(tc, process)*alpha;
  }else{
    vec4 p = vec4(.7,.2,.9,.45);  
    float normPro = 1.0-(process-0.5)*2.0;
    float curPro = KeySpline(p, normPro);
    float strength = strengthVal*random(vec2(curPro,0.0));
    float offset = (scanLineJitterGlitchX(tc, process, strength)+Wave_Jitter_Glitch(tc,process)*curPro);
    vec2 uv = vec2(tc.x-offset, tc.y)*iResolution;
    float alpha = INPUT2(tc).w;
    fragColor = vec4(sharpenFilter(uv, 1.0, 2), alpha)*color_glitch(process)+stripes(tc, process)*alpha;
  }

  float strength = 32.0;
  float x = (tc.x + 5.0 ) * (tc.y + 5.0 ) * (iGlobalTime * 20.0 + 10.0);
  float grain = (mod((mod(x, 13.0) + 1.0) * (mod(x, 123.0) + 1.0), 0.01) - 0.005) * strength;

  fragColor.rgb *= 1.0 - grain;
  fragColor = clamp(fragColor*exposure(process), 0.0, 1.0);

	return fragColor;	
}

// Glitch Wave Sweep
// The source runs a two-input procedural wipe and then a chromatic-aberration
// post pass. Both stages are folded into this shader so the target stays a
// minimal single-pass Transition.

float saturate(float v)
{
    return clamp(v, 0.0, 1.0);
}

float range01(float value, float startValue, float endValue)
{
    return saturate((value - startValue) / max(endValue - startValue, 0.00001));
}

float easeSinInOut(float t)
{
    return 0.5 - 0.5 * cos(3.14159265 * saturate(t));
}

float easeCubicInOut(float t)
{
    t = saturate(t);
    if (t < 0.5) {
        return 4.0 * t * t * t;
    }
    float q = -2.0 * t + 2.0;
    return 1.0 - q * q * q * 0.5;
}

float easeCircularInOut(float t)
{
    t = saturate(t);
    if (t < 0.5) {
        float q = 2.0 * t;
        return 0.5 * (1.0 - sqrt(max(0.0, 1.0 - q * q)));
    }
    float q = -2.0 * t + 2.0;
    return 0.5 * (sqrt(max(0.0, 1.0 - q * q)) + 1.0);
}

float easeExponentialOut(float t)
{
    t = saturate(t);
    if (t >= 1.0) {
        return 1.0;
    }
    return 1.0 - pow(2.0, -10.0 * t);
}

float tweenSin(float timeMs, float startMs, float endMs, float fromValue, float toValue)
{
    return mix(fromValue, toValue, easeSinInOut(range01(timeMs, startMs, endMs)));
}

float tweenCubic(float timeMs, float startMs, float endMs, float fromValue, float toValue)
{
    return mix(fromValue, toValue, easeCubicInOut(range01(timeMs, startMs, endMs)));
}

float hash12(vec2 p)
{
    vec3 p3 = fract(vec3(p.x, p.y, p.x) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec4 sampleRGBSplitA(vec2 uv, float shift)
{
    vec2 delta = uv - vec2(0.5);
    float len = length(delta);
    vec2 dir = (len < 0.0001) ? vec2(1.0, 0.0) : delta / len;
    vec2 off = dir * shift;
    vec4 source = INPUT1(clamp(uv, vec2(0.0), vec2(1.0)));
    float r = INPUT1(clamp(uv + off, vec2(0.0), vec2(1.0))).r;
    float g = source.g;
    float b = INPUT1(clamp(uv - off, vec2(0.0), vec2(1.0))).b;
    return vec4(r, g, b, source.a);
}

vec4 sampleRGBSplitB(vec2 uv, float shift)
{
    vec2 delta = uv - vec2(0.5);
    float len = length(delta);
    vec2 dir = (len < 0.0001) ? vec2(1.0, 0.0) : delta / len;
    vec2 off = dir * shift;
    vec4 source = INPUT2(clamp(uv, vec2(0.0), vec2(1.0)));
    float r = INPUT2(clamp(uv + off, vec2(0.0), vec2(1.0))).r;
    float g = source.g;
    float b = INPUT2(clamp(uv - off, vec2(0.0), vec2(1.0))).b;
    return vec4(r, g, b, source.a);
}

float flashAt(float timeMs)
{
    if (timeMs < 100.0) return 0.0;
    if (timeMs < 160.0) return tweenSin(timeMs, 100.0, 160.0, 0.0, 0.55);
    if (timeMs < 220.0) return tweenSin(timeMs, 160.0, 220.0, 0.55, 0.0);
    if (timeMs < 290.0) return tweenSin(timeMs, 220.0, 290.0, 0.0, 0.75);
    if (timeMs < 360.0) return tweenSin(timeMs, 290.0, 360.0, 0.75, 0.0);
    if (timeMs < 440.0) return tweenSin(timeMs, 360.0, 440.0, 0.0, 0.95);
    if (timeMs < 520.0) return tweenSin(timeMs, 440.0, 520.0, 0.95, 0.0);
    return 0.0;
}

float rgbShiftAt(float timeMs)
{
    if (timeMs < 100.0) return 0.0;
    if (timeMs < 160.0) return tweenCubic(timeMs, 100.0, 160.0, 0.0, 0.010);
    if (timeMs < 220.0) return tweenCubic(timeMs, 160.0, 220.0, 0.010, 0.0);
    if (timeMs < 290.0) return tweenCubic(timeMs, 220.0, 290.0, 0.0, 0.014);
    if (timeMs < 360.0) return tweenCubic(timeMs, 290.0, 360.0, 0.014, 0.0);
    if (timeMs < 440.0) return tweenCubic(timeMs, 360.0, 440.0, 0.0, 0.018);
    if (timeMs < 520.0) return tweenCubic(timeMs, 440.0, 520.0, 0.018, 0.0);
    if (timeMs < 620.0) return 0.0;
    if (timeMs < 760.0) return tweenCubic(timeMs, 620.0, 760.0, 0.0, 0.020);
    if (timeMs < 980.0) return tweenCubic(timeMs, 760.0, 980.0, 0.020, 0.0);
    if (timeMs < 1620.0) return 0.0;
    if (timeMs < 1660.0) return tweenCubic(timeMs, 1620.0, 1660.0, 0.0, 0.028);
    if (timeMs < 1700.0) return tweenCubic(timeMs, 1660.0, 1700.0, 0.028, 0.0);
    if (timeMs < 1740.0) return tweenCubic(timeMs, 1700.0, 1740.0, 0.0, 0.020);
    if (timeMs < 1780.0) return tweenCubic(timeMs, 1740.0, 1780.0, 0.020, 0.0);
    if (timeMs < 1820.0) return tweenCubic(timeMs, 1780.0, 1820.0, 0.0, 0.013);
    if (timeMs < 1860.0) return tweenCubic(timeMs, 1820.0, 1860.0, 0.013, 0.0);
    return 0.0;
}

float glitchAt(float timeMs)
{
    if (timeMs < 520.0) return 0.0;
    if (timeMs < 940.0) return tweenCubic(timeMs, 520.0, 940.0, 0.0, 0.75);
    if (timeMs < 1400.0) return tweenCubic(timeMs, 940.0, 1400.0, 0.75, 0.18);
    if (timeMs < 1620.0) return 0.18;
    if (timeMs < 1660.0) return tweenSin(timeMs, 1620.0, 1660.0, 0.18, 0.22);
    if (timeMs < 1700.0) return tweenSin(timeMs, 1660.0, 1700.0, 0.22, 0.12);
    if (timeMs < 1740.0) return tweenSin(timeMs, 1700.0, 1740.0, 0.12, 0.16);
    if (timeMs < 1780.0) return tweenSin(timeMs, 1740.0, 1780.0, 0.16, 0.08);
    if (timeMs < 1820.0) return tweenSin(timeMs, 1780.0, 1820.0, 0.08, 0.10);
    if (timeMs < 1860.0) return tweenSin(timeMs, 1820.0, 1860.0, 0.10, 0.0);
    return 0.0;
}

float debrisAt(float timeMs)
{
    if (timeMs < 560.0) return 0.0;
    if (timeMs < 1020.0) return tweenCubic(timeMs, 560.0, 1020.0, 0.0, 0.85);
    if (timeMs < 1500.0) return tweenCubic(timeMs, 1020.0, 1500.0, 0.85, 0.0);
    return 0.0;
}

float bwAt(float timeMs)
{
    if (timeMs < 520.0) return 0.0;
    if (timeMs < 820.0) return tweenCubic(timeMs, 520.0, 820.0, 0.0, 1.0);
    if (timeMs < 1860.0) return 1.0;
    if (timeMs < 1950.0) return tweenCubic(timeMs, 1860.0, 1950.0, 1.0, 0.0);
    return 0.0;
}

float postChromaticAt(float timeMs)
{
    if (timeMs < 100.0) return 0.0;
    if (timeMs < 520.0) {
        return mix(0.0, 0.22, easeSinInOut(range01(timeMs, 100.0, 520.0)));
    }
    if (timeMs < 1620.0) {
        return mix(0.22, 0.35, easeCircularInOut(range01(timeMs, 520.0, 1620.0)));
    }
    if (timeMs < 1950.0) {
        return mix(0.35, 0.0, easeExponentialOut(range01(timeMs, 1620.0, 1950.0)));
    }
    return 0.0;
}

float layerMask(float progress, float yOffset, vec2 uv, float seed, float timeMs)
{
    float p = saturate(progress);
    float wave = sin((uv.y + yOffset) * 13.0 + seed * 1.7 + timeMs * 0.011) * 0.035;
    wave += sin((uv.y + yOffset) * 31.0 + seed * 2.4 - timeMs * 0.008) * 0.018;
    float strip = floor((uv.y + yOffset + sin(timeMs * 0.02 + seed) * 0.01) * 52.0) / 52.0;
    float jag = (strip - (uv.y + yOffset)) * 0.18;
    float edge = -0.22 + p * 1.48 + wave + jag;
    return step(uv.x, edge);
}

vec3 highContrastBW(vec3 col)
{
    float gray = dot(col, vec3(0.299, 0.587, 0.114));
    return vec3(smoothstep(0.28, 0.72, gray));
}

vec4 renderCore(vec2 uv, float timeMs)
{
    float maskProgress1 = easeSinInOut(range01(timeMs, 520.0, 1620.0));
    float maskProgress2 = easeSinInOut(range01(timeMs, 560.0, 1580.0));
    float maskProgress3 = easeSinInOut(range01(timeMs, 600.0, 1620.0));
    float transitionMix = easeCubicInOut(range01(timeMs, 520.0, 1620.0));

    float l1 = layerMask(maskProgress1, 0.18, uv, 1.0, timeMs);
    float l2 = layerMask(maskProgress2, -0.07, uv, 2.0, timeMs);
    float l3 = layerMask(maskProgress3, 0.11, uv, 3.0, timeMs);
    float maskMix = max(max(l1, l2), l3) * smoothstep(0.0, 0.06, transitionMix);

    float rgbShift = rgbShiftAt(timeMs);
    vec4 colA = sampleRGBSplitA(uv, rgbShift);
    vec4 colB = sampleRGBSplitB(uv, rgbShift);
    vec3 bwB = mix(colB.rgb, highContrastBW(colB.rgb), bwAt(timeMs));

    float edge1 = -0.22 + maskProgress1 * 1.48;
    float edge2 = -0.22 + maskProgress2 * 1.48;
    float edge3 = -0.22 + maskProgress3 * 1.48;
    float edgeDist = min(min(abs(uv.x - edge1), abs(uv.x - edge2)), abs(uv.x - edge3));
    float edgeGlow = 1.0 - smoothstep(0.0, 0.07, edgeDist);

    float glitch = glitchAt(timeMs);
    vec2 block = floor(uv * vec2(220.0, 130.0));
    float n = hash12(block + floor(timeMs * 0.05));
    vec2 jitter = vec2((n - 0.5) * 0.08 * glitch * edgeGlow,
                       (hash12(block.yx + 5.13) - 0.5) * 0.02 * glitch);
    vec4 glitchB = sampleRGBSplitB(clamp(uv + jitter, vec2(0.0), vec2(1.0)),
                                   rgbShift + glitch * 0.01);

    float debris = debrisAt(timeMs);
    float debrisField = step(0.86, hash12(block * 1.37 + vec2(timeMs * 0.03, timeMs * 0.04)));
    debrisField *= edgeGlow * debris;

    vec3 neonPink = vec3(1.0, 0.31, 0.85);
    vec3 neonBlue = vec3(0.21, 0.95, 1.0);
    float scan = 0.5 + 0.5 * sin(uv.y * 48.0 + timeMs * 0.055);
    float flash = flashAt(timeMs);
    vec3 flashColor = mix(neonPink, neonBlue, scan) * (0.45 + 0.55 * scan) * flash;

    vec3 aStyled = colA.rgb * (1.0 + flash * 0.85) + flashColor;
    vec3 bStyled = mix(bwB, glitchB.rgb, glitch * edgeGlow);
    vec3 mixed = mix(aStyled, bStyled, saturate(maskMix));
    mixed += debrisField * mix(neonBlue, neonPink, n) * (0.55 + glitch * 0.45);
    float alpha = mix(colA.a, colB.a, saturate(maskMix));
    return vec4(mixed, alpha);
}

vec4 FUNCNAME(vec2 tc)
{
    float p = saturate(PREFIX(iProgress));
    // [@规则:R-T05] Close both endpoints before any procedural styling.
    if (p <= 0.0) return INPUT1(tc);
    if (p >= 1.0) return INPUT2(tc);

    float timeMs = p * 2000.0;
    float postIntensity = postChromaticAt(timeMs);
    float radial = length(tc - vec2(0.5));
    vec2 postOffset = vec2(0.05 * postIntensity * radial);

    vec4 center = renderCore(tc, timeMs);
    float r = renderCore(clamp(tc + postOffset, vec2(0.0), vec2(1.0)), timeMs).r;
    float b = renderCore(clamp(tc - postOffset, vec2(0.0), vec2(1.0)), timeMs).b;
    return vec4(r, center.g, b, center.a);
}

#define PI 3.141592653589793

float curveTime(float t) {
    t = t * 2.0 - 1.0;
    return 1.0 - pow(abs(sin(PI * t / 2.0)), 2.0);
}

float curveTime2(float t) {
    t = t * 2.0 - 1.0;
    return pow(cos(PI * t / 2.0), 4.0);
}

vec2 SetScale(vec2 uv, float sv) {
    vec2 st = uv;
    st -= 0.5;
    st /= sv;
    st += 0.5;
    return st;
}

float sat(float x) {
    return clamp(x, 0.0, 1.0);
}

vec4 mixFunc(vec4 back, vec4 overlap, float alp) {
    float invAlp = 1.0 - alp;
    vec4 ret = back;

    if (alp > 0.0) {
        ret.xyz = overlap.xyz + back.xyz * invAlp;
        ret.a = alp + back.a * invAlp;
    }
    return ret;
}

vec4 FUNCNAME(vec2 tc) {
    float mapIndex[25];
    mapIndex[0]  = 12.0; mapIndex[1]  = 5.0; mapIndex[2]  = 6.0; mapIndex[3]  = 7.0; mapIndex[4]  =  8.0;
    mapIndex[5]  = 11.0; mapIndex[6]  = 4.0; mapIndex[7]  = 1.0; mapIndex[8]  = 2.0; mapIndex[9]  =  9.0;
