    vec2 uv = tc;
    uv.y = 1.0 - uv.y;
    uv -= 0.125;
    float iPro = PREFIX(iPro);
    vec2 uvx4 = vec2(uv.x, uv.y) * 4.0;
    float x = floor(uvx4.x + 1.0);
    float y = floor(uvx4.y + 1.0);
    float fv = (x + y * 5.0);
    int iv = int(fv);

    float weight = (mapIndex[iv] / 12.0);

    float delayPos = 0.65;
    float curPro = sat((iPro - weight * delayPos) / (1.0 - delayPos));
    float curvePro = curveTime(curPro);
    float curvePro2 = curveTime2(curPro);

    // 完整的缩放循环：1.0 → 1.15 → 1.0
    float sv = mix(1.0, 1.15, curvePro);

    vec2 st = SetScale(tc, sv);
    vec4 retColor = vec4(0.0);
    if(curPro < 0.5){
