        retColor = INPUT2(st);
    }

    // 柔和的白色发光效果
    vec4 glowColor = vec4(1.0) * 0.5 * curvePro;
    vec4 finalColor = mixFunc(retColor, glowColor, glowColor.a * 0.8);

    return finalColor * mix(1.0, 1.3, curvePro);
}

#define PI 3.141592653589793
float easeInOutQuart(float x) {
return x < 0.5 ? 8.0 * x * x * x * x : 1.0 - pow(-2.0 * x + 2.0, 4.0) / 2.0;
}

// 获取动态黄色叠加强度的函数
int getDynamicYellowIntensity(float x, float y, float progress) {
    // 创建斜条纹：从左下到右上
    // 使用 x + y 来创建斜向条纹，斜率为45度
    float diagonalCoord = x + y;

    // 将对角坐标映射到16个条纹中的哪一个
    // diagonalCoord 的范围是 0-2，我们需要映射到 0-1 范围
    float normalizedDiagonal = diagonalCoord * 0.5;
    int stripeIndex = int(floor(normalizedDiagonal * 16.0));

    // 总共27个时间区域：16个条带激活 + 11个级别变化
    float totalTimeSteps = 27.0;
    float timeStepSize = 1.0 / totalTimeSteps; // 每个时间区域的大小

    // 计算当前是第几个时间步骤 (1-27)
    int currentTimeStep = int(floor(progress * totalTimeSteps)) + 1;

    // 计算该条带应该处于哪个级别
    // 条带在第(stripeIndex+1)个时间步骤开始激活
    int stripeActivationStep = stripeIndex + 1;

    // 如果当前时间步骤还没到达该条带的激活时间，返回0
    if (currentTimeStep < stripeActivationStep) {
        return -1;
    }

    // 计算该条带已经激活了多少个时间步骤
    int stepsActive = currentTimeStep - stripeActivationStep;

    if (stepsActive > 10) {
        return -2;
    }

    // 返回对应级别的强度
    return stepsActive;
}

float blendScreen(float base, float blend) 
{
    return 1. - ((1. - base) * (1. - blend));
}

vec3 blendScreen(vec3 base, vec3 blend) 
{
    return vec3(blendScreen(base.r, blend.r),
                blendScreen(base.g, blend.g),
                blendScreen(base.b, blend.b));
}
vec4 blendScreen(vec4 base, vec4 blend) 
{
    return vec4(blendScreen(base.r, blend.r),
                blendScreen(base.g, blend.g),
                blendScreen(base.b, blend.b),
                blendScreen(base.a, blend.a));
}
