float A(float aA1, float aA2) {
    return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
    return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
    return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
    return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
    return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
    float aGuessT = aX;
    for (int i = 0; i < 6; ++i) {
        float currentSlope = GetSlope(aGuessT, mX1, mX2);
        if (currentSlope == 0.0)
            return aGuessT;
        float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
        aGuessT -= currentX / currentSlope;
    }
    return aGuessT;
}

float KeySpline(vec4 p, float aX) {
    float mX1 = p.x;
    float mY1 = p.y;
    float mX2 = p.z; 
    float mY2 = p.w;
    if (mX1 == mY1 && mX2 == mY2)
        return aX;    // linear
    return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

float normpdf(float x, float sigma){
    return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

vec4 motionBlur(vec2 tc, vec2 direction, float strength) {
    float sigma = 28.0;
    float weight = normpdf(0.0, sigma);
    vec4 retCol = INPUT1(tc);
    retCol *= weight;
    float sum = weight;
    float radius = 0.005 * strength;

    for(float j = 1.0; j < 15.0; j += 1.0)
    {
        weight = normpdf(j / 10.0 * 25.0, sigma);
        float offset = radius * j;
        vec2 uv = tc + direction * offset;
        if(uv.x >= 0.0 && uv.x <= 1.0){
            retCol += INPUT1(uv) * weight;
        }
        sum += weight;

        uv = tc - direction * offset;
        if(uv.x >= 0.0 && uv.x <= 1.0){
            retCol += INPUT1(uv) * weight;
        }
        sum += weight;
    }

    retCol /= sum;
    retCol = clamp(retCol, 0.0, 1.0);

    return retCol;
}

vec4 FUNCNAME(vec2 tc)
{
    int uStep = PREFIX(uStep);
    float progress = PREFIX(progress);
    float y1_process = clamp(progress * 2.0, 0.0, 1.0);
    float y2_process = clamp((progress - 0.5) * 2.0, 0.0, 1.0);

    if(uStep == 1){
        float blur_process = pow(y1_process, 5.0);
        float strength = mix(0.0, 1.0, blur_process);
        if(progress > 0.5){
            strength = mix(1.0, 0.0, y2_process);
        }
        return motionBlur(tc, vec2(0.0, 1.0), strength);
    }else if(uStep == 2){
        return INPUT1(tc);
    }

    y1_process = pow(y1_process, 5.0);
    float scale1 = mix(1.0, 1.2, y1_process);
    vec2 uv1 = (tc - vec2(0.5)) * vec2(1.0, scale1) + vec2(0.5);

    float scale_process = clamp((y2_process - 0.4) / 0.18, 0.0, 1.0);
    vec4 p = vec4(.45,.77,.49,.99);
    scale_process = KeySpline(p, scale_process);
    float scale2 = mix(0.8, 1.0, scale_process);

    float offset_process1 = clamp(y2_process / 0.3, 0.0, 1.0);
    vec2 offset = vec2(0.0, mix(0.25, 0.0, offset_process1));
    if(y2_process > 0.45 && y2_process < 0.7){
        float offset_process2 = clamp((y2_process - 0.45) / 0.25, 0.0, 1.0);
        offset = vec2(0.0, mix(0.0, 0.03, offset_process2));
    }else if(y2_process >= 0.7){
        float offset_process3 = clamp((y2_process - 0.6) / 0.3, 0.0, 1.0);
        p = vec4(.56,.04,.4,.99);
        offset_process3 = KeySpline(p, offset_process3);
        offset = vec2(0.0, mix(0.03, 0.0, offset_process3));
    }

    vec2 uv2 = (tc - vec2(0.5)) * vec2(scale2) + vec2(0.5) - offset;

    vec4 y1 = INPUT1(uv1);
    vec4 y2 = INPUT2(uv2);

    vec4 retCol = y1;
    if(progress > 0.5){
        retCol = y2;
    }

    return retCol;
}

