vec3 Bokeh(vec2 uv, float radius)
{
	vec3 acc = vec3(0.0);
  vec3 div = acc;
  float r = 1.0;
  int ITERATIONS = 10;
  vec2 vangle = vec2(0.0, radius*0.01 / sqrt(150.0));
  vangle.x *= min(1.0, iResolution.x/iResolution.y);
  vangle.y *= max(1.0, iResolution.x/iResolution.y);
  mat2 rot = mat2(cos(2.3999632), sin(2.3999632), -sin(2.3999632), cos(2.3999632));

	for (int j = 0; j < 150; j++) {  
    // the approx increase in the scale of sqrt(0, 1, 2, 3...)
    r += 1. / r;
    vangle = rot * vangle;
    vec3 col = INPUT3(uv + (r-1.0) * vangle).xyz; /// ... Sample the image
    // col = col * col * 1.8; // ... Contrast it for better highlights - leave this out elsewhere.
    col = mix(col, col * col * 1.8, PREFIX(blurProcess));
    vec3 bokeh = pow(col, vec3(4.0));
    acc += col * bokeh;
    div += bokeh;
	}

	return acc / div;
}

