// =============================================================================
// Gray Smear · frag
// Pass0：A/B 硬切 + 去饱和 + AE Exposure
// Pass1：斜向 Gaussian 方向拖影（复刻 LumiDirectionalBlurs，directionNum=1）
// =============================================================================

const float kPI = 3.141592653589793;
const float kGamma = 2.2;
// CapCut InputTex 从 aeTime=0.16 起可用 → progress ≈ 0.333
const float kSwitchP = 0.16 / 0.48;

// CapCut LumiSaturation：u_intensity = AE_sat + 1（0=灰，1=彩）
vec3 applySaturation(vec3 rgb, float intensity) {
    vec3 grayW = vec3(0.20854, 0.702086, 0.089374) * (1.0 - intensity);
    return vec3(
        dot(rgb, grayW + vec3(intensity, 0.0, 0.0)),
        dot(rgb, grayW + vec3(0.0, intensity, 0.0)),
        dot(rgb, grayW + vec3(0.0, 0.0, intensity))
    );
}

// CapCut LumiExposure：linear light + pow(2, stops)
vec3 applyExposure(vec3 rgb, float exposureStops) {
    vec3 c = pow(max(rgb, vec3(0.0)), vec3(kGamma));
    c *= pow(2.0, exposureStops);
    c = pow(abs(c), vec3(1.0)) * sign(c);
    c = pow(abs(c), vec3(1.0 / kGamma)) * sign(c);
    return clamp(c, 0.0, 1.0);
}

vec4 sampleGrade(vec2 uv) {
    // [@规则:R-T05] p=0 只显示 A/INPUT1，p=1 只显示 B/INPUT2
    float p = PREFIX(iProgress);
    vec4 col = (p < kSwitchP) ? INPUT1(uv) : INPUT2(uv);
    col.rgb = applySaturation(col.rgb, PREFIX(uSat));
    col.rgb = applyExposure(col.rgb, PREFIX(uExposure));
    return col;
}

// [@pass:uStep=0]
vec4 featureGrade(vec2 tc) {
    return sampleGrade(tc);
}

float gaussianWeight(float x, float sigma) {
    return exp((-0.5 * x * x) / max(sigma * sigma, 1e-6));
}

vec2 aspectScale(vec2 wh) {
    float size1 = min(wh.x, wh.y);
    float size2 = max(wh.x, wh.y) * 0.5;
    float baseSize = max(size1, size2);
    return vec2(baseSize / max(wh.x, 1.0), baseSize / max(wh.y, 1.0));
}

// CapCut：startAngle = (-angle - 90) * pi/180；radius = intensity/1000
vec4 directionalBlur(vec2 tc, float intensity, float angleDeg) {
    if (intensity < 1e-3) {
        return INPUT1(tc);
    }

    // 采样数与降采样策略的近似（quality=0.5 → qualityParam≈1）
    float sampleNum = 0.0;
    if (intensity <= 10.0) {
        sampleNum = 0.8 * intensity;
    } else if (intensity <= 50.0) {
        sampleNum = (0.7 * intensity + 2.0) * 0.78;
    } else if (intensity <= 200.0) {
        sampleNum = (0.5 * intensity + 10.0) * 0.66;
    } else if (intensity <= 500.0) {
        sampleNum = (0.25 * intensity + 60.0) * 0.7;
    } else {
        sampleNum = (0.125 * intensity + 100.0) * 0.8;
    }
    sampleNum = max(sampleNum, 1.0);
    // 单 Pass 性能上限
    sampleNum = min(sampleNum, 48.0);

    float radius = intensity / 1000.0;
    float sigma = radius / 3.0;
    float ds = radius / sampleNum;
    float theta = (-angleDeg - 90.0) * kPI / 180.0;
    vec2 xyScale = aspectScale(iResolution.xy);
    vec2 stepUv = vec2(cos(theta), sin(theta)) * ds * xyScale;

    float wSum = gaussianWeight(0.0, sigma);
    vec4 acc = INPUT1(tc) * wSum;

    for (int i = 1; i <= 48; ++i) {
        float fi = float(i);
        if (fi > sampleNum) {
            break;
        }
        float w = gaussianWeight(length(stepUv * fi), sigma);
        vec2 o = stepUv * fi;
        vec2 u0 = tc - o;
        vec2 u1 = tc + o;
        // borderType=Normal：越界丢弃权重
        if (u0.x >= 0.0 && u0.y >= 0.0 && u0.x <= 1.0 && u0.y <= 1.0) {
            acc += INPUT1(u0) * w;
            wSum += w;
        }
        if (u1.x >= 0.0 && u1.y >= 0.0 && u1.x <= 1.0 && u1.y <= 1.0) {
            acc += INPUT1(u1) * w;
            wSum += w;
        }
    }

    return clamp(acc / max(wSum, 1e-6), 0.0, 1.0);
}

// [@pass:uStep=1]
vec4 featureBlur(vec2 tc) {
    return directionalBlur(tc, PREFIX(uBlur), PREFIX(uAngle));
}

