float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
  vec2 p1 = vec2(p.x, p.y);
  vec2 p2 = vec2(p.z, p.w);
  float mX1 = p1.x;
  float mY1 = p1.y;
  float mX2 = p2.x;
  float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;

  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec4 FUNCNAME(vec2 tc) {
    float global_time = PREFIX(global_time);
    float total_time = PREFIX(total_time);

    float progress = global_time / total_time;
    float duration = 0.5;
    float start_time = (1.0 - duration) * 0.5;
    progress = (progress - start_time) / duration;
    progress = clamp(progress, 0.0, 1.0);
    vec4 p = vec4(.41,0.0,.61,.99);
    progress = KeySpline(p, progress);

    vec4 foreCol = INPUT1(tc);
    vec4 backCol = INPUT2(tc);
    vec4 retCol = foreCol;

    if(progress < 0.00001){
      return retCol;
    }

    int cell_height = int(iResolution.y * (1.0 / 3.0)); 
    if(mod(float(cell_height), 2.0) > 0.0){
      cell_height += 1;
    }

    int cur_cell_height = int(progress * float(cell_height));
    if(mod(float(cur_cell_height), 2.0) > 0.0){
      cur_cell_height++;
    }
    int cur_border_y = int(float(cell_height - cur_cell_height) / 2.0 + 0.5);

    int cell_width = int(float(cell_height) * (iResolution.x / iResolution.y)); 
    int cur_cell_width = int(progress * float(cell_width));
    if(mod(float(cur_cell_width), 2.0) > 0.0){
      cur_cell_width++;
    }
    int cur_border_x = int(float(cell_width - cur_cell_width) / 2.0 + 0.5);

    vec2 fragCoord = tc * iResolution.xy;
    int cell_x = int(mod(fragCoord.x, float(cell_width)));
    int cell_y = int(mod(fragCoord.y, float(cell_height)));

    if(cell_x >= cur_border_x && cell_x <= cur_border_x + cur_cell_width &&
       cell_y >= cur_border_y && cell_y <= cur_border_y + cur_cell_height){
      retCol = backCol;
    }

    return retCol;
}

