}

vec4 FUNCNAME(vec2 tc) {
    float global_time = PREFIX(global_time);
    float total_time = PREFIX(total_time);

    vec2 size = vec2(2.0);
    float pause = 0.0;
    vec4 bgCol = vec4(0.0, 0.0, 0.0, 1.0);
    float randomness = 0.001;

    float progress = global_time / total_time;
    float duration = 0.8;
    float start_time = (1.0 - duration) * 0.5;
    progress = (progress - start_time) / duration;
    progress = clamp(progress, 0.0, 1.0);
    vec4 p = vec4(.49,.01,.52,1.0);
    progress = KeySpline(p, progress);

    // License: MIT
    // Author: TimDonselaar
    // ported by gre from https://gist.github.com/TimDonselaar/9bcd1c4b5934ba60087bdb55c2ea92e5
    vec2 rectanglePos = floor(size * tc);
    float r = rand(rectanglePos + vec2(100.0, 200.0));
    r = clamp(r, 0.0, 1.0);
    r = mix(0.4, 0.9, r) - randomness;
    float cp = smoothstep(0.0, r, progress);

    float rectangleSize = 1.0 / size.x;
    float delta = rectanglePos.x * rectangleSize;
    float offset = rectangleSize / 2.0 + delta;
    vec2 uv = tc;
    if(abs(cp - 0.5) > 0.0){
      uv.x = (uv.x - offset) / abs(cp - 0.5) * 0.5 + offset;
    }
    vec4 foreCol = INPUT1(uv);
    vec4 backCol = INPUT2(uv);

    float s = step(abs(size.x * (tc.x - delta) - 0.5), abs(cp - 0.5));
    return mix(bgCol, mix(backCol, foreCol, step(cp, 0.5)), s);
}

customize_in vec2 vUV;
customize_in float vPhase;

vec4 sampleGridSource(vec2 uv) {
    vec2 safeUV = clamp(uv, vec2(0.0), vec2(1.0));
    return vPhase < 0.5 ? INPUT4(safeUV) : INPUT5(safeUV);
}

vec4 featureGridFlip() {
    if (vPhase > 1.5) {
        return vec4(0.0, 0.0, 0.0, 1.0);
    }

    // 每块越过侧向最窄状态时完成 A/B 换面；不存在整画面交叉淡化。
    vec4 color = sampleGridSource(vUV);
    float motion = sin(clamp(vPhase, 0.0, 1.0) * 3.1415927);
    vec2 tileUV = fract(vUV * PREFIX(uGridSize));
    float edgeDistance = min(min(tileUV.x, 1.0 - tileUV.x), min(tileUV.y, 1.0 - tileUV.y));
    float edgeShade = mix(0.90, 1.0, smoothstep(0.0, 0.08, edgeDistance));
    color.rgb *= mix(1.0, edgeShade, motion);
    return vec4(color.rgb, 1.0);
}

vec4 featureBlurMask() {
    if (vPhase > 1.5) {
        return vec4(0.0, 0.0, 0.0, 1.0);
    }
    float blurPhase = abs(sin(clamp(vPhase, 0.0, 1.0) * 6.2831853));
    return vec4(vec3(blurPhase), 1.0);
}

vec4 sampleRawFrame(vec2 uv) {
    return INPUT1(clamp(uv, vec2(0.0), vec2(1.0)));
}

float sampleBlurMask(vec2 uv) {
    return INPUT2(clamp(uv, vec2(0.0), vec2(1.0))).r;
}

// [@特性:传播式运动模糊] 先按每块相位柔化真实几何及边缘，再进入历史残影环。
vec4 featureMotionBlur(vec2 uv) {
    vec2 maxProbe = vec2(0.0, 8.0 / iResolution.y);
    float blurMask = sampleBlurMask(uv);
    blurMask = max(blurMask, sampleBlurMask(uv + maxProbe));
    blurMask = max(blurMask, sampleBlurMask(uv - maxProbe));
    vec2 blurStep = vec2(0.0, (8.0 / 3.0) * blurMask / iResolution.y);
    vec4 color = sampleRawFrame(uv) * 0.40;
    color += sampleRawFrame(uv + blurStep) * 0.20;
    color += sampleRawFrame(uv - blurStep) * 0.20;
    color += sampleRawFrame(uv + blurStep * 2.0) * 0.08;
    color += sampleRawFrame(uv - blurStep * 2.0) * 0.08;
    color += sampleRawFrame(uv + blurStep * 3.0) * 0.02;
    color += sampleRawFrame(uv - blurStep * 3.0) * 0.02;
    return vec4(color.rgb, 1.0);
}

vec3 overlayGhost(vec3 base, vec3 ghost, float opacity) {
    return mix(base, max(base, ghost), opacity);
}

// [@特性:时间残影] 前一帧与前两帧的真实几何结果形成传播式双重曝光。
vec4 featureTemporalGhost(vec2 uv) {
    vec3 current = INPUT1(uv).rgb;
    vec3 previous1 = INPUT2(uv).rgb;
    vec3 previous2 = INPUT3(uv).rgb;
    float progress = clamp(PREFIX(iProgress), 0.0, 1.0);
    float activeIn = smoothstep(0.15, 0.23, progress);
    float activeOut = 1.0 - smoothstep(0.80, 0.85, progress);
    float ghostEnvelope = activeIn * activeOut;
    vec3 color = overlayGhost(current, previous1, 0.22 * ghostEnvelope);
    color = overlayGhost(color, previous2, 0.10 * ghostEnvelope);
    return vec4(color, 1.0);
}

vec4 FUNCNAME(vec2 tc) {
    int uStep = PREFIX(uStep);
    if (uStep == 0) {
        // [@规则:R-T05] mesh pass 中 INPUT4=A、INPUT5=B。
        return featureGridFlip();
    }
    if (uStep == 1) {
        return featureBlurMask();
    }
    if (uStep == 2) {
        return featureMotionBlur(tc);
    }
    if (uStep == 3) {
        return featureTemporalGhost(tc);
    }
    return vec4(0.0, 0.0, 0.0, 1.0);
}

#define PI 3.141592653589793
vec4 DirectionBlur(vec2 tc, float angle, int strength) {
    int radius = 2 * strength + 1;
    float theta = radians(angle);  
    vec2 dir = vec2(cos(theta), sin(theta));
    vec4 color = INPUT1(tc);
	  vec4 retCol = vec4(0.0);
    vec2 onePixel = 2.0 / iResolution.xy; 
    vec4 roi = PREFIX(orig_roi);
	  float matt = 0.0;
    for (int i = -strength; i <= strength; i++){
      vec2 t = vec2(float(i)) * onePixel;
      vec2 xy = dir * t * float(strength) / 10.0;
      vec2 uv = tc + xy;
      matt = step(roi.x, uv.x);
      uv.x = mix(roi.x * 2.0 - uv.x,uv.x,matt);
      matt = step(roi.x + roi.z,uv.x);
      uv.x = mix(uv.x,(roi.x + roi.z) * 2.0 - uv.x,matt);
      retCol += INPUT1(uv);
    }	
    retCol /= float(radius);
    matt = step(roi.x,tc.x)*step(tc.x,roi.x + roi.z + onePixel.x);
    retCol *= matt;

    return retCol;
}
float easeOutCubic(float x) {
  return 1.0 - pow(1.0 - x, 3.0);
}
float easeOutQuint(float x) {
  return 1.0 - pow(1.0 - x, 5.0);
}
vec4 lut3DFilter(vec4 textureColor, float opacity){
  float blueColor = textureColor.r * 63.0;
  vec2 quad1;
  quad1.y = floor(floor(blueColor) / 8.0);
  quad1.x = floor(blueColor) - (quad1.y * 8.0);
  vec2 quad2;
  quad2.y = floor(ceil(blueColor) /8.0);
  quad2.x = ceil(blueColor) - (quad2.y * 8.0);
  vec2 texPos1;
  texPos1.x = (quad1.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
  texPos1.y = (quad1.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
  vec2 texPos2;
  texPos2.x = (quad2.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
  texPos2.y = (quad2.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
  vec4 newColor1 = INPUT3(texPos1);
  vec4 newColor2 = INPUT3(texPos2);
  vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
  vec4 fragOutCol = vec4(mix(textureColor.rgb, newColor.rgb, opacity), textureColor.a);
  fragOutCol.rgb *= fragOutCol.a;
  return fragOutCol;
}


float rnd(vec3 scale, float seed, vec3 uv) {
