    }
    float Speed = 1.0 ;
    vec2 offset = vec2(0.5);
    vec2 uv = tc * prop ;
    vec4 resColor = vec4(0.0, 0.0, 0.0, 1.0);
    float anim1 = time*Speed;
    float scale = clamp(1.0 + (animcurve(time))*Speed,1.0,2.0) ;

    // image1
    vec2 image1Offset = vec2(0.5,0.5);
    image1Offset -= offset;
    vec2 uv1 = (uv - image1Offset) / prop ;
    uv1-=offset;
    uv1 *=2.0;
    uv1 += offset;
    vec4 input1 = INPUT1(uv1);
    resColor = mixImage(resColor, input1, uv1, image1Offset, prop);

    // image2
    vec2 image2Offset = vec2(-0.25, 0.75);
    image2Offset *= prop;
    vec2 uv2 =(uv-image2Offset)/prop;
    uv2 /=2.0;
    uv2 *= scale;
    vec4 input2 = INPUT1(uv2);
    resColor = mixImage(resColor, input2, uv,  image2Offset, prop);

    // image3
    vec2 image3Offset = vec2(-0.75, -0.25) ;
    image3Offset.y = clamp (image3Offset.y - anim1/4.0, -0.25,0.0 );
    image3Offset *= prop;
    vec2 uv3 = (uv-image3Offset)/prop;
    vec4 input3 = INPUT1(uv3);
    resColor = mixImage(resColor, input3, uv,  image3Offset, prop);

    // image4
    vec2 image4Offset = vec2(0.25, -0.75) ;
    if (time > 0.5){
        image4Offset.x += clamp((0.75 - animcurve(time))*Speed,0.0,0.5);
    }
    image4Offset *= prop;
    vec2 uv4 = (uv-image4Offset)/prop;
    uv4 /=2.0;
    uv4 *= scale;
    vec4 input4 = INPUT2(uv4);
    resColor = mixImage(resColor, input4, uv,  image4Offset, prop);

    // image5
    vec2 image5Offset = vec2(0.75, 0.25);
    image5Offset *= prop;
    vec2 uv5 = (uv-image5Offset)/prop;
    vec4 input5 = INPUT2(uv5);
    resColor = mixImage(resColor, input5, uv,  image5Offset, prop);

    return resColor;
}
