bool checkUvRange(float x) {
    float absX = abs(x);
    float floorX = floor(absX);
    bool modX = mod(floorX, 2.0) == 0.0;
    return x > 0.0 ? !modX : modX;
}

float customCurve(float x){
	if(x < 0.25){
      return 16.0 * pow(x, 3.0);
  }else if(x < 0.5){
      return 0.5 - 16.0 * pow(0.5 - x, 3.0);
  }else{
    //float v = mix(0.5, 1.0, (x-0.5)*6.0);
    //return clamp(v, 0.5, 1.0);
    float v = 0.5 - 8.0 * pow(0.5 - x, 3.0);
    return clamp(v, 0.5, 1.0);
  }
}

vec4 lut3DFilter(vec4 textureColor, float opacity){
  float blueColor = textureColor.r * 63.0;
  vec2 quad1;
  quad1.y = floor(floor(blueColor) / 8.0);
  quad1.x = floor(blueColor) - (quad1.y * 8.0);
  vec2 quad2;
  quad2.y = floor(ceil(blueColor) /8.0);
  quad2.x = ceil(blueColor) - (quad2.y * 8.0);
  vec2 texPos1;
  texPos1.x = (quad1.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
  texPos1.y = (quad1.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
  vec2 texPos2;
  texPos2.x = (quad2.x * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.b);
  texPos2.y = (quad2.y * 1.0/8.0) + 0.5/512.0 + ((1.0/8.0 - 1.0/512.0) * textureColor.g);
  vec4 newColor1 = INPUT3(texPos1);
  vec4 newColor2 = INPUT3(texPos2);
  vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
  vec4 fragOutCol = vec4(mix(textureColor.rgb, newColor.rgb, opacity), textureColor.a);
  fragOutCol.rgb *= fragOutCol.a;
  return fragOutCol;
}

//中间
vec4 sampleMiddleArea(vec2 uv) {
  vec4 retColor = vec4(0.0);
  if (uv.y >= 0.0 && uv.y <= 1.0) {
    if (uv.x >= -2.0 && uv.x <= -1.0) {
      retColor = INPUT2(uv);
    } else if (uv.x >= 0.0 && uv.x <= 1.0) {
      retColor = INPUT1(uv);
    }
  }
  return retColor;
}

//上部
vec4 sampleTopArea(vec2 uv) {
  vec4 retColor = vec4(0.0, 0.0, 0.0, 0.0);
  if(uv.y <= 2.0 && uv.y >= 1.0){
    uv.y = 1.0 - uv.y;
    uv.x = checkUvRange(uv.x) ? 1.0 - uv.x : uv.x;
    retColor = INPUT1(uv);
    retColor = lut3DFilter(retColor, 1.0);
  }
  return retColor;
}

//下部
vec4 sampleBottomArea(vec2 uv) {
  vec4 retColor = vec4(0.0, 0.0, 0.0, 0.0);
  if(uv.y <= 0.0 && uv.y >= -1.0){
    uv.y = 1.0 - uv.y;
    uv.x = checkUvRange(uv.x) ? 1.0 - uv.x : uv.x;
    retColor = INPUT1(uv);
    retColor = lut3DFilter(retColor, 1.0);
  }
  return retColor;
}

