float sdHeart(in vec2 p)
{
    return p.x*p.x+pow((p.y+1.5-2.3*sqrt(abs(p.x))),2.);
}

vec4 blur(vec2 uv, float blurSize, float heartIns, float lightIns)
{
    float amount = 40.0 + 0.9987 * 500.0;
    vec4 oriCol = INPUT1(uv);
    vec3 maxCol = oriCol.rgb;

    vec3 bokeh = pow(oriCol.rgb,vec3(9.0)) * amount+.4;
    vec3 sumCol= bokeh*oriCol.rgb;
    vec3 sumWeight = vec3(0.0);
    vec2 unitUV = vec2(1.35, 1.0) * vec2(blurSize) / iResolution;

    float myStep = 9.0 / 170.0;
    float i, j;

    // Loop optimization
    for (i = -9.0; i < 9.0; i += 1.5) {
        for (j = -8.0; j < 11.0; j += 1.5) {
            vec2 tempVec = vec2(i, j);
            float sdHeartVal = sdHeart(tempVec);
            if (sdHeartVal > 75.0 * heartIns) {
                continue;
            }
            vec2 offset = 0.5 * vec2(i, j) * unitUV;
            vec3 tempCol = INPUT1(uv - offset).rgb;
            maxCol = max(maxCol, tempCol);
            bokeh = pow(tempCol, vec3(9.0)) * amount + 0.4;
            sumCol += bokeh * tempCol;
            sumWeight += bokeh;
        }
    }

    // Additional optimizations
    float heartIns75 = 75.0 * heartIns;
    float sqrtVal;
    for (i = -9.0; i < 9.0; i += 1.5) {
        if (heartIns75 - i * i < 0.0) {
            continue;
        }
        sqrtVal = sqrt(heartIns75 - i * i) - 1.5 + 2.3 * sqrt(abs(i));
        for (j = -8.0; j < 11.0; j += 1.5) {
            vec2 tempVec = vec2(i, j);
            if (sdHeart(tempVec) > heartIns75) {
                continue;
            }
            vec2 offset = 0.5 * vec2(i, j) * unitUV;
            vec3 tempCol = INPUT1(uv - offset).rgb;
            maxCol = max(maxCol, tempCol);
            bokeh = pow(tempCol, vec3(9.0)) * amount + 0.4;
            sumCol += bokeh * tempCol;
            sumWeight += bokeh;
        }
    }

    vec3 resultCol = clamp(sumCol / sumWeight, 0.0, 1.0);
    return vec4(mix(resultCol, maxCol, clamp(resultCol * lightIns, 0.0, 1.0)), oriCol.a);
}

