// Horizontal Cutout 1
// Vertical Cutout 1 的水平变体（基准 2s / 60 帧，进度 p∈[0,1]）：
//   0~10  : 仅 A
//   10~40 : 5 条水平带等间隔出现，顺序 3-2-4-1-5（上→下编号 1..5；带宽 12%、间距 3%）
//         初始宽：1/5=40%，2/4=55%，3=70%
//   40~50 : 自外侧向中间左右拉长至 80%；中间完成时间距收为 0，露出缩小 B
//   50~60 : B 放大至原尺寸完成转场
// 阴影：每块同形偏右下 + 图层像素模糊（同 Vertical Cutout 1 / Glass Panel Flash）
//
// CapCut 源：matte 序列抠切 + B@70% 叠 A，约 1.5s 起无遮罩层 70→100 放大；
// 此处沿用 Vertical Cutout 1 的程序化时序与 80% 收束比例，仅将条带轴改为水平。
//
// Pass：uStep=0 硬阴影 → FBO；uStep=1 模糊阴影 + 合成

const float kStripCount = 5.0;
const float kStripW0 = 0.12;
const float kGapW0 = 0.02;
// 编号 1..5（上→下）初始宽度：1/5=40%，2/4=55%，3=70%；最终均拉长到 80%
const float kBaseW1 = 0.40;
const float kBaseW2 = 0.55;
const float kBaseW3 = 0.70;
const float kFinalW = 0.80;
const float kShadowDistNorm = 0.008;
const float kShadowBlurPx = 15.0;
const vec3 kShadowColor = vec3(0.28, 0.28, 0.28);
const float kShadowOpacity = 0.5;

// 60 帧归一化节点
const float kP10 = 10.0 / 60.0;
const float kP40 = 40.0 / 60.0;
const float kP50 = 50.0 / 60.0;

float saturate01(float x)
{
    return clamp(x, 0.0, 1.0);
}

float remap01(float a, float b, float v)
{
    return saturate01((v - a) / max(b - a, 1e-5));
}

float smooth01(float t)
{
    float x = saturate01(t);
    return x * x * (3.0 - 2.0 * x);
}

float inBound01(vec2 uv)
{
    vec2 bl = step(vec2(0.0), uv);
    vec2 tr = step(uv, vec2(1.0));
    return bl.x * bl.y * tr.x * tr.y;
}

vec2 scaleFromCenter(vec2 tc, float iscale)
{
    return vec2(0.5) + (tc - vec2(0.5)) / max(iscale, 1e-5);
}

vec4 sampleScaled(vec2 tc, float iscale)
{
    vec2 uv = scaleFromCenter(tc, iscale);
    return INPUT2(clamp(uv, vec2(0.0), vec2(1.0)));
}

// idx 0..4 = 条带 1..5（上→下）；出现顺序 3-2-4-1-5
int appearOrderRank(int idx)
{
    if (idx == 2) return 0; // 3
    if (idx == 1) return 1; // 2
    if (idx == 3) return 2; // 4
    if (idx == 0) return 3; // 1
    return 4;               // 5
}

float stripAppearP(int idx)
{
    float stepT = (kP40 - kP10) / kStripCount;
    return kP10 + float(appearOrderRank(idx)) * stepT;
}

float stripBaseW(int idx)
{
    if (idx == 0 || idx == 4) return kBaseW1; // 1、5
    if (idx == 1 || idx == 3) return kBaseW2; // 2、4
    return kBaseW3;                           // 3
}

// 40~50：外侧先拉长，再向中间；dist=|idx-2| → 2,1,0 三段等分
float stripExtendT(int idx, float p)
{
    float extendP = remap01(kP40, kP50, p);
    float dist = abs(float(idx) - 2.0);
    float seg = 1.0 / 3.0;
    float t0 = (2.0 - dist) * seg;
    float t1 = (3.0 - dist) * seg;
    return smooth01(remap01(t0, t1, extendP));
}

float stripWidth(int idx, float p)
{
    float baseW = stripBaseW(idx);
    if (p < stripAppearP(idx)) {
        return 0.0;
    }
    if (p < kP40) {
        return baseW;
    }
    float e = stripExtendT(idx, p);
    return mix(baseW, kFinalW, e);
}

// 中间条拉长接近完成时，间距 3%→0，带宽均分填满组高
void layoutParams(float p, out float stripH, out float gapH, out float totalH)
{
    float groupH0 = kStripCount * kStripW0 + (kStripCount - 1.0) * kGapW0;
    float gapClose = 0.0;
    if (p >= kP40) {
        float centerT = stripExtendT(2, p);
        gapClose = smooth01(centerT);
    }
    if (p >= kP50) {
        gapClose = 1.0;
    }
    gapH = mix(kGapW0, 0.0, gapClose);
    stripH = (groupH0 - (kStripCount - 1.0) * gapH) / kStripCount;
    totalH = groupH0;
}

float proceduralMatte(vec2 tc, float p)
{
    if (p < kP10) {
        return 0.0;
    }

    float stripH;
    float gapH;
    float totalH;
    layoutParams(p, stripH, gapH, totalH);

    float groupT = 0.5 - 0.5 * totalH;
    float pitch = stripH + gapH;

    // 沿 Y 划分水平条带（相对 Vertical 的 X 轴布局）
    float local = (tc.y - groupT) / max(pitch, 1e-5);
    float idxF = floor(local);
    float inStrip = local - idxF;
    float stripFrac = stripH / max(pitch, 1e-5);
    float inBand = step(0.0, idxF) * step(idxF, kStripCount - 1.0)
                 * step(0.0, inStrip) * step(inStrip, stripFrac + 1e-4);
    if (inBand < 0.5) {
        return 0.0;
    }

    int idx = int(idxF);
    float w = stripWidth(idx, p);
    if (w <= 1e-4) {
        return 0.0;
    }

    if (p >= kP50) {
        w = kFinalW;
    }

    float x0 = 0.5 - 0.5 * w;
    float x1 = 0.5 + 0.5 * w;
    vec2 aa = 1.5 / max(iResolution.xy, vec2(1.0));
    float mx = smoothstep(x0 - aa.x, x0 + aa.x, tc.x) * (1.0 - smoothstep(x1 - aa.x, x1 + aa.x, tc.x));
    return mx;
}

float cutoutScale()
{
    float groupH0 = kStripCount * kStripW0 + (kStripCount - 1.0) * kGapW0;
    return max(0.80, groupH0);
}

vec2 shadowOffsetUv()
{
    vec2 res = max(iResolution.xy, vec2(1.0));
    float distPx = kShadowDistNorm * min(res.x, res.y);
    return vec2(distPx / res.x, -distPx / res.y);
}

// [@pass:uStep=0] 阴影图层（条带阶段）
vec4 featureShadowLayer(vec2 tc)
{
    float p = PREFIX(iProgress);
    if (p < kP10 || p >= kP50) {
        return vec4(0.0);
    }
    float hard = proceduralMatte(tc - shadowOffsetUv(), p);
    return vec4(kShadowColor * hard, hard);
}

vec4 blurShadowLayer(vec2 tc)
{
    vec2 texel = 1.0 / max(iResolution.xy, vec2(1.0));
    float sigma = max(kShadowBlurPx / 3.0, 1e-4);
    float stepPx = kShadowBlurPx / 5.0;
    vec4 sum = vec4(0.0);
    float wSum = 0.0;
    for (int iy = -5; iy <= 5; iy++) {
        for (int ix = -5; ix <= 5; ix++) {
            vec2 dPx = vec2(float(ix), float(iy)) * stepPx;
            float w = exp(-0.5 * dot(dPx, dPx) / (sigma * sigma));
            // [@说明:通道绑定] INPUT3 = uStep=0 阴影 FBO
            sum += INPUT3(tc + dPx * texel) * w;
            wSum += w;
        }
    }
    return sum / max(wSum, 1e-5);
}

// [@pass:uStep=1] 主合成
vec4 featureMain(vec2 tc)
{
    float p = PREFIX(iProgress);
    vec4 colorA = INPUT1(tc);

    // [@规则:R-T05]
    if (p <= 0.0) {
        return colorA;
    }
    if (p >= 1.0) {
        return INPUT2(tc);
    }

    // 0~10：仅 A
    if (p < kP10) {
        return colorA;
    }

    float bScale0 = cutoutScale();
    vec4 result = colorA;

    // 10~50：水平条带 / 收缝后的缩小 B
    if (p < kP50) {
        float matte = clamp(proceduralMatte(tc, p), 0.0, 1.0);
        vec4 shadowSample = blurShadowLayer(tc);
        float shadowA = clamp(shadowSample.a * (1.0 - matte) * kShadowOpacity, 0.0, 1.0);
        result.rgb = result.rgb * (1.0 - shadowA) + kShadowColor * shadowA;
        vec4 colorBCutout = sampleScaled(tc, bScale0);
        result = mix(result, colorBCutout, matte);
        return result;
    }

    // 50~60：B 从缩小尺寸放大到 1.0
    float t = smooth01(remap01(kP50, 1.0, p));
    float bScale = mix(bScale0, 1.0, t);
    float cover = inBound01(scaleFromCenter(tc, bScale));
    vec4 colorB = sampleScaled(tc, bScale);
    return mix(colorA, colorB, cover);
}

vec4 FUNCNAME(vec2 tc)
{
    int uStep = PREFIX(uStep);
    if (uStep == 0) {
        return featureShadowLayer(tc);
    }
    return featureMain(tc);
}

vec4 directionBlur(vec2 tc, float angle, int strength) {
    int radius = 2 * strength + 1;
    float theta = radians(angle);  
    vec2 dir = vec2(cos(theta), sin(theta));
    vec4 color = INPUT1(tc);
	vec4 retCol = vec4(0.0);
    vec2 onePixel = 1.0 / iResolution.xy; 
    vec4 roi = PREFIX(orig_roi);
	float matt = 0.0;

	for (int i = -strength; i <= strength; i++){
		vec2 t = vec2(i) * onePixel;
        vec2 xy = dir * t;
		vec2 uv = tc + xy;

		matt = step(roi.x, uv.x);
		uv.x = mix(roi.x * 2.0 - uv.x,uv.x,matt);

		matt = step(roi.x + roi.z,uv.x);
		uv.x = mix(uv.x,(roi.x + roi.z) * 2.0 - uv.x,matt);

		retCol += INPUT1(uv);
	}	

	retCol /= float(radius);

	matt = step(roi.x,tc.x)*step(tc.x,roi.x + roi.z + onePixel.x);
	retCol *= matt;
	return retCol;
}

vec4 split(vec2 tc,float progress) {
    vec4 sum = vec4(0.0);
    if(progress < 0.5){
        progress *= 1.8;
        if(tc.y < 0.5){
            tc.x += progress*(1.0-tc.x);    //A 下面的图像
        }else{
            tc.x -= progress*tc.x;          //A 上面的图像
        }
        sum = INPUT1(tc);
    }else{
        if(tc.y < 0.5){
            tc.x -= (1.0-progress)*(1.0-tc.x);   //B 下面的图像
        }else{
            tc.x += (1.0-progress)*tc.x;      //B 上面的图像
        }
        sum = INPUT2(tc);
    }
    return sum;
}

