const float IP_PI = 3.14159265358979323846;

float ipSaturate(float value) {
    return clamp(value, 0.0, 1.0);
}

float ipBezierCoord(float t, float p1, float p2) {
    float omt = 1.0 - t;
    return 3.0 * omt * omt * t * p1 + 3.0 * omt * t * t * p2 + t * t * t;
}

float ipBezierSlope(float t, float p1, float p2) {
    float omt = 1.0 - t;
    return 3.0 * omt * omt * p1 + 6.0 * omt * t * (p2 - p1) + 3.0 * t * t * (1.0 - p2);
}

float ipKeySpline(vec4 curve, float linearT) {
    float x = ipSaturate(linearT);
    float guess = x;
    for (int i = 0; i < 6; i++) {
        float slope = ipBezierSlope(guess, curve.x, curve.z);
        if (abs(slope) > 0.00001) {
            guess -= (ipBezierCoord(guess, curve.x, curve.z) - x) / slope;
        }
        guess = ipSaturate(guess);
    }
    return ipBezierCoord(guess, curve.y, curve.w);
}

float ipSegment(float timeSec, float startSec, float endSec, vec4 curve) {
    float linearT = ipSaturate((timeSec - startSec) / max(endSec - startSec, 0.0001));
    return ipKeySpline(curve, linearT);
}

vec3 ipRotateX(vec3 point, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(point.x, c * point.y - s * point.z, s * point.y + c * point.z);
}

vec3 ipRotateY(vec3 point, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(c * point.x + s * point.z, point.y, -s * point.x + c * point.z);
}

vec3 ipRotateZ(vec3 point, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(c * point.x - s * point.y, s * point.x + c * point.y, point.z);
}

// 源 MotionBlur3D 的 AE 轴顺序：X、-Y、-Z。
vec3 ipRotateAe(vec3 point, vec3 degreesValue) {
    vec3 radiansValue = degreesValue * (IP_PI / 180.0);
    point = ipRotateX(point, radiansValue.x);
    point = ipRotateY(point, -radiansValue.y);
    return ipRotateZ(point, -radiansValue.z);
}

vec3 ipInverseRotateAe(vec3 point, vec3 degreesValue) {
    vec3 radiansValue = degreesValue * (IP_PI / 180.0);
    point = ipRotateZ(point, radiansValue.z);
    point = ipRotateY(point, radiansValue.y);
    return ipRotateX(point, -radiansValue.x);
}

void ipTransformA(float timeSec, out vec3 position, out vec3 pivot, out vec3 direction) {
    vec4 easeNear = vec4(0.333333, 0.0, 0.0, 1.0);
    vec4 easeFar = vec4(0.925873, 0.0, 0.666667, 1.0);
    float nearT = ipSegment(timeSec, 0.0, 0.466667, easeNear);
    float farT = ipSegment(timeSec, 0.466667, 1.033333, easeFar);
    position = mix(vec3(0.5, 0.5, 0.0), vec3(0.5, 0.5, 0.7666667), nearT);
    if (timeSec > 0.466667) {
        position = mix(vec3(0.5, 0.5, 0.7666667), vec3(-1.359375, 1.4444444, 3.4518519), farT);
    }

    float pivotT = ipSegment(timeSec, 0.0, 0.466667, vec4(0.166667, 0.166667, 0.666667, 1.0));
    pivot = mix(vec3(0.5, 0.5, 0.0), vec3(0.5, 0.5, -1.75), pivotT);

    float dirX = mix(0.0, 18.4, ipSegment(timeSec, 0.0, 0.566667, vec4(0.333333, 0.0, 0.666667, 1.0)));
    float dirY = mix(0.0, -20.2, ipSegment(timeSec, 0.0, 0.666667, vec4(0.333333, 0.0, 0.666667, 1.0)));
    float dirZ = mix(0.0, -9.4, ipSegment(timeSec, 0.0, 0.3, vec4(0.300431, 0.0, 0.702403, 1.0)));
    if (timeSec > 0.3) {
        dirZ = mix(-9.4, 0.0, ipSegment(timeSec, 0.3, 0.8, vec4(0.427965, 0.0, 0.78398, 1.0)));
    }
    direction = vec3(dirX, dirY, dirZ);
}

void ipTransformB(float timeSec, out vec3 position, out vec3 pivot, out vec3 direction) {
    vec4 easeMove = vec4(0.333333, 0.0, 0.0, 1.0);
    vec4 easeHome = vec4(0.333333, 0.0, 0.666667, 1.0);
    float moveT = ipSegment(timeSec, 0.133333, 0.666667, easeMove);
    float homeT = ipSegment(timeSec, 0.666667, 1.466667, easeHome);
    position = mix(vec3(1.65625, -0.787037, 1.7962963), vec3(0.7610379, 0.2094353, 1.2851659), moveT);
    if (timeSec > 0.666667) {
        position = mix(vec3(0.7610379, 0.2094353, 1.2851659), vec3(0.5, 0.5, 0.0), homeT);
    }
    pivot = vec3(0.5, 0.5, 0.0);

    float dirX = mix(-17.0, 0.0, ipSegment(timeSec, 0.4, 1.233333, vec4(0.333333, 0.0, 0.833333, 1.0)));
    float dirY = mix(-49.0, 24.1, ipSegment(timeSec, 0.133333, 0.666667, vec4(0.166667, 0.0, 0.0, 1.0)));
    if (timeSec > 0.666667) {
        dirY = mix(24.1, 0.0, ipSegment(timeSec, 0.666667, 1.4, easeHome));
    }
    float dirZ = mix(-4.0, 10.4, ipSegment(timeSec, 0.133333, 0.666667, vec4(0.166667, 0.0, 0.0, 1.0)));
    if (timeSec > 0.666667) {
        dirZ = mix(10.4, 0.0, ipSegment(timeSec, 0.666667, 1.366667, easeHome));
    }
    direction = vec3(dirX, dirY, dirZ);
}

// [@特性:3D] 复现源 MotionBlur3D 的相机、父节点位置、Pivot 与 AE 三轴旋转。
vec3 ipPanelUv(vec2 tc, vec3 position, vec3 pivot, vec3 direction) {
    float aspect = iResolution.x / max(iResolution.y, 1.0);
    float tanHalfFovX = tan(19.8 * IP_PI / 180.0);
    float cameraDistance = aspect / tanHalfFovX;
    float ratioZ = (1920.0 / 1080.0) / aspect;
    vec2 ndc = tc * 2.0 - vec2(1.0);
    vec3 rayDirection = normalize(vec3(ndc.x * tanHalfFovX, ndc.y * tanHalfFovX / aspect, -1.0));

    vec3 fatherPosition = vec3(
        (position.x - 0.5) * 2.0 * aspect,
        (position.y - 0.5) * 2.0,
        -cameraDistance - position.z * 2.0 / ratioZ
    );
    vec3 childPosition = vec3(
        -(pivot.x - 0.5) * 2.0 * aspect,
        -(pivot.y - 0.5) * 2.0,
        pivot.z * 2.0 / ratioZ
    );
    vec3 planeCenter = fatherPosition + ipRotateAe(childPosition, direction);
    vec3 planeNormal = ipRotateAe(vec3(0.0, 0.0, 1.0), direction);
    float denominator = dot(planeNormal, rayDirection);
    if (abs(denominator) < 0.00001) {
        return vec3(-2.0, -2.0, 0.0);
    }
    float hitDistance = dot(planeNormal, planeCenter) / denominator;
    if (hitDistance <= 0.0) {
        return vec3(-2.0, -2.0, 0.0);
    }
    vec3 worldPoint = rayDirection * hitDistance;
    vec3 localPoint = ipInverseRotateAe(worldPoint - fatherPosition, direction) - childPosition;
    vec2 uv = vec2(localPoint.x / aspect, localPoint.y) * 0.5 + vec2(0.5);
    float inside = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
    return vec3(uv.x, uv.y, inside);
}

vec4 ipReadA(vec2 uv, float blurRadius) {
    vec2 pixel = 1.0 / iResolution.xy;
    vec2 radius = pixel * blurRadius;
    vec4 color = INPUT1(uv) * 0.32;
    color += INPUT1(uv + vec2(radius.x, 0.0)) * 0.17;
    color += INPUT1(uv - vec2(radius.x, 0.0)) * 0.17;
    color += INPUT1(uv + vec2(0.0, radius.y)) * 0.17;
    color += INPUT1(uv - vec2(0.0, radius.y)) * 0.17;
    return color;
}

vec4 ipReadB(vec2 uv) {
    return INPUT2(uv);
}

vec4 ipOver(vec4 top, vec4 bottom) {
    vec3 rgb = top.rgb * top.a + bottom.rgb * bottom.a * (1.0 - top.a);
    float alpha = top.a + bottom.a * (1.0 - top.a);
    return vec4(rgb.r, rgb.g, rgb.b, alpha);
}

vec4 FUNCNAME(vec2 tc) {
    float progress = ipSaturate(PREFIX(iProgress));
    // [@规则:R-T05] 硬闭合端点，避免运动模糊采样污染 A/B 纯端点。
    if (progress <= 0.000001) return INPUT1(tc);
    if (progress >= 0.999999) return INPUT2(tc);

    float timeSec = progress * 2.0;
    vec4 accum = vec4(0.0);
    const int sampleCount = 8;
    for (int sampleIndex = 0; sampleIndex < sampleCount; sampleIndex++) {
        float sampleOffset = (float(sampleIndex) - 3.5) * 0.006;
        float sampleTime = clamp(timeSec + sampleOffset, 0.0, 2.0);

        vec3 positionA;
        vec3 pivotA;
        vec3 directionA;
        ipTransformA(sampleTime, positionA, pivotA, directionA);
        vec3 uvA = ipPanelUv(tc, positionA, pivotA, directionA);
        float visibleA = uvA.z * (1.0 - step(1.033333, sampleTime));
        float blurRamp = smoothstep(0.3, 0.6, sampleTime);
        vec4 colorA = ipReadA(clamp(uvA.xy, vec2(0.0), vec2(1.0)), 18.0 * blurRamp);
        colorA.a *= visibleA;

        vec3 positionB;
        vec3 pivotB;
        vec3 directionB;
        ipTransformB(sampleTime, positionB, pivotB, directionB);
        vec3 uvB = ipPanelUv(tc, positionB, pivotB, directionB);
        vec4 colorB = ipReadB(clamp(uvB.xy, vec2(0.0), vec2(1.0)));
        colorB.a *= uvB.z;

        vec4 frameColor = ipOver(colorB, colorA);
        accum += frameColor;
    }
    float sampleScale = 1.0 / float(sampleCount);
    return vec4(accum.r * sampleScale, accum.g * sampleScale, accum.b * sampleScale, 1.0);
}

