vec4 invertedStrobe(vec2 tc, float progress)
{
    const float burstPeak = 0.4;
    const float glowIntensity = 0.5;
    const float chromaticAmount = 0.05;
    const float shakeAmplitude = 0.01;
    const float prismStrength = 0.01;
    const float flickerFrequency = 20.0;

    float aspect = iResolution.x / max(iResolution.y, 1.0);
    float burstPhase = clamp(progress / burstPeak, 0.0, 1.0);
    float recoverPhase = clamp((progress - burstPeak) / (1.0 - burstPeak), 0.0, 1.0);
    float burstIntensity = burstPhase;
    float recoverIntensity = 1.0 - pow(recoverPhase, 3.0) *
        (1.0 + sin(recoverPhase * 12.0) * 0.15);
    float afterPeak = step(burstPeak, progress);
    float effectIntensity = mix(burstIntensity, recoverIntensity, afterPeak);

    float shakeFreq = flickerFrequency * mix(1.0, 3.5, effectIntensity);
    vec2 shakeOffset = vec2(
        sin(progress * shakeFreq) * shakeAmplitude * effectIntensity,
        cos(progress * shakeFreq) * shakeAmplitude * effectIntensity / aspect
    );
    vec2 uv = clampUV(tc + shakeOffset);

    vec2 chromaOffset = chromaticAmount * effectIntensity * vec2(1.0, 1.0 / aspect);
    vec4 centerA = sampleA(uv);
    vec4 chromaA = vec4(
        sampleA(uv + chromaOffset).r,
        centerA.g,
        sampleA(uv - chromaOffset).b,
        centerA.a
    );

    float brightness = dot(chromaA.rgb, vec3(0.299, 0.587, 0.114));
    vec2 prismOffset = prismStrength * effectIntensity * brightness *
        vec2(1.0, 1.0 / aspect);
    vec4 prismA = vec4(
        sampleA(uv + prismOffset * 0.4).r,
        chromaA.g,
        sampleA(uv - prismOffset * 0.4).b,
        chromaA.a
    );

    vec2 glowStep = vec2(0.005, 0.005 / aspect) * effectIntensity;
    vec4 glow = (sampleA(uv - glowStep) + sampleA(uv + glowStep)) *
        (0.5 * glowIntensity * effectIntensity);
    vec4 effectedA = prismA + glow;
    float flicker = 1.0 + sin(progress * flickerFrequency * 2.5) *
        0.25 * effectIntensity;
    effectedA.rgb *= flicker;

    vec4 effectedB = sampleB(uv);
    effectedA.rgb = mix(effectedA.rgb, vec3(1.0) - effectedA.rgb, afterPeak);
    effectedB.rgb = mix(effectedB.rgb, vec3(1.0) - effectedB.rgb, afterPeak);

    float blendFactor = afterPeak * smoothstep(0.0, 1.0, recoverPhase);
    vec4 result = mix(effectedA, effectedB, blendFactor);

    // 方案 A：反相复位拉到恢复段后 30%，中点用白闪抬过中灰，
    // 负片 → 白闪 → 正片 B，避免灰闪后硬切原图。
    float resetNegative = smoothstep(0.70, 1.0, recoverPhase);
    vec3 restored = mix(result.rgb, vec3(1.0) - result.rgb, resetNegative);
    float strobeFlash = smoothstep(0.70, 0.85, recoverPhase) *
        (1.0 - smoothstep(0.88, 1.0, recoverPhase));
    result.rgb = mix(restored, vec3(1.0), strobeFlash * 0.8);
    result.rgb = clamp(result.rgb, vec3(0.0), vec3(1.0));

    return result;
}

vec4 FUNCNAME(vec2 tc)
{
    float timelineProgress = clamp(PREFIX(iProgress), 0.0, 1.0);

    // 前 15% 保持 A；效果跑到片尾，复位与白闪叠在 B 的显现上，不再冻帧。
    float effectProgress = clamp((timelineProgress - 0.15) / 0.85, 0.0, 1.0);

    // [@规则:R-T05] 严格闭合转场端点。
    if (timelineProgress <= 0.0) return INPUT1(tc);
    if (timelineProgress >= 1.0) return INPUT2(tc);
    if (effectProgress <= 0.0) return INPUT1(tc);

    return invertedStrobe(tc, effectProgress);
}

