float laserRand(vec2 co)
{
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

// 源 Tween：0~15% 保持 A；15%~50% 推进到中点；50%~85% 推进到 B；末段保持 B。
float laserTimeline(float p)
{
    if (p <= 0.15) {
        return 0.0;
    }
    if (p < 0.5) {
        return 0.5 * (p - 0.15) / 0.35;
    }
    if (p < 0.85) {
        return 0.5 + 0.5 * (p - 0.5) / 0.35;
    }
    return 1.0;
}

vec4 laserWeb(vec2 tc, vec4 colorA, vec4 colorB, float progress)
{
    // 源 shader 的 ratio 始终保持默认 1.0；随机方向光带在中心汇聚后向外消散。
    vec2 uv = tc;
    float anim = progress < 0.5 ? progress * 2.0 : 2.0 * (1.0 - progress);
    float grain = laserRand(uv * 100.0 + vec2(progress, progress)) * PREFIX(grainStrength);

    float totalMask = 0.0;
    vec3 lightColor = vec3(0.0);
    float count = PREFIX(stripCount);
    float width = PREFIX(stripWidth);
    float wear = PREFIX(edgeWear);
    vec3 orangeColor = vec3(1.0, 0.35, 0.1);
    vec3 cyanColor = vec3(0.1, 0.75, 0.85);

    for (int i = 0; i < 24; i++) {
        float fi = float(i);
        if (fi >= count) {
            break;
        }

        float randVal = laserRand(vec2(fi, fi * 3.7));
        float angle = randVal * 6.28318;
        float isOrange = step(0.5, randVal);
        float speedOffset = 0.5 + laserRand(vec2(fi * 2.3, fi * 5.1)) * 0.5;
        float widthOffset = 0.8 + laserRand(vec2(fi * 7.2, fi * 1.9)) * 0.4;
        vec2 dir = vec2(cos(angle), sin(angle));
        float pos = mix(-1.0, 0.5, anim * speedOffset);
        float dist = dot(uv - vec2(0.5, 0.5), dir) - pos;

        float noise = (laserRand(uv * 20.0 + vec2(fi, 0.0)) - 0.5) * wear * 0.2;
        float stripEdge = max(width * widthOffset * 0.5 + noise, 0.0001);
        float stripMask = 1.0 - smoothstep(0.0, stripEdge, abs(dist));
        totalMask += stripMask;

        vec3 stripColor = mix(cyanColor, orangeColor, isOrange);
        lightColor += stripColor * stripMask * (0.6 + randVal * 0.4);
    }

    totalMask = clamp(totalMask, 0.0, 1.0);
    lightColor = clamp(lightColor, vec3(0.0), vec3(1.2));

    float centerPeak = smoothstep(0.3, 0.5, anim) * (1.0 - smoothstep(0.5, 0.7, anim));
    lightColor += vec3(1.0, 0.9, 0.8) * centerPeak * 0.8;
    totalMask = max(totalMask, centerPeak * 0.9);
    lightColor += vec3(grain) * totalMask;

    vec4 baseColor = progress < 0.5 ? colorA : colorB;
    vec3 fadedBase = mix(baseColor.rgb, vec3(0.9), totalMask * 0.7);
    vec3 finalRgb = mix(fadedBase, lightColor, totalMask * 0.8);
    return vec4(finalRgb, baseColor.a);
}

vec4 FUNCNAME(vec2 tc)
{
    float p = clamp(PREFIX(iProgress), 0.0, 1.0);
    vec4 colorA = INPUT1(tc);
    vec4 colorB = INPUT2(tc);

    float effectProgress = laserTimeline(p);
    float transitionProgress = clamp((effectProgress - 0.1) / 0.8, 0.0, 1.0);
    vec4 webColor = laserWeb(tc, colorA, colorB, transitionProgress);
    float blendIn = smoothstep(0.0, 0.1, effectProgress);
    float blendOut = smoothstep(0.9, 1.0, effectProgress);
    vec4 finalColor = mix(colorA, webColor, blendIn);
    finalColor = mix(finalColor, colorB, blendOut);

    // [@规则:R-T05] p=0 精确返回 A；p=1 精确返回 B。
    if (p <= 0.0) {
        return colorA;
    }
    if (p >= 1.0) {
        return colorB;
    }
    return finalColor;
}

#define PI 3.1415926

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

/*
 * @param aX: 传入时间变量
 * @param p1/p2: 贝塞尔曲线两个控制点
 * 说明: 这个函数以上的其他函数都是本函数使用的辅助函数
 */
float KeySpline(vec4 p, float aX) {
  float mX1 = p.x;
  float mY1 = p.y;
  float mX2 = p.z;
  float mY2 = p.w;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

float sdSegment(vec2 p, vec2 a, vec2 b, float blur){
  p = p * 2.0 - 1.0;
  a = a * 2.0 - 1.0;
  b = b * 2.0 - 1.0;
  vec2 pa = p-a;
  vec2 ba = b-a;
  float h = clamp(dot(pa,ba)/dot(ba,ba), 0.0, 1.0);
  return 1.0 - smoothstep(0.0, blur, length(pa - ba*h));
}

vec4 screen(vec4 fore, vec4 back){
  return 1.0 - (1.0 - fore) * (1.0 - back);
}

vec4 mixFunc(vec4 back, vec4 overlap, float alp) {
  float invAlp = 1.0 - alp;
  vec4 ret = back;

  if (alp > 0.0) {
    ret.xyz = overlap.xyz + back.xyz * invAlp;
    ret.a = alp + back.a * invAlp;
  }
  return ret;
}

float sat(float x){
  return clamp(x, 0.0, 1.0);
}

