float lavaFlashNoise(vec2 uv)
{
    return fract(sin(dot(uv, vec2(12.9898, 78.233))) * 43758.5453);
}

vec4 lavaFlashBlurA(vec2 uv, float radius)
{
    vec4 color = INPUT1(uv) * 0.5;
    color += INPUT1(uv + vec2(-radius, -radius)) * 0.125;
    color += INPUT1(uv + vec2( radius, -radius)) * 0.125;
    color += INPUT1(uv + vec2(-radius,  radius)) * 0.125;
    color += INPUT1(uv + vec2( radius,  radius)) * 0.125;
    return color;
}

vec4 lavaFlashBlurB(vec2 uv, float radius)
{
    vec4 color = INPUT2(uv) * 0.5;
    color += INPUT2(uv + vec2(-radius, -radius)) * 0.125;
    color += INPUT2(uv + vec2( radius, -radius)) * 0.125;
    color += INPUT2(uv + vec2(-radius,  radius)) * 0.125;
    color += INPUT2(uv + vec2( radius,  radius)) * 0.125;
    return color;
}

vec4 lavaFlashTransition(vec2 tc, vec4 colorA, vec4 colorB, float progress)
{
    float flashStrength = smoothstep(0.0, 0.5, progress) *
                          (1.0 - smoothstep(0.5, 1.0, progress)) * 2.0;
    float currentBlur = flashStrength * 0.05;
    float currentExposure = 1.0 + flashStrength * 8.0;
    vec3 flashColor = vec3(1.0, 0.5, 0.2);

    vec4 blurredColor;
    if (progress < 0.5) {
        blurredColor = lavaFlashBlurA(tc, currentBlur);
    } else {
        blurredColor = lavaFlashBlurB(tc, currentBlur);
    }

    blurredColor.rgb *= currentExposure;
    blurredColor.rgb = mix(blurredColor.rgb, flashColor, flashStrength * 0.8);

    float noise = lavaFlashNoise(tc) * 0.1 * flashStrength;
    vec3 noiseColor = vec3(noise, noise, noise);
    vec3 finalColor = mix(blurredColor.rgb, flashColor + noiseColor, flashStrength);
    return vec4(clamp(finalColor, 0.0, 1.0), max(colorA.a, colorB.a));
}

