    vec4 flashColor = lavaFlashTransition(tc, colorA, colorB, transitionProgress);

    float blendIn = smoothstep(0.0, 0.10, effectProgress);
    float blendOut = smoothstep(0.90, 1.0, effectProgress);
    vec4 result = mix(colorA, flashColor, blendIn);
    result = mix(result, colorB, blendOut);

    // [@规则:R-T05] timelineProgress=0 只显示 A，=1 只显示 B。
    return result;
}

