// 计算圆角遮罩
float roundedBoxMask(vec2 uv, float radius, float smoothness) {
    vec2 centered = uv - 0.5;
    vec2 distFromEdge = abs(centered) - (0.5 - radius);
    float cornerDist = length(max(distFromEdge, 0.0));
    float alpha = 1.0 - smoothstep(radius - smoothness, radius, cornerDist);

    return alpha;
}

vec4 InputCoordinate(vec2 uv) {
  float faceScaleX = 0.5625;
  if(abs(vIndex - 5.0) < 0.1) {
    faceScaleX = vRightMiddleScaleX;
  }
  if(abs(vIndex - 7.0) < 0.1) {
    faceScaleX = vRightTopScaleX;
  }

  vec2 uvCenter = vec2(0.5, 0.5);
  vec2 adjustedUV = uv;
  adjustedUV.x = uvCenter.x + (uv.x - uvCenter.x) * faceScaleX;
  // 如果 UV 超出范围，返回透明
  if (adjustedUV.x < 0.0 || adjustedUV.x > 1.0) {
    return vec4(0.0);
  }

  if(vIndex < 1.5){
    return vec4(INPUT2(adjustedUV).rgb, 1.0);
  } else if(vIndex < 2.5){
    return vec4(INPUT1(adjustedUV).rgb, 1.0);
  } else if(vIndex < 3.5){
    return vec4(INPUT2(adjustedUV).rgb, 1.0);
  } else if(vIndex < 4.5){
    return vec4(INPUT1(adjustedUV).rgb, 1.0);
  } else if(vIndex < 5.5){
    return vec4(INPUT1(adjustedUV).rgb, 1.0);
  } else if(vIndex < 6.5){
    return vec4(INPUT1(adjustedUV).rgb, 1.0);
  } else if(vIndex < 7.5){
    return vec4(INPUT2(adjustedUV).rgb, 1.0);
  } else if(vIndex < 8.5){
    return vec4(INPUT2(adjustedUV).rgb, 1.0);
  }

}

float normpdf(in float x, in float sigma)
{
  return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}

vec4 texture2Dmirror(vec2 uv) {
  uv = mod(uv, 2.0);
  uv = mix(uv, 2.0 - uv, step(vec2(1.0), uv));
  return InputCoordinate(fract(uv));
}

vec4 directionBlurFunc(vec2 tc, float strength, float angle)
{
  float theta = angle* 3.1415926 / 180.0;
  vec2 rect = vec2(min(720.0, 720.0 * iResolution.x / iResolution.y), min(720.0, 720.0 * iResolution.y / iResolution.x));
  vec2 dir = vec2(cos(theta), sin(theta)) / rect;

  float sigma = 4.0;
  float weight = normpdf(0.0, sigma);

  vec4 sum            = vec4(0.0);
  vec4 result         = vec4(0.0);
  vec2 unitUv        = dir * 6.0;
  float gamma         = 1.0;
  vec4 curColor       = InputCoordinate(tc);
  vec4 centerPixel    = pow(curColor, vec4(gamma))*weight;
  float sumWeight    = weight;

  for(int i=1;i<=100;i++)
  {
      if (float(i)>strength) break;
      vec2 curRightCoordinate = tc+float(i)*unitUv;
      vec2 curLeftCoordinate  = tc+float(-i)*unitUv;
      vec4 rightColor = texture2Dmirror(curRightCoordinate);
      vec4 leftColor = texture2Dmirror(curLeftCoordinate);
      weight = normpdf(float(i) / strength * 15.0, sigma);
      sum+=pow(rightColor, vec4(gamma))*weight;
      sum+=pow(leftColor, vec4(gamma))*weight;
      sumWeight+=weight*2.0;
  }
  result = (sum+centerPixel)/sumWeight; 
  result = pow(result, vec4(1.0 / gamma));
  return clamp(result, 0.0, 1.0);
}

vec4 FUNCNAME(vec2 tc)
{
  float blurRotateValue = PREFIX(blurRotateValue);
  float transitionProgress = PREFIX(transitionProgress);
  vec4 color;
  const float EPSILON = 0.001;
  if((vIndex >= 0.5 - EPSILON && vIndex < 1.5 + EPSILON) || vIndex >= 2.5 - EPSILON) {
    color = directionBlurFunc(tc, blurRotateValue, 0.0);
  } else {
    color = InputCoordinate(tc);
  }

  // 应用圆角遮罩：开始时缓慢出现(0~0.25)，结束时缓慢消失(0.75~1.0)
  float cornerRadiusBase = 0.12;  // 圆角半径
  float edgeSmoothness = 0.01; // 边缘平滑度，用于抗锯齿
  float fadeIn = smoothstep(0.0, 0.25, transitionProgress);
  float fadeOut = 1.0 - smoothstep(0.75, 1.0, transitionProgress);
  float cornerRadiusFade = cornerRadiusBase * fadeIn * fadeOut;
  // 保持最小半径 > edgeSmoothness，避免 roundedBoxMask 在 radius≈0 时使整块变透明
  float cornerRadius = max(cornerRadiusFade, edgeSmoothness * 1.5);

  float mask = roundedBoxMask(tc, cornerRadius, edgeSmoothness);
  color.a *= mask;

  // 第一遍：Metal + MSAA + Alpha 下 discard 易致整 pass 无有效输出（与 Depth Mosaic 相同）。
  // 仅用 alpha=0 混合；第二遍仍用 INPUT3 over，逻辑不变（第二遍不可 discard，见下）。
  // 第二遍（有深度）：与第一遍无深度 FBO（INPUT3）按像素对齐做 over。
  // OpenGL：gl_FragCoord.y 自下而上，FBO 纹理常按 1-y 采样；Metal：常与 gl_FragCoord 同向，用 y 即可。
  // 若编译器未定义 METAL，可通过 uInput3YFlip（由 effect 从 Input3YFlip 传入，默认 0）强制按 Metal 方式采样。
  if (PREFIX(uPassStage) == 1) {
    float fx = gl_FragCoord.x / iResolution.x;
    float fy = gl_FragCoord.y / iResolution.y;
#if defined(METAL)
    float sy = fy;
#else
    float sy = mix(1.0 - fy, fy, PREFIX(uInput3YFlip));
#endif
    vec2 suv = vec2(fx, sy);
    vec4 under = INPUT3(suv);
    float ta = color.a;
    vec3 tRgb = color.rgb;
    float outA = ta + under.a * (1.0 - ta);
    vec3 outRgb = (tRgb * ta + under.rgb * under.a * (1.0 - ta)) / max(outA, 1e-5);
    return vec4(outRgb, outA);
  }

  return color;
}

