vec4 step01(vec2 uv,vec2 center, float strength) {
    vec4 color = vec4(0.0);
    float total = 0.0;
    vec2 toCenter = center - uv;

    for (int i = 0; i < 20; i++) {
        float percent = float(i) / 20.0;
        float weight = 4.0 * (percent - percent * percent);
        vec4 sampleColor = INPUT1(uv + toCenter * percent * strength);

        color += sampleColor * weight;
        total += weight;
    }
    return color / total;
}
