vec4 lightLeakTransition(vec2 tc, vec4 colorA, vec4 colorB, float progress)
{
    float p = smoothstep(0.0, 1.0, progress);
    vec4 base = mix(colorA, colorB, p);

    vec2 uv = tc - 0.5;
    float sweepAngle = 0.35;
    vec2 direction = vec2(cos(sweepAngle), sin(sweepAngle));
    float lineCoord = dot(uv, direction);
    float sweepCenter = mix(-0.9, 0.9, p);
    float leakSoftness = 0.35;
    float band = 1.0 - smoothstep(0.0, leakSoftness, abs(lineCoord - sweepCenter));

    float pulse = sin(p * 3.14159265);
    float leakStrength = 1.25;
    float cover = clamp(pow(pulse, 0.6) * leakStrength, 0.0, 1.0);
    float grainLike = 0.85 + 0.15 * sin((uv.x * 17.0 + uv.y * 23.0) * 3.14159265);
    float leakMask = clamp(mix(cover, cover * band, 0.45) * grainLike, 0.0, 1.0);

    float luma = dot(base.rgb, vec3(0.299, 0.587, 0.114));
    float saturationBoost = 1.0 + 0.35 * pulse;
    vec3 saturated = mix(vec3(luma, luma, luma), base.rgb, saturationBoost);

    vec3 leakColor = vec3(1.0, 0.62, 0.2);
    vec3 tint = clamp(leakColor * (1.0 + 0.6 * leakMask), 0.0, 1.0);
    vec3 screened = vec3(1.0, 1.0, 1.0) -
                    (vec3(1.0, 1.0, 1.0) - saturated) *
                    (vec3(1.0, 1.0, 1.0) - tint * leakMask);
    vec3 finalRgb = clamp(mix(saturated, screened, leakMask), 0.0, 1.0);
    float finalAlpha = mix(colorA.a, colorB.a, p);
    return vec4(finalRgb.r, finalRgb.g, finalRgb.b, finalAlpha);
}

vec4 FUNCNAME(vec2 tc)
{
    float progress = PREFIX(iProgress);
    vec4 colorA = INPUT1(tc);
    vec4 colorB = INPUT2(tc);

    // 源 Shader 在进度两端各留 10% 平滑接入区，确保端点严格回到原画面。
    float transitionProgress = clamp((progress - 0.1) / 0.8, 0.0, 1.0);
    vec4 transitionColor = lightLeakTransition(tc, colorA, colorB, transitionProgress);
    float blendIn = smoothstep(0.0, 0.1, progress);
    float blendOut = smoothstep(0.9, 1.0, progress);
    vec4 finalColor = mix(colorA, transitionColor, blendIn);
    finalColor = mix(finalColor, colorB, blendOut);

    // [@规则:R-T05] progress=0 只显示 A，progress=1 只显示 B。
    return finalColor;
}

