float cross2d(vec2 a, vec2 b) { return a.x * b.y - a.y * b.x; }
vec2 invBilinear(vec2 p, vec2 a, vec2 b, vec2 c, vec2 d) {
  vec2 res = vec2(-1.0);
  vec2 e = b - a;
  vec2 f = d - a;
  vec2 g = a - b + c - d;
  vec2 h = p - a;
  float k2 = cross2d(g, f);
  float k1 = cross2d(e, f) + cross2d(h, g);
  float k0 = cross2d(h, e);
  // if edges are parallel, this is a linear equation
  if (abs(k2) < 0.001) {
    res = vec2((h.x * k1 + f.x * k0) / (e.x * k1 - g.x * k0), -k0 / k1);
  }
  // otherwise, it's a quadratic
  else {
    float w = k1 * k1 - 4.0 * k0 * k2;
    if (w < 0.0)
      return vec2(-1.0);
    w = sqrt(w);

    float ik2 = 0.5 / k2;
    float v = (-k1 - w) * ik2;
    float u = (h.x - f.x * v) / (e.x + g.x * v);

    if (u < 0.0 || u > 1.0 || v < 0.0 || v > 1.0) {
      v = (-k1 + w) * ik2;
      u = (h.x - f.x * v) / (e.x + g.x * v);
    }
    res = vec2(u, v);
  }

  return res;
}
vec2 CornerPin(vec2 tc, vec2 a, vec2 b, vec2 c, vec2 d) // [-1,1]
{
    vec2 uv = invBilinear(tc, a, b, c, d);
    return uv;
}

vec2 optical_compensate(vec2 tc, float u_fov) {    //
  const float u_strength = 0.7;
  const float intensity = 1.0;
  vec2 uv = tc;
  vec2 ratio = (iResolution.xy / max(iResolution.x, iResolution.y));
  float scale = max(iResolution.x / iResolution.y, iResolution.y / iResolution.x);
  for (int i = 1; i < 16; ++i)
  {
      uv -= 0.5;
      uv *= ratio;
      float d = length(uv * 2.0);
      uv = uv * pow((d*d) + 1.0, -1.0 * pow(u_fov * (scale / (16. / 9.)) * u_strength * intensity * 0.0059375, 3.0));
      u_fov = -u_fov;
      uv = uv * pow((pow(d-2.0, 2.0)) + 1.0, -1.0 * pow(u_fov * (scale / (16. / 9.)) * u_strength * intensity * 0.0059375, 3.0));

      uv /= ratio;

      uv += 0.5;
  }
  return uv; 
}




vec2 rotate_T(vec2 v, vec2 o, float a) {
    float s = sin(a);
    float c = cos(a);
    mat2 m = mat2(c, -s, s, c);
    return m * (v-o) + o;
}

vec2 TransformPlane(vec2 uv, vec2 center, float XRot, float YRot) {
    uv = uv*2.0-1.0;
    center = center*2.0-1.0;
    // First Rotate around Y axis
    vec2 RayDirection =  vec2(uv.x, 0.0);
    vec2 A1 = vec2(0.0, -1.0);
    //   vec2 A1 = vec2(-1.0, 0.0);
    vec2 B1 = RayDirection - A1;
    vec2 C1 = rotate_T(vec2(-1.0, 0.0), vec2(center.x, 0.0), YRot);
    vec2 D1 = rotate_T(vec2( 1.0, 0.0), vec2(center.x, 0.0), YRot) - C1;
    // calculate intersection point
    float u = ( (C1.y + 1.0) * D1.x - C1.x * D1.y ) / (D1.x*B1.y-D1.y*B1.x);
    // position on the plane:
    float sx = u * B1.x;
    float sy = u * uv.y;
    // Now Rotate around X axis
    if(XRot == 0.0){
      return vec2(sx, sy)*0.5+0.5;
    }
    RayDirection = vec2(sy, 0.0);
    vec2 B2 = RayDirection - A1;
    vec2 C2 = rotate_T(vec2(-1.0, 0.0), vec2(center.y, 0.0), XRot);
    vec2 D2 = rotate_T(vec2( 1.0, 0.0), vec2(center.y, 0.0), XRot) - C2;
    // calculate intersection point
    float v = ( (C2.y + 1.0) * D2.x - C2.x * D2.y ) / (D2.x*B2.y-D2.y*B2.x);
    // final position on the plane:
    return vec2(v * sx, v * B2.x )*0.5+0.5; 
}

