}

vec2 Random22(vec2 p){
  return  -1.0+2.0* 
          fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p, vec2(269.5,183.3))))
                * 43758.5453);
}

float NoisePerlin12 (vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);

  float a = dot(Random22(i),f); 
  float b = dot(Random22(i+vec2(1.,0.)),f-vec2(1.,0.));
  float c = dot(Random22(i+vec2(0.,1.)),f-vec2(0.,1.));
  float d = dot(Random22(i+vec2(1.,1.)),f-vec2(1.,1.));

  vec2 u = smoothstep(0.,1.,f);

  return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}

vec2 FbmNoise22(vec2 p){
  vec2 f = vec2(0.0);
  p -= 0.5;
  p *= 2.0;
  p += 0.5;
  float a = 1.0;
  for (int i = 0; i < OCTAVE_NUM; i++){
    f += a * vec2(NoisePerlin12(p),NoisePerlin12(-p.yx));
    p -= 0.5;
    p *= 2.0;
    p += 0.5;
    a /= 2.0;
  }
  return f;
}

