float random_wave(vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

vec2 hash22(vec2 p, vec2 seed) {
  float rnd = random_wave(p);
  float rnd0 = rnd + seed.x;
  float rnd1 = floor(rnd0);
  float rnd2 = rnd0 + 6.0;

  vec2 p1 = fract(p * (rnd1 * 100.0 + seed.y));
  p1 += dot(p1, p1.yx + 10.0);
  vec2 ret1 = fract((p1 + p1.yx + 0.8) * p1.yx + rnd0);

  vec2 p2 = fract(p * (rnd2 * 100.0 + seed.y));
  p2 += dot(p2, p2.yx + 10.0);
  vec2 ret2 = fract((p2 + p2.yx + 0.8) * p2.yx + rnd0);

  vec2 ret = mix(ret1, ret2, fract(rnd)) * 2.0 - 1.0;
  return ret;
}

float perlinNoise(vec2 uv, vec2 seed, vec2 resolution){
  vec2 prop = resolution.xy / min(resolution.x, resolution.y);
  vec2 i = floor(uv * prop * 6.0);
  vec2 f = fract(uv * prop * 6.0);

  vec2 offset = vec2(0.0, 1.0);
  vec2 a = hash22(i, seed);
  vec2 b = hash22(i + offset.yx, seed);
  vec2 c = hash22(i + offset.xy, seed);
  vec2 d = hash22(i + offset.yy, seed);

  vec2 u = smoothstep(vec2(0.0), vec2(1.0), f);
  float ret = mix(mix(dot(a, f), dot(b, f - offset.yx), u.x), mix(dot(c, f - offset.xy), dot(d, f - offset.yy), u.x), u.y);
  return smoothstep(-1.0, 1.0, ret);
}

float psrdnoise(vec2 st, vec2 period, float alpha)
{
  vec2 uv = vec2(st.x+st.y*0.5, st.y); 
  vec2 i0 = floor(uv), f0 = fract(uv);
  float cmp = step(f0.y, f0.x);
  vec2 o1 = vec2(cmp, 1.0-cmp);
  vec2 i1 = i0 + o1, i2 = i0 + 1.0;
  vec2 v0 = vec2(i0.x - i0.y*0.5, i0.y);
  vec2 v1 = vec2(v0.x + o1.x - o1.y*0.5, v0.y + o1.y);
  vec2 v2 = vec2(v0.x + 0.5, v0.y + 1.0); 
  vec2 x0 = st - v0, x1 = st - v1, x2 = st - v2;
  vec3 iu, iv, xw, yw;
  // if(any(greaterThan(period, vec2(0.0)))) {
  if (period.x > 0.0 || period.y > 0.0) {
    xw = vec3(v0.x, v1.x, v2.x);
    yw = vec3(v0.y, v1.y, v2.y);
    if(period.x > 0.0)
      xw = mod(vec3(v0.x, v1.x, v2.x), period.x);
    if(period.y > 0.0)
      yw = mod(vec3(v0.y, v1.y, v2.y), period.y);
    iu = floor(xw + 0.5*yw + 0.5); iv = floor(yw + 0.5);
  } else {
    iu = vec3(i0.x, i1.x, i2.x); iv = vec3(i0.y, i1.y, i2.y);
  }
  vec3 hash = mod(iu, 289.0);
  hash = mod((hash*51.0 + 2.0)*hash + iv, 289.0);
  hash = mod((hash*34.0 + 10.0)*hash, 289.0);
  vec3 psi = hash*0.07482 + alpha;
  vec3 gx = cos(psi); vec3 gy = sin(psi);
  vec2 g0 = vec2(gx.x, gy.x);
  vec2 g1 = vec2(gx.y, gy.y);
  vec2 g2 = vec2(gx.z, gy.z);
  vec3 w = 0.8 - vec3(dot(x0, x0), dot(x1, x1), dot(x2, x2));
  w = max(w, 0.0); vec3 w2 = w*w; vec3 w4 = w2*w2;
  vec3 gdotx = vec3(dot(g0, x0), dot(g1, x1), dot(g2, x2));
  float n = dot(w4, gdotx);
  vec3 w3 = w2*w; vec3 dw = -8.0*w3*gdotx;
  vec2 dn0 = w4.x*g0 + dw.x*x0;
  vec2 dn1 = w4.y*g1 + dw.y*x1;
  vec2 dn2 = w4.z*g2 + dw.z*x2;
  return 10.9*n;
}

float fbm(vec2 x,float n, float iTime){
  vec2 p = vec2(4.);
  float alpha = iTime*1.;
  float scale = 1.0;
  float noise = 0.0;
  float weight = 0.0;
  for (float i=0.0;i<n;i+=1.0){
    noise += psrdnoise(x , p, alpha)*scale;
    weight += scale;
    x *= 2.0;
    scale /= 2.0;
    alpha *= 1.4;
    p *= 2.0;
  }
  noise /= weight;
  return clamp(noise*0.5+0.5, 0.0, 1.0);
}

float FBMnoise(vec2 uv, float scaleVal, float randVal, vec2 resolution) {
  vec2 seed = vec2(1.0, 1.0 + randVal);
  float sum = perlinNoise(uv, seed, resolution);
  vec2 tc = (uv - vec2(0.5)) * scaleVal + vec2(0.5);
  sum += perlinNoise(tc, seed, resolution);
  sum = clamp(sum / 2.0, 0.0, 1.0);
  return sum;
}


vec2 hash_SimplexNoise( vec2 p )
{
	p = vec2( dot(p,vec2(127.1,311.7)),
			  dot(p,vec2(269.5,183.3)) );

	return -1.0 + 2.0*fract(sin(p)*43758.5453123);
}

float SimplexNoise(vec2 p )
{
    float K1 = 0.366025404; // (sqrt(3)-1)/2;
    float K2 = 0.211324865; // (3-sqrt(3))/6;
    vec2 i = floor( p + (p.x+p.y)*K1 );
    vec2 a = p - i + (i.x+i.y)*K2;
    vec2 o = (a.x>a.y) ? vec2(1.0,0.0) : vec2(0.0,1.0); //vec2 of = 0.5 + 0.5*vec2(sign(a.x-a.y), sign(a.y-a.x));
    vec2 b = a - o + K2;
    vec2 c = a - 1.0 + 2.0*K2;
    vec3 h = max( 0.5-vec3(dot(a,a), dot(b,b), dot(c,c) ), 0.0 );
    vec3 n = h*h*h*h*vec3( dot(a,hash_SimplexNoise(i+0.0)), dot(b,hash_SimplexNoise(i+o)), dot(c,hash_SimplexNoise(i+1.0)));
    return dot( n, vec3(70.0) );

}
vec2 mirror(vec2 uv){
  // return vec2(uv.x, uv.y < 0.0 ? uv.y + 1.0 : (uv.y > 1.0 ? uv.y - 1.0 : uv.y));
  // return vec2(uv.x, uv.y < 0.0 ? (uv.y + 1.0) : (uv.y > 1.0 ? (uv.y - 1.0) : uv.y));
  float y = uv.y;
  if (y < 0.0) {
      y += 1.0;
  } else if (y > 1.0) {
      y -= 1.0;
  }
  return vec2(uv.x, y);
}


vec2 rotate_uv(vec2 v, vec2 o, float a) {
  float s = sin(a);
  float c = cos(a);
  mat2 m = mat2(c, -s, s, c);
  return m * (v-o) + o;
}

vec2 TransformPlane(vec2 uv, vec2 center, float XRot, float YRot) {
  uv = uv*2.0-1.0;
  center = center*2.0-1.0;
  // First Rotate around Y axis
  vec2 RayDirection =  vec2(uv.x, 0.0);
  vec2 A1 = vec2(0.0, -1.0);
  //   vec2 A1 = vec2(-1.0, 0.0);
  vec2 B1 = RayDirection - A1;
  vec2 C1 = rotate_uv(vec2(-1.0, 0.0), vec2(center.x, 0.0), YRot);
  vec2 D1 = rotate_uv(vec2( 1.0, 0.0), vec2(center.x, 0.0), YRot) - C1;
  // calculate intersection point
  float u = ( (C1.y + 1.0) * D1.x - C1.x * D1.y ) / (D1.x*B1.y-D1.y*B1.x);
  // position on the plane:
  float sx = u * B1.x;
  float sy = u * uv.y;
  // Now Rotate around X axis
  if(XRot == 0.0){
    return vec2(sx, sy)*0.5+0.5;
  }
  RayDirection = vec2(sy, 0.0);
  vec2 B2 = RayDirection - A1;
  vec2 C2 = rotate_uv(vec2(-1.0, 0.0), vec2(center.y, 0.0), XRot);
  vec2 D2 = rotate_uv(vec2( 1.0, 0.0), vec2(center.y, 0.0), XRot) - C2;
  // calculate intersection point
  float v = ( (C2.y + 1.0) * D2.x - C2.x * D2.y ) / (D2.x*B2.y-D2.y*B2.x);
  // final position on the plane:
  return vec2(v * sx, v * B2.x )*0.5+0.5; 
}
