float KeySpline(vec4 p, float aX) {
    float mX1 = p.x;
    float mY1 = p.y;
    float mX2 = p.z; 
    float mY2 = p.w;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec2 rotate(vec2 v, vec2 o, float a) {
    float s = sin(a);
    float c = cos(a);
    mat2 m = mat2(c, -s, s, c);
    return m * (v-o) + o;
}

vec2 TransformPlane(vec2 uv, vec2 center, float XRot, float YRot) {
  uv = uv*2.0-1.0;
  center = center*2.0-1.0;
  // First Rotate around Y axis
  vec2 RayDirection =  vec2(uv.x, 0.0);
  vec2 A1 = vec2(0.0, -1.0);
  vec2 B1 = RayDirection - A1;
  vec2 C1 = rotate(vec2(-1.0, 0.0), vec2(center.x, 0.0), YRot);
  vec2 D1 = rotate(vec2( 1.0, 0.0), vec2(center.x, 0.0), YRot) - C1;
  // calculate intersection point
  float u = ( (C1.y + 1.0) * D1.x - C1.x * D1.y ) / (D1.x*B1.y-D1.y*B1.x);
  // position on the plane:
  float sx = u * B1.x;
  float sy = u * uv.y;
  // Now Rotate around X axis
  if(XRot == 0.0){
    return vec2(sx, sy)*0.5+0.5;
  }
  RayDirection = vec2(sy, 0.0);
  vec2 B2 = RayDirection - A1;
  vec2 C2 = rotate(vec2(-1.0, 0.0), vec2(center.y, 0.0), XRot);
  vec2 D2 = rotate(vec2( 1.0, 0.0), vec2(center.y, 0.0), XRot) - C2;
  // calculate intersection point
  float v = ( (C2.y + 1.0) * D2.x - C2.x * D2.y ) / (D2.x*B2.y-D2.y*B2.x);
  // final position on the plane:
  return vec2(v * sx, v * B2.x )*0.5+0.5; 
}

float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453) * 2.0 - 1.0;
}

vec4 motionBlur(vec2 _st, vec2 speed, int imgIndex) {
    vec2 texCoord = _st.xy;
    vec4 color = vec4(0.0);
    float total = 0.0;
    float offset = rand(_st);

    float iterNum = 20.0;
    for (float t = 0.0; t <= iterNum; t+=1.0) {
        float percent = (t + offset) / iterNum;
        float weight = 4.0 * (percent - percent * percent);
        vec2 uv = texCoord + speed * percent;
        if(imgIndex == 1){
            color += INPUT1(uv) * weight;
        }else{
            color += INPUT2(uv) * weight;
        }            
        total += weight;
    }
    color /= total;
    return color;
}

float calBellTime(float x) {
  vec4 p = vec4(.45,.06,.28,.98);
  if(x < 0.5){
    float y = x * 2.0;
    return KeySpline(p, y);
  }else{
    float y = 1.0-(x-0.5)*2.0;
    return KeySpline(p, y);
  }
}

float randomNoise(vec2 c)
{
  return fract(sin(dot(c.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

float truncFunc(float x, float num_levels){
  return floor(x * num_levels) / num_levels;
}

vec2 truncVec2(vec2 x, vec2 num_levels){
  return floor(x * num_levels) / num_levels;
}

float randomTrunc(vec2 uv, float iTime){
  float truncTime = truncFunc(iTime, 4.0);
  float uv_trunc = randomNoise(truncVec2(uv.yy, vec2(8.0, 8.0)) + 100.0 * truncTime);
  float uv_randomTrunc = 6.0*truncFunc(iTime, 24.0*uv_trunc);
  float lineWidth = 1.0;
  float amount = 0.4;
  float blockLine_random = 0.5 * randomNoise(truncVec2(uv.yy + uv_randomTrunc, vec2(8.0 * lineWidth, 8.0 * lineWidth)));
  blockLine_random += 0.5 * randomNoise(truncVec2(uv.yy + uv_randomTrunc, vec2(7.0, 7.0)));
  blockLine_random = blockLine_random * 2.0 - 1.0;
  blockLine_random = sign(blockLine_random) * clamp((abs(blockLine_random) - amount) / (0.4), 0.0, 1.0);

  return blockLine_random;
}

vec4 FUNCNAME(vec2 tc)
{
  float iGlobalTime = PREFIX(global_time);
  float totalTime = PREFIX(total_time);
  float progress = min(iGlobalTime / totalTime, 1.0);
  vec4  fragColor = vec4(0.0);  
  float rotateX = 0.0;
  float bellTime = calBellTime(progress);
  vec2  uv = tc;
  float rotateY = radians(-35.0)*bellTime;
  float moveRadio = 8.0;
  vec2 center = vec2(0.15,0.5)*vec2(bellTime, 1.0);

  float blurDirRad = 0.0;
  int   iteration = 15;
  float blurRadius = bellTime*1.0;
  float curPro = 0.0;

  vec2 transformUV = TransformPlane(uv, center, rotateX, rotateY);
  vec4 p = vec4(.78,.05,.27,.95);
  transformUV.x -= moveRadio*KeySpline(p, progress);

  vec2 speed = vec2(bellTime, 0.0)*0.1;
  if(progress < 0.5){
      fragColor = motionBlur(transformUV, speed, 1);
  }else{
      fragColor = motionBlur(transformUV, speed, 2);
  }

  return fragColor;
}

vec4 FUNCNAME(vec2 tc) {
    int uType = PREFIX(uType);
    if(uType == 0) {
        vec4 src = INPUT1(tc);
        vec4 mask = INPUT2(tc);
        return vec4(src.rgb * mask.a, mask.a * src.a);
    }
    else if(uType == 1) {//overlay transition
        vec4 fg = INPUT1(tc);
        vec4 bg = INPUT2(tc);
        float w = iResolution.y * 1920.0 / 1080.0;
        vec2 tc_new = vec2((tc.x - 0.5) * iResolution.x / w + 0.5, tc.y);
        vec4 overlay = INPUT3(tc_new);
        vec4 overlay_Mask = INPUT4(tc_new);
        vec4 fgMix = mix(fg, overlay, overlay_Mask.g);
        return mix(fgMix, bg, overlay_Mask.b);
    }
    return vec4(1.0);
}

