float curveOffset(float x, float curveMag, float curveDir) {
    // curveMag: magnitude of curve
    // curveDir: +1.0 = concave (upper), -1.0 = convex (lower)
    // Sine-based curve: max at center, 0 at edges
    float cx = x;  // x in [0,1]
    float curve = sin(cx * 3.14159) * curveMag * curveDir;
    return curve;
}

vec4 FUNCNAME(vec2 tc) {
    // Animation parameters
    float yOffset    = PREFIX(Anim01);  // Y offset: 1.0 (off-screen) -> 0.0 (at center)
    float strip1Fact = PREFIX(Anim02);  // Strip 1 width factor 1.0→0.0
    float strip2Fact = PREFIX(Anim03);  // Strip 2 width factor 1.0→0.0
    float strip3Fact = PREFIX(Anim04);  // Strip 3 width factor 1.0→0.0
    float curve1Fact = PREFIX(Anim05);  // Strip 1 curve factor 1.0→0.0
    float curve2Fact = PREFIX(Anim06);  // Strip 2 curve factor 1.0→0.0
    float curve3Fact = PREFIX(Anim07);  // Strip 3 curve factor 1.0→0.0

    // User parameters
    float scaleParam = float(PREFIX(Scale)) / 100.0;
    float speedParam = float(PREFIX(Speed)) / 100.0;

    float aspect = iResolution.x / iResolution.y;
    float aaWidth = 1.5 / iResolution.y;

    // Blue color for strip 1
    vec4 blueColor = vec4(0.85, 0.52,0.45,  1.0);

    // Base widths (each strip uses its own factor)
    float strip1Width = 0.15 * strip1Fact;
    float strip2Width = 0.15 * strip2Fact;
    float strip3Width = 0.0 * strip3Fact;

    // Gaps shrink later: stay full until inner strip is half gone, then collapse
    float gap12 = 0.15 * min(strip1Fact * 2.5, 1.0);  // gap12 starts shrinking when strip1Fact < 0.4
    float gap23 = 0.15 * min(strip2Fact * 2.5, 1.0);  // gap23 starts shrinking when strip2Fact < 0.4

    // Per-strip curve magnitude (independent curve factors, flatten earlier than width)
    float baseCurve = 0.18 * (0.3 + 0.7 * scaleParam);
    float curveMag1 = baseCurve * curve1Fact;
    float curveMag2 = baseCurve * curve2Fact;
    float curveMag3 = baseCurve * curve3Fact;

    // Y center: upper slides from top, lower from bottom, both toward 0.5
    float upperCenterY = 0.5 - yOffset * 0.8;
    float lowerCenterY = 0.5 + yOffset * 0.8;

    // Start with INPUT1 as default background
    vec4 result = INPUT1(tc);

    // ========== Determine strip3 outer boundary ==========
    // Upper group layout: each strip centered
    float u_s1_inner = upperCenterY + strip1Width * 0.5;
    float u_s1_outer = upperCenterY - strip1Width * 0.5;
    float u_s2_center = u_s1_outer - gap12 - strip2Width * 0.5;
    float u_s2_inner = u_s2_center + strip2Width * 0.5;
    float u_s2_outer = u_s2_center - strip2Width * 0.5;
    float u_s3_center = u_s2_outer - gap23 - strip3Width * 0.5;
    float u_s3_inner = u_s3_center + strip3Width * 0.5;
    float u_s3_outer = u_s3_center - strip3Width * 0.5;

    // Lower group layout: each strip centered
    float l_s1_inner = lowerCenterY - strip1Width * 0.5;
    float l_s1_outer = lowerCenterY + strip1Width * 0.5;
    float l_s2_center = l_s1_outer + gap12 + strip2Width * 0.5;
    float l_s2_inner = l_s2_center - strip2Width * 0.5;
    float l_s2_outer = l_s2_center + strip2Width * 0.5;
    float l_s3_center = l_s2_outer + gap23 + strip3Width * 0.5;
    float l_s3_inner = l_s3_center - strip3Width * 0.5;
    float l_s3_outer = l_s3_center + strip3Width * 0.5;

    // Outside strip3 = INPUT2 (use curve to find outer boundary)
    float cOff3_up = curveOffset(tc.x, curveMag3, 1.0);
    float cOff3_dn = curveOffset(tc.x, curveMag3, -1.0);
    float effY_up = tc.y - cOff3_up;
    float effY_dn = tc.y - cOff3_dn;

    // If pixel is above upper strip3 outer edge or below lower strip3 outer edge -> INPUT2
    if (strip3Fact > 0.001) {
        if (effY_up < u_s3_outer || effY_dn > l_s3_outer) {
            result = INPUT2(tc);
        }
    }

    // ========== UPPER GROUP (curveDir = +1.0, concave) ==========
    {
        float curveDir = 1.0;

        // Layout: each strip centered on its midpoint
        float s1_inner = upperCenterY + strip1Width * 0.5;
        float s1_outer = upperCenterY - strip1Width * 0.5;

        float s2_center = s1_outer - gap12 - strip2Width * 0.5;
        float s2_inner = s2_center + strip2Width * 0.5;
        float s2_outer = s2_center - strip2Width * 0.5;

        float s3_center = s2_outer - gap23 - strip3Width * 0.5;
        float s3_inner = s3_center + strip3Width * 0.5;
        float s3_outer = s3_center - strip3Width * 0.5;

        // Strip 1: blue, own curve
        if (strip1Fact > 0.001) {
            float cOff = curveOffset(tc.x, curveMag1, curveDir);
            float effY = tc.y - cOff;
            if (effY > s1_outer && effY < s1_inner) {
                float mask = smoothstep(s1_outer - aaWidth, s1_outer + aaWidth, effY)
                           * (1.0 - smoothstep(s1_inner - aaWidth, s1_inner + aaWidth, effY));
                result = mix(result, blueColor, mask);
            }
        }

        // Strip 2: INPUT2, own curve
        if (strip2Fact > 0.001) {
            float cOff = curveOffset(tc.x, curveMag2, curveDir);
            float effY = tc.y - cOff;
            if (effY > s2_outer && effY < s2_inner) {
                float mask = smoothstep(s2_outer - aaWidth, s2_outer + aaWidth, effY)
                           * (1.0 - smoothstep(s2_inner - aaWidth, s2_inner + aaWidth, effY));
                result = mix(result, INPUT2(tc), mask);
            }
        }

        // Strip 3: INPUT2, own curve
        if (strip3Fact > 0.001) {
            float cOff = curveOffset(tc.x, curveMag3, curveDir);
            float effY = tc.y - cOff;
            if (effY > s3_outer && effY < s3_inner) {
                float mask = smoothstep(s3_outer - aaWidth, s3_outer + aaWidth, effY)
                           * (1.0 - smoothstep(s3_inner - aaWidth, s3_inner + aaWidth, effY));
                result = mix(result, INPUT2(tc), mask);
            }
        }
    }

    // ========== LOWER GROUP (curveDir = -1.0, convex) ==========
    {
        float curveDir = -1.0;

        // Layout: each strip centered on its midpoint
        float s1_inner = lowerCenterY - strip1Width * 0.5;
        float s1_outer = lowerCenterY + strip1Width * 0.5;

        float s2_center = s1_outer + gap12 + strip2Width * 0.5;
        float s2_inner = s2_center - strip2Width * 0.5;
        float s2_outer = s2_center + strip2Width * 0.5;

        float s3_center = s2_outer + gap23 + strip3Width * 0.5;
        float s3_inner = s3_center - strip3Width * 0.5;
        float s3_outer = s3_center + strip3Width * 0.5;

        // Strip 1: blue, own curve
        if (strip1Fact > 0.001) {
            float cOff = curveOffset(tc.x, curveMag1, curveDir);
            float effY = tc.y - cOff;
            if (effY > s1_inner && effY < s1_outer) {
                float mask = smoothstep(s1_inner - aaWidth, s1_inner + aaWidth, effY)
                           * (1.0 - smoothstep(s1_outer - aaWidth, s1_outer + aaWidth, effY));
                result = mix(result, blueColor, mask);
            }
        }

        // Strip 2: INPUT2, own curve
        if (strip2Fact > 0.001) {
            float cOff = curveOffset(tc.x, curveMag2, curveDir);
            float effY = tc.y - cOff;
            if (effY > s2_inner && effY < s2_outer) {
                float mask = smoothstep(s2_inner - aaWidth, s2_inner + aaWidth, effY)
                           * (1.0 - smoothstep(s2_outer - aaWidth, s2_outer + aaWidth, effY));
                result = mix(result, INPUT2(tc), mask);
            }
        }

        // Strip 3: INPUT2, own curve
        if (strip3Fact > 0.001) {
            float cOff = curveOffset(tc.x, curveMag3, curveDir);
            float effY = tc.y - cOff;
            if (effY > s3_inner && effY < s3_outer) {
                float mask = smoothstep(s3_inner - aaWidth, s3_inner + aaWidth, effY)
                           * (1.0 - smoothstep(s3_outer - aaWidth, s3_outer + aaWidth, effY));
                result = mix(result, INPUT2(tc), mask);
            }
        }
    }

    // When all strips gone, show INPUT2
    float allGone = (1.0 - step(0.001, strip1Fact))
                  * (1.0 - step(0.001, strip2Fact))
                  * (1.0 - step(0.001, strip3Fact));
    result = mix(result, INPUT2(tc), allGone);

    return result;
}

// Ease-out quadratic (similar to KeySpline(0.25, 0.46, 0.45, 0.94))
float easeOut(float t) {
    return t * (2.0 - t);
}

vec4 FUNCNAME(vec2 tc) {
    vec4 result = INPUT1(tc);
    float aaWidth = 1.5 / iResolution.y;
    float nTime = PREFIX(uProgress);  // normalized time 0~1

    // 8 strips, each 1/8 screen height
    float stripH = 0.125;

    // Determine which strip this pixel belongs to
    int stripIdx = int(floor(tc.y / stripH));
    if (stripIdx < 0) stripIdx = 0;
    if (stripIdx > 7) stripIdx = 7;

    float stripBot = float(stripIdx) * stripH;
    float stripTop = stripBot + stripH;

    // Per-strip delay: strip 0 (bottom) = 0.0, strip 7 (top) = 0.35
    // Each strip's animation maps [delay, 1.0] to [0, 1]
    float delay = float(stripIdx) * 0.1;

    // Before animation starts, this strip is invisible (show INPUT1 only)
    if (nTime <= delay) {
        return result;
    }

    float localT = min((nTime - delay) / (1.0 - delay), 1.0);
    float progress = easeOut(localT);

    // Block X: -0.2 -> 0.5
    float blockX = mix(-0.2, 0.5, progress);
    float blockXR = 1.0 - blockX;

    // Widths: 0.5 -> 0.0 (half screen, shrinks with progress)
    float blueW = 0.5 * (1.0 - progress);
    float blurW = 0.5 * (1.0 - progress);

    // Full coverage - no edge fading between adjacent strips
    float edgeMask = 1.0;

    // Skip if blocks fully collapsed
    if (blueW < 0.001 && blurW < 0.001) {
        result = INPUT2(tc);
        return result;
    }

    // === LEFT GROUP: moves left to right ===
    float L_blueLeft  = blockX - blueW * 0.5;
    float L_blueRight = blockX + blueW * 0.5;
    float L_blurRight = L_blueLeft;
    float L_blurLeft  = L_blurRight - blurW;

    // === RIGHT GROUP (mirror): moves right to left ===
    float R_blueRight = blockXR + blueW * 0.5;
    float R_blueLeft  = blockXR - blueW * 0.5;
    float R_blurLeft  = R_blueRight;
    float R_blurRight = R_blurLeft + blurW;

    vec4 blueColor = vec4(0.85,0.52,  0.45, 1.0);

    // Right group
    if (tc.x >= R_blueLeft && tc.x <= R_blueRight) {
        result = mix(INPUT1(tc), blueColor, edgeMask);
    } else if (tc.x > R_blurLeft && tc.x <= R_blurRight) {
        result = mix(INPUT1(tc), INPUT3(tc), edgeMask);
    } else if (tc.x > R_blurRight) {
        result = mix(INPUT1(tc), INPUT2(tc), edgeMask);
    }
    // Left group
    else if (tc.x >= L_blueLeft && tc.x <= L_blueRight) {
        result = mix(INPUT1(tc), blueColor, edgeMask);
    } else if (tc.x >= L_blurLeft && tc.x < L_blurRight) {
        result = mix(INPUT1(tc), INPUT3(tc), edgeMask);
    } else if (tc.x < L_blurLeft) {
        result = mix(INPUT1(tc), INPUT2(tc), edgeMask);
    }

    return result;
}

