// 添加模糊效果函数
vec4 blur(vec2 uv, float blur_amount) {
    vec4 color = vec4(0.0);
    float total = 0.0;

    // 采样9x9网格
    float offset = blur_amount * 0.01;

    for(float x = -2.0; x <= 2.0; x++) {
        for(float y = -2.0; y <= 2.0; y++) {
            vec2 off = vec2(x, y) * offset;
            float weight = 1.0 - length(off) * 0.25;
            if(weight <= 0.0) continue;

            color += getFromColor(uv + off) * weight;
            total += weight;
        }
    }

    return color / total;
}

vec4 OverlayColors(vec4 inputColor1, vec4 inputColor2) {
    // 使用 alpha 混合公式：result = foreground * alpha + background * (1 - alpha)
    vec4 resultColor = vec4(
        inputColor2.rgb * inputColor2.a + inputColor1.rgb * (1.0 - inputColor2.a),
        inputColor2.a + inputColor1.a * (1.0 - inputColor2.a)
    );
    return resultColor;
}

vec4 transition_scale_1(vec2 p, float progress, vec4 bgcolor, float currentScale) {
    // 加快整体进度
    float adjustedProgress = smoothstep(0.0, 0.54, progress);

    // 基础UV计算
    vec2 uv = p - vec2(0.5, 0.5);
    vec2 finalUV = uv / currentScale + vec2(0.5, 0.5);
    float dist = length((vec2(finalUV) - 0.5) * ratio2);

    // 简化变焦计算
    vec2 r = ((vec2(finalUV) - 0.5) * ratio2);
    float r_length = length(r);

    // 只在圆形区域内应用变焦效果
    if (dist < adjustedProgress) {
        vec4 blurredColor;
        float zoomStrength = 1.0 - (0.25 * adjustedProgress); // 统一的变焦强度计算

        // 定义区域边界
        float region1 = adjustedProgress * 0.7;
        float region2 = adjustedProgress * 0.8;
        float region3 = adjustedProgress * 0.9;

        // 加快过渡带的变化
        float transitionWidth1 = mix(0.1, 0.005, smoothstep(0.0, 0.25, adjustedProgress));
        float transitionWidth2 = mix(0.1, 0.01, smoothstep(0.0, 0.25, adjustedProgress));
        float transitionWidth3 = mix(0.1, 0.1, smoothstep(0.0, 0.25, adjustedProgress));
        if(adjustedProgress > 0.18)
        {
            // transitionWidth1 = 0.001;
        }
        // 计算每个区域的混合因子，使用动态过渡带宽度
        float blend1 = smoothstep(region1 - transitionWidth1, region1 + transitionWidth1, r_length);
        float blend2 = smoothstep(region2 - transitionWidth2, region2 + transitionWidth2, r_length);
        float blend3 = smoothstep(region3 - transitionWidth3, region3 + transitionWidth3, r_length);

        // 加快模糊清晰化的时间点
        vec4 color1 = blur(finalUV, (adjustedProgress > 0.18 ? 0.0 : 0.5));

        vec2 zoomUV2 = zoom(finalUV, zoomStrength * 0.9);
        vec4 color2 = blur(zoomUV2, (adjustedProgress > 0.18 ? GetValue2(adjustedProgress) : 0.5));
        //圆圈变化
        float a =  adjustedProgress > 0.55 ? GetValue5((adjustedProgress-0.55)/(1.0-0.55)) : 0.8;
        if(adjustedProgress > 0.55&& dist >=adjustedProgress * 0.73 && dist <= adjustedProgress *a)
        {
            // 定义区域边界和过渡宽度
            float innerRadius = adjustedProgress * 0.73;  // 内边界
            float outerRadius = adjustedProgress * a;      // 外边界
            float transitionWidth = mix(0.05, 0.005, smoothstep(0.0, 1.0, adjustedProgress));

            // 计算混合因子
            float blendInner = smoothstep(innerRadius - transitionWidth, innerRadius + transitionWidth, dist);
            float blendOuter = 1.0 - smoothstep(outerRadius - transitionWidth, outerRadius + transitionWidth, dist);
            float finalBlend = blendInner * blendOuter;

            // 渐变混合颜色（原 color2 和新颜色之间）
            vec4 originalColor = color2;    // 保留原 color2 的值
            vec4 targetColor = INPUT2(finalUV); // 新颜色
            color2 = mix(originalColor, targetColor, finalBlend);
        }

        vec2 zoomUV3 = zoom(finalUV, zoomStrength * 0.8);
        vec4 color3 = blur(zoomUV3, (adjustedProgress > 0.18 ? GetValue3(adjustedProgress) : 0.5));

        vec2 zoomUV4 = zoom(finalUV, zoomStrength * 0.7);
        vec4 color4 = blur(zoomUV4, (adjustedProgress > 0.18 ? GetValue4(adjustedProgress) : 0.5));

        // 混合所有区域
        blurredColor = mix(
            color1,
            mix(
                mix(color2, color3, blend2),
                color4,
                blend3
            ),
            blend1
        );

        // blurredColor = vec4(blurredColor.b,blurredColor.g,blurredColor.r,1.0);

            blurredColor.a = (blurredColor.a == 0.0 ? 1.0 : blurredColor.a);

        return blurredColor;

    }
    else {
        // 区域外提供“后图颜色但 alpha=0”，便于第二阶段进行全局淡入
        vec4 nextColor = INPUT2(finalUV);
        return vec4(nextColor.rgb, 0.0);
    }

    return bgcolor;
}

vec4 FUNCNAME(vec2 tc) {
    int stepType = PREFIX(stepType);
    if(stepType == 0){
        return INPUT1(tc);
    }else if(stepType == 1){
        float progressValue = PREFIX(progressValue);
        vec4 bgcolor = vec4(0.0, 0.0, 0.0, 1.0);

        float scale_Progress = GetValue1(progressValue);
        float currentScale = mix(0.001, 1.0, scale_Progress);

        vec2 uv = vec2(tc.x, tc.y);
        return transition_scale_1(uv, progressValue, bgcolor, currentScale);
    }
    else{
        // 第二阶段：全局淡出前图，淡入后图，同时用效果 alpha 覆盖以保证局部细节
        vec4 prevColor = INPUT1(tc);   // 前一张（开始时完全可见）
        vec4 nextFx    = INPUT2(tc);   // 后一张颜色，alpha 为效果区域
        float p = clamp(PREFIX(progressValue) / 0.54, 0.0, 1.0);
        float fade = smoothstep(0.0, 1.0, p); // 渐进淡出/淡入

        // 基础：按进度在全局范围内从前图过渡到后图
        vec4 nextOpaque = vec4(nextFx.rgb, 1.0);
        vec4 baseMix = mix(prevColor, nextOpaque, fade);

        // 在效果区域内，用效果结果覆盖，确保“出现后就是后图”
        vec4 finalColor = mix(baseMix, nextOpaque, nextFx.a);
        return finalColor;
    }
    return INPUT1(tc);
}

