vec2 cubicBezier(vec2 p1, vec2 p2, vec2 p3, vec2 p4, float t) {
    vec2 result;
    result.x = p1.x * pow(1.0 - t, 3.0) + 3.0 * p2.x * pow(1.0 - t, 2.0) * t + 3.0 * p3.x * (1.0 - t) * pow(t, 2.0) + p4.x * pow(t, 3.0);
    result.y = p1.y * pow(1.0 - t, 3.0) + 3.0 * p2.y * pow(1.0 - t, 2.0) * t + 3.0 * p3.y * (1.0 - t) * pow(t, 2.0) + p4.y * pow(t, 3.0);
    return result;
}

float getBezier01X(vec4 bezier_val, float x) {
    float ts = 0.0;
    float te = 1.0;
    float epsilon = 0.0001;
    while (te - ts > epsilon) {
        float tm = (ts + te) * 0.5;
        vec2 value = cubicBezier(vec2(0.0), vec2(bezier_val.xy), vec2(bezier_val.zw), vec2(1.0), tm);
        if (value.x > x) {
            te = tm;
        } else {
            ts = tm;
        }
    }
    return (te + ts) * 0.5;
}

float cubicBezier01(vec4 bezier_val, float p) {
    float x = getBezier01X(bezier_val, p);
    vec2 result = cubicBezier(vec2(0.0), vec2(bezier_val.xy), vec2(bezier_val.zw), vec2(1.0), x);
    return result.y;
}

float remap(float a, float b, float x){
	if (x < a) return 0.0;
	if (x > b) return 1.0;
	return (x-a)/(b-a);
}

