	if (x > b) return 1.0;
	return (x-a)/(b-a);
}

float getValue(float iPro, vec2 timeFrame, vec2 valueRange, vec4 lineRange, int numFrames) {
    float res = 0.0;
    float start_frame = timeFrame.x;
    float end_frame = timeFrame.y;
    vec4 p = lineRange;
    if (iPro > start_frame && iPro <= end_frame) {
        float cur_process = remap(start_frame, end_frame, iPro);
        float bezier = cubicBezier01(p, cur_process);
        res = mix(valueRange.x, valueRange.y, bezier);
        return res;
    }
    if (iPro <= timeFrame.x) {
        return valueRange.x;
    }
    if (iPro >= timeFrame.y) {
        return valueRange.y;
    }
    return res;
}
