// 添加模糊效果函数
vec4 blur(vec2 uv, float blur_amount) {
    vec4 color = vec4(0.0);
    float total = 0.0;

    // 采样9x9网格
    float offset = blur_amount * 0.01;

    for(float x = -2.0; x <= 2.0; x++) {
        for(float y = -2.0; y <= 2.0; y++) {
            vec2 off = vec2(x, y) * offset;
            float weight = 1.0 - length(off) * 0.25;
            if(weight <= 0.0) continue;

            color += getFromColor(uv + off) * weight;
            total += weight;
        }
    }

    return color / total;
}

vec4 OverlayColors(vec4 inputColor1, vec4 inputColor2) {
    // 使用 alpha 混合公式：result = foreground * alpha + background * (1 - alpha)
    vec4 resultColor = vec4(
        inputColor2.rgb * inputColor2.a + inputColor1.rgb * (1.0 - inputColor2.a),
        inputColor2.a + inputColor1.a * (1.0 - inputColor2.a)
    );
    return resultColor;
}

// 添加边界平滑函数
float getSmoothBoundary(vec2 uv, float dot_y, float dot_x) {
    float boundary = uv.x * (1.0-dot_y)/dot_x + dot_y;
    float dist = uv.y - boundary;
    return dist; 
}

vec4 applyExposure(vec4 color, float exposure) {
    // 应用曝光调整
    vec3 exposedColor = color.rgb * pow(2.0, exposure);
    return vec4(exposedColor, color.a);
}

vec4 brightenColor(vec4 color, float brightness) {
    // 确保亮度值在合理范围内（例如0到1之间）
    vec3 brightenedColor = color.rgb + brightness;
    // 防止颜色值超出[0,1]范围
    brightenedColor = clamp(brightenedColor, 0.0, 1.0);
    return vec4(brightenedColor, color.a);
}

vec2 distortLeftUp45(vec2 texCoord, float intensity) {
    vec2 center = vec2(0.5, 0.5); // 纹理中心点
    vec2 coord = texCoord - center; // 相对于中心的坐标

    // 计算角度和半径
    float angle = atan(coord.y, coord.x);
    float radius = length(coord);

    // 左上45度方向扭曲
    angle += (intensity * (1.0 - radius)) * radians(45.0);

    // 转换回笛卡尔坐标系
    coord.x = radius * cos(angle);
    coord.y = radius * sin(angle);

    // 回到原始坐标空间
    return coord + center;
}

