        float ratio = iResolution.x / iResolution.y;


        // 使用平滑的映射函数，在中间部分才开始转场
        float startProgress = 0.33;  // 开始转场的进度点
        float endProgress = 0.66;    // 结束转场的进度点
        progressValue = clamp((progressValue - startProgress)/(endProgress - startProgress), 0.0, 1.0);


        vec2 boomUV;
        // 初始化结果颜色
        vec4 resultColor = vec4(0.0);
        float effectMask = 0.0;


        // 从前向后渲染5层
        float layerDelay = 0.068; // 每层延迟

        float progress1;
        float slowStart = 0.1;
        float slow;

        for(int i = 0; i <= 4; i++) {
            float startTime = float(i) * layerDelay;
            float layerProgress = clamp((progressValue - startTime) / (1.0 - startTime), 0.0, 1.0);
            if(i==0){
                slow = 0.75;
            }else if(i==1){
                slow = 0.5;
            }else if(i==2){
                slow = 0.55;
            }else if(i==3){
                slow = 0.57;
            }else{
                slow = 0.59;
            }

            if (layerProgress < slowStart) {
                progress1 = layerProgress;
            } else if (layerProgress < 1.0) {
                float t = (layerProgress - slowStart) / (1.0 - slowStart);
                float speedFactor = mix(1.0, slow, smoothstep(0.0, 1.0, t));
                progress1 = slowStart + (layerProgress - slowStart) * (speedFactor);
            } else{
                progress1 = 1.0 + (layerProgress - slowStart);
            }
            progress1 = clamp(progress1, 0.0, 1.0);

            float k = GetValuek(progress1);
            float b = GetValueb(progress1);

            float k2 = -ratio/k;
            float b2 = -2.0*b*1.1/k;

            vec2 uv = tc - vec2(0.5, 0.5);

            // 使用平滑边界判断替代硬边界
            float smoothWidth = 0.005; // 平滑过渡的宽度
            float smoothWidth_1 = mix(0.005,0.06,layerProgress); // 平滑过渡的宽度
            float boundary1 = smoothBoundary(uv.y, k * uv.x + b, smoothWidth_1);
            float boundary2 = smoothBoundary(k * uv.x - b, uv.y, smoothWidth_1);
            float boundary3 = smoothBoundary(uv.y, k2 * uv.x + b2, smoothWidth);
            float boundary4 = smoothBoundary(k2 * uv.x - b2, uv.y, smoothWidth);

            // 计算最终的混合因子
            float blendFactor = boundary1 * boundary2 * boundary3 * boundary4;

            vec2 finalUV = uv + vec2(0.5, 0.5);

            // 使用混合因子进行颜色混合
            if(blendFactor > 0.0) {
                vec4 layerColor;
                if(i == 0){
                    layerColor = blur(tc, 0.3)*1.1;
                }else if(i == 1){
                    layerColor = blur(tc, 0.3);
                }else if(i == 2){
                    boomUV = zoom(tc, 1.2);
                    layerColor = blur(boomUV, 0.3);
                }else if(i == 3){
                    boomUV = zoom(tc, 1.05);
                    layerColor = INPUT2(boomUV);
                    layerColor.a=(layerColor.a==0.0? 1.0:layerColor.a);
                }else{
                    layerColor = INPUT2(tc);
                    layerColor.a=(layerColor.a==0.0? 1.0:layerColor.a);
                }

                // 使用混合因子进行平滑过渡
                resultColor = mix(resultColor, layerColor, blendFactor);
                effectMask = max(effectMask, blendFactor);
            }

        }
        // 兜底：仅对处于特效区域(effectMask>0)的像素补背景，避免影响背景区域
        if (effectMask > 0.0 && resultColor.a < 0.999) {
            // 使用 clamp 收缩取样范围，避开边缘黑边；再轻度模糊柔化
            float margin = 0.04; // 4% 内缩，可按需要调 0.02~0.08
            vec2 safeUV = clamp(tc, vec2(margin), vec2(1.0 - margin));
            vec4 bg1 = INPUT1(safeUV);
            vec4 bg2 = INPUT2(safeUV);
            // 选亮度较高的一路作为基底，避免选到黑边
            float l1 = dot(bg1.rgb, vec3(0.2126, 0.7152, 0.0722));
            float l2 = dot(bg2.rgb, vec3(0.2126, 0.7152, 0.0722));
            vec4 chooseBG = mix(bg2, bg1, step(l2, l1));
            vec4 softBG = mix(chooseBG, blur(safeUV, 0.5), 0.5);
            resultColor = vec4(resultColor.rgb + (1.0 - resultColor.a) * softBG.rgb, 1.0);
        }
        return resultColor;
    }
    else{
        vec4 inputColor1 = INPUT1(tc);
        vec4 inputColor2 = INPUT2(tc);
        vec4 finalColor = OverlayColors(inputColor1, inputColor2);
        return finalColor;
    }
    return INPUT1(tc);
}

// ==========================================
// Multiple Close
// Reverse of Multipe Open: strips start spread
// apart and close toward center.
// Outer pair has white border, shows blurred INPUT1
// inside. Inner pair (no border) shows blurred
// INPUT1 zoomed 1.3x.
// Between bordered strips: INPUT1.
// Between inner strips: INPUT1.
// Outside all strips: INPUT2.
// INPUT3 = blurred INPUT1 (from effect)
// ==========================================

// Signed distance to a tilted rectangle (infinite height)
float stripSDF(vec2 tc, float centerX, float angle, float halfWidth, float aspect) {
    vec2 d = tc - vec2(centerX, 0.5);
    d.x *= aspect;
    float ca = cos(angle);
    float sa = sin(angle);
    float localX = d.x * ca - d.y * sa;
    return abs(localX) - halfWidth;
}

// Get the local X coordinate in rotated strip space
float stripLocalX(vec2 tc, float centerX, float angle, float aspect) {
    vec2 d = tc - vec2(centerX, 0.5);
    d.x *= aspect;
    float ca = cos(angle);
    float sa = sin(angle);
    return d.x * ca - d.y * sa;
}

vec4 FUNCNAME(vec2 tc) {
    // Animation parameters
    float borderedWidthAnim = PREFIX(Anim01);   // Bordered strips width
    float borderedMoveAnim  = PREFIX(Anim02);   // Bordered strips L/R movement
    float innerWidthAnim    = PREFIX(Anim03);    // Inner strips width
    float innerMoveAnim     = PREFIX(Anim04);    // Inner strips L/R movement

    // User parameters
    float scaleParam = float(PREFIX(Scale)) / 100.0;
    float speedParam = float(PREFIX(Speed)) / 100.0;

    // Aspect ratio & portrait/landscape adaptation
    float aspect = iResolution.x / iResolution.y;
    float refAspect = 16.0 / 9.0;
    float aspectAdj = min(aspect / refAspect, 1.0);  // 1.0 for landscape, <1 for portrait

    // Anti-aliasing width
    float aaWidth = 1.5 / iResolution.y;

    // Tilt angle: 15 degrees
    float angle = radians(-15.0);

    // Strip half-width: scaled by aspect so screen proportion stays consistent
    float stripHalfWidthMax = (0.10 + scaleParam * 0.08) * aspectAdj;
    float stripHalfWidth = stripHalfWidthMax * borderedWidthAnim;
    float borderWidth = 0.004 * aspectAdj;

    // === BORDERED STRIPS (outer pair) ===
    float bWidth = stripHalfWidth;

    // Movement: compute range so strips start fully off-screen
    float sinA = abs(sin(angle));
    float cosA = abs(cos(angle));
    float maxExtent = (stripHalfWidthMax + sinA * 0.5) / (aspect * cosA);
    float moveRange = 0.5 + maxExtent + 0.05;
    float bLeftX  = 0.5 - borderedMoveAnim * moveRange;
    float bRightX = 0.5 + borderedMoveAnim * moveRange;

    // === INNER STRIPS (no border, delayed) ===
    float iWidth = stripHalfWidth * innerWidthAnim;

    float iLeftX  = 0.5 - innerMoveAnim * moveRange;
    float iRightX = 0.5 + innerMoveAnim * moveRange;

    // === Determine background regions ===
    float bLeftLocalX  = stripLocalX(tc, bLeftX, angle, aspect);
    float bRightLocalX = stripLocalX(tc, bRightX, angle, aspect);
    float iLeftLocalX  = stripLocalX(tc, iLeftX, angle, aspect);
    float iRightLocalX = stripLocalX(tc, iRightX, angle, aspect);

    // "Between bordered strips"
    float betweenBordered = step(bWidth, bLeftLocalX) * step(-bWidth, -bRightLocalX);
    // "Between inner strips"
    float betweenInner = step(iWidth, iLeftLocalX) * step(-iWidth, -iRightLocalX);

    float showInner = step(0.001, innerWidthAnim);

    // Background: default INPUT2 (outside all strips)
    vec4 bg = INPUT2(tc);

    // Between inner strips: show normal INPUT1
    if (showInner > 0.5 && betweenInner > 0.5) {
        bg = INPUT1(tc);
    }

    vec4 result = bg;

    // === Draw Inner strips (bottom layer, no border) ===
    if (showInner > 0.5) {
        // Left inner strip
        float distL = stripSDF(tc, iLeftX, angle, iWidth, aspect);
        if (distL < aaWidth) {
            float alphaL = 1.0 - smoothstep(-aaWidth, aaWidth, distL);
            // Blurred INPUT2 zoomed 1.3x from center
            vec2 zoomedTC = (tc - 0.5) / 1.3 + 0.5;
            zoomedTC = clamp(zoomedTC, vec2(0.0), vec2(1.0));
            vec4 innerColor = INPUT3(zoomedTC);
            result = mix(result, innerColor, alphaL);
        }

        // Right inner strip
        float distR = stripSDF(tc, iRightX, angle, iWidth, aspect);
        if (distR < aaWidth) {
            float alphaR = 1.0 - smoothstep(-aaWidth, aaWidth, distR);
            vec2 zoomedTC = (tc - 0.5) / 1.3 + 0.5;
            zoomedTC = clamp(zoomedTC, vec2(0.0), vec2(1.0));
            vec4 innerColor = INPUT3(zoomedTC);
            result = mix(result, innerColor, alphaR);
        }
    }

    // === Draw Bordered strips (top layer, with white border) ===
    if (borderedWidthAnim > 0.001) {
        // Left bordered strip
        float distBL = stripSDF(tc, bLeftX, angle, bWidth, aspect);
        if (distBL < aaWidth) {
            float alphaBL = 1.0 - smoothstep(-aaWidth, aaWidth, distBL);

            float localXL = abs(stripLocalX(tc, bLeftX, angle, aspect));
            float innerEdgeL = bWidth - borderWidth;
            float contentMaskL = step(borderWidth, bWidth) * (1.0 - smoothstep(max(innerEdgeL, 0.0) - aaWidth, max(innerEdgeL, 0.0) + aaWidth, localXL));

            vec4 stripColor = INPUT3(tc);
            vec4 color = mix(vec4(1.0), stripColor, contentMaskL);
            result = mix(result, color, alphaBL);
        }

        // Right bordered strip
        float distBR = stripSDF(tc, bRightX, angle, bWidth, aspect);
        if (distBR < aaWidth) {
            float alphaBR = 1.0 - smoothstep(-aaWidth, aaWidth, distBR);

            float localXR = abs(stripLocalX(tc, bRightX, angle, aspect));
            float innerEdgeR = bWidth - borderWidth;
            float contentMaskR = step(borderWidth, bWidth) * (1.0 - smoothstep(max(innerEdgeR, 0.0) - aaWidth, max(innerEdgeR, 0.0) + aaWidth, localXR));

            vec4 stripColor = INPUT3(tc);
            vec4 color = mix(vec4(1.0), stripColor, contentMaskR);
            result = mix(result, color, alphaBR);
        }
    }

    // Final: when all strips have fully shrunk to 0 width, show INPUT2
    float allClosed = (1.0 - step(0.001, borderedWidthAnim)) * (1.0 - step(0.001, innerWidthAnim));
    result = mix(result, INPUT2(tc), allClosed);

    return result;
}

float triangularPeak(float p)
{
    return 1.0 - abs(2.0 * p - 1.0);
}

vec3 neonCornerPair(vec2 uv, vec2 corner, vec2 center, vec3 color,
                    float moveProgress, float leakWidth, float glowPower)
{
    vec2 leakPos = mix(corner, center, moveProgress);
    vec2 dir = normalize(center - corner);

    // 源效果的两束光相对中心方向各偏转 0.175 rad。
    float c = cos(0.175);
    float s = sin(0.175);
    vec2 dirA = vec2(dir.x * c + dir.y * s, -dir.x * s + dir.y * c);
    vec2 dirB = vec2(dir.x * c - dir.y * s,  dir.x * s + dir.y * c);
    vec2 perpA = vec2(-dirA.y, dirA.x);
    vec2 perpB = vec2(-dirB.y, dirB.x);

    float distA = abs(dot(uv - leakPos, perpA));
    float distB = abs(dot(uv - leakPos, perpB));
    float maskA = 1.0 - smoothstep(0.0, leakWidth, distA);
    float maskB = 1.0 - smoothstep(0.0, leakWidth, distB);
    return color * (maskA + maskB) * glowPower * moveProgress;
}

vec4 sampleDispersedA(vec2 tc, vec2 offset)
{
    return vec4(INPUT1(tc + offset).r,
                INPUT1(tc).g,
                INPUT1(tc - offset).b,
                1.0);
}

vec4 sampleDispersedB(vec2 tc, vec2 offset)
{
    return vec4(INPUT2(tc + offset).r,
                INPUT2(tc).g,
                INPUT2(tc - offset).b,
                1.0);
}

vec4 neonTransition(vec2 tc, float transitionProgress)
{
    float moveProgress = triangularPeak(transitionProgress);
    vec2 center = vec2(0.5, 0.5);
    float leakWidth = PREFIX(leakWidth);
    float glowPower = PREFIX(glowPower);

    vec3 leakColor = vec3(0.0, 0.0, 0.0);
    leakColor += neonCornerPair(tc, vec2(0.0, 0.0), center,
                                vec3(1.0, 0.2, 0.2), moveProgress, leakWidth, glowPower);
    leakColor += neonCornerPair(tc, vec2(1.0, 0.0), center,
                                vec3(0.2, 0.5, 1.0), moveProgress, leakWidth, glowPower);
    leakColor += neonCornerPair(tc, vec2(1.0, 1.0), center,
                                vec3(0.8, 0.2, 1.0), moveProgress, leakWidth, glowPower);
    leakColor += neonCornerPair(tc, vec2(0.0, 1.0), center,
                                vec3(0.2, 1.0, 0.9), moveProgress, leakWidth, glowPower);

    float glitchOffset = PREFIX(glitchIntensity) * moveProgress;
    vec2 channelOffset = vec2(glitchOffset, glitchOffset * 0.5);
    vec4 colorA = sampleDispersedA(tc, channelOffset);
    vec4 colorB = sampleDispersedB(tc, channelOffset);

    // 参考实现于正中点从 A 硬切到 B，白闪与色散遮蔽切点。
    float showB = step(0.5, transitionProgress);
    vec4 baseColor = mix(colorA, colorB, showB);
    baseColor.rgb *= 1.0 + 2.0 * moveProgress;
    baseColor.rgb += leakColor * 0.5;
    baseColor.rgb = clamp(baseColor.rgb, 0.0, 1.0);
    return baseColor;
}

vec4 FUNCNAME(vec2 tc)
{
    float timelineProgress = clamp(PREFIX(iProgress), 0.0, 1.0);
    // [@规则:R-T05] 强制闭合端点，避免边界采样或浮点误差污染 A/B。
    if (timelineProgress <= 0.0) return INPUT1(tc);
    if (timelineProgress >= 1.0) return INPUT2(tc);

    // [@动画:A-帧进度] 源 Tween 在 15%~85% 区间线性推进 Shader progress。
    float shaderProgress = clamp((timelineProgress - 0.15) / 0.70, 0.0, 1.0);
    float transitionProgress = clamp((shaderProgress - 0.10) / 0.80, 0.0, 1.0);

    vec4 colorA = INPUT1(tc);
    vec4 colorB = INPUT2(tc);
    vec4 effectColor = neonTransition(tc, transitionProgress);

    float blendIn = smoothstep(0.0, 0.10, shaderProgress);
    float blendOut = smoothstep(0.90, 1.0, shaderProgress);
    vec4 result = mix(colorA, effectColor, blendIn);
    result = mix(result, colorB, blendOut);
    return result;
}

float DrawRect(vec2 tc) {
  vec2 bl = smoothstep(vec2(-1.01, 0.0), vec2(-1.0, 0.0), tc);
  vec2 tr = smoothstep(vec2(-0.01, 0.0), vec2(0.0), 1.0 - tc);
  return bl.x * bl.y * tr.x * tr.y;
}

vec4 ScreenBlend(vec4 bg_col, vec4 fg_col) {
  return 1.0 - (1.0 - bg_col) * (1.0 - fg_col);
}

float hash11(float p) {
  p = fract(p * .1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

vec2 SmoothCurve(vec2 uv) {
  return uv * uv * (3.0 - 2.0 * uv);
}

vec2 SmoothCurve(vec2 uv, int iter) {
  for (int i = 0; i < iter; i++) {
    uv = SmoothCurve(uv);
  }
  return uv;
}

vec3 pal(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
  return a + b * cos(6.28318 * (c * t + d));
}

vec2 MosaicGlass(vec2 uv, float BlockSize) {
  vec2 tc = uv;
  float mosaicScaler = BlockSize;
  float textureResolution = 1024.0 / 2.0 * mosaicScaler;
  vec2 prop;
  if (iResolution.x < iResolution.y) {
    prop = vec2(iResolution.x / iResolution.y, 1.0);
  } else {
    prop = vec2(1.0, iResolution.y / iResolution.x);
  }
  uv = uv * vec2(textureResolution) * prop + 0.5;
  vec2 iuv = floor(uv);
  vec2 fuv = fract(uv);

  fuv = SmoothCurve(fuv, 3);
  vec2 xsq = fuv * fuv;
  vec2 xsqsq = xsq * xsq;
  fuv = xsqsq * (25.0 - 48.0 * fuv + xsq * (25.0 - xsqsq));
  fuv = SmoothCurve(fuv, 2);
  uv = iuv + fuv;
  uv = (uv - 0.5) / (textureResolution * prop);
  return uv;
}

vec4 FUNCNAME(vec2 tc) {
  int uStep = PREFIX(uStep);
  float iPro = PREFIX(iPro);
  if (uStep == 0) {
    vec4 noise = INPUT1(tc);
    float displaceVal = ((noise.r - 0.5) * 2.0);
    float displaceStrength = 20.0 / 100.0;
    float offset = mix(1.1, -0.1, iPro);
    vec2 uv = vec2(tc.x + offset, tc.y);
    vec2 displaceUV = uv + vec2(displaceStrength, 0.0) * displaceVal * step(0.5 - offset, uv.x);
    return vec4(1.0 - DrawRect(displaceUV));
  } else if (uStep == 1) {
    vec2 uv = tc;
    float BlockSize = (1.0 - min(PREFIX(BlockSize), 0.96)) * 0.3;
    BlockSize = BlockSize * step(iPro, 0.99);
    vec2 mosaicUV = MosaicGlass(uv, BlockSize);
    vec4 glassColor = INPUT1(mosaicUV);
    float iGlobalTime = PREFIX(global_time);
    vec3 col = pal(mod(mosaicUV.y + hash11(mosaicUV.x + iGlobalTime * 11.4), 1.0), 
               vec3(0.5,0.5,0.5), vec3(0.5,0.5,0.5), vec3(1.0,1.0,1.0), vec3(0.0,0.33,0.67));
    return vec4(vec3(step(glassColor.a, 250.0 / 255.0)) * col, 1.0) * glassColor.a;
  } else if (uStep == 2) {
    vec2 uv = tc;
    vec4 incol01 = INPUT1(uv);
    vec4 incol02 = INPUT2(uv);
    vec4 glass = INPUT3(uv);
    vec4 bloom = INPUT4(uv);
    bloom.rgb *= 0.8;
    float maxv = max(max(bloom.r, bloom.g), bloom.b);
    float intensity = pow(maxv, 0.5) * 1.5;
    bloom.rgb *= intensity;
    bloom = clamp(bloom, 0.0, 1.0);
    vec4 glassBloom = ScreenBlend(glass, bloom);
    vec4 retCol = mix(incol02, incol01, glass.a);
    return ScreenBlend(retCol, glassBloom);
  }
}

