vec3 sampleTarget(vec2 uv, float offset) {
    vec3 color = INPUT2(uv).rgb;
    color += INPUT2(uv + vec2(offset, 0.0)).rgb;
    color += INPUT2(uv - vec2(offset, 0.0)).rgb;
    color += INPUT2(uv + vec2(0.0, offset)).rgb;
    color += INPUT2(uv - vec2(0.0, offset)).rgb;
    return color * 0.2;
}

int gridOrder(int x, int y) {
    if (x == 0 && y == 2) return 0;
    if (x == 1 && y == 2) return 1;
    if (x == 2 && y == 2) return 2;
    if (x == 2 && y == 1) return 3;
    if (x == 2 && y == 0) return 4;
    if (x == 1 && y == 0) return 5;
    if (x == 0 && y == 0) return 6;
    if (x == 0 && y == 1) return 7;
    if (x == 1 && y == 1) return 8;
    return 0;
}

float sourceProgress(float timelineProgress) {
    // [@动画:A-帧进度] 参考包：0~15% 停留 A，15%~85% 线性过渡，85%~100% 停留 B。
    if (timelineProgress <= 0.15) return 0.0;
    if (timelineProgress >= 0.85) return 1.0;
    return (timelineProgress - 0.15) / 0.70;
}

vec4 nineGridTransition(vec2 tc, vec4 colorA, vec4 colorB, float progress) {
    if (progress <= 0.0) return colorA;
    if (progress >= 1.0) return colorB;

    float globalFadeIn = smoothstep(0.0, 1.0 / 9.0, progress);
    vec2 gridUv = clamp(tc, 0.0, 1.0) * 3.0;
    int x = min(int(floor(gridUv.x)), 2);
    int y = min(int(floor(gridUv.y)), 2);
    int order = gridOrder(x, y);
    vec2 blockUv = fract(gridUv);

    float startTime = float(order) / 9.0;
    float blockProgress = clamp((progress - startTime) * 9.0, 0.0, 1.0);

    float luma = dot(colorA.rgb, vec3(0.299, 0.587, 0.114));
    vec3 grayA = vec3(luma);
    vec3 baseA = mix(colorA.rgb, grayA, globalFadeIn);

    float blurOffset = 0.005 * (1.0 - smoothstep(0.0, 0.7, blockProgress));
    vec3 blurredB = sampleTarget(tc, blurOffset);
    vec3 result = mix(baseA, blurredB, blockProgress);

    float leak = smoothstep(0.0, 0.3, blockProgress) *
                 smoothstep(1.0, 0.3, blockProgress);
    result += vec3(1.0, 0.4, 0.1) * leak * PREFIX(LeakIntensity);

    float noise = fract(sin(dot(tc + progress, vec2(12.9898, 78.233))) * 43758.5453);
    result += (noise - 0.5) * PREFIX(GrainIntensity) *
              (1.0 - blockProgress) * globalFadeIn;

    float currentGap = PREFIX(GapWidth) * globalFadeIn * step(progress, 8.0 / 9.0);
    float isGap = step(blockUv.x, currentGap) +
                  step(1.0 - blockUv.x, currentGap) +
                  step(blockUv.y, currentGap) +
                  step(1.0 - blockUv.y, currentGap);
    result = mix(result, vec3(0.0), clamp(isGap, 0.0, 1.0));
    return vec4(clamp(result, 0.0, 1.0), 1.0);
}

vec4 FUNCNAME(vec2 tc) {
    float timelineProgress = clamp(PREFIX(iProgress), 0.0, 1.0);
    vec4 colorA = INPUT1(tc);
    vec4 colorB = INPUT2(tc);

    // [@规则:R-T05] 先闭合标准转场端点，再进入参考包的九宫格时间轴。
    if (timelineProgress <= 0.0) return colorA;
    if (timelineProgress >= 1.0) return colorB;

    float progress = sourceProgress(timelineProgress);
    const float fadeInEnd = 0.1;
    const float fadeOutStart = 0.9;
    float transitionProgress = clamp((progress - fadeInEnd) /
                                     (fadeOutStart - fadeInEnd), 0.0, 1.0);
    vec4 transitionColor = nineGridTransition(tc, colorA, colorB, transitionProgress);
    float blendIn = smoothstep(0.0, fadeInEnd, progress);
    float blendOut = smoothstep(fadeOutStart, 1.0, progress);
    vec4 result = mix(colorA, transitionColor, blendIn);
    return mix(result, colorB, blendOut);
}

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

