vec2 rotate2D(vec2 _st, float _angle, float aspt,vec2  blurCenter)
{
    _st.x  -= blurCenter.x;
    _st.y  -= blurCenter.y;
    _st.x  = _st.x * aspt;
    _st 	 = mat2(cos(_angle),-sin(_angle),sin(_angle),cos(_angle))*_st;
    _st.x  = _st.x / aspt;
    _st.x	 += blurCenter.x;
    _st.y  += blurCenter.y;
    return _st;
}

vec4 CreateDstColor(float process, int num, float rightAngle, float deltAngle, float r, vec2 blurCenter, vec2 iResolution, float leftAngle)
{
    vec4  rightColor = vec4(0.0);
    vec4  leftColor  = vec4(0.0);
    if(process < 0.5)
    {
      for(int i = 0; i < num; i++)
      {
          rightAngle += deltAngle;
          float rightNewX = r*cos(rightAngle) + blurCenter.x;
          float rightNewY = r*sin(rightAngle) + blurCenter.y;           
          rightColor += INPUT1(vec2(rightNewX,rightNewY)/iResolution);

          leftAngle -= deltAngle;
          float leftNewX = r*cos(leftAngle) + blurCenter.x;
          float leftNewY = r*sin(leftAngle) + blurCenter.y;          
          leftColor += INPUT1(vec2(leftNewX,leftNewY)/iResolution);
      }
    }else
    {
      for(int i = 0; i < num; i++)
      {
          rightAngle += deltAngle;
          float rightNewX = r*cos(rightAngle) + blurCenter.x;
          float rightNewY = r*sin(rightAngle) + blurCenter.y;           
          rightColor += INPUT2(vec2(rightNewX,rightNewY)/iResolution);

          leftAngle -= deltAngle;
          float leftNewX = r*cos(leftAngle) + blurCenter.x;
          float leftNewY = r*sin(leftAngle) + blurCenter.y;          
          leftColor += INPUT2(vec2(leftNewX,leftNewY)/iResolution);
      }
    }

    rightColor /= float(num);
    leftColor  /= float(num);
    return (rightColor+leftColor)/2.0;
}

float sdBox(vec2 p, vec2 b)
{
	vec2 d = abs(p) - b;
    return length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0);
}

mat2 rotate2d(float _angle){
    return mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle));
}

