	if (point.x < 0.0 || point.y < 0.0 || point.x > 1.0 || point.y > 1.0)
	{
		return seeThroughWithShadow(tc, yc, texCoord, point, rotation, rrotation, cylinderAngle, amount);
	}

	vec4 color = backside(yc, point);

	vec4 otherColor;
	if (yc < 0.0)
	{
		float shado = 1.0 - (sqrt(pow(point.x - 0.5, 2.0) + pow(point.y - 0.5, 2.0)) / 0.71);
		shado *= pow(-yc / cylinderRadius, 3.0);
		shado *= 0.5;
		otherColor = vec4(0.0, 0.0, 0.0, shado);
	}
	else
	{
		otherColor = INPUT1(texCoord);
	}

	color = antiAlias(color, otherColor, cylinderRadius - abs(yc));

	vec4 cl = seeThroughWithShadow(tc, yc, texCoord, point, rotation, rrotation, cylinderAngle, amount);
	float dist = distanceToEdge(point);

	return antiAlias(color, cl, dist);
}

vec4 FUNCNAME(vec2 tc) {
    float p = clamp(PREFIX(iProgress), 0.0, 1.0);

    // 横向推进的软折线；折线两侧分别压缩 A、展开 B，形成翻页式拉伸。
    float fold = smoothstep(0.0, 1.0, p * 2.0 + tc.x - 1.0);
    vec2 centered = tc - vec2(0.5, 0.5);
    vec2 uvA = centered * (1.0 - fold) + vec2(0.5, 0.5);
    vec2 uvB = centered * fold + vec2(0.5, 0.5);

    // [@规则:R-T05] p=0 时 fold=0，仅 A；p=1 时 fold=1，仅 B。
    return mix(INPUT1(uvA), INPUT2(uvB), fold);
}

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
  vec2 p1 = vec2(p.x, p.y);
  vec2 p2 = vec2(p.z, p.w);
  float mX1 = p1.x;
  float mY1 = p1.y;
  float mX2 = p2.x;
  float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;

  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec2 rotateFunc(vec2 uv, vec2 center, float theta, vec2 resolution)
{
  vec2 tc = uv - center;
  tc.y *= resolution.y / resolution.x;
  vec2 temp;
  temp.x = dot(vec2(cos(theta), -sin(theta)), tc);
  temp.y = dot(vec2(sin(theta), cos(theta)), tc);
  temp.y /= resolution.y / resolution.x;
  temp += center;
  return temp;
}

