float easeOutExpo(float x) {
    return x == 1.0 ? 1.0 : 1.0 - pow(2.0, -10.0 * x);
}

vec4 pan(vec2 tc, float process) {
    vec4 fragColor = vec4(0.0);
    process = easeOutExpo(process);
    if (tc.x < (1.0 - process)) {
        fragColor = INPUT1(tc); 
    } else {
        tc.x = tc.x - (1.0 - process);
        fragColor = INPUT2(tc);
    }
    return fragColor;
}


vec4 FUNCNAME(vec2 tc) {
