    float totalTime = PREFIX(total_time);

    float duration_ratio = 0.5;
    float delay_ratio = (1.0 - duration_ratio) * 0.5;
    float iPro = clamp((iGlobalTime - totalTime * delay_ratio) / (totalTime * duration_ratio), 0.0, 1.0);

    vec2 uv = tc;
    vec4 retCol = vec4(0.0);
    float process = 0.0;
    if(iPro < 0.2){
        process = iPro / 0.2;
        retCol = INPUT1(uv);
    }else if(iPro < 0.8){
        process = (iPro - 0.2) / 0.6;
        retCol = pan(uv, process);
    }else{
        retCol = INPUT2(uv);
    }   
    return retCol; 
}

// ==========================================
// Panel Collapse Transition
// 3 portrait cards with rounded corners arranged in a fan arc.
// Cards slide left along the arc path:
//   Card 1 exits left, Card 2 -> Card 1 pos,
//   Card 3 -> Card 2 pos, new card enters from right.
// Full screen -> fan cards -> arc slide -> zoom back to full.
// ==========================================

// Rounded rectangle SDF
float roundedBoxSDF(vec2 center, vec2 halfSize, float radius) {
    vec2 d = abs(center) - halfSize + radius;
    return length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0) - radius;
}

// Rotate point around pivot
vec2 rotatePoint(vec2 pt, vec2 pivot, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    vec2 d = pt - pivot;
    return vec2(d.x * c - d.y * s, d.x * s + d.y * c) + pivot;
}

vec4 FUNCNAME(vec2 tc) {
    // Animation parameters from effect
    float anim01 = PREFIX(Anim01);   // Phase 1: Full screen -> fan cards
    float anim02 = PREFIX(Anim02);   // Phase 2: Slide along arc
    float anim03 = PREFIX(Anim03);   // Phase 3: Zoom center card to full
    float anim04 = PREFIX(Anim04);   // Phase 4: Settle
    float eItime = PREFIX(eItime);

    // User parameters
    float strength = float(PREFIX(Strength)) / 100.0;
    float scaleParam = float(PREFIX(Scale)) / 100.0;

    float time = float(PREFIX(global_time)) / max(float(PREFIX(total_time)), 1.0);
    float aspect = iResolution.x / iResolution.y;

    // Aspect correction: designed for 16:9, scale to preserve physical proportions
    float designAspect = 16.0 / 9.0;
    float aspectScale = sqrt(aspect / designAspect);

    // ── Card dimensions (portrait orientation) ── corrected for aspect
    float cardW = (0.13 + scaleParam * 0.04) / aspectScale;
    float cardH = (0.27 + scaleParam * 0.06) * aspectScale;
    float cornerRadius = 0.018;

    // Full-screen card dimensions: must cover entire [0,1]² screen for any aspect
    float fullScreenW = max(0.5, 0.5 * aspect);
    float fullScreenH = max(0.5, 0.5 / aspect);

    // ── Fan arc parameters ──
    // Cards sit on a circular arc whose center is below the screen.
    // arcRadius controls curvature; angleSpacing controls spread.
    float arcRadius = 1.8 - strength * 0.5;
    vec2 arcCenter = vec2(0.5, 0.5 - arcRadius);  // Keeps center card at y≈0.5
    float angleSpacing = (0.19 + strength * 0.07) / aspectScale;   // Angular gap between cards

    // ── Phase logic ──
    float fanAmount   = 0.0;   // 0 = full screen, 1 = fan layout
    float scrollOffset = 0.0;  // 0 = initial, 1 = shifted by 1 card
    float zoomAmt     = 0.0;   // 0 = card view, 1 = full screen again

    if (time < 0.22) {
        // Phase 1: Full screen shrinks into 3 fan cards
        fanAmount = anim01;
    } else if (time < 0.66) {
        // Phase 2: Cards 1-3 slide together, new card 4 enters with delay
        fanAmount = 1.0;
        scrollOffset = anim02;
    } else if (time < 0.72) {
        // Brief hold — all cards settled
        fanAmount = 1.0;
        scrollOffset = 1.0;
    } else {
        // Phase 3: Center card zooms back to full screen (0.72-1.0)
        fanAmount = 1.0;
        scrollOffset = 1.0;
        zoomAmt = anim03;
    }

    // ── Early outs ──
    if (zoomAmt > 0.995) {
        return INPUT2(tc);
    }
    if (fanAmount < 0.005 && zoomAmt < 0.005) {
        return INPUT1(tc);
    }

    // Transparent background — lets lower track show through
    vec4 result = vec4(0.0, 0.0, 0.0, 0.0);

    // ══════════════════════════════════════════
    // Draw 5 virtual card slots (back → front)
    // Slot indices: 0=far-left  1=left  2=center  3=right  4=far-right
    // Initially visible: slots 1, 2, 3
    // After scroll by 1: slots 2, 3, 4 become visible
    // Draw order: 4 → 3 → 2 → 1 → 0  (left cards on top)
    // ══════════════════════════════════════════

    for (int drawIdx = 0; drawIdx < 5; drawIdx++) {
        int slotIdx = 4 - drawIdx;  // Draw right-to-left: left on top
        float fSlot = float(slotIdx);

        // ── Per-card scroll with speed contrast ──
        // Card 1: ease-in (accelerate out) — rushes off screen
        // Card 2,3: linear normal movement
        // Card 4: ease-out (decelerate in) — drifts in slowly
        float perCardScroll = scrollOffset;
        if (slotIdx == 1) {
            // Accelerating exit: aggressive cubic ease-in — snaps out fast
            perCardScroll = scrollOffset * scrollOffset * scrollOffset*5.0;
        } else if (slotIdx == 4) {
            // Delayed decelerating entry: starts at scrollOffset=0.55, eases in
            // smoothstep: 0.55 < 1.0 ✓
            float delayed = smoothstep(0.6, 1.0, scrollOffset);
            perCardScroll = 1.0 - (1.0 - delayed) * (1.0 - delayed);
        }
        // slots 2,3 keep perCardScroll = scrollOffset (linear)
        float shiftedSlot = fSlot - perCardScroll;

        // Skip cards far off screen
        if (shiftedSlot < 0.2 || shiftedSlot > 3.8) continue;

        // Position relative to center (slot 2 = center = 0.0)
        float posFromCenter = shiftedSlot - 2.0;

        // ── Arc-based positioning ──
        // theta = angular offset from arc apex
        float theta = posFromCenter * angleSpacing;
        float cx = arcCenter.x + arcRadius * sin(theta);
        float cy = arcCenter.y + arcRadius * cos(theta);

        // Card rotation follows the arc tangent direction
        // Negate so left card leans left, right card leans right (fan-out)
        // 0.75 dampening for a more natural look (like Split Dimension's 0.6)
        float cardAngle = -theta * 0.75;

        // ── Size compensation: center larger to balance tilted side cards ──
        float posAbs = min(abs(clamp(posFromCenter, -1.5, 1.5)), 1.0);
        float sizeScale = mix(0.9, 0.85, posAbs);

        float scaledCardW = cardW * sizeScale;
        float scaledCardH = cardH * sizeScale;

        // ── Side cards fade in during fan-out ──
        float cardOpacity = 1.0;
        if (abs(posFromCenter) > 0.5) {
            // edge0 < edge1 ✓
            cardOpacity = smoothstep(0.0, 0.4, fanAmount);
        }

        // ── Phase 3: reverse Phase 1 for zoom card ──
        bool isZoomCard = (abs(posFromCenter) < 0.5);
        float effFan = fanAmount;
        if (isZoomCard && zoomAmt > 0.001) {
            effFan = 1.0 - zoomAmt;
        }

        // ── Lerp from full-screen to card layout ──
        vec2 cardPos = mix(vec2(0.5, 0.5), vec2(cx, cy), effFan);
        float cardRot = cardAngle * effFan;
        // Zoom card: target 0.5 so UV naturally converges to tc
        float targetW = (isZoomCard && zoomAmt > 0.001) ? 0.5 : fullScreenW;
        float targetH = (isZoomCard && zoomAmt > 0.001) ? 0.5 : fullScreenH;
        float cardSzW = mix(targetW, scaledCardW, effFan);
        float cardSzH = mix(targetH, scaledCardH, effFan);
        float cRadius = mix(0.0, cornerRadius, effFan);

        // Fade non-zoom cards during zoom-out
        float cAlpha = cardOpacity;
        if (!isZoomCard && zoomAmt > 0.001) {
            cAlpha *= max(1.0 - zoomAmt * 2.0, 0.0);
        }
        if (cAlpha < 0.01) continue;

        // ── Content assignment ──
        // Odd slots (1, 3) → INPUT2;  Even slots (0, 2, 4) → INPUT1
        // Initially: Card1(slot1)=INPUT2, Card2(slot2)=INPUT1, Card3(slot3)=INPUT2
        bool useInput2 = (mod(fSlot, 2.0) >= 0.5);

        // ── Hit-test: rotate screen coord into card's local space ──
        // Correct for aspect ratio: convert to physical space before rotation
        vec2 tcAspect = vec2((tc.x - cardPos.x) * aspect, tc.y - cardPos.y);
        float cRot = -cardRot;
        float cosR = cos(cRot);
        float sinR = sin(cRot);
        vec2 rotAspect = vec2(tcAspect.x * cosR - tcAspect.y * sinR,
                              tcAspect.x * sinR + tcAspect.y * cosR);
        // Convert back to normalized space
        vec2 localPos = vec2(rotAspect.x / aspect, rotAspect.y);

        vec2 halfSz = vec2(cardSzW, cardSzH);
        float dist = roundedBoxSDF(localPos, halfSz, cRadius);

        if (dist < 0.015) {
            // ── Map local position to card UV [0,1] — unified for all cards ──
            vec2 cardUV = vec2(localPos.x / cardSzW, localPos.y / cardSzH) * 0.5 + 0.5;

            // Cover-fit: preserve input aspect ratio, crop excess
            float ratio = cardSzW / max(cardSzH, 0.001);
            if (ratio < 1.0) {
                cardUV.x = (cardUV.x - 0.5) * ratio + 0.5;
            } else {
                cardUV.y = (cardUV.y - 0.5) / ratio + 0.5;
            }
            cardUV = clamp(cardUV, vec2(0.0), vec2(1.0));

            // ── Sample texture ──
            vec4 texColor = vec4(0.0);
            if (isZoomCard && zoomAmt > 0.001) {
                texColor = INPUT2(cardUV);
            } else if (useInput2) {
                texColor = INPUT2(cardUV);
            } else {
                texColor = INPUT1(cardUV);
            }

            // Anti-aliased edge — resolution-based width (compatible with all GPUs)
            float aaWidth = 1.5 / min(iResolution.x, iResolution.y);
            float aa = 1.0 - smoothstep(-aaWidth, aaWidth, dist);
            float finalAlpha = aa * cAlpha * texColor.a;

            result.rgb = mix(result.rgb, texColor.rgb, finalAlpha);
            result.a = result.a + finalAlpha * (1.0 - result.a);
        }
    }

    return result;
}

customize_in vec2 vUVOverW;
customize_in float vInvW;
customize_in float vPhase;

vec4 FUNCNAME(vec2 tc) {
    float progress = clamp(PREFIX(iProgress), 0.0, 1.0);
    int meshMode = PREFIX(uMeshMode);
    // [@规则:R-T05] 整屏直通：起点只显示 A，闭合段只显示 B。
    if (meshMode == 0) {
        if (progress <= 0.00001) {
            return INPUT1(tc);
        }
        return INPUT2(tc);
    }
    vec2 uv = vUVOverW / max(vInvW, 0.000001);
    uv = clamp(uv, vec2(0.0, 0.0), vec2(1.0, 1.0));
    if (vPhase < 0.5) {
        // [@规则:R-T04] 正面固定采样 A/INPUT1。
        return INPUT1(uv);
    }

    // 背面 V 已在 mesh 里按条带对调，180° 终态直接采 B 正向。
    return INPUT2(uv);
}

