}

float boxSDF(vec2 centerPos, vec2 size) {
    vec2 d = abs(centerPos) - size;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

vec2 fisheyeDistortion(vec2 uv, float strength) {
    vec2 center = vec2(0.5, 0.5);
    vec2 delta = uv - center;
    float dist = length(delta);
    float distortion = 1.0 + strength * dist * dist;
    return center + delta * distortion;
}

vec2 figure8Path(float t) {
    float x = sin(t);
    float y = sin(t) * cos(t);
    return vec2(x, y) * 0.04;
}

float getRadialScale(vec2 uv) {
    vec2 center = vec2(0.5, 0.5);
    float dist = length(uv - center);
    float maxDist = 0.707;
    float normalizedDist = clamp(dist / maxDist, 0.0, 1.0);
    return mix(1.0, 1.5, normalizedDist);
}

vec4 renderBox(vec2 tc, float boxSize, float borderWidth, float fisheyeStrength, 
               vec2 boxOffset, float xOffset, bool useInput1, float litAlpha) {
    vec2 uv = tc;
    uv.x += xOffset;

    vec2 distortedUV = fisheyeDistortion(uv, fisheyeStrength * 0.5);

    float radialScale = getRadialScale(distortedUV);
    vec2 imageOffset = boxOffset * radialScale;
    vec2 imageUV = distortedUV - imageOffset;

    vec2 centeredDistortedUV = distortedUV - 0.5 - boxOffset;

    vec2 boxHalfSize = vec2(boxSize * 0.5);
    float boxDist = boxSDF(centeredDistortedUV, boxHalfSize);

    float aaWidth = 0.001;
    float boxMask = 1.0 - smoothstep(-aaWidth, aaWidth, boxDist);

    float outerBoxDist = boxSDF(centeredDistortedUV, boxHalfSize + borderWidth);
    float outerBoxMask = 1.0 - smoothstep(-aaWidth, aaWidth, outerBoxDist);
    float borderMask = outerBoxMask - boxMask;
    if (outerBoxMask < 0.01) {
        return vec4(0.0);
    }

    vec4 color = vec4(0.0);

    if (boxMask > 0.01) {
        if (imageUV.x >= 0.0 && imageUV.x <= 1.0 && imageUV.y >= 0.0 && imageUV.y <= 1.0) {
            color = useInput1 ? INPUT1(imageUV) : INPUT2(imageUV);

            vec2 litUV = distortedUV - boxOffset;
            if (litUV.x >= 0.0 && litUV.x <= 1.0 && litUV.y >= 0.0 && litUV.y <= 1.0) {
                vec4 litTexture = INPUT3(litUV);
                color.rgb += litTexture.rgb * litTexture.a * 0.5 * litAlpha;
            }

            color.a *= boxMask;
        }
    }

    if (borderMask > 0.01) {
        vec3 borderColor = vec3(1.0);
        color.rgb = mix(color.rgb, borderColor, borderMask);
        color.a = max(color.a, borderMask);
    }

    return color;
}

