float bezier(float t) {
    float p0 = 0.0;
    float p1 = 0.0;
    float p2 = 0.05;
    float p3 = 1.0;

    float q0 = mix(p0, p1, t);
    float q1 = mix(p1, p2, t);
    float q2 = mix(p2, p3, t);

    float r0 = mix(q0, q1, t);
    float r1 = mix(q1, q2, t);

    return mix(r0, r1, t);
}
vec4 FUNCNAME(vec2 tc)
{
    float Strength = 100.0;
    float Speed = 60.0;
    float progress = PREFIX(global_time)/PREFIX(total_time);


    vec2 prop = vec2(1.0, iResolution.y / iResolution.x);
    if(iResolution.y > iResolution.x){ 
        prop = vec2(iResolution.x / iResolution.y, 1.0);
    }

    vec4 resColor;
    vec2 uv = tc;
    vec2 offset = vec2 (0.5,0.5);
    vec2 ndcPos = uv - offset;
    float aspect = prop.x/ prop.y;

    float u_angle =  ((Strength/1.6)-(progress*Speed))/100.0;
    u_angle = max(u_angle,0.01);
    float eye_angle = abs(u_angle);
    float half_angle = eye_angle*2.0;
    float half_dist = tan(half_angle);
    vec2  vp_scale = vec2(aspect, 1.0);

    vec2  P = ndcPos * vp_scale; 
    float vp_dia   = length(vp_scale);
    float rel_dist = length(P) / vp_dia;  
    vec2  rel_P = normalize(P) / normalize(vp_scale);
    vec2 pos_prj = ndcPos;

    float beta = rel_dist * half_angle;
    pos_prj = rel_P * tan(beta*1.5) / half_dist*2.0;  
    vec2 uv_prj = pos_prj/3.0 + offset;

    vec4 resColor1 = INPUT1(uv_prj.st);
    vec4 resColor2 = INPUT2(uv_prj.st);
    resColor = mix(resColor1, resColor2, bezier(progress));

	return resColor;
}

customize_in vec2 outUV;
vec2 GetSuCaiUV(vec2 tc, vec2 OrigResolution, vec2 SuCaiResolution, vec2 ResizeResolution, float NormalScale)
{
    vec2 WenLiFragCoord = tc * OrigResolution;
    vec2 sucaiUV = (WenLiFragCoord - ResizeResolution) / (SuCaiResolution * NormalScale) + vec2(0.5);
    return sucaiUV;
}
vec2 SucaiUVs(vec2 uv, vec2 SuCaiResolution, float positionX, float range, float sucaiScale)
{
    vec2 OirgResolution = vec2(iResolution.x, iResolution.y);
    vec2 ResizeResolution = OirgResolution * 0.5;
    float scale = 1.0;
    float OirgRatio = OirgResolution.x / OirgResolution.y;
    float SuCaiRatio = SuCaiResolution.x / SuCaiResolution.y;
    if (OirgRatio >= SuCaiRatio)
    {
        scale = OirgResolution.x / SuCaiResolution.x;
    }
    else
    {
        scale = OirgResolution.y / SuCaiResolution.y;
    }
    vec2 sucaiUV = GetSuCaiUV(uv, OirgResolution, SuCaiResolution, ResizeResolution, scale * sucaiScale);
    float range1 = 1.0 * range;
    sucaiUV.x += positionX;
    sucaiUV = sucaiUV * range1 + (1.0 - range1) * 0.5;
    sucaiUV.y = 1.0 - sucaiUV.y;
    return sucaiUV;
}

vec2 GetScaleResult(vec2 uv, float scale)
{
    vec2 center = vec2(0.5, 0.5);
    uv = uv - center;
    uv = uv * scale;
    uv = uv + center;
    return uv;
}

vec4 lut3DFilter(vec4 textureColor, float opacity)
{
    float blueColor = textureColor.r * 63.0;
    vec2 quad1;
    quad1.y = floor(floor(blueColor) / 8.0);
    quad1.x = floor(blueColor) - (quad1.y * 8.0);
    vec2 quad2;
    quad2.y = floor(ceil(blueColor) / 8.0);
    quad2.x = ceil(blueColor) - (quad2.y * 8.0);
    vec2 texPos1;
    texPos1.x = (quad1.x * 1.0 / 8.0) + 0.5 / 512.0 + ((1.0 / 8.0 - 1.0 / 512.0) * textureColor.b);
    texPos1.y = (quad1.y * 1.0 / 8.0) + 0.5 / 512.0 + ((1.0 / 8.0 - 1.0 / 512.0) * textureColor.g);
    vec2 texPos2;
    texPos2.x = (quad2.x * 1.0 / 8.0) + 0.5 / 512.0 + ((1.0 / 8.0 - 1.0 / 512.0) * textureColor.b);
    texPos2.y = (quad2.y * 1.0 / 8.0) + 0.5 / 512.0 + ((1.0 / 8.0 - 1.0 / 512.0) * textureColor.g);
    vec4 newColor1 = INPUT5(texPos1);
    vec4 newColor2 = INPUT5(texPos2);
    vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
    vec4 fragOutCol = vec4(mix(textureColor.rgb, newColor.rgb, opacity), textureColor.a);
    fragOutCol.rgb *= fragOutCol.a;
    return fragOutCol;
}



