        fragColors = INPUT1(uv);
        vec4 OrigiGray = INPUT2(uv);
        vec4 sucai = INPUT5(vec2(uv.x, 1.0 - uv.y));

        fragColors = mix(OrigiGray, fragColors, sucai.a);

        vec4 white = vec4(1.0);
