        }
        else if(uiPro < 0.14){
            fragColors = fragColors;
        }else if(uiPro < 0.9){
            fragColors = fragColors;
        }else if(uiPro < 1.0){
            float t = (uiPro - 0.9) / 0.1;
            fragColors = mix(fragColors, INPUT4(uv), t);
