vec4 imageRand(vec4 l, vec4 k){
	return  vec4(min(1.0, l.r + k.r), min(1.0, l.g + k.g), min(1.0, l.b + k.b), min(1.0, l.a + k.a));
}
vec4 ReadLocalTexture1(vec2 tc){
    float aspect = iResolution.x / iResolution.y;
    float anim05 =PREFIX(Anim05);
    vec2 uv = vec2(tc.x - 0.5, tc.y - 0.5);
    vec2 texResolution = vec2(1920.0, 1080.0);
    if(aspect < 1.0){
        uv.x *= (texResolution.y / texResolution.x) * aspect;
    }else{
        uv.y *= (texResolution.x / texResolution.y) * (1.0 / aspect);
    }
    uv = vec2(uv.x + 0.5, uv.y + 0.5);
    vec4 res = INPUT3(vec2(uv.x,1.0-  uv.y));
    res.rgb *= res.a;
    return res;
}
vec4 step0(vec2 tc, float anim01, float anim02,float time,float clItime){

    vec2 offset = vec2(0.5);
    vec4 color01;
    vec2 uv = tc;
    int samples = 10;
    vec4 result = vec4(0.0);
    uv-=offset;

    if(time<1.0){
        uv/=mix(1.0,0.2,anim01);
    }else{
        uv/=mix(3.0,1.0, anim02);
    }
    uv+=offset;
    color01 =ReadLocalTexture1(uv);

    if(time<1.0){
        result = INPUT1(uv);
        result = imageRand(result,color01);
    }else{
        result = INPUT2(uv);
        result = imageRand(result,color01);
    }
    return result;
}
vec4 step1(vec2 tc,float anim03, float clItime){
    vec2 offset = vec2(0.5);
    float time = clItime;

    float scale = 1.0 ;
    vec2 uv = tc;
    int samples = 10;
    vec4 result = vec4(0.0);
    for (int i = 0; i < samples; i++)
    {   
        uv-=offset;
        if(time<0.5){
            uv*=mix(1.0,1.1,anim03);
        }else{
            uv/=mix(1.1,1.0,anim03);
        }
        uv+=offset;
        result += INPUT1(uv);
    }
    result = result / float(samples);
    return result;
}
vec4 FUNCNAME (vec2 tc){
    float clItime = PREFIX(progress);
    float clItime2 = PREFIX(progress2);
    float clItime3 = PREFIX(progress3);
    float anim01 =PREFIX(Anim01);
    float anim02 =PREFIX(Anim02);
    float anim03 =PREFIX(Anim03);
    float anim04 =PREFIX(Anim04);

    float blurAmount = 0.04* anim04 * (1.0 - anim04); 
    float angle = mix(0.0,1380.0,anim04);
    vec2 rotationDirection = vec2( sin(angle * PI / 180.0),-cos(angle * PI / 180.0));
    vec2 blurredUV = tc + rotationDirection * blurAmount;

    int Type = PREFIX(Type);
