            overlayCol = INPUT7(uv)*matt;
            maskColor = INPUT8(uv)*matt;    
        }else{
            uv.y = 1.0 - uv.y;
            overlayCol = INPUT4(uv)*matt;
            maskColor = INPUT6(uv)*matt;
        }
        if(iPro < 1.0) fragColor = mix(blurColor, fragColor, maskColor.a);

        fragColor = mix(fragColor, overlayCol, overlayCol.a);
        return fragColor;
    }

}

#define PI 3.14159265
vec2 rotate(vec2 videoImageCoord, vec2 centerImageCoord, float radianAngle)
{
    mat2 rotateMat = mat2(cos(radianAngle),sin(radianAngle),
                        -sin(radianAngle),cos(radianAngle));
    vec2 deltaOffset = rotateMat * (videoImageCoord - centerImageCoord);
    videoImageCoord = deltaOffset + centerImageCoord;
    return videoImageCoord;
}
vec4 FUNCNAME(vec2 tc) {

    int stepType = PREFIX(stepType);
    if(stepType == 1){
        return INPUT2(tc);
    }else{
        float blur_pro = PREFIX(blur_pro);
        float iGlobalTime = PREFIX(global_time);
        float iPro = PREFIX(iPro);
        vec2 org_tc = tc;
        if(iPro > 0.82){
            float progress = (iPro - 0.82) / 0.18;
            tc = (tc - vec2(0.5)) * (1.0 - 0.27*progress) + vec2(0.5);
        }

        vec2 uv = tc;
        uv = (uv - 0.5) * (1.4) + 0.5;    
        uv.y += 0.001;

        vec4 textureColor = vec4(0.0);
        if(iResolution.x >= iResolution.y){
            textureColor = INPUT3(vec2(tc.x, 1.0 - tc.y));
            float uOffsetX = PREFIX(uOffsetX);
            float uOffsetY = PREFIX(uOffsetY);
            uv.x += uOffsetX;
            uv.y += uOffsetY;
        }else{
            textureColor = INPUT3(vec2(tc.y, 1.0 - tc.x));  
            float uOffsetX = PREFIX(uOffsetY);
            float uOffsetY = PREFIX(uOffsetX);
            uv.x += uOffsetX;
            uv.y += uOffsetY;
        }

        float uv_scale = 0.5 - 0.5 + 0.1;
        uv = (uv - 0.5) * (1.0 - 1.0*uv_scale) + 0.5;

        vec2 rotateCenter = vec2(0.5)*iResolution.xy;
        // uv = rotate(uv*iResolution.xy, rotateCenter, -PI * 0.0061)/iResolution.xy;
        float rotateAngle = -PI * 0.0061;
        if(iResolution.x < iResolution.y){
          rotateAngle = -rotateAngle;
        }
        uv = rotate(uv*iResolution.xy, rotateCenter, rotateAngle)/iResolution.xy;


        vec4 fragColor = INPUT1(uv);
        if(blur_pro > 0.0){
            fragColor = INPUT2(uv);
        }    
        float opacity = 1.0;
        if(iPro > 0.88){
            float progress = (iPro - 0.88) / 0.12;
            opacity = 1.0 - progress;
        }
        fragColor = mix(fragColor, INPUT1(org_tc), 1.0 - opacity);
        fragColor = mix(fragColor, textureColor, textureColor.a * opacity);
        return fragColor;
    }


}

vec2 RotateFunc(vec2 iuv, float angle, vec2 icenter) {
  vec2 rotateUV = iuv * iResolution;
  vec2 center = icenter;
  float rotation = angle;
  rotateUV -= center * iResolution;
  vec4 rotateMat = vec4(cos(rotation), -sin(rotation), sin(rotation), cos(rotation));
  float new_x = rotateUV.x*rotateMat.x + rotateUV.y*rotateMat.z;
  float new_y = rotateUV.x*rotateMat.y + rotateUV.y*rotateMat.w;
  rotateUV = vec2(new_x, new_y);
  rotateUV += center * iResolution;
  rotateUV = rotateUV / iResolution;

  return rotateUV;
}

