vec4 FUNCNAME(vec2 tc)
{   
  vec4 fragOutCol = vec4(0.0, 0.0, 0.0, 1.0);
  vec2 center = vec2(0.5);
  float iGlobalTime = PREFIX(global_time) / PREFIX(total_time);
  vec2 uv = tc;
  float PI = 3.14159265;
  float process = iGlobalTime;

  float zp = exp(-15.0*pow(abs(2.0*iGlobalTime-1.0), 20.0));
  vec2 zoom_uv = uv;
  float zoom_scale = 1.15;
  zoom_uv = (zoom_uv-center) * mix(1.0, zoom_scale, zp) + center;

  vec2 zoom_uv_mask = uv;
  float zoom_mask_scale = 35.0 * (iResolution.x / 480.0);
  zoom_uv_mask.x = (zoom_uv_mask.x-0.5) * mix(1.0, 1.0 + zoom_mask_scale / iResolution.x, zp) + 0.5;
  zoom_uv_mask.y = (zoom_uv_mask.y-0.5) * mix(1.0, 1.0 + zoom_mask_scale / iResolution.y, zp) + 0.5;

  if (PREFIX(uStep) == 1) {
    vec4 fg = INPUT1(zoom_uv);
    fg.rgb = fg.rgb * Corner(zoom_uv_mask * iResolution.xy, 1.0) * 
              step(0.0, zoom_uv_mask.x) * step(zoom_uv_mask.x, 1.0) * 
              step(0.0, zoom_uv_mask.y) * step(zoom_uv_mask.y, 1.0);

    vec4 bg = INPUT2(zoom_uv);
    bg.rgb = bg.rgb * Corner(zoom_uv_mask * iResolution.xy, 1.0) * 
              step(0.0, zoom_uv_mask.x) * step(zoom_uv_mask.x, 1.0) * 
              step(0.0, zoom_uv_mask.y) * step(zoom_uv_mask.y, 1.0);

    fragOutCol = bg;
    fragOutCol.a = min(1.0, fg.a + bg.a);
  } else {
    vec4 layer_1 = INPUT1(zoom_uv) * Corner(zoom_uv_mask * iResolution.xy, 1.0);
    layer_1.rgb = layer_1.rgb * step(0.0, zoom_uv_mask.x) * step(zoom_uv_mask.x, 1.0) * step(0.0, zoom_uv_mask.y) * step(zoom_uv_mask.y, 1.0);

    float p2 = min(1.0, max((iGlobalTime-0.3) / 0.5, 0.0));
    float mp2 = 1.0 - pow(1.0 - p2, 3.0);
    vec2 move_uv = uv;
    move_uv.x -= 1.25 * (1.0 - mp2);
    float rp2 = pow(p2, 2.0);
    vec2 rotate_uv = move_uv;
    rotate_uv = RotateFunc(rotate_uv, mix(-0.1, 0.0, rp2), vec2(0.5 - 0.5*(1.0-mp2), 0.0));

    vec4 layer_2 = INPUT2(rotate_uv);
    layer_2 = layer_2 * step(0.0, rotate_uv.x) * step(rotate_uv.x, 1.0) * step(0.0, rotate_uv.y) * step(rotate_uv.y, 1.0);

    ////////////////////////

    float p3 = min(1.0, max((iGlobalTime-0.25) / 0.5, 0.0));
    float mp3 = 1.0 - pow(1.0 - p3, 3.0);
    move_uv = uv;
    move_uv.x -= 1.25 * (1.0 - mp3);
    float rp3 = pow(p3, 2.0);
    rotate_uv = move_uv;
    rotate_uv = RotateFunc(rotate_uv, mix(-0.05, 0.0, rp3), vec2(0.5 - 0.5*(1.0-mp3), 0.0));

    vec4 layer_3 = INPUT2(rotate_uv);
    layer_3 = layer_3 * step(0.0, rotate_uv.x) * step(rotate_uv.x, 1.0) * step(0.0, rotate_uv.y) * step(rotate_uv.y, 1.0);
    layer_3 = mix(layer_3, layer_2, layer_2.a);

    ////////////////////////

    float p4 = min(1.0, max((iGlobalTime-0.2) / 0.5, 0.0));
    float mp4 = 1.0 - pow(1.0 - p4, 3.0);
    move_uv = uv;
    move_uv.x -= 1.25 * (1.0 - mp4);
    float rp4 = pow(p4, 2.0);
    rotate_uv = move_uv;
    rotate_uv = RotateFunc(rotate_uv, mix(-0.025, 0.0, rp4), vec2(0.5 - 0.5*(1.0-mp4), 0.0));

    vec4 layer_4 = INPUT2(rotate_uv);
    layer_4 = layer_4 * step(0.0, rotate_uv.x) * step(rotate_uv.x, 1.0) * step(0.0, rotate_uv.y) * step(rotate_uv.y, 1.0);
    layer_4 = mix(layer_4, layer_3, layer_3.a);

    fragOutCol = mix(layer_1, layer_4, layer_4.a);

    vec4 texture = INPUT3(uv);
    texture.rgb *= texture.a;

    fragOutCol.rgb = mix(fragOutCol.rgb, texture.rgb, texture.a * zp * 0.75);
  }

  return fragOutCol;
}

vec2 RotateFunc(vec2 iuv, float angle, vec2 icenter) {
  vec2 rotateUV = iuv * iResolution;
  vec2 center = icenter;
  float rotation = angle;
