vec3 colorDodge(vec3 s, vec3 d)
{
	float r = 1.0 - s.r;
	float g = 1.0 - s.g;
	float b = 1.0 - s.b;

	vec3 ret = s;
	if(r > 0.0){
		ret.r = d.r / r;
	}

	if(g > 0.0){
		ret.g = d.g / g;
	}

	if(b > 0.0){
		ret.b = d.b / b;
	}

	return ret;
}

