vec2 rotate(vec2 uv, float angle, vec2 center){
    float cosTheta = cos(radians(angle));
    float sinTheta = sin(radians(angle));
    mat2 rotationMatrix = mat2(cosTheta, sinTheta, -sinTheta, cosTheta);
    vec2 uv1=uv;
    uv1 -= center;
    uv1.y *= iResolution.y / iResolution.x;
    uv1=uv1*rotationMatrix;
    uv1.y *= iResolution.x / iResolution.y;
    uv1 += center;
    return uv1;
}

vec2 scale(vec2 uv, float scaleIns, vec2 center){
    mat2 scaleMatrix = mat2(1.0/(scaleIns + 0.000001), 0.0, 0.0, 1.0/(scaleIns + 0.000001));
    vec2 uv1=uv;
    uv1 -= center;
    uv1=uv1*scaleMatrix;
    uv1 += center;
    return uv1;
}

vec4 applyBlend0 (vec4 dst0, vec4 src0, float opacity) {
    src0 *= opacity;
    return src0 + dst0 * (1.0 - src0.a);
}

