     float timeDuration = 1.0 / 3.0;
     float imgOneStartRad = radians(-1.0), imgOneMiddleRad = radians(-2.0), imgOneEndRad = radians(-30.0);
     float imgOneStartSize = 0.92, imgOneEndSize = 0.8;
     float imgTwoStartRad = radians(4.0), imgTwoEndRad = 0.0;
     float imgTwoStartSize = 0.5, imgTwoMiddleSize = 0.8, imgTwoEndSize = 1.0;
     if(iPro <= timeDuration){
        float curProcess = clamp(iPro/timeDuration, 0.0, 1.0);

        int imgIndex = 1;
        float rad = mix(imgOneStartRad, imgOneMiddleRad, curProcess);
        float imgSize = mix(imgOneStartSize, imgOneEndSize, curProcess);
        retCol = GetPhotographFrame(tc, imgIndex, rad, imgSize);
     }else if(iPro <= timeDuration*2.0){
        float curProcess = clamp((iPro - timeDuration)/timeDuration, 0.0, 1.0);

        int imgIndex = 1;       
        float rad_1 = mix(imgOneMiddleRad, imgOneEndRad, curProcess);
        float imgSize_1 = imgOneEndSize;
        vec2 frame_offset = mix(vec2(0.0), vec2(-0.8,0.8), curProcess);
        vec2 curUV_1 = tc - frame_offset;
        vec4 retCol_1 = clamp(GetPhotographFrame(curUV_1, imgIndex, rad_1, imgSize_1),0.0,1.0);

        imgIndex = 2;
        float rad_2 = imgTwoStartRad;
        float imgSize_2 = mix(imgTwoStartSize, imgTwoMiddleSize, curProcess);
        vec2 curUV_2 = tc;
        vec4 retCol_2 = clamp(GetPhotographFrame(curUV_2, imgIndex, rad_2, imgSize_2),0.0,1.0);
        retCol = mixFunc(retCol_2, retCol_1, retCol_1.a);

     }else{
        float curProcess = clamp((iPro - 2.0*timeDuration)/timeDuration, 0.0, 1.0);

        int imgIndex = 2;
        float rad_2 = mix(imgTwoStartRad, imgTwoEndRad, curProcess);
        float imgSize_2 = mix(imgTwoMiddleSize, imgTwoEndSize, curProcess); 
        vec2 curUV_2 = tc;
        retCol = GetPhotographFrame(curUV_2, imgIndex, rad_2, imgSize_2);
     }
   }

	return mixFunc(bgCol,retCol,retCol.a);
}

#define PI 3.1415926

float hash11(float p) {
  p = fract(p * .1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

vec2 hash21(float p){
  vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx+p3.yz)*p3.zy);
}

vec2 fbmNoise(float p){
  vec2 value = vec2(0.0);
  float freq = 1.13;
  float amp = 0.57;
  const int octaves = 3;
  for (int i = 0; i < octaves; i++){
    value += amp * (hash21((p-(1.0))*freq)*2.0-1.0);
    freq *= 1.61;
    amp *= 0.47;
  }
  return value;
}

vec2 Shake(float maxshake, float mag, float iTime){
  if(iTime <= 0.0 || iTime >= 1.0){
    return vec2(0.0);
  }

  float speed = 5.0*mag;
  float shakescale = maxshake*mag;

  float time = iTime*speed;  // speed of shake
  vec2 noiseMove = fbmNoise(time);

  return vec2(noiseMove.x*shakescale*1.2, noiseMove.y*shakescale*0.6);
}

float easeInCubic(float x){
  return 1. - cos((x * PI) / 2.);
}

float calHighLightRange(float progress){
  float range = mix(progress * 2.0, (1. - progress) * 2.0, step(0.5, progress));
  range = clamp(1. - easeInCubic(range), 0.2, 1.0);
  return range;
}

vec4 imageLightning(vec2 uv, float progress){
  vec4 origCol = INPUT1(uv);
  float range = calHighLightRange(progress);
  vec4 highlightColor = INPUT2(uv);
  return clamp(highlightColor * 2.0 * range + origCol, 0.0, 1.0);
}

vec4 highLightImage(vec2 uv, float progress){
  vec4 origCol = INPUT1(uv);
  float range = calHighLightRange(progress);
  return clamp(vec4(smoothstep(range - 0.15, range, origCol)), 0.0, 1.0);
}

vec4 effectSwitchGlitch(vec2 tc, float bellPro, float iPro, float lightStrength){
  if(iPro <= 0.0 || iPro > 0.5){
    return INPUT1(tc);
  }

  int frameID = int(PREFIX(curFrame));
  int surplus = frameID % 3;

  vec4 color = imageLightning(tc, lightStrength);
  if(surplus == 1){
    float grayCol = (color.r + color.g + color.b) / 3.0;
    return vec4(vec3(grayCol), color.a);
  }else{
    return color;
  }
}

vec4 scanLineJitterGlitchX(vec2 tc, float bellPro, float iPro, float lightStrength){
  if(iPro <= 0.0 || iPro >= 1.0){
    return effectSwitchGlitch(tc, bellPro, iPro, lightStrength);
  }

  vec4 retCol = vec4(0.0);
  float strength = mix(0.003, 0.009, bellPro) * (hash11(iPro) * 0.2 + 0.8);
  for(int i = 0; i < 4; i++){
    float offset = mix(1.0, -1.0, float(int(tc.y * iResolution.y / 2.0) % 2)) * strength *
                  ((sin((tc.y + iPro) * iResolution.y / 5.0 * PI) * 0.5 + 0.5) * 0.2 + 0.8) * (float(i + 1));
    vec2 uv = vec2(tc.x + offset, tc.y);
    retCol += effectSwitchGlitch(uv, bellPro, iPro, lightStrength);
  }
  return retCol / 4.0;
}

vec4 FUNCNAME(vec2 tc) 
{
  float iPro = PREFIX(iPro);
  float bellPro = PREFIX(bellPro);
  float lightStrength = PREFIX(lightStrength);

