vec3 GetColor(int col) {
  float r = float((col >> 16) & 0xFF) / 255.0;
  float g = float((col >> 8) & 0xFF) / 255.0;
  float b = float(col & 0xFF) / 255.0;
  return vec3(b, g, r);
}

vec4 directBlur(vec2 uv, float blurRadius, vec2 dir, int iteration, float sigma) {
  vec4 color = INPUT1(uv) * exp(0.0);
  color *= step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
  float weight = exp(0.0);
  for (int k = 1; k <= iteration; k++) {
    float offset = float(k) / float(iteration);
    float w = exp(-offset * offset * sigma);

    vec2 curUV1 = uv + dir * offset * blurRadius;
    vec2 curUV2 = uv - dir * offset * blurRadius;

    vec4 col_1 = INPUT1(curUV1);
    vec4 col_2 = INPUT1(curUV2);
    col_1 *= step(0.0, curUV1.x) * step(curUV1.x, 1.0) * step(0.0, curUV1.y) * step(curUV1.y, 1.0);
    col_2 *= step(0.0, curUV2.x) * step(curUV2.x, 1.0) * step(0.0, curUV2.y) * step(curUV2.y, 1.0);
    color += (col_1 + col_2) * w;

    weight += 2.0 * w;
  }

  return color / weight;
}

vec2 scaleFunc(vec2 uv, vec2 scale, vec2 center) {
  return (uv - center) / (scale) + center;
}

vec3 rgb2hsv(vec3 c) {
  vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

  float d = q.x - min(q.w, q.y);
  float e = 1.0e-10;
  return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

vec3 permute(vec3 x) { return mod(((x*34.0)+1.0)*x, 289.0); }

float snoise(vec2 v){
  const vec4 C = vec4(0.211324865405187, 0.366025403784439,
           -0.577350269189626, 0.024390243902439);
  vec2 i  = floor(v + dot(v, C.yy) );
  vec2 x0 = v -   i + dot(i, C.xx);
  vec2 i1;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod(i, 289.0);
  vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
  + i.x + vec3(0.0, i1.x, 1.0 ));
  vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy),
    dot(x12.zw,x12.zw)), 0.0);
  m = m*m ;
  m = m*m ;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

float lum(vec4 c) { return dot(c.rgb, vec3(0.3, 0.59, 0.11)); }

float sobel(vec2 tc) {

  float size = 0.2;
  vec2 imageIncrement = vec2(2.0 * size) / iResolution.xy;

  float t00 = lum(INPUT1(tc + imageIncrement * vec2(-1.0, -1.0)));
  float t10 = lum(INPUT1(tc + imageIncrement * vec2(0.0, -1.0)));
  float t20 = lum(INPUT1(tc + imageIncrement * vec2(1.0, -1.0)));
  float t01 = lum(INPUT1(tc + imageIncrement * vec2(-1.0, 0.0)));
  float t21 = lum(INPUT1(tc + imageIncrement * vec2(1.0, 0.0)));
  float t02 = lum(INPUT1(tc + imageIncrement * vec2(-1.0, 1.0)));
  float t12 = lum(INPUT1(tc + imageIncrement * vec2(0.0, 1.0)));
  float t22 = lum(INPUT1(tc + imageIncrement * vec2(1.0, 1.0)));

  vec2 grad;
  grad.x = t00 + 2.0 * t01 + t02 - t20 - 2.0 * t21 - t22;
  grad.y = t00 + 2.0 * t10 + t20 - t02 - 2.0 * t12 - t22;

  return pow(length(grad), 1.);
}

vec4 HDR(vec2 uv) {

  vec4 color = INPUT1(uv);
  float gamma = 0.03;
  float exposure = 9.0;

  vec3 hdrColor = color.rgb;

  // exposure tone mapping
  vec3 mapped = vec3(1.0) - exp(-hdrColor * exposure);
  // gamma correction
  mapped = pow(mapped, vec3(1.0 / gamma));

  return vec4(mapped, color.a);
}

vec4 FUNCNAME(vec2 tc) {

  float time = PREFIX(global_time);
  float total_time = PREFIX(total_time);
  float process = time / total_time;
  process = smoothstep(0.1, 0.9, process);

  int uStep = PREFIX(uStep);
  if (uStep == 0) {
    vec4 col = INPUT1(tc);
    if (process > 0.5) {
      col = INPUT2(tc);
    }
    return col;
  } else if (uStep == 1) {
    float square_size = 0.1 * pow(smoothstep(0.2, 0.5, process) * (1.0 - smoothstep(0.5, 0.8, process)), 0.5);
    if (iResolution.x >= iResolution.y) {
      // tc.x *= (float(iResolution.x) / float(iResolution.y));
      float scale = float(iResolution.x) / float(iResolution.y);
      tc.x  = (tc.x - 0.5) * scale + 0.5;
    } else {
      // tc.y *= (float(iResolution.y) / float(iResolution.x));
      float scale = float(iResolution.y) / float(iResolution.x);
      tc.y  = (tc.y - 0.5) * scale + 0.5;
    }
    if (square_size > 0.0) {
      tc = floor(tc / square_size) * square_size + square_size * 0.5;
    }

    if (iResolution.x >= iResolution.y) {
      float scale = float(iResolution.y) / float(iResolution.x);
      tc.x = (tc.x - 0.5) * scale + 0.5;
      // tc.x *= iResolution.y / iResolution.x;
    } else {
      float scale = float(iResolution.x) / float(iResolution.y);
      tc.y = (tc.y - 0.5) * scale + 0.5;
      // tc.y *= iResolution.x / iResolution.y;
    }

    vec4 col = INPUT1(tc);
    return col;

  } else  if (uStep == 3) {
    float sobel_val = sobel(tc);
    vec4 col = INPUT2(tc);
    float sobel_process = smoothstep(0.0, 0.5, process) * (1.0 - smoothstep(0.5, 1.0, process));
    col.rgb = mix(col.rgb, col.rgb + vec3(sobel_val), pow(sobel_process, 0.75));
    return col;
  } else  if (uStep == 4) {
    return HDR(tc);
  }

  float factor = floor(tc.x / 0.01);
  factor += floor(tc.x / 0.002) * smoothstep(0.3, 0.5, process) * (1.0 - smoothstep(0.5, 0.7, process));
  float glitch = pow(smoothstep(0.0, 0.5, process) * (1.0 - smoothstep(0.5, 1.0, process)), 3.0);
  tc.y -= abs(snoise(vec2(tc.y, factor * 0.1 + time * 0.1))) * glitch * 0.4;

  float scale = 1.0 + 0.5 * smoothstep(0.0, 0.5, process) * (1.0 - smoothstep(0.5, 1.0, process));
  vec2 offset = vec2(0.0, 0.4) * smoothstep(0.0, 0.5, process) * (1.0 - smoothstep(0.5, 1.0, process));
  if (process < 0.5) {
      tc -= offset;
  } else {
      tc += offset;
  }
  tc = scaleFunc(tc, vec2(scale), vec2(0.5));

  vec4 col = INPUT1(tc);
  vec3 hsv = rgb2hsv(col.rgb);
  float stauration = mix(hsv.y, hsv.y * 0.3, smoothstep(0.3, 0.5, process) * (1.0 - smoothstep(0.5, 0.7, process)));
  float hue = mix(hsv.x, mod(hsv.x + 0.5, 1.0), smoothstep(0.3, 0.5, process) * (1.0 - smoothstep(0.5, 0.7, process)));
  col.rgb = hsv2rgb(vec3(hue, stauration , hsv.z));
  return col;

}

