// ============================================================
// 螺旋抖动轨迹函数
// 输入：
//   p : 轨迹归一化进度 [0, 1]
//   r : 大圆半径（小圆半径固定为 r * 0.5）
// 输出：以画面中心为原点的 uv 单位位移向量
//
// 注意：实测本引擎 tc.y 朝上（OpenGL 标准），因此直接用 (cos θ, sin θ) 即可。
//       由于 shakeOffset 返回的是采样偏移量，frag 里用 tc - offset 表示
//       "锚点向 offset 方向移动"，offset 向量本身就是锚点在屏幕上的位移方向。
//       在当前坐标系下，"屏幕逆时针" 对应 θ 递增（右→上→左→下）。
//
// 轨迹（5 段）：
//   段① [0.00, 0.10] 圆心 → 大圆右顶点         直线 (带缓动入)
//   段② [0.10, 0.40] 大圆右顶点 → 大圆下顶点    沿大圆逆时针 3/4 圈 (屏幕: 右→上→左→下)
//                                                θ: 0 → 3π/2
//   段③ [0.40, 0.55] 大圆下顶点 → 小圆右顶点    极坐标短弧 ρ:2r→r, θ:3π/2→2π
//   段④ [0.55, 0.80] 小圆右顶点 → 小圆左顶点    沿小圆逆时针下半圈 (屏幕: 右→上→左)
//                                                θ: 2π → 3π
//   段⑤ [0.80, 1.00] 小圆左顶点 → 圆心          极坐标短弧 ρ:r→0, θ:3π→5π/2
// ============================================================
// ============================================================
// 锚点轨迹：单一阿基米德螺线 + cubic-out 缓入
// 起点：(r, 0) —— 画面中心右侧 r 处（r 由调用方传入，作为螺线起始半径）
// 终点：(0, 0) —— 圆心，零速度自然收尾（无惯性抖动）
// 数学：
//   easeT = 1 - (1 - p)^3                ← cubic-out，越到后面越慢
//   ρ(p)  = r * (1 - easeT)              ← 半径线性收缩到 0
//   θ(p)  = 2π * N * easeT               ← 总共转 N 圈（N 在函数内可调）
// 性质：
//   * 全程一条解析曲线，无分段拼接 → 不会有交界处卡顿
//   * cubic-out 让动画末段速度趋近于 0 → 平滑收尾，不需要惯性抖动
//   * 圈数 N 直接作为局部变量暴露，方便手工调节节奏
// ============================================================
vec2 ChordPluckAnchor(float p, float r) {
    float PI = 3.1415927;

    // —— 可调参数 ——
    float N = 2.5;                        // 螺旋总圈数 (1.0 简洁 / 1.5 经典 / 2.0 更丝滑旋转感)

    if (p <= 0.0) {
        return vec2(r, 0.0);              // 起点：右侧 (r, 0)
    }
    if (p >= 1.0) {
        return vec2(0.0, 0.0);            // 终点：圆心
    }

    // cubic-out 缓入：开始快、末尾慢，自然零速度收尾
    float easeT = 1.0 - pow(1.0 - p, 3.0);

    float rho   = r * (1.0 - easeT);
    float theta = 2.0 * PI * N * easeT;   // 逆时针累积旋转

    return vec2(cos(theta), sin(theta)) * rho;
}

// ============================================================
// 顺时针版本：与 ChordPluckAnchor 起点完全一致 (r, 0)，但旋转方向相反。
// 数学：把 sin(theta) 取负即可让向量从 (r,0) → (0,-r) → (-r,0) → (0,r) → (r,0)，
//       这是顺时针方向的运动轨迹。
// 用于 Portrait Depth Rotate 特效以区别于 Portrait Depth Shake 的逆时针螺旋。
// ============================================================
vec2 ChordPluckAnchorCW(float p, float r) {
    float PI = 3.1415927;

    float N = 2.5;

    if (p <= 0.0) {
        return vec2(r, 0.0);              // 起点：右侧 (r, 0)，与逆时针版本一致
    }
    if (p >= 1.0) {
        return vec2(0.0, 0.0);            // 终点：圆心
    }

    float easeT = 1.0 - pow(1.0 - p, 3.0);

    float rho   = r * (1.0 - easeT);
    float theta = 2.0 * PI * N * easeT;   // 角度累积量与逆时针版本相同

    // 关键：sin(theta) 取负 → 顺时针旋转
    return vec2(cos(theta), -sin(theta)) * rho;
}

// ============================================================
// 反向轨迹版本：与 ChordPluckAnchor 中心点对称 (x,y) → (-x,-y)
// 视觉效果：
//   - 段① 直线方向反向：大圆左顶点 → 小圆右顶点
//   - 段②~⑤ 大圆/小圆螺旋由"逆时针"翻转为"顺时针"
//   - 段⑥ 圆心惯性螺旋同样顺时针
// 用途：与 ChordPluckAnchor 配对，让两份 INPUT2 副本
//       从画面左右两侧反向螺旋汇合到中心
// ============================================================
vec2 ChordPluckAnchorReverse(float p, float r) {
    // (x, y) 取负 = 中心点对称 = θ + π，
    // 同时把直线段的方向反过来（由原始 cos/sin 取负自动得到）
    return -ChordPluckAnchor(p, r);
}

// ============================================================
// 顺时针螺旋的反向版本：与 ChordPluckAnchorCW 中心点对称
// 起点 (-r, 0)，整体顺时针旋转，用于人物/前景区域
// ============================================================
vec2 ChordPluckAnchorCWReverse(float p, float r) {
    return -ChordPluckAnchorCW(p, r);
}

// ============================================================
// 反向版双层螺旋抖动 → 返回采样 UV
// 与 DualSpiralShakeUV 用法一致, 仅轨迹方向相反
// 注意：弦剖面权重 (vProfile / hProfile) 与方向无关，复用即可
// ============================================================
vec2 DualSpiralShakeUVReverse(vec2 tc, float p, float rPluck, float rRigid) {
    // 1) 反向版本 anchor（中心点对称）
    vec2 anchorPluck = ChordPluckAnchorReverse(p, rPluck);
    vec2 anchorRigid = ChordPluckAnchorReverse(p, rRigid);

    // 2) 弦剖面权重（与正向版完全一致）
    float vy = 2.0 * tc.y - 1.0;
    float vx = 2.0 * tc.x - 1.0;
    float vProfile = sqrt(max(0.0, 1.0 - vy * vy));
    float hProfile = sqrt(max(0.0, 1.0 - vx * vx));

    // 3) 抖动 A：弦拉扯（每像素不同）
    vec2 pluckOffset = vec2(anchorPluck.x * vProfile, anchorPluck.y * hProfile);

    // 4) 抖动 B：整画面螺旋平移（每像素相同）
    vec2 rigidOffset = anchorRigid;

    // 5) 双层叠加
    return clamp(tc - (pluckOffset + rigidOffset), vec2(0.0), vec2(1.0));
}

// ============================================================
// 双层螺旋抖动 → 返回采样 UV
// 输入：
//   tc      : 当前像素的归一化 UV 坐标
//   p       : 轨迹归一化进度 [0, 1]
//   rPluck  : 弦拉扯抖动幅度（大圆半径），中间被扯、四周钉死
//   rRigid  : 整画面螺旋平移抖动幅度（大圆半径），rigid translation
// 输出：
//   叠加双层抖动后的采样 UV（已 clamp 到 [0,1]，可直接喂给 INPUT*）
// ============================================================
vec2 DualSpiralShakeUV(vec2 tc, float p, float rPluck, float rRigid) {
    // 1) 分别计算两层的锚点偏移（同轨迹同相位，幅度独立）
    vec2 anchorPluck = ChordPluckAnchor(p, rPluck);
    vec2 anchorRigid = ChordPluckAnchor(p, rRigid);

    // 2) 弦剖面权重：靠近中心被完全拉扯，靠近边缘不动
    //    - vProfile：基于 y 的"竖线剖面"，缩放 x 方向的水平拉扯
    //    - hProfile：基于 x 的"横线剖面"，缩放 y 方向的垂直拉扯
    float vy = 2.0 * tc.y - 1.0;
    float vx = 2.0 * tc.x - 1.0;
    float vProfile = sqrt(max(0.0, 1.0 - vy * vy));
    float hProfile = sqrt(max(0.0, 1.0 - vx * vx));

    // 3) 抖动 A：弦拉扯（每像素不同，受剖面权重缩放）
    vec2 pluckOffset = vec2(anchorPluck.x * vProfile, anchorPluck.y * hProfile);

    // 4) 抖动 B：整画面螺旋平移（每像素相同的 rigid translation）
    vec2 rigidOffset = anchorRigid;

    // 5) 双层叠加，UV 域直接相加
    return clamp(tc - (pluckOffset + rigidOffset), vec2(0.0), vec2(1.0));
}

// ============================================================
// 边界采样辅助：
//   - mirror01(v)：把 v 沿 [0,1] 区间做无限镜像反射
//                  v=1.1 → 0.9；v=-0.1 → 0.1；v=1.5 → 0.5
//                  数学：mod 到 [0,2) 后，>1 的部分折叠回去
//   - boundarySampleUV：xy 双向镜像采样，超出 [0,1] 范围都折回画面内
//                       完全不出现黑边
// ============================================================
float mirror01(float v) {
    float m = mod(v, 2.0);          // GLSL mod 对负数也返回非负值
    return m > 1.0 ? 2.0 - m : m;
}

vec2 boundarySampleUV(vec2 sUV) {
    // x、y 方向都做镜像反射
    sUV.x = mirror01(sUV.x);
    sUV.y = mirror01(sUV.y);
    return sUV;
}

vec4 FUNCNAME(vec2 tc) {
    int step = PREFIX(uStep);

    if (step == 0) {
        // ========== RGB 故障：在人物边缘做 RGB 通道分离 ==========
        // 视觉目标：人物边缘出现明显的"红-绿-蓝"三条带（R 在一侧、B 在另一侧、G 居中）
        //
        // 思路：
        //   1) 用人物 mask（INPUT3.r）做"宽边缘"检测，得到 [0,1] 的边缘强度 edge
        //   2) 对 INPUT2 沿水平方向偏移采样 R 和 B 通道（G 通道不偏移）
        //   3) 用 edge 把"原图"和"通道分离图"混合，仅边缘带显示故障

        // —— 可调参数 ——
        float kShift   = PREFIX(uHumanEdgeRGBTrength);    // RGB 通道偏移距离（UV 单位），值越大三条带越宽
        float kEdgeR   = PREFIX(uHumanEdgeRGBTrength);     // 人物边缘检测半径（UV 单位），需 ≥ kShift 让边缘带覆盖三条带
        float kBoost   = 3.0;      // 人物边缘强度增益（让较薄的 mask 过渡也能拉成强烈条带）
        float kHFR     = 0.004;    // 高频检测半径（UV 单位），通常取较小值采到细节而非大块色差
        float kHFBoost = 4.0;      // 高频检测增益（亮度差通常较小，需要较大增益）
        float kHFScale = PREFIX(uEdgeRGBTrength);      // 高频区故障强度系数（用户指定为人物边缘的一半）

        // 1) 人物边缘检测：在 ±kEdgeR 范围内十字形采样 mask，取最大/最小差
        //    边缘带内 mask 同时存在接近 1 与接近 0 的样本 → maxM - minM ≈ 1
        //    远离边缘（人物中心或纯背景）所有样本一致 → maxM - minM ≈ 0
        float m0 = INPUT3(tc).r;
        float mL = INPUT3(clamp(tc + vec2(-kEdgeR,     0.0), vec2(0.0), vec2(1.0))).r;
        float mR = INPUT3(clamp(tc + vec2( kEdgeR,     0.0), vec2(0.0), vec2(1.0))).r;
        float mU = INPUT3(clamp(tc + vec2(    0.0,  kEdgeR), vec2(0.0), vec2(1.0))).r;
        float mD = INPUT3(clamp(tc + vec2(    0.0, -kEdgeR), vec2(0.0), vec2(1.0))).r;
        float maxM = max(max(max(m0, mL), max(mR, mU)), mD);
        float minM = min(min(min(m0, mL), min(mR, mU)), mD);
        float edgePerson = clamp((maxM - minM) * kBoost, 0.0, 1.0);

        // 2) 高频区域检测：采样 INPUT2 邻域亮度，取 max-min（Rec.601 亮度系数）
        //    亮度极差大 = 高频纹理/细节边缘；均匀色块 = 低频，差≈0 不会触发故障
        vec3 LUMA = vec3(0.299, 0.587, 0.114);
        float l0 = dot(INPUT2(tc).rgb,                                                      LUMA);
        float lL = dot(INPUT2(clamp(tc + vec2(-kHFR,     0.0), vec2(0.0), vec2(1.0))).rgb, LUMA);
        float lR = dot(INPUT2(clamp(tc + vec2( kHFR,     0.0), vec2(0.0), vec2(1.0))).rgb, LUMA);
        float lU = dot(INPUT2(clamp(tc + vec2(    0.0,  kHFR), vec2(0.0), vec2(1.0))).rgb, LUMA);
        float lD = dot(INPUT2(clamp(tc + vec2(    0.0, -kHFR), vec2(0.0), vec2(1.0))).rgb, LUMA);
        float maxL = max(max(max(l0, lL), max(lR, lU)), lD);
        float minL = min(min(min(l0, lL), min(lR, lU)), lD);
        // 注意：先 clamp 到 [0,1] 再乘 kHFScale，确保高频故障"封顶"严格不超过人物边缘的一半
        float edgeHF = clamp((maxL - minL) * kHFBoost, 0.0, 1.0) * kHFScale;

        // 3) 合并两种 edge：取较大值，避免重叠区域强度叠加变诡异
        //    - 纯人物边缘：edge = edgePerson  ∈ [0, 1]（最强故障）
        //    - 纯高频纹理：edge = edgeHF      ∈ [0, kHFScale=0.5]（半强度）
        //    - 二者重叠：edge = max(...)，仍由人物边缘主导
        float edge = max(edgePerson, edgeHF);

        // 4) RGB 通道分离：水平方向 R 向右偏、B 向左偏、G 不动
        //    采样 UV 都做 clamp，避免越界
        vec2 uvR = clamp(tc + vec2( kShift, 0.0), vec2(0.0), vec2(1.0));
        vec2 uvG = tc;
        vec2 uvB = clamp(tc + vec2(-kShift, 0.0), vec2(0.0), vec2(1.0));

        vec4 srcR = INPUT2(uvR);
        vec4 srcG = INPUT2(uvG);
        vec4 srcB = INPUT2(uvB);

        // 故障颜色：每个通道来自不同位置 —— 边缘处自然形成 R/G/B 三条带
        vec4 glitch = vec4(srcR.r, srcG.g, srcB.b, srcG.a);

        // 5) 用合并后的 edge 强度把原图和故障图混合
        vec4 baseCol = mix(srcG, glitch, edge);

        // ========== 曝光增强：高光区域大幅提亮 ==========
        // 思路：
        //   1) 计算当前像素亮度（Rec.601）
        //   2) 用 smoothstep 在 [kExpThreshold, kExpThreshold + kExpSoft] 区间
        //      平滑过渡，得到 [0, 1] 的"高光权重" t
        //   3) gain = mix(1, kExpBoost, t)，仅在高光时显著大于 1
        //   4) 直接对 RGB 乘 gain，再 clamp 到 [0, 1]，模拟相机过曝

        // —— 可调参数 ——
        float kExpThreshold = 0.8;     // 触发曝光的亮度阈值（lum 低于此值不增强）
        float kExpSoft      = 0.1;     // 阈值过渡软边带宽（避免硬切产生色带）
        float kExpBoost     = PREFIX(uExpBoost);     // 最大增益（极亮区域 RGB 乘以 2.5）

        float lumExp = dot(baseCol.rgb, LUMA);
        float tExp   = smoothstep(kExpThreshold, kExpThreshold + kExpSoft, lumExp);
        float gain   = mix(1.0, kExpBoost, tExp);

        vec3 boosted = baseCol.rgb * gain;
        return vec4(min(boosted, vec3(1.0)), baseCol.a);
    } else if (step == 1) {
        // 1) 时间 → 轨迹进度：0.25 前静止
        float u = PREFIX(uCurTime);
        float p = clamp((u - 0.25) / (0.9 - 0.25), 0.0, 1.0);

        // 2) 基准螺旋半径（最远深度 depth=0 时的最大抖动幅度）
        float rBase = 0.15;

        // 3) 采样深度：1=近=不抖，0=远=最大抖
        float depth = INPUT4(tc).r;
        float depthFactor = 1.0 - depth;          // 0=近=因子0，1=远=因子1

        // 4) 实际螺旋半径（按深度缩放）
        float rSpiral = rBase * depthFactor;

        // 5) 根据像素属于人体/前景还是背景，选择正反向螺旋偏移
        //    本特效（Rotate）使用顺时针 CW 版本，与 Shake（逆时针）形成视觉区别
        //    起始位置 (r, 0) / (-r, 0) 与 Shake 完全一致，仅旋转方向相反
        vec2 offset;
        if (INPUT3(tc).r > 0.5 || INPUT2(tc).a < 0.01) {
            offset = ChordPluckAnchorCWReverse(p, rSpiral);
        } else {
            offset = ChordPluckAnchorCW(p, rSpiral);
        }

        // 6) 采样：偏移的反方向作为采样 UV
        // vec2 sampleUV = clamp(tc - offset, vec2(0.0), vec2(1.0));
        vec2 sampleUV = tc - offset;
        return INPUT2(sampleUV);
    } else {
        // ========== step == 2：旋转转场 + 圆周尾迹（运动模糊型像素残留）==========
        // 旋转节奏由 effect 端 KeySpline(vec4(0.8688, -0.0029, 1.0, 1.0)) 提供
        // 进度参数 uRotateProgress ∈ [0, 1]，开始慢、后段加速：
        //   progress ∈ [0,    0.5]：显示 INPUT1（旧画面），从 0° 顺时针旋到 +90°（横着）
        //   progress == 0.5 瞬间   ：切换到 INPUT2（新画面），此时 INPUT2 处于 −90°（同样横着）
        //   progress ∈ [0.5,  1.0]：INPUT2 从 −90° 顺时针旋到 0°（回正）
        //   progress == 1.0 之后   ：INPUT2 静态显示（缓动曲线达到 1 后保持）
        // 由于 KeySpline 前半段慢、后段急加速，画面切换的"视觉时刻"会比线性时刻靠后。
        //
        // 旋转方向修正：
        //   - 用户视觉上希望"画面顺时针转"，但 UV 坐标系下 atan(y, x) 的正向是顺时针（y 朝下）
        //     还是逆时针（y 朝上）取决于引擎贴图坐标方向
        //   - 经实测引擎下，要画面"顺时针"，采样角度应为 a + baseAngle（而非 a - baseAngle）
        //
        // 圆周尾迹（运动模糊型残留）：
        //   - 每个像素绕画面中心做圆周运动，半径 r 不变
        //   - 屏幕固定位置 (r, a) 显示的颜色 = 源贴图沿圆弧"扫过"留下的累积痕迹
        //   - 在 [startAngle, baseAngle] 区间反向采样 SAMPLES 次，加权平均
        //   - 因为每次采样的 r 不变 → 尾迹严格在该像素所属的同心圆上，不径向扩散
        //   - 权重沿尾迹分布：fi=1（当前位置）最大，fi=0（尾末端）最小
        //     视觉效果：当前位置颜色最浓，越远的"过去位置"越淡，形成圆弧拖尾
        //
        // 边界采样策略（用户指定）：
        //   - x、y 双向越界都镜像反射（mirror），画面四周完全不出现黑边
        float kSamplesM1 = 71.0;     // SAMPLES - 1，用于 fi = i / (N-1)

        float PI2        = 3.1415927;
        float kSwitch    = 0.5;      // 进度 0.5 切画面（INPUT1 → INPUT2）
        float kRingInner = 0.02;     // 中心保护区半径（UV 单位）
        float kRingSoft  = 0.0;      // 中心保护软边宽（0=硬切，>0 软过渡）
        float kFalloff   = 2.0;      // 尾迹权重衰减指数（1 线性 / 2 平方 / 3 立方更聚焦）

        // 1) 进度 → 当前画面、起止姿态角度
        //    progress 已在 effect 端经过 KeySpline 缓动，本 shader 仅做线性映射到角度即可。
        //    顺时针方向：基于 atan(y,x) 在本引擎下的正向，画面顺时针对应"采样点角度 + baseAngle"。
        float progress = PREFIX(uRotateProgress);
        bool  useFirst = (progress < kSwitch);
        float baseAngle;
        float startAngle;
        if (useFirst) {
            // 第一段：INPUT1，progress ∈ [0, 0.5] → 角度 0 → +π/2
            float p1 = progress / kSwitch;
            baseAngle  = mix(0.0, 0.5 * PI2, p1);
            startAngle = 0.0;
        } else {
            // 第二段：INPUT2，progress ∈ [0.5, 1.0] → 角度 -π/2 → 0
            // startAngle 固定为 -π/2（切入瞬间画面姿态），baseAngle 由 p2 线性插值到 0。
            // 当 progress = 1.0 时 baseAngle = 0，但 startAngle = -π/2 仍存在 → 此时若不处理
            // 24 个采样点会铺满整个 [-π/2, 0] 区间，画面虽然回正但仍有完整尾迹"残留"。
            // 解决：用 (1 - p2) 作为 fade 因子，让第二段结尾的 startAngle 也滑向 baseAngle，
            //       视觉上尾迹"被画面回正过程吸收"，progress=1.0 时尾迹完全消失。
            float p2 = (progress - kSwitch) / (1.0 - kSwitch);
            baseAngle  = mix(-0.5 * PI2, 0.0, p2);
            // tailFade ∈ [1, 0]：p2=0 时 tailFade=1（保留完整切入尾迹），p2=1 时 tailFade=0（无尾迹）
            float tailFade = 1.0 - p2;
            startAngle = mix(baseAngle, -0.5 * PI2, tailFade);
        }

        // 2) 屏幕坐标 → 中心极坐标
        vec2 center = vec2(0.5, 0.5);
        vec2 d = tc - center;
        float r = length(d);
        float a = atan(d.y, d.x);

        // 3) 中心保护：r 越小线速度越小，理论尾迹越短，所以中心区直接刚体旋转
        float ringMask = smoothstep(kRingInner, kRingInner + kRingSoft, r);

        // 4) 尾迹累加：沿圆弧反向采样 SAMPLES 次
        //    - sampleAngle = a + mix(startAngle, baseAngle, fi)  ← 注意符号 +，让画面顺时针
        //    - fi=0 → 回到该段起始姿态（最早，权重最小）
        //    - fi=1 → 回到当前姿态（最近，权重最大）
        //    - 所有采样点都在同一个 r 圆上 → 尾迹严格沿圆周分布
        //    - xy 双向镜像采样，画面边缘完全不出现黑边
        vec4  accum = vec4(0.0);
        float wSum  = 0.0;
        for (int i = 0; i < 24; ++i) {
            float fi = float(i) / kSamplesM1;
            float backRotate  = mix(startAngle, baseAngle, fi);
            float sampleAngle = a + backRotate;          // 顺时针：符号取正
            vec2  sUV = center + r * vec2(cos(sampleAngle), sin(sampleAngle));

            // 边界处理：xy 双向镜像
            sUV = boundarySampleUV(sUV);

            float w = pow(fi, kFalloff);
            vec4 c = useFirst ? INPUT1(sUV) : INPUT2(sUV);
            accum += c * w;
            wSum  += w;
        }
        vec4 trailCol = wSum > 0.0001 ? accum / wSum : vec4(0.0, 0.0, 0.0, 1.0);

        // 5) 中心区刚体旋转采样（无尾迹）
        float aRigid = a + baseAngle;                    // 顺时针：符号取正
        vec2  rigidUV = center + r * vec2(cos(aRigid), sin(aRigid));
        rigidUV = boundarySampleUV(rigidUV);             // xy 双向镜像
        vec4  rigidCol = useFirst ? INPUT1(rigidUV) : INPUT2(rigidUV);

        // 6) 中心保护区平滑过渡：内部刚体、外部尾迹
        return mix(rigidCol, trailCol, ringMask);
    }
}

