float sinusoidalInOut(float t)
{
    float t01 = clamp(t, 0.0, 1.0);
    return 0.5 - 0.5 * cos(3.14159265358979323846 * t01);
}

float tilePopScale(float progress, float delay, float duration)
{
    float localT = clamp((progress - delay) / duration, 0.0, 1.0);
    float eased = sinusoidalInOut(localT);
    float zPosition = 2.0 * sin(3.14159265358979323846 * eased);

    // 源场景：PerspectiveCamera(fov=53.1), cameraZ=10，平面朝向相机。
    // 平面向镜头移动 zPosition 后，其屏幕投影倍率为 10/(10-z)。
    return 10.0 / max(10.0 - zPosition, 0.0001);
}

vec4 FUNCNAME(vec2 tc)
{
    float p = clamp(PREFIX(iProgress), 0.0, 1.0);

    // [@规则:R-T05] 显式闭合端点，避免 step 在对角线起点提前露出 B。
    if (p <= 0.0) {
        return INPUT1(tc);
    }
    if (p >= 1.0) {
        return INPUT2(tc);
    }

    // 源场景的四块顺序：左上、右下、右上、左下；均在 80% 处归位。
    bool right = tc.x >= 0.5;
    bool top = tc.y >= 0.5;
    float popScale = 1.0;
    if (!right && top) {
        popScale = tilePopScale(p, 0.10, 0.70);
    } else if (right && !top) {
        popScale = tilePopScale(p, 0.15, 0.65);
    } else if (right && top) {
        popScale = tilePopScale(p, 0.20, 0.60);
    } else {
        popScale = tilePopScale(p, 0.25, 0.55);
    }

    // 四块平面以画面中心交点为共同内角。透视弹出等价为各象限绕该内角放大，
    // 逆变换后采样 A/B 的同一块原始画面区域。
    vec2 sampledUv = vec2(0.5, 0.5) + (tc - vec2(0.5, 0.5)) / popScale;

    vec2 tileOffset = vec2(right ? 0.5 : 0.0, top ? 0.5 : 0.0);
    vec2 localUv = (sampledUv - tileOffset) * 2.0;

    // 源 Tween：300ms 延迟、1200ms 正弦缓入缓出；每块内部沿对角线硬切换。
    float revealT = clamp((p - 0.15) / 0.60, 0.0, 1.0);
    float reveal = sinusoidalInOut(revealT);
    float diagonal = 0.5 * (localUv.x + localUv.y);
    float mask = step(diagonal, reveal);

    vec4 colorA = INPUT1(sampledUv);
    vec4 colorB = INPUT2(sampledUv);
    return mix(colorA, colorB, mask);
}

