// =============================================================================
// Ragged Blur Slide · frag
// CapCut CustomShaderPass：水平甩镜运动模糊 + 中段灰度桥接 + 首尾淡入淡出。
// INPUT1=A（转场前），INPUT2=B（转场后）。
// =============================================================================

// CapCut 默认：whipStrength=1.0，whipDirection=+1（正向水平甩）
const float kWhipStrength = 1.0;
const float kWhipDirection = 1.0;

// 超出 0~1 时复制边缘像素（如 uv.x<0 取 x=0 竖列，uv.x>1 取 x=1 竖列）
vec2 clampEdgeUV(vec2 uv) {
    return clamp(uv, vec2(0.0), vec2(1.0));
}

vec4 sampleA(vec2 uv) {
    return INPUT1(clampEdgeUV(uv));
}

vec4 sampleB(vec2 uv) {
    return INPUT2(clampEdgeUV(uv));
}

vec4 motionBlurFromCenter(vec2 uv, vec4 centerTexel, vec2 delta, int which) {
    vec4 c1 = (which == 0) ? sampleA(uv + delta) : sampleB(uv + delta);
    vec4 c2 = (which == 0) ? sampleA(uv - delta) : sampleB(uv - delta);
    vec4 c3 = (which == 0) ? sampleA(uv + delta * 2.0) : sampleB(uv + delta * 2.0);
    vec4 c4 = (which == 0) ? sampleA(uv - delta * 2.0) : sampleB(uv - delta * 2.0);
    return centerTexel * 0.40 + (c1 + c2) * 0.24 + (c3 + c4) * 0.06;
}

vec4 transitionCore(vec2 tc, vec4 texel1, vec4 texel2, float progress) {
    // [@规则:R-T05] 端点闭合
    if (progress <= 0.0) {
        return texel1;
    }
    if (progress >= 1.0) {
        return texel2;
    }

    float p = smoothstep(0.0, 1.0, progress);
    float midPeak = 1.0 - abs(2.0 * p - 1.0);

    float dirSign = (kWhipDirection >= 0.0) ? 1.0 : -1.0;
    float blurRadius = (0.002 + 0.045 * kWhipStrength) * (0.15 + 0.85 * midPeak);
    vec2 delta = vec2(blurRadius * dirSign, 0.0);

    // A 沿甩镜反向退出，B 沿甩镜正向进入
    vec2 shiftA = vec2(-dirSign * blurRadius * 10.0 * p, 0.0);
    vec2 shiftB = vec2(dirSign * blurRadius * 10.0 * (1.0 - p), 0.0);

    vec4 aCenter = sampleA(tc + shiftA);
    vec4 bCenter = sampleB(tc + shiftB);

    vec4 aBlur = motionBlurFromCenter(tc + shiftA, aCenter, delta, 0);
    vec4 bBlur = motionBlurFromCenter(tc + shiftB, bCenter, delta, 1);

    float grayA = dot(aBlur.rgb, vec3(0.299, 0.587, 0.114));
    float grayB = dot(bBlur.rgb, vec3(0.299, 0.587, 0.114));
    vec3 bridgeGray = vec3(mix(grayA, grayB, smoothstep(0.46, 0.54, p)));

    float aFade = 1.0 - smoothstep(0.0, 0.45, p);
    vec3 aStage = aBlur.rgb * (0.35 + 0.65 * aFade);

    float bRecover = smoothstep(0.55, 1.0, p);
    vec3 bStage = mix(bBlur.rgb, texel2.rgb, bRecover);

    float toGray = smoothstep(0.22, 0.50, p);
    float fromGray = smoothstep(0.50, 0.78, p);

    vec3 color = mix(aStage, bridgeGray, toGray);
    color = mix(color, bStage, fromGray);

    return vec4(clamp(color, 0.0, 1.0), mix(texel1.a, texel2.a, p));
}

vec4 FUNCNAME(vec2 tc) {
    float progress = PREFIX(iProgress);
    // [@规则:R-T05] p=0 只显示 A/INPUT1，p=1 只显示 B/INPUT2
    vec4 texel1 = INPUT1(tc);
    vec4 texel2 = INPUT2(tc);

    if (progress <= 0.0) {
        return texel1;
    }
    if (progress >= 1.0) {
        return texel2;
    }

    // CapCut：首 10% / 末 10% 与原片淡入淡出，中间跑完整转场
    const float fadeInEnd = 0.1;
    const float fadeOutStart = 0.9;

    float transitionProgress = clamp((progress - fadeInEnd) / (fadeOutStart - fadeInEnd), 0.0, 1.0);
    vec4 transitionColor = transitionCore(tc, texel1, texel2, transitionProgress);

    float blendInFactor = smoothstep(0.0, fadeInEnd, progress);
    float blendOutFactor = smoothstep(fadeOutStart, 1.0, progress);

    vec4 finalColor = mix(texel1, transitionColor, blendInFactor);
    finalColor = mix(finalColor, texel2, blendOutFactor);
    return finalColor;
}

