float hash(vec2 p)
{   
    p = 50.0 * fract(p * 0.3183099 + vec2(0.71, 0.113));
    return (-1.0 + 2.0 * fract(p.x * p.y * (p.x + p.y)));
}

float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return (mix(a, b, u.x) + (c - a)* u.y * (1.0 - u.x) + (d - b) * u.x * u.y);
}

float fbm(vec2 p, vec2 iResolution)
{
    vec2 uv = p * vec2(iResolution.x / iResolution.y, 1.0) * 1.5;
    mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
    float f = 0.0;
    f  = 0.5000 * noise(uv); uv = m * uv;
    f += 0.2500 * noise(uv); uv = m * uv;
    f += 0.1250 * noise(uv); uv = m * uv;
    f += 0.0625 * noise(uv); uv = m * uv;
    f = 0.5 + 0.5 * f;
    return f;
}

vec4 FUNCNAME(vec2 tc) 
{
    float iGlobalTime = PREFIX(global_time);
    float totalTime = PREFIX(total_time);

    float process = min(iGlobalTime / totalTime, 1.0);
    float iPro = (3.0 * process * process - 2.0 * process * process * process);

    vec4 y1 = INPUT1(tc);
    vec4 y2 = INPUT2(tc);

    vec4 retCol = y1;

    float alpha = fbm(tc, iResolution) * 0.95;
    alpha = smoothstep(alpha, alpha + 0.3, iPro);
    alpha = clamp(alpha, 0.0, 1.0);
    retCol = mix(y1, y2, alpha);
    retCol.rgb *= retCol.a;

    return retCol;
}

