vec4 rasterPush(vec2 tc, float progress) {
    // [@规则:R-T05] 端点提前返回，确保 p=0 仅 A、p=1 仅 B。
    if (progress <= 0.0) return INPUT1(tc);
    if (progress >= 1.0) return INPUT2(tc);

    float p = smoothstep(0.0, 1.0, progress);
    vec2 centered = tc - 0.5;
    float lenC = length(centered);
    vec2 dir = centered / max(lenC, 0.00001);

    // A 向画面中心方向拖影，B 向画面外侧拖影。
    float aBlurAmt = (1.0 - p) * (1.0 - p);
    vec2 aOff = dir * aBlurAmt * 0.02;
    vec4 blurA = INPUT1(tc) * 0.40;
    blurA += INPUT1(tc - aOff * 0.5) * 0.28;
    blurA += INPUT1(tc - aOff) * 0.20;
    blurA += INPUT1(tc - aOff * 1.5) * 0.12;

    float bBlurAmt = 1.0 - p;
    vec2 bOff = dir * bBlurAmt * 0.015;
    vec4 blurB = INPUT2(tc) * 0.42;
    blurB += INPUT2(tc + bOff * 0.5) * 0.28;
    blurB += INPUT2(tc + bOff) * 0.18;
    blurB += INPUT2(tc + bOff * 1.5) * 0.12;

    // 12 列光栅从每列中心向两侧同步张开，逐步以 B 替换 A。
    float local = fract(tc.x * 12.0);
    float distToCenter = abs(local - 0.5);
    float halfWidth = 0.5 * p;
    float slitMask = step(distToCenter, halfWidth);
    float edgeProximity = abs(distToCenter - halfWidth);
    float slitEdgeGlow = smoothstep(0.03, 0.0, edgeProximity)
        * (1.0 - smoothstep(0.9, 1.0, p));

    float frameEdge = min(min(tc.x, 1.0 - tc.x), min(tc.y, 1.0 - tc.y));
    float frameGlow = smoothstep(0.16, 0.0, frameEdge) * (1.0 - p);
    vec4 base = mix(blurA, blurB, slitMask);

    vec3 neonColor = vec3(0.72, 0.55, 1.0);
    vec3 glow = neonColor * 0.8 * (slitEdgeGlow * 0.9 + frameGlow * 0.35);
    vec3 rgbFringe = vec3(1.0, 0.55, 1.25) * (0.25 * slitEdgeGlow * 0.12);
    vec3 finalRgb = clamp(base.rgb + glow + rgbFringe, 0.0, 1.0);
    return vec4(finalRgb, mix(INPUT1(tc).a, INPUT2(tc).a, p));
}

vec4 FUNCNAME(vec2 tc) {
    float progress = min(1.0, max(0.0, PREFIX(iProgress)));

    // 源 Shader 在自身进度的前后 10% 再做一次原图/目标图闭合混合。
    float transitionProgress = min(1.0, max(0.0, (progress - 0.1) / 0.8));
    vec4 transitionColor = rasterPush(tc, transitionProgress);
    float blendInFactor = smoothstep(0.0, 0.1, progress);
    float blendOutFactor = smoothstep(0.9, 1.0, progress);
    vec4 finalColor = mix(INPUT1(tc), transitionColor, blendInFactor);
    return mix(finalColor, INPUT2(tc), blendOutFactor);
}

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
  vec2 p1 = vec2(p.x, p.y);
  vec2 p2 = vec2(p.z, p.w);
  float mX1 = p1.x;
  float mY1 = p1.y;
  float mX2 = p2.x;
  float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;

  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

