    vec4 retCol = tempCol;
    retCol.rgb = overlayCol.rgb + tempCol.rgb;
    retCol.rgb = mix(tempCol.rgb, retCol.rgb, alpha);
    retCol.rgb *= retCol.a;

    return retCol;
}

