bool insideBox(vec2 v, vec2 left_bottom, vec2 right_top) {
    vec2 s = step(left_bottom, v) - step(right_top, v);
    return s.x * s.y > 0.0;
}

bool inBoxRightSide(vec2 v, vec2 left_bottom, vec2 right_top) {
	vec2 s = step(right_top, v);
	return s.x > 0.0;
}

bool inBoxLeftSide(vec2 v, vec2 left_bottom, vec2 right_top) {
	vec2 s = step(left_bottom, v);
	return s.x < 1.0;
}

bool inBoxTopSide(vec2 v, vec2 left_bottom, vec2 right_top) {
	vec2 s = step(right_top, v);
	return s.y > 0.0;
}

bool inBoxBottomSide(vec2 v, vec2 left_bottom, vec2 right_top) {
	vec2 s = step(left_bottom, v);
	return s.y < 1.0;
}

