	background_side[11] = 1;

	box_position[12] = vec2(0.574, 0.0); 
	box_size[12] = vec2(0.162, 0.48); 
	clone_tc[12] = vec4(0.574, 0.0, 0.162, 0.24);
	clone_postion[12] = clone_tc[12].xy;
