	clone_postion[12].y += smoothstep(0.6, 0.85, process) * clone_size[12].y;
	clip_size[12] = clone_size[12] * vec2(0.0, smoothstep(0.75, 1.0, process));
	clone_postion[12].y += clip_size[12].y;
	background_side[12] = 2;

	box_position[13] = vec2(0.574, 0.48); 
	box_size[13] = vec2(0.162, 0.306); 
	clone_tc[13] = vec4(box_position[13], box_size[13]);
	clone_postion[13] = clone_tc[13].xy;
	clone_size[13] = clone_tc[13].zw;
	clip_size[13] = clone_size[13] * vec2(smoothstep(0.45, 0.8, process), 0.0);
	clone_postion[13].x += clip_size[13].x;
	background_side[13] = 0;

	box_position[14] = vec2(0.275, 0.85); 
	box_size[14] = vec2(0.299, 0.15); 
	clone_tc[14] = vec4(box_position[14], box_size[14]);
	clone_postion[14] = clone_tc[14].xy;
	clone_size[14] = clone_tc[14].zw;
	clip_size[14] = clone_size[14] * vec2(0.0, smoothstep(0.3, 0.9, process));
	clone_postion[14].y += clip_size[14].y;
