	clone_size[15] = clone_tc[15].zw;
	clip_size[15] = clone_size[15] * vec2(0.0, smoothstep(0.6, 1.0, process));
	background_side[15] = 3;

	for (int i = 0 ; i < box_num ; ++i) {
		if (insideBox(tc, box_position[i], box_position[i] + box_size[i])) {
			if (insideBox(tc, clone_postion[i], clone_postion[i] + clone_size[i] - clip_size[i])){
				vec2 new_tc = (tc - clone_postion[i]) / clone_size[i];
				new_tc = new_tc * clone_tc[i].zw + clone_tc[i].xy;
				outColor = INPUT1(new_tc);
				break;
			} else {
				if (0 == background_side[i]) {
					if (inBoxLeftSide(tc, clone_postion[i], clone_postion[i] + clone_size[i] - clip_size[i])) {
						outColor = background;
					}
				} else if (1 == background_side[i]) {
					if (inBoxRightSide(tc, clone_postion[i], clone_postion[i] + clone_size[i] - clip_size[i])) {
						outColor = background;
					}
				} else if (2 == background_side[i]) {
					if (inBoxBottomSide(tc, clone_postion[i], clone_postion[i] + clone_size[i] - clip_size[i])) {
						outColor = background;
					}
				} else if (3 == background_side[i]) {
					if (inBoxTopSide(tc, clone_postion[i], clone_postion[i] + clone_size[i] - clip_size[i])) {
						outColor = background;
					}
				}
			}
		}
	}

    return outColor;
}

vec4 FUNCNAME(vec2 tc) {
