// snow color
vec3 RGBToHSL(vec3 color){
    vec3 hsl;
    float fmin = min(min(color.r, color.g), color.b);
    float fmax = max(max(color.r, color.g), color.b);
    float delta = fmax - fmin;

    hsl.z = (fmax + fmin) / 2.0;

    if (delta == 0.0)
    {
        hsl.x = 0.0;
        hsl.y = 0.0;
    }
    else
    {
        if (hsl.z < 0.5)
            hsl.y = delta / (fmax + fmin);
        else
            hsl.y = delta / (2.0 - fmax - fmin);

        float deltaR = (((fmax - color.r) / 6.0) + (delta / 2.0)) / delta;
        float deltaG = (((fmax - color.g) / 6.0) + (delta / 2.0)) / delta;
        float deltaB = (((fmax - color.b) / 6.0) + (delta / 2.0)) / delta;

        if (color.r == fmax )
            hsl.x = deltaB - deltaG;
        else if (color.g == fmax)
            hsl.x = (1.0 / 3.0) + deltaR - deltaB;
        else if (color.b == fmax)
            hsl.x = (2.0 / 3.0) + deltaG - deltaR;

        if (hsl.x < 0.0)
            hsl.x += 1.0;
        else if (hsl.x > 1.0)
            hsl.x -= 1.0;
    }

    return hsl;
}

float HueToRGB(float f1, float f2, float hue){
    if (hue < 0.0)
        hue += 1.0;
    else if (hue > 1.0)
        hue -= 1.0;
    float res;
    if ((6.0 * hue) < 1.0)
        res = f1 + (f2 - f1) * 6.0 * hue;
    else if ((2.0 * hue) < 1.0)
        res = f2;
    else if ((3.0 * hue) < 2.0)
        res = f1 + (f2 - f1) * ((2.0 / 3.0) - hue) * 6.0;
    else
        res = f1;
    return res;
}

vec3 HSLToRGB(vec3 hsl){
    vec3 rgb;

    if (hsl.y == 0.0)
        rgb = vec3(hsl.z);
    else
    {
        float f2;

        if (hsl.z < 0.5)
            f2 = hsl.z * (1.0 + hsl.y);
        else
            f2 = (hsl.z + hsl.y) - (hsl.y * hsl.z);

        float f1 = 2.0 * hsl.z - f2;

        rgb.r = HueToRGB(f1, f2, hsl.x + (1.0/3.0));
        rgb.g = HueToRGB(f1, f2, hsl.x);
        rgb.b= HueToRGB(f1, f2, hsl.x - (1.0/3.0));
    }

    return rgb;
}

vec3 blendSnowColor(vec3 blend, vec3 bgColor) {
    vec3 blendHSL = RGBToHSL(blend);
    vec3 hsl = RGBToHSL(bgColor);
    return HSLToRGB(vec3(blendHSL.r, blendHSL.g, hsl.b));
}

// snow hue
vec3 blendSnowHue(vec3 blend, vec3 bgColor) {
    vec3 baseHSL = RGBToHSL(bgColor.rgb);
    return HSLToRGB(vec3(RGBToHSL(blend.rgb).r, baseHSL.g, baseHSL.b));
}

vec3 blendFunc(vec3 base, vec3 blend, float opacity,int blendMode) {
	if (blendMode == 1)
    	return (blendAdd(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 2)
    	return (blendAverage(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 3)
    	return (blendColorBurn(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 4)
		return (blendColorDodge(base, blend) * opacity + base * (1.0 - opacity));   
	else if (blendMode == 5)
		return (blendDarken(base, blend) * opacity + base * (1.0 - opacity)); 
	else if (blendMode == 6)
		return (blendDifference(base, blend) * opacity + base * (1.0 - opacity));
	else if (blendMode == 7)
		return (blendExclusion(base, blend) * opacity + base * (1.0 - opacity));
	else if (blendMode == 8)
		return (blendGlow(base, blend) * opacity + base * (1.0 - opacity));
	else if (blendMode == 9)
		return (blendHardLight(base, blend) * opacity + base * (1.0 - opacity));
	else if (blendMode == 10)
		return (blendHardMix(base, blend) * opacity + base * (1.0 - opacity));	
	else if (blendMode == 11)
		return (blendLighten(base, blend) * opacity + base * (1.0 - opacity));
	else if (blendMode == 12)
		return (blendLinearBurn(base, blend) * opacity + base * (1.0 - opacity));
	else if (blendMode == 13)
		return (blendLinearDodge(base, blend) * opacity + base * (1.0 - opacity));
	else if (blendMode == 14)
		return (blendLinearLight(base, blend) * opacity + base * (1.0 - opacity));
	else if (blendMode == 15)
		return (blendMultiply(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 16)
        return (blendNegation(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 17)
        return (blendOverlay(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 18)
        return (blendPhoenix(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 19)
        return (blendPinLight(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 20)
        return (blendReflect(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 21)
        return (blendScreen(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 22)
        return (blendSoftLight(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 23)
        return (blendSubstract(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 24)
        return (blendVividLight(base, blend) * opacity + base * (1.0 - opacity));
    else if (blendMode == 25)
        return blendSnowColor(blend, blend);
    else if (blendMode == 26)
        return blendSnowHue(blend, blend);
    else 
        return base;
}




vec4 ChangeFilter(vec4 color, float intensity){
    vec4 textureColor = color;

     float blueColor = textureColor.r * 63.0;

     vec2 quad1;
     quad1.y = floor(floor(blueColor) / 8.0);
     quad1.x = floor(blueColor) - (quad1.y * 8.0);

     vec2 quad2;
     quad2.y = floor(ceil(blueColor) / 8.0);
     quad2.x = ceil(blueColor) - (quad2.y * 8.0);

     vec2 texPos1;
     texPos1.x = (quad1.x * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.b);
     texPos1.y = (quad1.y * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.g);

     vec2 texPos2;
     texPos2.x = (quad2.x * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.b);
     texPos2.y = (quad2.y * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.g);

     vec4 newColor1 = INPUT4(vec2(texPos1.x,texPos1.y)); // 采样滤镜素材
     vec4 newColor2 = INPUT4(vec2(texPos1.x,texPos1.y));

     vec4 newColor = mix(newColor1, newColor2, fract(blueColor));

     vec4 outputFragCol = mix(textureColor, vec4(newColor.rgb, textureColor.s), intensity);
	 outputFragCol.a = textureColor.a;
	 return outputFragCol;
}
vec4 FUNCNAME(vec2 tc) {
    vec2 uv = tc;
    vec2 uv1 = tc;
    float iPro = PREFIX(iglobaltime);
    float uOffsetY = PREFIX(uOffsetY);
    uv1.y -= uOffsetY;
