    if(iPro>=0.57){
        bgColor = INPUT2(uv1);
    }
    vec4 OriImage = bgColor;
    bgColor = ChangeFilter(bgColor, 1.0);
    if(OriImage.r == 0.0 && OriImage.g == 0.0 && OriImage.b == 0.0){
        bgColor = vec4(0.0);
    }
    uv.y = 1.0 - uv.y;

    vec4 fgColor = INPUT3(uv);
    vec3 color = blendFunc(bgColor.rgb, clamp(fgColor.rgb * (1.0 / fgColor.a), 0.0, 1.0), 1.0, 14);
    float gray = dot(color, vec3(0.299, 0.587, 0.114));
    float graybg = dot(bgColor.rgb, vec3(0.299, 0.587, 0.114));
    if(graybg > 0.0 ){
        gray = bgColor.a;
    }
    vec4 fragColors = vec4(bgColor.rgb * (1.0 - fgColor.a) + color.rgb * fgColor.a, gray);

    vec4 fgColor2 =  INPUT5(uv1);
    fgColor2.rgba *= vec4(4.0, 2.0, 3.0, 4.0);
    vec3 color2 = blendFunc(fragColors.rgb, clamp(fgColor2.rgb * (1.0 / fgColor2.a), 0.0, 1.0), 1.0, 22);
    fragColors = vec4(fragColors.rgb * (1.0 - fgColor2.a) + color2.rgb * fgColor2.a, fragColors.a);

    return fragColors;
}

