    float ratio = iResolution.x / iResolution.y;
    vec2 SuCaiResolution = vec2(1920.0, 1080.0);
    if (PREFIX(uStep) == 0)
    {
        vec2 uv = tc;
        vec2 uv1 = tc;
        float iPro = PREFIX(iglobaltime);
        float uOffsetX = PREFIX(uOffsetX);

        uv1 = NormalRotate(uv1, uAngle, 1.0, ratio);
        uv = NormalRotate(uv, uAngle, 1.0, ratio);
        uv1.y -= uOffsetY;
        uv1.y = fract(uv1.y);
        uv1 = GetScaleResult(uv1, vec2(uScale, uScale));
        vec4 bgColor = INPUT1(uv1);
        if (iPro >= 0.45)
        {
            vec4 fg = INPUT1(uv1);
            vec4 bg = INPUT2(uv1);
            bgColor = mix(fg, bg, uBgFgOpacity);
        }
        vec4 LutColor = ChangeFilter(bgColor, 1.0);
        if(bgColor.r == 0.0 && bgColor.g == 0.0 && bgColor.b == 0.0){
            LutColor = vec4(0.0);
        }
        bgColor = mix(bgColor, LutColor, uLutOpacity);
        bgColor *= uGlow;

        // use sucai to blend
        // uv = SucaiUVs(uv, SuCaiResolution, 0.0, 1.0, 1.0);

        uv.y = 1.0 - uv.y;

        vec4 fgColor = INPUT3(uv);
        vec3 color = blendFunc(bgColor.rgb, clamp(fgColor.rgb * (1.0 / fgColor.a), 0.0, 1.0), 1.0, 14);
        fragColors = vec4(bgColor.rgb * (1.0 - fgColor.a) + color.rgb * fgColor.a, bgColor.a);
    }
    else
    {
        vec2 uv = tc;
        uv.x += uStep2OffsetX;
        fragColors = INPUT1(uv);
    }
    return fragColors;
}

