float hash11(float p)
{
  p = fract(p * .1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash12(vec2 p)
{
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec4 colorShift(vec4 icolor, vec2 iuv, float iglobalTime) {
  vec2 shiftUV = iuv;
  vec4 shiftColor = vec4(0.0);
  shiftUV.x = fract(shiftUV.x);
  shiftUV.x += 0.01 * (1.0 - abs(2.0 * iglobalTime - 1.0));
  // if(iglobalTime <= 0.5){
  //   shiftColor += INPUT1(shiftUV);
  // }else{
  //   shiftColor += INPUT2(shiftUV);
  // }
  shiftColor += INPUT3(shiftUV);
  float randomShift = step(0.5, hash11(iglobalTime));
  icolor.rg = shiftColor.rg * randomShift + icolor.rg * (1.0 - randomShift);
  icolor.rb = shiftColor.rb * (1.0 - randomShift) + icolor.gb * randomShift;

  return icolor;
}

