  float seedTime = floor(shiftProcess * 30.0 * iFrequency);
  float halfAmp = iStrength * 0.1;
  float sliceAmount = 8.0 * (1.0-pow(abs(2.0*shiftProcess-1.0), 4.0));

  float rgbSplit = 2.0 * hash12(vec2(shiftProcess * 200.0)) - 1.0;

  vec4 layer1 = vec4(0.0);
  vec4 layer2 = vec4(0.0);
  vec4 layer3 = vec4(0.0);
  vec4 layer4 = vec4(0.0);
  vec4 layer5 = vec4(0.0);

  // fragOutCol = DirectionBlur(uv, blurProcess, iGlobalTime);
  fragOutCol = INPUT3(uv);
