  // layer3 = DirectionBlur((uv - center) * 0.94 + center, blurProcess, iGlobalTime);
  layer3 = INPUT3((uv - center) * 0.86 + center);
  layer3 = colorShift(layer3, (uv - center) * 0.86 + center, iGlobalTime);
  // layer4 = DirectionBlur((uv - center) * 0.88 + center, blurProcess, iGlobalTime);
  layer4 = INPUT3((uv - center) * 0.74 + center);
  layer4 = colorShift(layer4, (uv - center) * 0.74 + center, iGlobalTime);
  // layer5 = DirectionBlur((uv - center) * 0.8 + center, blurProcess, iGlobalTime);
  layer5 = INPUT3((uv - center) * 0.58 + center);
  layer5 = colorShift(layer5, (uv - center) * 0.58 + center, iGlobalTime);

  //// frame 1
  if (iGlobalTime >= 0.4 && shiftProcess >= 0.05 && shiftProcess < 0.25 && iGlobalTime <= 0.6) {
    fragOutCol = mix(layer1, layer2, step(0.8, uv.y));
    fragOutCol = mix(layer2, fragOutCol, step(0.4, uv.y));
  } else if (iGlobalTime >= 0.4 && shiftProcess >= 0.25 && shiftProcess < 0.35 && iGlobalTime <= 0.6) {
  //// frame 2
    fragOutCol = mix(layer2, layer3, step(0.4, uv.y));
    fragOutCol = mix(fragOutCol, layer2, step(0.8, uv.y));
  } else if (iGlobalTime >= 0.4 && shiftProcess >= 0.35 && shiftProcess < 0.45 && iGlobalTime <= 0.6) {
  //// frame 3
    fragOutCol = mix(layer3, layer4, step(0.5, uv.y));
  } else if (iGlobalTime >= 0.4 && shiftProcess >= 0.45 && iGlobalTime <= 0.6){
  //// frame 4
    vec4 mixLayer = mix(layer3, layer4, 0.4);
    fragOutCol = mix(layer5, mixLayer, step(0.5, uv.y));
    fragOutCol = mix(fragOutCol, layer5, step(0.8, uv.y)); 
  }

