  color = vec3(mix(greyScaleColor, contrastColor, 1.0 + shiftProcess*8.0));

  fragOutCol.rgb = fragOutCol.rgb + fragOutCol.rgb*color*step(0.01, shiftProcess);

  return fragOutCol;
}

