#define PI 3.14159265

float random(float p){
  return fract(sin(p*12.9898) * 43758.5453123);
}

float fbmNoise(float p) {
  float value = 0.0;
  float freq = 1.13;
  float amp = 0.57;
  const int octaves = 3;
  for (int i = 0; i < octaves; i++) {
    value += amp * (random((p-0.3)*freq)*2.0-1.0);
    freq *= 1.61;
    amp *= 0.47;
  }
  return value;
}

vec4 RGBSplit(vec2 uv, vec2 offset1, vec2 offset2) {
  vec2 uvSplit1 = uv + offset1;
  vec2 uvSplit2 = uv + offset2;

  vec4 retColor = INPUT1(uv);
  retColor.r = INPUT1(uvSplit1).r;
  retColor.b = INPUT1(uvSplit2).b;

  return retColor*retColor.a;
}

float CLAMP01(float x){
  return clamp(x, 0.0, 1.0);
}

float clampWaveFunc(float t, float lv, float rv){
  return CLAMP01((t-lv)/(rv-lv));
}

float tipTimeCurve(float t){
  t = t*2.0-1.0;
  return CLAMP01(pow(min(cos(PI*t/2.0), 1.0-abs(t)), 2.0));
}

float signFunc(float x){
  if(x < 0.0){
    return -1.0;
  }
  return 1.0;
}

vec4 FUNCNAME(vec2 tc) {
  vec2  uv = tc;
  float iPro = PREFIX(iPro);

  vec2  offset1 = vec2(0.12, 0.0);
  vec2  offset2 = vec2(-0.114, 0.0);

  iPro = CLAMP01(iPro-0.07)*3.0;
  float f = fract(iPro);
  float i = floor(iPro);
  if(i == 2.0){
    return INPUT1(uv);
  }

  float lv = mix(0.2, 0.0, i);
  float rv = mix(0.78, 0.64, i);
  float tPro = clampWaveFunc(f, lv, rv);
  tPro = tipTimeCurve(tPro)*signFunc(fbmNoise((f*11.2+i*2.3)*13.5));

  return RGBSplit(uv, offset1*tPro, offset2*tPro);
}

