float easeOutQuint(float x) {
    return 1.0 - pow(1.0 - x, 5.0);
}

float easeOutCirc(float x) {
    return sqrt(1.0 - pow(x - 1.0, 2.0));
}

vec4 rgbSeparation(vec2 uv, float angle) {
    float splitAmount = angle; 
    splitAmount = clamp(splitAmount, 0.0, 1.0); 

    float amount = splitAmount*0.2; 

    vec3 col;
    col.r = INPUT1(vec2(uv.x + amount, uv.y)).r;
    col.g = INPUT1(uv).g;
    col.b = INPUT1(vec2(uv.x - amount, uv.y)).b; 
    col *= (1.0 - amount * 0.5);

    float alpha = INPUT1(uv).a;

    return vec4(col, alpha);
}

vec4 rgbSeparation1(vec2 uv, float angle) {
    float splitAmount = angle; 
    splitAmount = clamp(splitAmount, 0.0, 1.0); 

    float amount = splitAmount*0.2; 

    vec3 col;
    col.r = INPUT2(vec2(uv.x + amount, uv.y)).r;
    col.g = INPUT2(uv).g;
    col.b = INPUT2(vec2(uv.x - amount, uv.y)).b; 

    col *= (1.0 - amount * 0.5);

    float alpha = INPUT2(uv).a;
    return vec4(col, alpha);
}


vec2 rotate(vec2 videoImageCoord, vec2 centerImageCoord, float radianAngle)
{
    mat2 rotateMat = mat2(cos(radianAngle), -sin(radianAngle),
                          sin(radianAngle), cos(radianAngle));
    vec2 deltaOffset = rotateMat * (videoImageCoord - centerImageCoord);
    videoImageCoord = deltaOffset + centerImageCoord;
    return videoImageCoord;
}

vec4 RotateBlur(vec2 tc, vec2 blurCenter, int numSamples, float rotateAngle) {
    vec4 fragColor = vec4(0.0);
    vec2 rotateCenter = blurCenter * iResolution.xy;

    for (int i = 0; i < numSamples; i++) {
        float fraction = float(i) / float(numSamples);
        float sampleAngle = fraction * rotateAngle; 
        vec2 sampleUV = rotate(tc * iResolution.xy, rotateCenter, sampleAngle) / iResolution.xy;
        //fragColor += INPUT1(sampleUV);
        fragColor += rgbSeparation(sampleUV, sampleAngle);
    }
    fragColor=fragColor / float(numSamples);
    return fragColor;
}

vec4 RotateBlur2(vec2 tc, vec2 blurCenter, int numSamples, float rotateAngle) {
    vec4 fragColor = vec4(0.0);
    vec2 rotateCenter = blurCenter * iResolution.xy;

    for (int i = 0; i < numSamples; i++) {
        float fraction = float(i) / float(numSamples);
        float sampleAngle = fraction * rotateAngle; 
        vec2 sampleUV = rotate(tc * iResolution.xy, rotateCenter, sampleAngle) / iResolution.xy;
        //fragColor += INPUT2(sampleUV);
        fragColor += rgbSeparation1(sampleUV, sampleAngle);
    }
    return fragColor / float(numSamples);
}

