bool insideUnit(vec2 uv) {
    return uv.x > 0.0 && uv.x < 1.0 && uv.y > 0.0 && uv.y < 1.0;
}

vec2 reflectionUv(vec2 uv) {
    return uv * vec2(1.0, -1.2);
}

vec4 reflectedBackground(vec2 uvA, vec2 uvB) {
    const vec4 floorColor = vec4(0.12, 0.12, 0.12, 1.0);
    const float reflection = 0.4;

    vec2 reflectedB = reflectionUv(uvB);
    if (insideUnit(reflectedB)) {
        float strength = reflection * (1.0 - reflectedB.y);
        vec4 color = floorColor + mix(floorColor, INPUT2(reflectedB), strength);
        color.rgb *= 1.0 - reflectedB.y;
        color.a = 1.0;  // 反射投影命中：保留深色地面与反射内容
        return color;
    }

    vec2 reflectedA = reflectionUv(uvA);
    if (insideUnit(reflectedA)) {
        float strength = reflection * (1.0 - reflectedA.y);
        vec4 color = floorColor + mix(floorColor, INPUT1(reflectedA), strength);
        color.rgb *= 1.0 - reflectedA.y;
        color.a = 1.0;  // 反射投影命中：保留深色地面与反射内容
        return color;
    }

    // 无画面、无反射覆盖：保持透明，透出下层轨道。
    return vec4(0.0);
}

vec4 FUNCNAME(vec2 tc) {
    float linearProgress = clamp(PREFIX(iProgress), 0.0, 1.0);

    // [@规则:R-T05] 源包把 0→1 的线性关键帧送入 sin(time)*1.19；
    // 这里保留该节奏并显式闭合端点，避免源公式在尾帧略微超过 1。
    if (linearProgress <= 0.0) return INPUT1(tc);
    if (linearProgress >= 1.0) return INPUT2(tc);
    float progress = clamp(sin(linearProgress) * 1.19, 0.0, 1.0);

    // [@特性:透视切屏] A 以左边缘为轴压缩退场，B 从右侧透视展开进入。
    float scaleA = mix(1.0, 3.0, progress);
    float skewA = 0.2 * progress;
    vec2 uvA = (tc - vec2(0.0, 0.5)) * vec2(
        scaleA / (1.0 - skewA),
        scaleA / (1.0 - scaleA * skewA * tc.x)
    ) + vec2(0.0, 0.5);

    float inverseProgress = 1.0 - progress;
    float scaleB = mix(1.0, 3.0, inverseProgress);
    float skewB = 0.2 * inverseProgress;
    vec2 uvB = (tc - vec2(1.0, 0.5)) * vec2(
        scaleB / (1.0 - skewB),
        scaleB / (1.0 - scaleB * skewB * (0.5 - tc.x))
    ) + vec2(1.0, 0.5);

    // 源 Shader 在交叠区域前半程优先 A、后半程优先 B。
    if (progress < 0.5) {
        if (insideUnit(uvA)) return INPUT1(uvA);
        if (insideUnit(uvB)) return INPUT2(uvB);
    } else {
        if (insideUnit(uvB)) return INPUT2(uvB);
        if (insideUnit(uvA)) return INPUT1(uvA);
    }

    return clamp(reflectedBackground(uvA, uvB), 0.0, 1.0);
}

vec2 SetFixScale(vec2 p, float ratio){
  p -= 0.5;
  p.x *= iResolution.x / iResolution.y * ratio;
  p += 0.5;
  return p;
}

float sdCircle( vec2 p, vec2 c, float r, float ratio, out float out_step){
  p = SetFixScale(p, ratio);
  c = SetFixScale(c, ratio);
  out_step = step(c.x, p.x);
  return (1.0 - smoothstep(r, r + 0.005, length(p - c)));// * step(c.x, p.x);
}

float sat(float x){
  return clamp(x, 0.0, 1.0);
}

vec4 mixFunc(vec4 back, vec4 overlap, float alp) {
  float invAlp = 1.0 - alp;
  vec4 ret = back;

  if (alp > 0.0) {
    ret.xyz = overlap.xyz + back.xyz * invAlp;
    ret.a = alp + back.a * invAlp;
  }
  return ret;
}

