// =============================================================================
// Direction Blur · frag
// Pass0：progress<0.5→A，>=0.5→B
// Pass1：LumiDirectionalBlurs 单方向 Gaussian（borderType=Black + exposure 乘数）
// Pass2：直通/上采样
// =============================================================================

const float kPI = 3.141592653589793;
// CapCut LumiLayer_54：InputTex 在 aeTime∈[0,1]（总 2s）→ 中点硬切
const float kSwitchP = 0.5;

// [@pass:uStep=0]
vec4 featureSelect(vec2 tc) {
    // [@规则:R-T05] p=0 只显示 A/INPUT1，p=1 只显示 B/INPUT2
    float p = PREFIX(iProgress);
    if (p <= 0.0) {
        return INPUT1(tc);
    }
    if (p >= 1.0) {
        return INPUT2(tc);
    }
    return (p < kSwitchP) ? INPUT1(tc) : INPUT2(tc);
}

float gaussianWeight(float x, float sigma) {
    return exp((-0.5 * x * x) / max(sigma * sigma, 1e-6));
}

vec2 aspectScale(vec2 wh) {
    // CapCut getXYScale：避免极端宽高比
    float size1 = min(wh.x, wh.y);
    float size2 = max(wh.x, wh.y) * 0.5;
    float baseSize = max(size1, size2);
    return vec2(baseSize / max(wh.x, 1.0), baseSize / max(wh.y, 1.0));
}

// CapCut getSampleNum + quality=0.5 → qualityParam≈1
float calcSampleNum(float intensity) {
    float sampleNum = 0.0;
    if (intensity <= 10.0) {
        sampleNum = 0.8 * intensity;
    } else if (intensity <= 50.0) {
        sampleNum = (0.7 * intensity + 2.0) * 0.78;
    } else if (intensity <= 200.0) {
        sampleNum = (0.5 * intensity + 10.0) * 0.66;
    } else if (intensity <= 500.0) {
        sampleNum = (0.25 * intensity + 60.0) * 0.7;
    } else {
        sampleNum = (0.125 * intensity + 100.0) * 0.8;
    }
    return max(sampleNum, 1.0);
}

// CapCut：startAngle=(-angle-90)*pi/180；radius=intensity/1000；borderType=Black
vec4 directionalBlur(vec2 tc, float intensity, float angleDeg, float exposure) {
    if (intensity < 1e-3) {
        return INPUT1(tc);
    }

    float sampleNum = calcSampleNum(intensity);
    // 降采样后仍设采样上限，兼顾质量与性能
    sampleNum = min(sampleNum, 64.0);

    float radius = intensity / 1000.0;
    float sigma = radius / 3.0;
    float ds = radius / max(sampleNum, 1e-5);
    float theta = (-angleDeg - 90.0) * kPI / 180.0;
    vec2 xyScale = aspectScale(iResolution.xy);
    vec2 stepUv = vec2(cos(theta), sin(theta)) * ds * xyScale;

    float wSum = gaussianWeight(0.0, sigma);
    vec4 acc = INPUT1(tc) * wSum;

    for (int i = 1; i <= 64; ++i) {
        float fi = float(i);
        if (fi > sampleNum) {
            break;
        }
        float w = gaussianWeight(length(stepUv * fi), sigma);
        vec2 o = stepUv * fi;
        vec2 u0 = tc - o;
        vec2 u1 = tc + o;

        // borderType=Black：越界只累加权重，不加颜色（边缘压暗）
        bool in0 = (u0.x >= 0.0 && u0.y >= 0.0 && u0.x <= 1.0 && u0.y <= 1.0);
        bool in1 = (u1.x >= 0.0 && u1.y >= 0.0 && u1.x <= 1.0 && u1.y <= 1.0);
        if (in0) {
            acc += INPUT1(u0) * w;
        }
        wSum += w;
        if (in1) {
            acc += INPUT1(u1) * w;
        }
        wSum += w;
    }

    vec4 outCol = acc / max(wSum, 1e-6);
    // CapCut directionNum==1：rgb *= exposure
    outCol.rgb *= exposure;
    return clamp(outCol, 0.0, 1.0);
}

// [@pass:uStep=1]
vec4 featureBlur(vec2 tc) {
    return directionalBlur(tc, PREFIX(uBlur), PREFIX(uAngle), PREFIX(uExposure));
}

// [@pass:uStep=2]
vec4 featureCopy(vec2 tc) {
    return INPUT1(tc);
}

vec4 FUNCNAME(vec2 tc) {
