// 贝塞尔曲线
vec2 bezier(float t) {
// 控制点
vec2 points[4] = vec2[](
  vec2(0.00, 0.00),
vec2(0.25, -0.01),
vec2(0.74, 0.73),
vec2(1.00, 1.00)
);
  // 计算贝塞尔曲线
  vec2 p = vec2(0.0);
  int n1 = 3;
  for(int i = 0; i <= n1; i++) {
      float coef = float(1);
      // 计算组合数 C(n1,i)
      for(int j = 1; j <= i; j++) {
          coef *= float(n1 - j + 1) / float(j);
      }
      // 计算贝塞尔多项式
      p += points[i] * coef * pow(1.0 - t, float(n1 - i)) * pow(t, float(i));
  }

  return p;
}

float findBezierY(float x) {
  float epsilon = 0.0001;  // 精度控制
  float tMin = 0.0;
  float tMax = 1.0;
  float t = 0.5;

  // 二分查找
  for(int i = 0; i < 16; i++) {  // 最多迭代16次
      vec2 p = bezier(t);

      // 如果找到足够接近的点，返回y值
      if(abs(p.x - x) < epsilon) {
          return p.y;
      }

      // 二分查找
      if(p.x < x) {
          tMin = t;
      } else {
          tMax = t;
      }

      t = (tMin + tMax) / 2.0;
  }

  // 返回最终找到的y值
  return bezier(t).y;
}


