// Ease-out quadratic
float easeOut(float t) {
    return t * (2.0 - t);
}

vec4 FUNCNAME(vec2 tc) {
    vec4 result = INPUT1(tc);
    float nTime = PREFIX(uProgress);  // normalized time 0~1

    // 8 vertical strips, each 1/8 screen width
    float stripW = 0.125;

    // Determine which strip this pixel belongs to
    int stripIdx = int(floor(tc.x / stripW));
    if (stripIdx < 0) stripIdx = 0;
    if (stripIdx > 7) stripIdx = 7;

    // Per-strip delay: strip 0 (left) = 0.0, strip 7 (right) = 0.35
    float delay = float(stripIdx) * 0.05;

    // Before animation starts, this strip shows INPUT1 only
    if (nTime <= delay) {
        return result;
    }

    float localT = min((nTime - delay) / (1.0 - delay), 1.0);
    float progress = easeOut(localT);

    // Block Y: top group center moves from 0.5 (center) toward 1.2 (off top)
    float blockY = mix(0.5, 1.2, progress);
    // Bottom group mirror: 0.5 -> -0.2
    float blockYB = 1.0 - blockY;

    // Heights shrink: blue narrows faster (x1.5 speed), blur at normal speed
    float blueH = 0.3 * max(1.0 - progress * 1.5, 0.0);
    float blurH = 0.5 * (1.0 - progress);

    // Blocks fully collapsed -> show INPUT2
    if (blueH < 0.001 && blurH < 0.001) {
        result = INPUT2(tc);
        return result;
    }

    // === TOP GROUP: blue moves up, blur sits BELOW blue (toward center) ===
    float T_blueBot = blockY - blueH * 0.5;
    float T_blueTop = blockY + blueH * 0.5;
    float T_blurTop = T_blueBot;
    float T_blurBot = max(T_blurTop - blurH, 0.5);  // clamp at center

    // === BOTTOM GROUP (mirror): blue moves down, blur sits ABOVE blue (toward center) ===
    float B_blueTop = blockYB + blueH * 0.5;
    float B_blueBot = blockYB - blueH * 0.5;
    float B_blurBot = B_blueTop;
    float B_blurTop = min(B_blurBot + blurH, 0.5);  // clamp at center

    vec4 blueColor = vec4( 0.85, 0.52,0.45, 1.0);

    // Scaled UV for 1.3x zoom on INPUT2/INPUT3 (center at 0.5)
    vec2 scaledTc = (tc - 0.5) / 1.3 + 0.5;

    // Determine color based on Y position (top to bottom)
    // Above top blue: INPUT1
    if (tc.y > T_blueTop) {
        // INPUT1 (default)
    }
    // Top blue zone
    else if (tc.y >= T_blueBot) {
        result = blueColor;
    }
    // Top blur zone (between blue and center)
    else if (tc.y >= T_blurBot) {
        result = INPUT3(scaledTc);
    }
    // Center: between top blur and bottom blur -> INPUT2 (revealed)
    else if (tc.y > B_blurTop) {
        result = INPUT2(tc);
    }
    // Bottom blur zone (between center and blue)
    else if (tc.y >= B_blurBot) {
        result = INPUT3(scaledTc);
    }
    // Bottom blue zone
    else if (tc.y >= B_blueBot) {
        result = blueColor;
    }
    // Below bottom blue: INPUT1
    else {
        // INPUT1 (default)
    }

    return result;
}

#define PI 3.141592653

float A(float aA1, float aA2) {
    return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
    return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
    return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
    return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
    return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
    float aGuessT = aX;
    for (int i = 0; i < 6; ++i) {
        float currentSlope = GetSlope(aGuessT, mX1, mX2);
        if (currentSlope == 0.0)
            return aGuessT;
        float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
        aGuessT -= currentX / currentSlope;
    }
    return aGuessT;
}

float KeySpline(vec4 p, float aX) {
    float mX1 = p.x;
    float mY1 = p.y;
    float mX2 = p.z; 
    float mY2 = p.w;
    if (mX1 == mY1 && mX2 == mY2)
        return aX;    // linear
    return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

float normpdf(float x, float sigma){
    return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

vec4 GaussianBlur(vec2 tc, vec2 dir, float strength, float samples, vec2 iResolution)
{
    float sigma = 5.0;
    float weight = normpdf(0.0, sigma);

    vec4 sumCol = vec4(0.0);
    vec4 retCol = vec4(0.0);
    vec2 offset = dir * strength;
    vec4 origCol = pow(INPUT1(tc), vec4(2.2)) * weight;
    float total_weight = weight;

    for(float i = 1.0; i <= samples; i += 1.0)
    {
        vec2 uv1 = tc + (-i) * offset / iResolution;
        vec2 uv2  = tc + i * offset / iResolution;
        vec4 color1 = INPUT1(uv1);
        vec4 color2 = INPUT1(uv2);
        weight = normpdf(i / samples * 15.0, sigma);
        sumCol += pow(color1, vec4(2.2)) * weight;
        sumCol += pow(color2, vec4(2.2)) * weight;
        total_weight += weight * 2.0;
    }

    retCol = (sumCol + origCol) / total_weight; 
    retCol = clamp(pow(retCol, vec4(1.0 / 2.2)), 0.0, 1.0);

    return retCol;
}

float Sample(vec2 uv, vec2 offset, vec2 iResolution)
{
    float factor = iResolution.y / 433.0;
    vec4 color = INPUT1(uv + (offset / iResolution.xy) * factor);
    return dot(color.rgb, vec3(0.114, 0.587, 0.299));
}

vec4 SobelFilter(vec2 uv, vec2 iResolution, int Color, float Glow, float process)
{
    float tl = Sample(uv, vec2(-1.0, 1.0), iResolution);
    float tc = Sample(uv, vec2(0.0, 1.0), iResolution);
    float tr = Sample(uv, vec2(1.0, 1.0), iResolution);

    float l = Sample(uv, vec2(-1.0, 0.0), iResolution);
    float c = Sample(uv, vec2(0.0, 0.0), iResolution);
    float r = Sample(uv, vec2(1.0, 0.0), iResolution);

    float bl = Sample(uv, vec2(-1.0, -1.0), iResolution);
    float bc = Sample(uv, vec2(0.0, -1.0), iResolution);
    float br = Sample(uv, vec2(1.0, -1.0), iResolution);

    float gx = tl - tr + 2.0 * l - 2.0 * r + bl - br;
    float gy = -tl - 2.0 * tc - tr + bl + 2.0 * bc + br;

    vec3 inputCol = vec3(float(Color & 0xff), float((Color >> 8) & 0xff), float((Color >> 16) & 0xff)) / 255.0;

    float gradient = gx * gx + gy * gy;
    float strength = mix(0.5, 2.0, process);
    vec3 sobelCol = (step(0.00001, inputCol.r + inputCol.g + inputCol.b) * (inputCol.rgb - vec3(-0.2)) + vec3(-0.2)) * gradient * strength * Glow;

    vec4 retCol = INPUT1(uv);
    retCol.rgb = sobelCol;
    retCol = clamp(retCol, 0.0, 1.0);

    return retCol;
}

vec4 adjustExposure(vec4 color, float exposure, float contrast){
    vec4 retCol = color;
    retCol.rgb = pow(retCol.rgb, vec3(2.2));
    if(exposure < 0.0){
        retCol.rgb *= pow(2.0, exposure * 0.02353);
    }else if(exposure > 0.0){
        retCol.rgb *= 1.0 + pow(vec3(6.0), -retCol.rgb) * exposure * 0.034;
    }
    retCol.rgb = pow(retCol.rgb, vec3(1.0 / contrast));
    retCol.rgb = pow(retCol.rgb, vec3(1.0 / 2.2));
    retCol = clamp(retCol, 0.0, 1.0);
    return retCol;
}

