vec4 opticsCompensation(vec2 tc)
{
    vec2 distort = PREFIX(distortParam);
    //vec2 distort = vec2(1.0, 1.0);
    vec2 uv = tc - vec2(0.5);

    float x = uv.x * 0.8;
    float y = uv.y * 0.8;
    float r2 = x * x + y * y;
    float r = sqrt(r2);

    float distortFactor = 1.;
    distortFactor = 1. / (1. + distort.x * r + distort.y * r2);
    vec4 resColor = vec4(0.);
    if (distortFactor > 0.) {
        uv.x = uv.x * distortFactor;
        uv.y = uv.y * distortFactor;
        uv += vec2(0.5);
        if (uv.x >= 0. && uv.x <= 1.0 && uv.y >= 0. && uv.y <= 1.0) {
            resColor = INPUT2(uv);
        }
    }
    return resColor;
}

vec4 exposure(vec4 col){
    float progress = PREFIX(progress);
    progress = clamp(progress, 0.4, 0.6);
    progress = (progress - 0.4) / 0.2;

    progress = sin(progress*PI);
    float intensity = 2.0*progress;
    col.rgb = pow(col.rgb, vec3(2.2));
    col.rgb *= pow(2.0, intensity);
    vec3 s = sign(col.rgb);
    col.rgb = pow(abs(col.rgb), vec3(1.0)) * s;
    s = sign(col.rgb);
    col.rgb = pow(abs(col.rgb), vec3(0.454545454545)) * s;
    return col;
}

