    vec2 uv = tc;
    vec2 center = vec2(0.5);
    float progress = PREFIX(progress);
    int nsamples = 30;
    uv -= center;
    uv = uv * (1.0 - exp(-20.0*pow(progress-0.5, 2.0))*0.125);
