    uv += center;

    float blurStart = 1.0;
    float blurWidth = exp(-20.0*pow(progress-0.5, 2.0))*0.2;

    uv -= center;
    float precompute = blurWidth * (1.0 / float(nsamples - 1));

    vec4 color = vec4(0.0);
