float Corner(vec2 itc, float iprocess)
{
    float radius = 50.0 * iprocess;
    float top = iResolution.y - radius;
    float right = iResolution.x - radius;
    vec4 fill = vec4(0.0, 1.0, 0.0, 1.0);
    vec4 none = vec4(1.0, 1.0, 1.0, 1.0);
    float state = 0.0;

    if (itc.x < radius) {
      if (itc.y < radius) {
        if (distance(itc, vec2(radius, radius)) <= radius) {
          state = 1.0;
        }
      } else if (itc.y > top) {
        if (distance(itc, vec2(radius, top)) <= radius) {
          state = 1.0;
        }
      } else {
        state = 1.0;
      }
    } else if (itc.x > right) {
      if (itc.y < radius) {
