float motionBlurEnvelope(float progress) {
    // 清晰 → 模糊 → 清晰；峰值覆盖主体翻转最快的约 0.60～0.68。
    float rise = smoothstep(0.45, 0.60, progress);
    float fall = 1.0 - smoothstep(0.68, 0.84, progress);
    return rise * fall;
}

vec4 renderHorizontalMotionBlur(vec2 uv) {
    float blurStrength = motionBlurEnvelope(clamp(PREFIX(iProgress), 0.0, 1.0));
    if (blurStrength <= 0.0001) {
        return INPUT1(uv);
    }

    // [@特性:水平运动模糊] 密集 17-tap 高斯采样，最大覆盖约 ±12 像素。
    // 相邻采样仅约 1.5 像素，避免稀疏采样形成梳状细纹和离散重影。
    vec2 stepUV = vec2(1.5 * blurStrength / iResolution.x, 0.0);
    vec4 color = vec4(0.0);
    float weightSum = 0.0;
    for (float offset = -8.0; offset <= 8.0; offset += 1.0) {
        float weight = exp(-0.5 * (offset * offset) / 9.0);
        color += INPUT1(uv + stepUV * offset) * weight;
        weightSum += weight;
    }
    return color / max(weightSum, 0.0001);
}

