        // FBO 未被 3D 几何覆盖的位置保持纯黑且不透明。
        return vec4(sliceColor.rgb, 1.0);
    }
    return vec4(0.0, 0.0, 0.0, 1.0);
}

float sineInOut(float t)
{
    float x = clamp(t, 0.0, 1.0);
    return 0.5 - 0.5 * cos(3.14159265358979323846 * x);
}

float sineOut(float t)
{
    float x = clamp(t, 0.0, 1.0);
    return sin(1.57079632679489661923 * x);
}

float exponentialIn(float t)
{
    float x = clamp(t, 0.0, 1.0);
    return x <= 0.0 ? 0.0 : pow(2.0, 10.0 * x - 10.0);
}

int tileRank(int row, int col)
{
    // 源数组按距中心稳定排序：中心4块 → 边中8块 → 四角。
    if (row == 1 && col == 1) return 0;
    if (row == 1 && col == 2) return 1;
    if (row == 2 && col == 1) return 2;
    if (row == 2 && col == 2) return 3;
    if (row == 0 && col == 1) return 4;
    if (row == 0 && col == 2) return 5;
    if (row == 1 && col == 0) return 6;
    if (row == 1 && col == 3) return 7;
    if (row == 2 && col == 0) return 8;
    if (row == 2 && col == 3) return 9;
    if (row == 3 && col == 1) return 10;
    if (row == 3 && col == 2) return 11;
    if (row == 0 && col == 0) return 12;
    if (row == 0 && col == 3) return 13;
    if (row == 3 && col == 0) return 14;
    return 15;
}

float tileZ(float p, float rank)
{
    // 2秒源时间轴：100ms + rank*40ms 后冲出750ms，随后回落850ms。
    float flyOutStart = 0.05 + rank * 0.02;
    float flyBackStart = 0.425 + rank * 0.02;
    if (p < flyOutStart) return 0.0;
    if (p < flyBackStart) {
        return 7.0 * exponentialIn((p - flyOutStart) / 0.375);
    }
    return 7.0 * (1.0 - sineOut((p - flyBackStart) / 0.425));
}

float cameraZ(float p)
{
    // PerspectiveCamera(53.1°)：50–900ms 从 z=10 推到8，900–1950ms 回到10。
    if (p < 0.45) {
        return mix(10.0, 8.0, sineInOut((p - 0.025) / 0.425));
    }
    return mix(8.0, 10.0, sineInOut((p - 0.45) / 0.525));
}

float revealMask(vec2 uv, float p)
{
    // 源 shader 的画幅校正与 200–1800ms 中心向外圆形揭示。
    float ratio = iResolution.x / max(iResolution.y, 1.0);
    vec2 aspectUv = uv;
    if (ratio > 1.0) {
        aspectUv.y = aspectUv.y / ratio + (1.0 - 1.0 / ratio) * 0.5;
    } else {
        aspectUv.x = aspectUv.x * ratio + (1.0 - ratio) * 0.5;
    }
    float reveal = sineInOut((p - 0.10) / 0.80);
    float radius = reveal * 1.5;
    float dist = distance(aspectUv, vec2(0.5, 0.5));
    return smoothstep(radius - 0.01, radius + 0.01, dist);
}

vec4 featureTiles(vec2 tc)
{
    // iProgress 已由 effect 映射到 20%–80% 窗口内的 0→1。
    float p = clamp(PREFIX(iProgress), 0.0, 1.0);
    float camZ = cameraZ(p);
    float bestZ = -1.0;
    vec4 result = vec4(0.0);

    // 每块始终正对相机，仅沿 Z 轴运动。用透视逆映射还原等价的16平面投影，
    // 并以最大 Z 选择最靠近相机的重叠块。
    for (int i = 0; i < 16; i++) {
        int row = i / 4;
        int col = i - row * 4;
        float z = tileZ(p, float(tileRank(row, col)));
        float scale = 10.0 / max(camZ - z, 0.05);
        vec2 sourceUv = vec2(0.5, 0.5) + (tc - vec2(0.5, 0.5)) / scale;
        vec2 tileMin = vec2(float(col), float(3 - row)) * 0.25;
        vec2 tileMax = tileMin + vec2(0.25, 0.25);
        bool inside = sourceUv.x >= tileMin.x && sourceUv.x <= tileMax.x
                   && sourceUv.y >= tileMin.y && sourceUv.y <= tileMax.y;
        if (inside && z >= bestZ) {
            vec4 colorA = INPUT1(sourceUv);
            vec4 colorB = INPUT2(sourceUv);
            result = mix(colorB, colorA, revealMask(sourceUv, p));
            bestZ = z;
        }
    }
    return result;
}

float blurIntensity(float p)
{
    // 50–900ms 指数增强，900–1950ms 正弦衰减。
    if (p < 0.45) {
        return exponentialIn((p - 0.025) / 0.425);
    }
    return 1.0 - sineOut((p - 0.45) / 0.525);
}

vec4 featureRadialBlur(vec2 tc)
{
    float p = clamp(PREFIX(iProgress), 0.0, 1.0);
    float amount = 0.24 * blurIntensity(p);
    vec2 center = vec2(0.5, 0.5);
    vec2 direction = tc - center;
    vec4 sum = vec4(0.0);
    float weightSum = 0.0;
    float weight = 1.0;
    for (int i = 0; i < 64; i++) {
        float t = float(i) / 63.0;
        vec2 sampleUv = center + direction * (1.0 - t * amount);
        sum += INPUT1(clamp(sampleUv, vec2(0.0), vec2(1.0))) * weight;
        weightSum += weight;
        weight *= 0.95;
    }
    vec4 color = sum / max(weightSum, 0.0001);
    return color;
}

