// =============================================================================
// Soundwave Blur · frag
// CapCut CustomShaderPass：中心 Spin Blur + Zoom Morph + 陡峭 Cross Dissolve。
// INPUT1=A（转场前），INPUT2=B（转场后）。
// =============================================================================

// 保持 CapCut 默认公共强度，避免同步放大去饱和与 Zoom Morph
const float kBlurIntensity = 0.5;
// 仅将旋转模糊角度增强 50%
const float kSpinBlurMultiplier = 1.0;
const float kPI = 3.1415926;
const int kSamples = 12;

vec2 clampEdgeUV(vec2 uv) {
    return clamp(uv, vec2(0.0), vec2(1.0));
}

vec4 sampleA(vec2 uv) {
    return INPUT1(clampEdgeUV(uv));
}

vec4 sampleB(vec2 uv) {
    return INPUT2(clampEdgeUV(uv));
}

// CapCut transition()：sin 峰值强度驱动旋转模糊与中段缩小，中点陡峭切到 B。
vec4 transitionCore(vec2 tc, float progress, float ratio) {
    // [@规则:R-T05] 端点闭合
    if (progress <= 0.0) {
        return sampleA(tc);
    }
    if (progress >= 1.0) {
        return sampleB(tc);
    }

    vec2 center = vec2(0.5, 0.5);
    float strength = sin(progress * kPI) * kBlurIntensity;
    float maxAngle = strength * 0.5 * kSpinBlurMultiplier;
    // 中段 zoom out，模拟牵引/形变
    float zoom = 1.0 + (strength * 0.2);

    vec4 finalColor = vec4(0.0);
    float totalWeight = 0.0;
    float cut = smoothstep(0.45, 0.55, progress);

    for (int i = 0; i <= kSamples; ++i) {
        float offset = (float(i) / float(kSamples)) - 0.5;
        float currentAngle = maxAngle * offset;
        float s = sin(currentAngle);
        float c = cos(currentAngle);

        vec2 uv = tc - center;
        uv.x *= ratio;
        uv = mat2(c, -s, s, c) * uv;
        uv.x /= ratio;
        uv /= max(zoom, 1e-5);
        uv += center;

        vec4 c1 = sampleA(uv);
        vec4 c2 = sampleB(uv);

        finalColor += mix(c1, c2, cut);
        totalWeight += 1.0;
    }

    return finalColor / max(totalWeight, 1.0);
}

vec4 FUNCNAME(vec2 tc) {
    float progress = PREFIX(iProgress);
    // [@规则:R-T05] p=0 只显示 A/INPUT1，p=1 只显示 B/INPUT2
    vec4 texel1 = sampleA(tc);
    vec4 texel2 = sampleB(tc);

    if (progress <= 0.0) {
        return texel1;
    }
    if (progress >= 1.0) {
        return texel2;
    }

    float ratio = iResolution.x / max(iResolution.y, 1.0);

    // CapCut：首 10% / 末 10% 与原片淡入淡出，中间跑完整转场
    const float fadeInEnd = 0.1;
    const float fadeOutStart = 0.9;

    float transitionProgress = clamp((progress - fadeInEnd) / (fadeOutStart - fadeInEnd), 0.0, 1.0);
    vec4 transitionColor = transitionCore(tc, transitionProgress, ratio);

    float blendInFactor = smoothstep(0.0, fadeInEnd, progress);
    float blendOutFactor = smoothstep(fadeOutStart, 1.0, progress);

    vec4 finalColor = mix(texel1, transitionColor, blendInFactor);
    finalColor = mix(finalColor, texel2, blendOutFactor);
    return finalColor;
}

customize_in vec3 normal;
