float luma(vec3 c)
{
    // INPUT 为 BGRA：亮度权 (B,G,R)=(0.114,0.587,0.299) 对应源 RGB (0.299,0.587,0.114)
    return dot(c, vec3(0.114, 0.587, 0.299));
}

vec3 layerWeights(vec3 c)
{
    float y = luma(c);
    float wBg = smoothstep(0.55, 1.0, y);
    float wFg = 1.0 - smoothstep(0.20, 0.55, y);
    float wMid = clamp(1.0 - wBg - wFg, 0.0, 1.0);
    return vec3(wFg, wMid, wBg);
}

vec4 speedShiftTransition(vec2 uv, vec4 texel1, vec4 texel2, float progress)
{
    if (progress <= 0.0) {
        return texel1;
    }
    if (progress >= 1.0) {
        return texel2;
    }

    float t = smoothstep(0.0, 1.0, progress);
    vec3 wA = layerWeights(texel1.rgb);
    vec3 wB = layerWeights(texel2.rgb);

    float aMove = smoothstep(0.0, 0.55, t);
    float bMove = 1.0 - smoothstep(0.45, 1.0, t);

    // [@规则:R-UV-01] Blit 采样空间：V=0 底 / V=1 顶。texture(uv - dir*amp) 使画面沿 dir 移动。
    vec2 dirFg = vec2(-1.0, 0.0);
    vec2 dirMid = vec2(1.0, 0.0);
    vec2 dirBg = vec2(0.0, 1.0);

    float shakeAmount = 0.55;
    float splitAmount = 0.75;
    float ratio = 1.0;
    vec2 scale = vec2(1.0, 1.0 / max(ratio, 1e-4));
    float ampA = shakeAmount * aMove;
    float ampB = shakeAmount * bMove;

    vec2 shAFg = dirFg * ampA * scale;
    vec2 shAMid = dirMid * ampA * scale;
    vec2 shABg = dirBg * ampA * scale;
    vec2 shBFg = -dirFg * ampB * scale;
    vec2 shBMid = -dirMid * ampB * scale;
    vec2 shBBg = -dirBg * ampB * scale;

    vec4 cAFg = INPUT1(clamp(uv - shAFg, 0.0, 1.0));
    vec4 cAMid = INPUT1(clamp(uv - shAMid, 0.0, 1.0));
    vec4 cABg = INPUT1(clamp(uv - shABg, 0.0, 1.0));
    vec4 cBFg = INPUT2(clamp(uv - shBFg, 0.0, 1.0));
    vec4 cBMid = INPUT2(clamp(uv - shBMid, 0.0, 1.0));
    vec4 cBBg = INPUT2(clamp(uv - shBBg, 0.0, 1.0));

    vec3 aLayer = wA.x * cAFg.rgb + wA.y * cAMid.rgb + wA.z * cABg.rgb;
    vec3 bLayer = wB.x * cBFg.rgb + wB.y * cBMid.rgb + wB.z * cBBg.rgb;

    // 源 RGB 拆分 (R_fg, G_mid, B_bg)；BGRA 落盘为 (B_bg, G_mid, R_fg)
    vec3 aSplit = vec3(cABg.r, cAMid.g, cAFg.b);
    vec3 bSplit = vec3(cBBg.r, cBMid.g, cBFg.b);

    float splitA = splitAmount * aMove;
    float splitB = splitAmount * bMove;
    vec3 aFinal = mix(aLayer, aSplit, splitA);
    vec3 bFinal = mix(bLayer, bSplit, splitB);
    aFinal *= (1.0 - 0.20 * aMove);

    float centerBand = exp(-abs(uv.x - 0.5) * 18.0) * exp(-abs(uv.y - 0.5) * 10.0);
    float chaos = (1.0 - abs(2.0 * t - 1.0)) * centerBand;
    // 源 RGB cross (A.R, B.G, avg(A.B,B.B)) → BGRA (avg B, B.G, A.R)
    vec3 crossColor = vec3(0.5 * (aSplit.r + bSplit.r), bSplit.g, aSplit.b);

    vec3 mixed = mix(aFinal, bFinal, t);
    mixed = mix(mixed, crossColor, 0.22 * chaos);

    float outPhase = 1.0 - smoothstep(0.35, 0.65, t);
    float inPhase = smoothstep(0.35, 0.65, t);
    vec3 staged = mix(texel1.rgb, mixed, outPhase + inPhase - outPhase * inPhase);

    vec3 finalRgb = clamp(staged, 0.0, 1.0);
    float finalA = mix(texel1.a, texel2.a, t);
    return vec4(finalRgb, finalA);
}

vec4 FUNCNAME(vec2 tc)
{
    float progress = PREFIX(iProgress);
    vec4 texel1 = INPUT1(tc);
    vec4 texel2 = INPUT2(tc);

    // [@规则:R-T05]
    if (progress <= 0.0) {
        return texel1;
    }
    if (progress >= 1.0) {
        return texel2;
    }

    float fadeInEnd = 0.1;
    float fadeOutStart = 0.9;
    float transitionProgress = clamp((progress - fadeInEnd) / (fadeOutStart - fadeInEnd), 0.0, 1.0);
    vec4 transitionColor = speedShiftTransition(tc, texel1, texel2, transitionProgress);

    float blendInFactor = smoothstep(0.0, fadeInEnd, progress);
    float blendOutFactor = smoothstep(fadeOutStart, 1.0, progress);
    vec4 finalColor = mix(texel1, transitionColor, blendInFactor);
    finalColor = mix(finalColor, texel2, blendOutFactor);
    return finalColor;
}

#define PI 3.1415926535
float A(float aA1, float aA2) {
    return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
    return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
    return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
    return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
    return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
    float aGuessT = aX;
    for (int i = 0; i < 6; ++i) {
        float currentSlope = GetSlope(aGuessT, mX1, mX2);
        if (currentSlope == 0.0)
            return aGuessT;
        float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
        aGuessT -= currentX / currentSlope;
    }
    return aGuessT;
}
float KeySpline(vec4 p, float aX) {
    float mX1 = p.x;
    float mY1 = p.y;
    float mX2 = p.z;
    float mY2 = p.w;
    if (mX1 == mY1 && mX2 == mY2)
        return aX; // linear
    return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}
// @param p1/p2: 贝塞尔曲线两个控制点

mat2 roataionAngle (float a ){
    float s = sin(a * PI / 180.0);
    float c = cos(a * PI / 180.0);
    return mat2(c,-s,s,c);
}
vec2 textureRotationOffset(vec2 uv,float offset,vec2 prop,vec2 add){   
    uv -= add;
    uv *= prop;
    uv = roataionAngle(offset) * uv;
    uv /= prop;
    uv += add;
    return uv;
}
vec4 FUNCNAME (vec2 tc){
    vec2 center = vec2(0.5, 0.0); 
    float clItime = PREFIX(global_time)/PREFIX(total_time);
    float newItime = clamp(clItime,0.35,0.65);
    newItime = (newItime-0.35)/0.3;
    float newItime2 = clamp(clItime,0.35,0.75); 
    newItime2 = (newItime2-0.35)/0.4;

    vec2 prop = vec2(iResolution.x / iResolution.y, 1.0);
    if(iResolution.y > iResolution.x){
        prop = vec2(1.0, iResolution.y / iResolution.x);
    }
    float time = newItime;

    float anim02 = KeySpline(vec4(.62,0.0,.41,.99), newItime2);

    vec2 uv = tc;
    vec4 result = vec4(0.0);

    uv = textureRotationOffset(uv,mix(0.0,-180.0,anim02),prop,center);


    int samples = 30;
    float totalWeight = 0.0;
    float rotationAngle = mix(0.0, mix(135.0,0.0,newItime2), anim02);
    float blurStrength = 0.1 * abs(rotationAngle) / 180.0;

    for (int i = 0; i < samples; i++) {
        float t = float(i) / float(samples - 1);
        float weight = 1.0 - t;

        float angle = rotationAngle * t;
        vec2 rotationDirection = vec2(sin(angle * PI / 180.0),-cos(angle * PI / 180.0));

        vec2 radialOffset = (uv - center) * prop;
        float radialDistance = length(radialOffset);
        vec2 normalizedRadialOffset = radialOffset / radialDistance;

        vec2 blurredUV = uv + rotationDirection * blurStrength * radialDistance + normalizedRadialOffset * blurStrength * t;

        blurredUV = textureRotationOffset(blurredUV, angle, prop, center);

        if(clItime <= 0.5){
            result += INPUT1(blurredUV) * weight;
        }
        else{
            result += INPUT2(vec2(1.0-blurredUV.x,blurredUV.y)) * weight;
        }
        totalWeight += weight;
    }
    result /= totalWeight;

    return result;
}

