float layerEdgeCoverage(vec2 uv) {
    // [@规则:R-AA-01] 孤立卡片：UV 0/1 内侧约 2px 覆盖率，与底色混合。
    float sd = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
    float fw = max(length(vec2(dFdx(sd), dFdy(sd))) * 2.0, 1e-5);
    return smoothstep(-fw, fw, sd);
}

