// ==========================================
// Split Dimension Transition
// 7 rounded-square cards in an upward arc,
// scrolling left-to-right along the arc.
// Left card is on top (highest z-order).
// ==========================================

// Rounded rectangle SDF
float roundedBoxSDF(vec2 center, vec2 halfSize, float radius) {
    vec2 d = abs(center) - halfSize + radius;
    return length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0) - radius;
}

// Rotate point around pivot
vec2 rotatePoint(vec2 pt, vec2 pivot, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    vec2 d = pt - pivot;
    return vec2(d.x * c - d.y * s, d.x * s + d.y * c) + pivot;
}

vec4 FUNCNAME(vec2 tc) {
    // Animation parameters
    float anim01 = PREFIX(Anim01);   // Phase 1: Full screen -> fan (0.0-0.3)
    float anim02 = PREFIX(Anim02);   // Phase 2: Scroll along arc (0.3-0.8)
    float anim03 = PREFIX(Anim03);   // Phase 3: Zoom one card to full (0.8-0.95)
    float anim04 = PREFIX(Anim04);   // Phase 4: Settle
    float eItime = PREFIX(eItime);

    // User parameters
    float strength = float(PREFIX(Strength)) / 100.0;
    float glowIntensity = float(PREFIX(Glow)) / 100.0;
    float scaleParam = float(PREFIX(Scale)) / 100.0;

    float time = float(PREFIX(global_time)) / max(float(PREFIX(total_time)), 1.0);

    // Fixed 7 cards
    int NUM_CARDS = 7;

    float aspect = iResolution.x / iResolution.y;

    // Card dimensions (roughly square, adjusted for aspect)
    float cardSize = 0.17 + scaleParam * 0.09;  // Half-size of card
    float cornerRadius = 0.018;

    // Full-screen dimensions: must cover entire [0,1]² for any aspect ratio
    float fullScreenW = max(0.5, 0.5 * aspect);
    float fullScreenH = max(0.5, 0.5 / aspect);

    // Arc parameters - arc bows UPWARD (center is highest)
    // Arc is a circle segment; cards are placed on this arc
    float arcRadius = 1.8 + strength * 0.5;   // Radius of the arc circle
    vec2 arcOrigin = vec2(0.5, 0.38 - arcRadius);  // Center of arc circle (above screen since arc bows down ∪)
    float arcSpan = 0.55 + strength * 0.15;   // Angular span for all 7 cards (radians)

    // === Phase logic ===
    float fanAmount = 0.0;      // 0 = full screen, 1 = fully fanned
    float scrollOffset = 0.0;   // Scroll position along arc (in card-index units)
    float zoomAmt = 0.0;        // 0 = card, 1 = full screen
    int zoomCardIdx = 3;        // Which card zooms (center)

    if (time < 0.20) {
        // Phase 1: Full screen -> fan out
        fanAmount = anim01;
    } else if (time < 0.80) {
        // Phase 2: Scroll 1 card with anticipation (anim02: -0.15 to 1.0)
        fanAmount = 1.0;
        scrollOffset = anim02 * 1.0;
    } else {
        // Phase 3: Zoom center card to full screen (0.80-1.0)
        // Keep fanAmount=1.0 so card base size stays constant;
        // only zoomAmt drives the center card expansion to avoid double-scaling
        fanAmount = 1.0;
        scrollOffset = 1.0;
        zoomAmt = anim03;
    }

    // Early out: full screen
    if (zoomAmt > 0.995) {
        return INPUT2(tc);
    }
    if (fanAmount < 0.005 && zoomAmt < 0.005) {
        return INPUT1(tc);
    }

    // Transparent background — lets lower track show through
    vec4 result = vec4(0.0, 0.0, 0.0, 0.0);

    // === Draw cards along the arc ===
    // Use 9 virtual slots (0-8) to ensure enough cards visible during scroll.
    // scrollOffset shifts all card positions continuously along the arc.
    // Content is tied to the original slot index (no discrete switching).
    // Draw RIGHT to LEFT so left card is on top.

    for (int drawIdx = 0; drawIdx < 9; drawIdx++) {
        int slotIdx = 8 - drawIdx;  // Draw: 8,7,6,...,0 => left on top
        float fSlot = float(slotIdx);

        // Shift slot by scroll offset (continuous, no floor/fract)
        float shiftedSlot = fSlot + scrollOffset;

        // Skip cards that are off the visible 7-card range (0~6) with margin
        if (shiftedSlot < -0.6 || shiftedSlot > 6.6) continue;

        // Arc position based on shifted slot
        float t_arc = (shiftedSlot / 6.0) * 2.0 - 1.0;  // -1 to 1

        // Angle on arc (center = +PI/2, arc bows downward ∪)
        float theta = 1.5707963 - t_arc * arcSpan * 0.5;

        // Position on arc
        float cx = arcOrigin.x + arcRadius * cos(theta);
        float cy = arcOrigin.y + arcRadius * sin(theta);

        // Tangent angle for card rotation
        float cardAngle = -t_arc * arcSpan * 0.5 * 0.6;

        // Lerp from full-screen to fan position
        vec2 fullScreenPos = vec2(0.5, 0.5);
        vec2 fanPos = vec2(cx, cy);

        // === Handle zoom for center card in phase 3 ===
        bool isZoomCard = (abs(shiftedSlot - 3.0) < 0.5);

        // Zoom card: reverse Phase 1 — fanAmount goes 1.0 -> 0.0
        // Exact same math as Phase 1 shrink, just played backwards
        float effFan = fanAmount;
        if (isZoomCard && zoomAmt > 0.001) {
            effFan = 1.0 - zoomAmt;
        }

        vec2 cardPos = mix(fullScreenPos, fanPos, effFan);
        float cardRot = cardAngle * effFan;

        // Cards scale and lift by proximity to center (slot 3)
        float distFromCenter = abs(shiftedSlot - 3.0);
        // All cards same size
        float sizeScale = 1.0;
        // Zoom card: use 0.5 as fullscreen target (exact screen half)
        // so UV naturally converges to tc without any correction
        float targetW = (isZoomCard && zoomAmt > 0.001) ? 0.5 : fullScreenW;
        float targetH = (isZoomCard && zoomAmt > 0.001) ? 0.5 : fullScreenH;
        float cardSzW = mix(targetW, cardSize * sizeScale, effFan);
        float cardSzH = mix(targetH, cardSize * sizeScale, effFan);
        // Lift: center = 0.15 up, edges = 0.0
        float liftAmount = mix(0.25, 0.0, smoothstep(0.0, 1.8, distFromCenter));
        cardPos.y += liftAmount * effFan;
        float cRadius = mix(0.0, cornerRadius, effFan);

        // Fade non-zoom cards during zoom phase
        float cAlpha = 1.0;
        if (!isZoomCard && zoomAmt > 0.001) {
            cAlpha = max(1.0 - zoomAmt * 2.0, 0.0);
        }
        if (cAlpha < 0.01) continue;

        // === Content: fixed to original slot index ===
        // Odd slot = INPUT2(card1,3,5,7), Even slot = INPUT1(card2,4,6,8)
        bool useInput2 = (mod(fSlot, 2.0) < 0.5);

        // === Test pixel against card ===
        // Correct for aspect ratio: convert to physical space before rotation
        vec2 tcAspect = vec2((tc.x - cardPos.x) * aspect, tc.y - cardPos.y);
        float cRot = -cardRot;
        float cosR = cos(cRot);
        float sinR = sin(cRot);
        vec2 rotAspect = vec2(tcAspect.x * cosR - tcAspect.y * sinR,
                              tcAspect.x * sinR + tcAspect.y * cosR);
        // Convert back to normalized space
        vec2 localPos = vec2(rotAspect.x / aspect, rotAspect.y);

        vec2 halfSz = vec2(cardSzW, cardSzH);
        float dist = roundedBoxSDF(localPos, halfSz, cRadius);

        if (dist < 0.003) {
            // Map to UV — unified for all cards including zoom
            vec2 cardUV = vec2(localPos.x / cardSzW, localPos.y / cardSzH) * 0.5 + 0.5;

            // Cover-fit: preserve input aspect ratio, crop excess
            float ratio = cardSzW / max(cardSzH, 0.001);
            if (ratio < 1.0) {
                cardUV.x = (cardUV.x - 0.5) * ratio + 0.5;
            } else {
                cardUV.y = (cardUV.y - 0.5) / ratio + 0.5;
            }
            cardUV = clamp(cardUV, vec2(0.0), vec2(1.0));

            // Sample the right texture
            vec4 texColor = vec4(0.0);
            if (isZoomCard && zoomAmt > 0.001) {
                // Zoom card: show INPUT2, same UV mapping as other cards
                texColor = INPUT2(cardUV);
            } else if (useInput2) {
                texColor = INPUT2(cardUV);
            } else {
                texColor = INPUT1(cardUV);
            }

            // Anti-aliased edge — resolution-based width (compatible with all GPUs)
            float aaWidth = 1.5 / min(iResolution.x, iResolution.y);
            float aa = 1.0 - smoothstep(-aaWidth, aaWidth, dist);
            float finalAlpha = aa * cAlpha * texColor.a;

            result.rgb = mix(result.rgb, texColor.rgb, finalAlpha);
            result.a = result.a + finalAlpha * (1.0 - result.a);
        }
    }

    return result;
}

float cubicIn(float t) {
    return t * t * t;
}

float tearNoise(float y) {
    return fract(sin(y * 12.0 * 127.1 + 311.7) * 43758.5453);
}

vec2 inverseRotate(vec2 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec2(c * p.x + s * p.y, -s * p.x + c * p.y);
}

vec4 sampleHalf(vec2 screenPos, float side, float moveT, float aspect) {
    float initialCenterX = side * 0.25 * aspect;
    float currentCenterX = initialCenterX + side * 0.8 * aspect * moveT;
    float angle = side * 1.57079632679 * moveT;

    vec2 local = inverseRotate(screenPos - vec2(currentCenterX, 0.0), angle);
    local += vec2(initialCenterX, 0.0);

    float uvX = local.x / aspect + 0.5;
    float uvY = local.y + 0.5;
    float jaggedInset = (0.5 - tearNoise(uvY)) * 0.035 * moveT;

    bool insideY = uvY >= 0.0 && uvY <= 1.0;
    bool insideX = false;
    if (side < 0.0) {
        insideX = uvX >= 0.0 && uvX <= 0.5 - jaggedInset;
    } else {
        insideX = uvX >= 0.5 + jaggedInset && uvX <= 1.0;
    }

    if (!insideX || !insideY) {
        return vec4(0.0, 0.0, 0.0, 0.0);
    }
    vec4 colorA = INPUT1(vec2(uvX, uvY));
    return vec4(colorA.rgb, 1.0);
}

vec4 FUNCNAME(vec2 tc) {
    // iProgress 已由 effect 映射到 30%–70% 窗口内的 0→1。
    float p = clamp(PREFIX(iProgress), 0.0, 1.0);
    float aspect = max(PREFIX(iAspect), 0.0001);

    vec4 colorB = INPUT2(tc);
    // [@规则:R-T05] 窗口外：animProgress=0 仅 A，animProgress=1 仅 B。
    if (p <= 0.0) {
        return INPUT1(tc);
    }
    if (p >= 1.0) {
        return colorB;
    }

    // 源时间轴：200~400ms 降饱和，400~1950ms 分片外移并旋转，均为 Cubic.In。
    float saturationT = cubicIn(clamp((p - 0.1) / 0.1, 0.0, 1.0));
    float saturation = mix(1.0, 0.6, saturationT);
    float moveT = cubicIn(clamp((p - 0.2) / 0.775, 0.0, 1.0));

    vec2 screenPos = vec2((tc.x - 0.5) * aspect, tc.y - 0.5);
    vec4 leftA = sampleHalf(screenPos, -1.0, moveT, aspect);
    vec4 rightA = sampleHalf(screenPos, 1.0, moveT, aspect);
    vec4 splitA = leftA.a > 0.0 ? leftA : rightA;

    float gray = dot(splitA.rgb, vec3(0.299, 0.587, 0.114));
    splitA.rgb = mix(vec3(gray, gray, gray), splitA.rgb, saturation);

    // [@规则:R-T05] p=0 仅 A；两片离场后露出 B；p=1 仅 B。
    return mix(colorB, splitA, splitA.a);
}

