vec4 blur(vec2 uv, float blurSize, float blurRadius, float starIns, float lightIns)
{
    float amount = 40.0;
    amount += 0.9987 * 500.0;
    vec4 oriCol = INPUT1(uv);
    vec3 maxCol = oriCol.rgb;

    vec3 bokeh = pow(oriCol.rgb,vec3(9.0)) * amount+.4;
    vec3 sumCol= bokeh*oriCol.rgb;
    vec3 sumWeight = bokeh;
    vec2 unitUV = vec2(blurSize) / iResolution;

    vec2 iOffset = vec2(0.0, 1.0);
    vec2 jOffsetL = vec2(-0.588, 0.809);
    vec2 jOffsetR = vec2(0.588, 0.809);

    // Loop optimization
    for (int h = 0; h < 5; h++) {
        iOffset *= rot(0.0);
        jOffsetL *= rot(0.0);
        jOffsetR *= rot(0.0);

        for (float i = 0.0; i < blurRadius; i += 1.0) {
            for (float j = 0.0 + step(i, 0.5); j < blurRadius - i; j += 1.0) {
                vec2 offsetL = i * iOffset + starIns * j * jOffsetL;
                vec2 offsetR = i * iOffset + starIns * j * jOffsetR;
                vec3 tempColL = INPUT1(uv - offsetL * unitUV).rgb;
                vec3 tempColR = INPUT1(uv - offsetR * unitUV).rgb;
                maxCol = max(maxCol, tempColL);
                maxCol = max(maxCol, tempColR);
                vec3 bokehL = pow(tempColL, vec3(9.0)) * amount + 0.4;
                vec3 bokehR = pow(tempColR, vec3(9.0)) * amount + 0.4;
                sumCol += bokehL * tempColL + bokehR * tempColR;
                sumWeight += bokehL + bokehR;
            }
        }
    }

    vec3 resultCol = clamp(sumCol / sumWeight, 0.0, 1.0);
    return vec4(mix(resultCol, maxCol, clamp(resultCol * lightIns, 0.0, 1.0)), oriCol.a);
}

