vec4 step1(vec2 tc){
    float heartNumber = 1.0;
    float aspect = iResolution.x / iResolution.y;
    vec2 uv = vec2(tc.x - 0.5, tc.y - 0.5);
	vec2 texResolution = vec2(540.0, 720.0);
    if(aspect < 1.0){
        uv.x *= (texResolution.y / texResolution.x) * aspect;
    }else{
        uv.y *= (texResolution.x / texResolution.y) * (1.0 / aspect);
    }
	uv = vec2(uv.x + 0.5, uv.y + 0.5);
    vec4 orgCol = INPUT1(tc);   
    vec4 textureCol = INPUT3(vec2(uv.x, 1.0 - uv.y)) * heartNumber;
	return  sum(orgCol, textureCol);
}

vec4 step2(vec2 tc){
    float blurSize = PREFIX(sizeParameter);
    float blurRadius = PREFIX(radiusParameter);

    return blur(tc, blurSize, blurRadius, 0.5, 1.0);
}

