}
vec2 NormRotate(vec2 uv0, float angle, float scale, float ratio){
  vec2 uv = Rot(angle) * vec2((uv0.x * 2.0 - 1.0) * ratio, uv0.y * 2.0 - 1.0) * scale;
  uv = vec2((uv.x/ratio + 1.0)/2.0, (uv.y + 1.0)/2.0);
  return uv;
}



vec4 blurFunc2(vec2 tc, int strength){
  // horizon blur
  int radius = 2 * strength + 1;
  float theta = 1.57;  
  vec2 dir = vec2(sin(theta), cos(theta));
	vec4 retCol = vec4(0.0, 0.0, 0.0, 0.0);
  vec2 onePixel = 4.0 / iResolution.xy; 
  vec4 roi = vec4(0.0, 0.0, 1.0, 1.0);
	float matt = 0.0;

  for (int i = -strength; i <= strength; i++){
    vec2 t = vec2(i) * onePixel;
    vec2 xy = dir * t;
    vec2 uv = tc + xy;

    matt = step(roi.x, uv.x);
    uv.x = mix(roi.x * 2.0 - uv.x, uv.x, matt);

    matt = step(roi.x + roi.z,uv.x);
    uv.x = mix(uv.x, (roi.x + roi.z) * 2.0 - uv.x, matt);

    retCol += INPUT1(uv);
  }	

  retCol /= float(radius);
  return retCol;
}
