      float offsetx = (bez - 1.0) * (0.1) + 0.35;
      float angle = radians(-5.0) * 0.5; 
      uv1 = NormRotate(uv1, -angle, 1.0, ratio) - (center);
      uv1 += center;
    }
    float ip = (iPro) / 0.5;
    vec2 center = vec2(0.8, 0.2);
    vec4 p = vec4(.99,0,.99,.87);
    float bez = KeySpline(p, ip);
    float offsetx = bez * 0.35;
    uv1.x += offsetx;
    return blurFunc2(uv1, int(floor(blurstep)));
  }else{
    vec2 center = vec2(0.8, 0.2);
    float blurstep = 10.0 - (iPro-0.5) * 20.0;
    float ip = (iPro-0.5) / 0.5;
    vec4 p = vec4(.06,.67,.48,.96);
    float bez = 1.0 - KeySpline(p, ip);
    float t1 = bez * 10.0;
    float offsetx = bez * 0.45;
    uv1.x -= offsetx;
    float angle = radians(t1)*0.5; 
    uv1 = NormRotate(uv1, angle, 1.0, ratio) - (center);
    uv1 += center;
    return blurFunc3(uv1, int(floor(blurstep)));
  }
}

#define PI 3.14159265

vec4 horizontalBlurInput2(vec2 uv, float radius, float sigma) {
    float twoSigma2 = 2.0 * sigma * sigma;
    float sigmaRoot = sqrt(6.28318530718 * sigma * sigma);
    float weightSum = 0.0;
    vec4 colorSum = vec4(0.0);

    for (int x = -int(radius); x <= int(radius); ++x) {
        float fx = float(x);
        vec2 offset = vec2(fx / iResolution.x, 0.0);
        vec2 sampleUV = uv.xy + offset;

        float weight = exp(-(fx * fx) / twoSigma2) / sigmaRoot;
        vec4 sampledColor = INPUT2(sampleUV);

        colorSum += sampledColor * weight;
        weightSum += weight;
    }

    return colorSum / weightSum;
}

vec2 rotate(vec2 videoImageCoord, vec2 centerImageCoord, float radianAngle)
{
    mat2 rotateMat = mat2(cos(radianAngle), -sin(radianAngle),
                          sin(radianAngle), cos(radianAngle));
    vec2 deltaOffset = rotateMat * (videoImageCoord - centerImageCoord);
    videoImageCoord = deltaOffset + centerImageCoord;
    return videoImageCoord;
}

vec4 swipe(vec2 tc, float process) {
    process = process;
    vec4 fragColor = vec4(0.0);

    vec2 uv = tc;
    vec2 rotateCenter = vec2(0.5, 3.0);
    uv = rotate(uv, rotateCenter, (1.0 - process) * PI * 0.25);
    vec4 blurColor = horizontalBlurInput2(uv, 35.0, 20.0);
    float transition = smoothstep(0.75, 0.95, process);
    fragColor = mix(INPUT1(tc), mix(blurColor, INPUT2(uv), transition), smoothstep(-0.1, 0.1, uv.x));
    return fragColor;   
}


vec4 FUNCNAME(vec2 tc) {
    float iGlobalTime = PREFIX(global_time);
    float totalTime = PREFIX(total_time);

    float duration_ratio = 0.3;
    float delay_ratio = (1.0 - duration_ratio) * 0.5;
    float iPro = clamp((iGlobalTime - totalTime * delay_ratio) / (totalTime * duration_ratio), 0.0, 1.0);

    vec4 retCol = vec4(0.0);
    vec2 uv = tc;
    float process = iPro;
    if (iPro < 0.2) {
        retCol = INPUT1(tc);
    } else if (iPro < 0.9) {
        process = (iPro - 0.2) / 0.7;
        retCol = swipe(uv, process);
    } else {
        retCol = INPUT2(uv);
    }
    return retCol;
}

