customize_in vec2 vUVOverW;
customize_in float vInvW;
customize_in float vPacked;

vec4 FUNCNAME(vec2 tc) {
    float p = clamp(PREFIX(iProgress), 0.0, 1.0);
    if (PREFIX(uMeshMode) == 0) {
        // [@规则:R-T05] p=0 只显示 A，p=1 只显示 B。
        if (p <= 0.0) {
            return INPUT1(tc);
        }
        return INPUT2(tc);
    }

    vec2 uv = vUVOverW / max(vInvW, 0.000001);
    uv = clamp(uv, vec2(0.0), vec2(1.0));
    vec4 colorA = INPUT1(uv);
    vec4 colorB = INPUT2(uv);

    float brightness = vPacked;
    vec4 color = colorA;
    if (vPacked >= 9.0) {
        brightness = vPacked - 10.0;
        float mixFactor = clamp(PREFIX(uMixFactor), 0.0, 1.0);
        color = mix(colorA, colorB, mixFactor);
    }

    return vec4(color.rgb * brightness, color.a);
}

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
	vec2 p1 = vec2(p.x, p.y);
	vec2 p2 = vec2(p.z, p.w);
    float mX1 = p1.x;
    float mY1 = p1.y;
    float mX2 = p2.x; 
    float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

float normpdf(float x, float sigma){
	return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

vec4 motionBlur1(vec2 tc, vec2 direction, float strength, float scale) {
	float sigma = 28.0;
	if(strength > 0.3)
		tc /= 1.0 + (scale - 1.0) * strength * 2.0; 
	float weight = normpdf(0.0, sigma);
	vec4 retCol = INPUT1(tc);
	retCol *= weight;
	float sum = weight;
	float radius = 0.03 * strength;

	for(float j = 1.0; j < 21.0; j += 1.0)
	{
		weight = normpdf(j / 10.0 * 25.0, sigma);
		float offset = radius * j;
		vec2 uv = tc + direction * offset;
		retCol += INPUT1(uv) * weight;
		sum += weight;

		uv = tc - direction * offset;
		retCol += INPUT1(uv) * weight;
		sum += weight;
	}

	retCol /= sum;
	retCol = clamp(retCol, 0.0, 1.0);
	return retCol;
}

vec4 motionBlur2(vec2 tc, vec2 direction, float strength, float scale) {
	float sigma = 28.0;
	if(strength < 0.3)
	{

		tc *= 1.0 + (scale - 1.0) * strength * 2.0; 
	}

	float weight = normpdf(0.0, sigma);
	vec4 retCol = INPUT2(tc);
	retCol *= weight;
	float sum = weight;
	float radius = 0.03 * strength;

	for(float j = 1.0; j < 21.0; j += 1.0)
	{
		weight = normpdf(j / 10.0 * 25.0, sigma);
		float offset = radius * j;
		vec2 uv = tc + direction * offset;
		retCol += INPUT2(uv) * weight;
		sum += weight;

		uv = tc - direction * offset;
		retCol += INPUT2(uv) * weight;
		sum += weight;
	}

	retCol /= sum;
	retCol = clamp(retCol, 0.0, 1.0);
	return retCol;
}

