vec2 rotate(vec2 videoImageCoord, vec2 centerImageCoord, float radianAngle)
{
    mat2 rotateMat = mat2(cos(radianAngle),sin(radianAngle),
                        -sin(radianAngle),cos(radianAngle));
    vec2 deltaOffset = rotateMat * (videoImageCoord - centerImageCoord);
    videoImageCoord = deltaOffset + centerImageCoord;
    return videoImageCoord;
}

// 漩涡扭曲函数：将UV坐标转换为极坐标，根据半径扭曲角度，产生清晰的图像变形
vec2 twirlDistort(vec2 uv, vec2 center, float strength, float progress)
{
    vec2 delta = uv - center;
    float angle = atan(delta.y, delta.x);
    float radius = length(delta);
    float maxRadius = length(vec2(0.5, 0.5));
    float normalizedRadius = clamp(radius / maxRadius, 0.0, 1.0);

    float twistAngle = strength * progress * normalizedRadius * normalizedRadius;

    angle -= twistAngle;
    return center + radius * vec2(cos(angle), sin(angle));
}

vec4 GetRadialRotate(vec2 uv, vec2 center, float Blur, float Rotate, float progress, float iPro)
{
    float outSize = Blur;
    float inSize = -Blur;
    float u_angle = Rotate;
    float u_blurSize = 0.3 - 0.3 * iPro;
    vec4 col = vec4(0.0);
    float weight = 0.;
    float blurRadius = (1.0 + u_angle * 8.0)*(8.0 - 6.5*(clamp(progress*2.2, 0.0, 1.0)));
	// float blurRadius = 8.0 * (1.0 + u_angle * 12.0);
    blurRadius = max(blurRadius * sqrt(length(uv - center)) * 4.0, 6.);
    for (int i = 0; i <= 1024; i++)
    {
        float j = float(i);
        if (j > blurRadius)
            break;
        vec2 newUV = (uv - center) / mix(1.0, outSize, u_blurSize / 79.) + center;
        vec2 newUV2 = (uv - center) / mix(1.0, inSize, u_blurSize / 79.) + center;
        newUV = mix(newUV2, newUV, j / blurRadius);
        newUV = rotate(newUV*iResolution.xy, center*iResolution.xy, u_angle * (j / blurRadius - 0.5))/iResolution.xy;
        col += INPUT1(newUV);
        weight += 1.0;
    }
    return col /= weight;
}

