float A(float aA1, float aA2) {
    return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
    return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
    return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
    return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
    return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
    float aGuessT = aX;
    for (int i = 0; i < 6; ++i) {
        float currentSlope = GetSlope(aGuessT, mX1, mX2);
        if (currentSlope == 0.0)
            return aGuessT;
        float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
        aGuessT -= currentX / currentSlope;
    }
    return aGuessT;
}

/*
* @param aX: 传入时间变量
* @param p1/p2: 贝塞尔曲线两个控制点
* 说明: 这个函数以上的其他函数都是本函数使用的辅助函数
*/
float KeySpline(vec4 p, float aX) {
    float mX1 = p.x;
    float mY1 = p.y;
    float mX2 = p.z;
    float mY2 = p.w;
    if (mX1 == mY1 && mX2 == mY2)
        return aX; // linear
    return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

#define PI 3.1415926
vec2 mirror(vec2 vec) {
    vec2 res = vec;
    if (res.x < 0.) res.x = -res.x;
    if (res.y < 0.) res.y = -res.y;
    if (res.x > 1.) res.x = 2. - res.x;
    if (res.y > 1.) res.y = 2. - res.y;
    return res;
}
vec2 rot(float angle, vec2 uv)
{
    float theta = angle * PI / 180.;
    mat2 r = mat2(cos(theta), -sin(theta), sin(theta), cos(theta));
    float ratio = iResolution.x / iResolution.y;
    if (ratio < 1.) uv.x *= ratio;
    else uv.y /= ratio;
    vec2 uv1 = uv * r;
    if (ratio < 1.) uv1.x /= ratio;
    else uv1.y *= ratio;
    return uv1;
}
