        float d = length(uv * 2.0);
        uv = uv / pow((d*d*30.0) + 1.0, -pow(u_fov * (1. / (16. / 9.)) * u_strength * 0.0059375, 3.0 + (1. - x2) * .5));
        uv *= ratio;
        uv *= 1. + pow(u_fov - 10., 2.) / 18000. * smoothstep(-10., 10., u_fov - 10.) * mix(0., 2., x2);
        uv -= offset;
        uv = rot(rotateZ, uv);
        uv *= scaleVec;
        uv += .5;
        return uv;
}
