vec2 scale(vec2 uv, vec2 scaleIns, vec2 center){
    mat2 scaleMatrix = mat2(1.0/(scaleIns.x + 0.000001), 0.0, 0.0, 1.0/(scaleIns.y + 0.000001));
    vec2 uv1=uv;
    uv1 -= center;
    uv1=uv1*scaleMatrix;
    uv1 += center;
    return uv1;
}

float normpdf(in float x, in float sigma)
{
	return 0.39894*exp(-0.5*x*x/(sigma*sigma))/sigma;
}

vec4 texture2Dmirror(vec2 uv) {
    uv = mod(uv, 2.0);
    uv = mix(uv, 2.0 - uv, step(vec2(1.0), uv));
    return INPUT1(fract(uv));
}

vec4 directionBlur(vec2 tc)
{
    float uSample = PREFIX(directionBlur);
    float theta = 90.0 * 3.1415926 / 180.0;
    vec2 rect = vec2(min(720.0, 720.0 * iResolution.x / iResolution.y), min(720.0, 720.0 * iResolution.y / iResolution.x));
    vec2 dir = vec2(cos(theta), sin(theta)) / rect;

    float sigma = 4.0;
    float weight = normpdf(0.0, sigma);

    vec4 sum            = vec4(0.0);
    vec4 result         = vec4(0.0);
    vec2 unit_uv        = dir * 6.0;
    float gamma         = 1.0;
    vec4 curColor       = INPUT1(tc);
    vec4 centerPixel    = pow(curColor, vec4(gamma))*weight;
    float sum_weight    = weight;

    float s = uSample;
    for(int i=1;i<=100;i++)
    {
        if (float(i)>uSample) break;
        vec2 curRightCoordinate = tc+float(i)*unit_uv;
        vec2 curLeftCoordinate  = tc+float(-i)*unit_uv;
        vec4 rightColor = texture2Dmirror(curRightCoordinate);
        vec4 leftColor = texture2Dmirror(curLeftCoordinate);
        weight = normpdf(float(i) / s * 15.0, sigma);
        sum+=pow(rightColor, vec4(gamma))*weight;
        sum+=pow(leftColor, vec4(gamma))*weight;
        sum_weight+=weight*2.0;
    }
    result = (sum+centerPixel)/sum_weight; 
    result = pow(result, vec4(1.0 / gamma));
    return clamp(result, 0.0, 1.0);
}

