// Zoom Wipe · 全屏 UV 变焦划像转场
// 源：scriptScene.js 线性 tween（0–0.15 停 A，0.15–0.85 推 progress，0.85–1 停 B）
//     + shaderFrag.js 中心变焦 / 径向模糊 / 左→右垂直划像 / 扫描亮边
// [@规则:R-T01][@规则:R-T05][@规则:R-UV-01][@动画:A-帧进度]

vec4 sampleZoomBlurA(vec2 uv, float zoom, float blurAmt)
{
    vec2 center = vec2(0.5, 0.5);
    vec2 dir = uv - center;
    vec2 n = normalize(dir + vec2(1e-6, 0.0));
    vec2 zUv = center + dir / max(zoom, 1e-4);

    vec4 s0 = INPUT1(zUv);
    vec4 s1 = INPUT1(zUv - n * blurAmt);
    vec4 s2 = INPUT1(zUv - n * blurAmt * 2.0);
    vec4 avg = (s0 + s1 + s2) / 3.0;

    vec2 perp = normalize(vec2(-n.y, n.x));
    vec2 ca = perp * blurAmt * 1.2;
    float r = INPUT1(zUv + ca).r;
    float b = INPUT1(zUv - ca).b;

    return vec4(r, avg.g, b, avg.a);
}

vec4 sampleZoomBlurB(vec2 uv, float zoom, float blurAmt)
{
    vec2 center = vec2(0.5, 0.5);
    vec2 dir = uv - center;
    vec2 n = normalize(dir + vec2(1e-6, 0.0));
    vec2 zUv = center + dir / max(zoom, 1e-4);

    vec4 s0 = INPUT2(zUv);
    vec4 s1 = INPUT2(zUv - n * blurAmt);
    vec4 s2 = INPUT2(zUv - n * blurAmt * 2.0);

    return (s0 + s1 + s2) / 3.0;
}

vec4 zoomWipeTransition(vec2 tc, float progress, vec4 texel1, vec4 texel2)
{
    float p = clamp(progress, 0.0, 1.0);
    float wipeFeather = 0.08;
    float blurStrength = 1.0;
    float zoomA = 1.25;
    float zoomBStart = 1.5;
    float edgeIntensity = 0.35;

    float aDrive = smoothstep(0.0, 0.45, p);
    float bDrive = smoothstep(0.35, 1.0, p);

    float aZoom = mix(1.0, zoomA, aDrive);
    float aBlur = blurStrength * aDrive * 0.02;
    float aDark = mix(1.0, 0.72, aDrive);

    float bZoom = mix(zoomBStart, 1.0, bDrive);
    float bBlur = blurStrength * (1.0 - bDrive) * 0.018;

    vec4 aCol = sampleZoomBlurA(tc, aZoom, aBlur);
    aCol.rgb *= aDark;

    vec4 bCol = sampleZoomBlurB(tc, bZoom, bBlur);

    // 划像边沿沿 UV.x 从左向右推进：左侧揭示 B，右侧保留 A
    float wipePos = mix(-2.0 * wipeFeather, 1.0 + 2.0 * wipeFeather, p);
    float mask = 1.0 - smoothstep(wipePos - wipeFeather, wipePos + wipeFeather, tc.x);

    float edge = exp(-abs(tc.x - wipePos) / max(wipeFeather * 0.35, 1e-4));
    vec3 glow = vec3(1.0, 1.0, 1.0) * edge * edgeIntensity * (0.4 + 0.6 * (1.0 - p));

    vec4 col = mix(aCol, bCol, mask);
    col.rgb = clamp(col.rgb + glow * (1.0 - abs(mask - 0.5) * 2.0), 0.0, 1.0);
    col.a = mix(texel1.a, texel2.a, mask);

    return col;
}

