    if (clipP <= 0.15) {
        progress = 0.0;
    } else if (clipP >= 0.85) {
        progress = 1.0;
    } else {
        progress = (clipP - 0.15) / 0.70;
    }

    vec4 texelA = INPUT1(tc);
    vec4 texelB = INPUT2(tc);

    float fadeInEnd = 0.1;
    float fadeOutStart = 0.9;
    float transitionProgress = clamp((progress - fadeInEnd) / (fadeOutStart - fadeInEnd), 0.0, 1.0);
    vec4 transitionColor = zoomWipeTransition(tc, transitionProgress, texelA, texelB);

    float blendInFactor = smoothstep(0.0, fadeInEnd, progress);
    float blendOutFactor = smoothstep(fadeOutStart, 1.0, progress);

    vec4 finalColor = mix(texelA, transitionColor, blendInFactor);
    finalColor = mix(finalColor, texelB, blendOutFactor);
    return finalColor;
}
